val LocalInfoCardsEnabled = androidx.compose.runtime.compositionLocalOf { true }

class MainActivity : ComponentActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val viewModel = androidx.lifecycle.ViewModelProvider(this)[HabitsViewModel::class.java]
        handleWidgetIntent(intent, viewModel)
        handleReviewIntent(intent, viewModel)
        enableEdgeToEdge()
        setContent {
            val darkModeEnabled by viewModel.darkModeEnabled.collectAsStateWithLifecycle()
            MyApplicationTheme(darkTheme = darkModeEnabled) {
                MainAppScreen(viewModel = viewModel)
            }
        }
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
        val viewModel = androidx.lifecycle.ViewModelProvider(this)[HabitsViewModel::class.java]
        handleWidgetIntent(intent, viewModel)
        handleReviewIntent(intent, viewModel)
    }

    private fun handleWidgetIntent(intent: Intent?, viewModel: HabitsViewModel) {
        if (intent?.action == "com.example.widget.ACTION_WIDGET_ADD_VALUE") {
            val habitId = intent.getIntExtra("com.example.widget.EXTRA_HABIT_ID", -1)
            if (habitId != -1) {
                viewModel.setPendingWidgetHabitId(habitId)
            }
        }
    }

    private fun handleReviewIntent(intent: Intent?, viewModel: HabitsViewModel) {
        if (intent != null && intent.hasExtra("OPEN_REVIEW_TYPE")) {
            val reviewType = intent.getStringExtra("OPEN_REVIEW_TYPE")
            val year = intent.getIntExtra("REVIEW_YEAR", -1)
            val month = intent.getIntExtra("REVIEW_MONTH", -1)
            if (reviewType == "MONTHLY" && year != -1 && month != -1) {
                viewModel.setDeepLinkReviewMonth(year to month)
            } else if (reviewType == "YEARLY" && year != -1) {
                viewModel.setDeepLinkReviewYear(year)
            }
            intent.removeExtra("OPEN_REVIEW_TYPE")
        }
    }
}

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun ClearFocusOnKeyboardDismiss() {
    val focusManager = LocalFocusManager.current
    val keyboardController = LocalSoftwareKeyboardController.current
    val isImeVisible = WindowInsets.isImeVisible
    var wasImeVisible by remember { mutableStateOf(false) }

    LaunchedEffect(isImeVisible) {
        if (isImeVisible) {
            wasImeVisible = true
        } else if (wasImeVisible) {
            focusManager.clearFocus(force = true)
            wasImeVisible = false
        }
    }

    if (wasImeVisible || isImeVisible) {
        BackHandler {
            focusManager.clearFocus(force = true)
            keyboardController?.hide()
            wasImeVisible = false
        }
    }
}

@Composable
fun rememberResumeAnimationTrigger(): Int {
    val lifecycleOwner = LocalLifecycleOwner.current
    var trigger by remember { mutableIntStateOf(0) }
    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, event ->
            if (event == Lifecycle.Event.ON_RESUME) {
                trigger++
            }
        }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose {
            lifecycleOwner.lifecycle.removeObserver(observer)
        }
    }
    return trigger
}

@Composable
fun MainAppScreen(viewModel: HabitsViewModel) {
    val context = LocalContext.current
    val activity = context as? Activity
    
    ClearFocusOnKeyboardDismiss()

    var selectedTab by remember { mutableStateOf("TODAY") }
    val navController = rememberNavController()
    val language by viewModel.language.collectAsStateWithLifecycle()
    val infoCardsEnabled by viewModel.infoCardsEnabled.collectAsStateWithLifecycle()

    val todayListState = rememberLazyListState()
    val statsListState = rememberLazyListState()
    val profileListState = rememberLazyListState()
    val coroutineScope = rememberCoroutineScope()
    val mainTabRoutes = remember { setOf("TODAY", "STATS", "PROFILE") }
    var previousRoute by remember { mutableStateOf<String?>(null) }

    CompositionLocalProvider(LocalInfoCardsEnabled provides infoCardsEnabled) {
    val navBackStackEntry by navController.currentBackStackEntryAsState()
    val currentRoute = navBackStackEntry?.destination?.route

    val pendingWidgetHabitId by viewModel.pendingWidgetHabitId.collectAsStateWithLifecycle()
    val newlyUnlockedAchievement by viewModel.newlyUnlockedAchievement.collectAsStateWithLifecycle()
    val hasOnboarded by viewModel.hasOnboarded.collectAsStateWithLifecycle()
    var showCreateFirstHabitHint by remember { mutableStateOf(false) }

    LaunchedEffect(Unit) {
        FeedbackHelper.init(context.applicationContext)
    }

    LaunchedEffect(pendingWidgetHabitId) {
        if (pendingWidgetHabitId != null) {
            if (currentRoute != "TODAY" && currentRoute != null) {
                navController.navigate("TODAY") {
                    popUpTo(navController.graph.findStartDestination().id) {
                        saveState = true
                    }
                    launchSingleTop = true
                    restoreState = true
                }
            }
        }
    }

    var editingHabit by remember { mutableStateOf<Habit?>(null) }

    val allHabitsForPopup by viewModel.allHabits.collectAsStateWithLifecycle()
    val allLogsForPopup by viewModel.allLogs.collectAsStateWithLifecycle()

    val nyPrefs = context.getSharedPreferences("habits_settings", Context.MODE_PRIVATE)
    val isNYPopupWindow = remember { isNewYearPopupPeriod() }
    val currentYearVal = remember { java.time.LocalDate.now().year }
    val reviewYearVal = remember { if (java.time.LocalDate.now().monthValue == 1) currentYearVal - 1 else currentYearVal }
    val nyPopupKey = "has_seen_ny_popup_$reviewYearVal"

    var showNewYearPopup by remember {
        mutableStateOf(isNYPopupWindow && !nyPrefs.getBoolean(nyPopupKey, false))
    }
    var popupReviewYearState by remember { mutableStateOf<Int?>(null) }

    if (showNewYearPopup) {
        NewYearReviewPopupDialog(
            reviewYear = reviewYearVal,
            language = language,
            onStartReview = {
                showNewYearPopup = false
                nyPrefs.edit().putBoolean(nyPopupKey, true).apply()
                popupReviewYearState = reviewYearVal
            },
            onDismiss = {
                showNewYearPopup = false
                nyPrefs.edit().putBoolean(nyPopupKey, true).apply()
            }
        )
    }

    if (popupReviewYearState != null) {
        YearlyReviewDialog(
            year = popupReviewYearState!!,
            allHabits = allHabitsForPopup,
            allLogs = allLogsForPopup,
            language = language,
            viewModel = viewModel,
            onDismiss = { popupReviewYearState = null }
        )
    }

    // Keep tab selected state in synchronization if user navigates & scroll to top when switching main tabs
    LaunchedEffect(currentRoute) {
        if (currentRoute != null) {
            if (mainTabRoutes.contains(currentRoute)) {
                if (previousRoute != null && mainTabRoutes.contains(previousRoute) && previousRoute != currentRoute) {
                    when (currentRoute) {
                        "TODAY" -> todayListState.scrollToItem(0, 0)
                        "STATS" -> statsListState.scrollToItem(0, 0)
                        "PROFILE" -> profileListState.scrollToItem(0, 0)
                    }
                }
            }
            previousRoute = currentRoute
        }
        if (currentRoute != null && !currentRoute.startsWith("DETAIL") && selectedTab != currentRoute) {
            selectedTab = currentRoute
        }
        if (currentRoute != "CREATE") {
            editingHabit = null
        }
    }



    Scaffold(
        modifier = Modifier.fillMaxSize(),
        bottomBar = {
            if (currentRoute != null && !currentRoute.startsWith("DETAIL") && currentRoute != "CREATE" && currentRoute != "OVERALL_STATS" && !currentRoute.startsWith("MORE") && editingHabit == null) {
                HabitBottomNavigation(
                    selectedTab = selectedTab,
                    onTabSelected = { tab ->
                        if (tab == "STATS" && allHabitsForPopup.none { !it.isArchived }) {
                            Toast.makeText(
                                context,
                                if (language == "de") "Erstelle zuerst eine Gewohnheit, um Statistiken zu sehen." else if (language == "ka") "შექმენით ჩვევა ჯერ სტატისტიკის სანახავად." else "Create a habit first to view statistics.",
                                Toast.LENGTH_SHORT
                            ).show()
                        } else {
                            val targetState = when (tab) {
                                "TODAY" -> todayListState
                                "STATS" -> statsListState
                                "PROFILE" -> profileListState
                                else -> null
                            }
                            if (selectedTab != tab) {
                                selectedTab = tab
                                navController.navigate(tab) {
                                    popUpTo(navController.graph.findStartDestination().id) {
                                        saveState = true
                                    }
                                    launchSingleTop = true
                                    restoreState = true
                                }
                            }
                            coroutineScope.launch {
                                targetState?.scrollToItem(0, 0)
                            }
                        }
                    },
                    onAddClick = {},
                    language = language
                )
            }
        },
        containerColor = AppBg,
        contentWindowInsets = WindowInsets.systemBars
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(AppBg)
                .padding(top = innerPadding.calculateTopPadding())
        ) {
            val mainTabRoutes = remember { listOf("TODAY", "STATS", "PROFILE") }
            fun isMainTabRoute(route: String?): Boolean {
                if (route.isNullOrEmpty()) return true
                return mainTabRoutes.contains(route)
            }

            NavHost(
                navController = navController,
                startDestination = "TODAY",
                modifier = Modifier.fillMaxSize(),
                enterTransition = {
                    val initialRoute = initialState.destination.route
                    val targetRoute = targetState.destination.route
                    if (isMainTabRoute(initialRoute) && isMainTabRoute(targetRoute)) {
                        fadeIn(animationSpec = tween(150, easing = LinearOutSlowInEasing))
                    } else {
                        slideInHorizontally(
                            initialOffsetX = { fullWidth -> fullWidth },
                            animationSpec = tween(320, easing = FastOutSlowInEasing)
                        ) + fadeIn(animationSpec = tween(200))
                    }
                },
                exitTransition = {
                    val initialRoute = initialState.destination.route
                    val targetRoute = targetState.destination.route
                    if (isMainTabRoute(initialRoute) && isMainTabRoute(targetRoute)) {
                        fadeOut(animationSpec = tween(120, easing = FastOutLinearInEasing))
                    } else {
                        slideOutHorizontally(
                            targetOffsetX = { fullWidth -> -fullWidth },
                            animationSpec = tween(320, easing = FastOutSlowInEasing)
                        ) + fadeOut(animationSpec = tween(200))
                    }
                },
                popEnterTransition = {
                    val initialRoute = initialState.destination.route
                    val targetRoute = targetState.destination.route
                    if (isMainTabRoute(initialRoute) && isMainTabRoute(targetRoute)) {
                        fadeIn(animationSpec = tween(150, easing = LinearOutSlowInEasing))
                    } else {
                        slideInHorizontally(
                            initialOffsetX = { fullWidth -> -fullWidth },
                            animationSpec = tween(320, easing = FastOutSlowInEasing)
                        ) + fadeIn(animationSpec = tween(200))
                    }
                },
                popExitTransition = {
                    val initialRoute = initialState.destination.route
                    val targetRoute = targetState.destination.route
                    if (isMainTabRoute(initialRoute) && isMainTabRoute(targetRoute)) {
                        fadeOut(animationSpec = tween(120, easing = FastOutLinearInEasing))
                    } else {
                        slideOutHorizontally(
                            targetOffsetX = { fullWidth -> fullWidth },
                            animationSpec = tween(320, easing = FastOutSlowInEasing)
                        ) + fadeOut(animationSpec = tween(200))
                    }
                }
            ) {
                composable("PROFILE") {
                    ProfileScreen(
                        viewModel = viewModel,
                        language = language,
                        onSettingsClick = { subpage ->
                            val dest = if (subpage != null) "MORE?subpage=$subpage" else "MORE"
                            navController.navigate(dest) {
                                launchSingleTop = true
                            }
                        },
                        listState = profileListState
                    )
                }
                composable("TODAY") {
                    val onAddClick = remember {
                        {
                            editingHabit = null
                            navController.navigate("CREATE") {
                                launchSingleTop = true
                            }
                        }
                    }
                    TodayScreen(
                        viewModel = viewModel,
                        language = language,
                        onAddClick = onAddClick,
                        onEditHabit = { habit ->
                            editingHabit = habit
                            navController.navigate("CREATE") {
                                launchSingleTop = true
                            }
                        },
                        showCreateFirstHabitHint = showCreateFirstHabitHint,
                        onDismissFirstHabitHint = { showCreateFirstHabitHint = false },
                        listState = todayListState
                    )
                }
                composable("CREATE") {
                    DisposableEffect(Unit) {
                        onDispose {
                            editingHabit = null
                        }
                    }
                    CreateHabitScreen(
                        language = language,
                        editingHabit = editingHabit,
                        onDismiss = {
                            editingHabit = null
                            navController.navigate("TODAY") {
                                popUpTo(navController.graph.findStartDestination().id) {
                                    inclusive = false
                                }
                            }
                        },
                        onSave = { name, isNeg, cat, icon, color, type, unit, target, clickIncrement, freq, start, specDays, remEnabled, remHour, remMin, customReminders, description, milestoneRewards ->
                            if (editingHabit != null) {
                                val updated = editingHabit!!.copy(
                                    name = name,
                                    isNegative = isNeg,
                                    category = cat,
                                    icon = icon,
                                    color = color,
                                    type = type,
                                    unit = unit,
                                    targetValue = target,
                                    clickIncrement = clickIncrement,
                                    frequency = freq,
                                    startDate = start,
                                    specificDays = specDays,
                                    reminderEnabled = remEnabled,
                                    reminderHour = remHour,
                                    reminderMinute = remMin,
                                    customReminders = customReminders,
                                    description = description
                                )
                                viewModel.updateHabit(updated)
                                if (milestoneRewards.isNotEmpty()) {
                                    milestoneRewards.forEach { reward ->
                                    }
                                }
                                editingHabit = null
                                Toast.makeText(
                                    context,
                                    if (language == "de") "Gewohnheit aktualisiert!" else if (language == "ka") "ჩვევა განახლებულია!" else "Habit updated!",
                                    Toast.LENGTH_SHORT
                                ).show()
                            } else {
                                viewModel.addHabit(name, cat, icon, color, isNeg, type, unit, target, freq, start, specDays, remEnabled, remHour, remMin, customReminders, description, clickIncrement, milestoneRewards)
                                Toast.makeText(
                                    context,
                                    if (language == "de") "Gewohnheit hinzugefügt!" else if (language == "ka") "ჩვევა დაემატა!" else "Habit added!",
                                    Toast.LENGTH_SHORT
                                ).show()
                            }
                            navController.navigate("TODAY") {
                                popUpTo(navController.graph.findStartDestination().id) {
                                    inclusive = false
                                }
                            }
                        }
                    )
                }
                composable("STATS") {
                    val onAddClick = remember {
                        {
                            editingHabit = null
                            navController.navigate("CREATE") {
                                launchSingleTop = true
                            }
                        }
                    }
                    StatsScreen(
                        viewModel = viewModel,
                        language = language,
                        onAddClick = onAddClick,
                        onHabitClick = { habitId ->
                            if (navController.currentDestination?.route?.startsWith("DETAIL") != true) {
                                navController.navigate("DETAIL/$habitId") {
                                    launchSingleTop = true
                                }
                            }
                        },
                        onOverallClick = {
                            if (navController.currentDestination?.route != "OVERALL_STATS") {
                                navController.navigate("OVERALL_STATS") {
                                    launchSingleTop = true
                                }
                            }
                        },
                        listState = statsListState
                    )
                }
                composable("OVERALL_STATS") {
                    OverallStatsScreen(
                        viewModel = viewModel,
                        language = language,
                        onBack = {
                            navController.popBackStack()
                        },
                        onNavigateToToday = {
                            navController.navigate("TODAY") {
                                popUpTo(navController.graph.findStartDestination().id) {
                                    saveState = true
                                }
                                launchSingleTop = true
                                restoreState = true
                            }
                            coroutineScope.launch {
                                todayListState.scrollToItem(0, 0)
                            }
                        }
                    )
                }
                composable(
                    route = "MORE?subpage={subpage}",
                    arguments = listOf(
                        navArgument("subpage") {
                            type = NavType.StringType
                            nullable = true
                            defaultValue = null
                        }
                    )
                ) { backStackEntry ->
                    val subpage = backStackEntry.arguments?.getString("subpage")
                    SettingsScreen(
                        viewModel = viewModel,
                        language = language,
                        initialSubpage = subpage,
                        onBack = {
                            navController.popBackStack()
                        }
                    )
                }
                composable(
                    route = "DETAIL/{habitId}",
                    arguments = listOf(navArgument("habitId") { type = NavType.IntType })
                ) { backStackEntry ->
                    val habitId = backStackEntry.arguments?.getInt("habitId") ?: -1
                    LaunchedEffect(habitId) {
                        viewModel.selectHabitForDetail(habitId)
                    }
                    DisposableEffect(Unit) {
                        onDispose {
                            viewModel.selectHabitForDetail(null)
                        }
                    }

                    val habits by viewModel.allHabits.collectAsStateWithLifecycle()
                    val habit = remember(habitId, habits) { habits.find { it.id == habitId } }

                    if (habit != null) {
                        val detailState by viewModel.selectedHabitDetailState.collectAsStateWithLifecycle()
                        val isStateMatching = detailState != null && detailState!!.habit.id == habitId
                        val onBack = remember { {
                            navController.popBackStack()
                            Unit
                        } }
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(bottom = innerPadding.calculateBottomPadding())
                        ) {
                            HabitDetailScreen(
                                habit = habit,
                                state = if (isStateMatching) detailState else null,
                                viewModel = viewModel,
                                language = language,
                                onBack = onBack
                            )
                        }
                    } else {
                        Box(
                            modifier = Modifier.fillMaxSize(),
                            contentAlignment = Alignment.Center
                        ) {
                            CircularProgressIndicator(color = PrimaryViolet)
                        }
                    }
                }
            }

            // Fading overlay at the bottom so content beautifully fades out behind the floating nav bar
            if (currentRoute != null && !currentRoute.startsWith("DETAIL") && currentRoute != "CREATE" && currentRoute != "OVERALL_STATS" && !currentRoute.startsWith("MORE") && editingHabit == null) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(140.dp)
                        .align(Alignment.BottomCenter)
                        .background(
                            brush = Brush.verticalGradient(
                                colors = listOf(
                                    Color.Transparent,
                                    AppBg.copy(alpha = 0.8f),
                                    AppBg
                                )
                            )
                        )
                )
            }
        }
    }

    if (pendingWidgetHabitId != null) {
        WidgetAddValueDialog(
            habitId = pendingWidgetHabitId!!,
            viewModel = viewModel,
            language = language,
            onDismiss = { viewModel.clearPendingWidgetHabitId() }
        )
    }

    if (newlyUnlockedAchievement != null) {
        AchievementUnlockedOverlay(
            achievement = newlyUnlockedAchievement!!,
            language = language,
            onDismiss = { viewModel.dismissUnlockedAchievement() }
        )
    }

    var showOnboardingCelebration by remember { mutableStateOf(false) }

    if (showOnboardingCelebration) {
        FullScreensCelebrationConfetti(
            onFinished = { showOnboardingCelebration = false }
        )
    }

    if (!hasOnboarded) {
        OnboardingScreen(
            viewModel = viewModel,
            language = language,
            onComplete = {
                viewModel.setOnboarded(true)
                showOnboardingCelebration = true
                showCreateFirstHabitHint = true
            }
        )
    }
    }
}

// AUDIO SOUNDSCAPE MANAGER & PERSISTENCE
object AudioSoundscapeManager {
    private const val PREFS_NAME = "audio_soundscape_prefs"
    private const val KEY_LAST_SELECTED_AUDIO = "last_selected_audio_filename"
    private const val KEY_RECENT_AUDIOS = "recent_audio_filenames"
    private const val PREFIX_CATEGORY = "sound_category_"

    val CATEGORIES = listOf(
        "Alle",
        "Natur & Wetter",
        "Fokus & Noise",
        "Ambiente & Ruhe",
        "Eigene Sounds"
    )

    fun getLastSelectedAudio(context: android.content.Context): String {
        val prefs = context.getSharedPreferences(PREFS_NAME, android.content.Context.MODE_PRIVATE)
        return prefs.getString(KEY_LAST_SELECTED_AUDIO, "") ?: ""
    }

    fun getRecentAudios(context: android.content.Context): List<String> {
        val prefs = context.getSharedPreferences(PREFS_NAME, android.content.Context.MODE_PRIVATE)
        val raw = prefs.getString(KEY_RECENT_AUDIOS, "") ?: ""
        if (raw.isEmpty()) return emptyList()
        return raw.split(";").filter { it.isNotEmpty() }
    }

    fun setLastSelectedAudio(context: android.content.Context, filename: String?) {
        val prefs = context.getSharedPreferences(PREFS_NAME, android.content.Context.MODE_PRIVATE)
        prefs.edit().putString(KEY_LAST_SELECTED_AUDIO, filename ?: "").apply()
        if (!filename.isNullOrEmpty()) {
            val recents = getRecentAudios(context).toMutableList()
            recents.remove(filename)
            recents.add(0, filename)
            val trimmed = recents.take(3)
            prefs.edit().putString(KEY_RECENT_AUDIOS, trimmed.joinToString(";")).apply()
        }
    }

    fun getSoundCategory(context: android.content.Context, filename: String): String {
        val prefs = context.getSharedPreferences(PREFS_NAME, android.content.Context.MODE_PRIVATE)
        val stored = prefs.getString(PREFIX_CATEGORY + filename, null)
        if (!stored.isNullOrEmpty()) return stored

        val lower = filename.lowercase()
        return when {
            lower.contains("rain") || lower.contains("regen") || lower.contains("forest") || lower.contains("wald") ||
            lower.contains("ocean") || lower.contains("meer") || lower.contains("wind") || lower.contains("stream") || lower.contains("fluss") ||
            lower.contains("water") || lower.contains("wasser") || lower.contains("storm") -> "Natur & Wetter"

            lower.contains("binaural") || lower.contains("focus") || lower.contains("fokus") || lower.contains("white") ||
            lower.contains("noise") || lower.contains("alpha") || lower.contains("wave") || lower.contains("brown") || lower.contains("pink") -> "Fokus & Noise"

            lower.contains("meditation") || lower.contains("zen") || lower.contains("piano") || lower.contains("ambient") ||
            lower.contains("ruhe") || lower.contains("calm") || lower.contains("sleep") || lower.contains("relax") -> "Ambiente & Ruhe"

            else -> "Eigene Sounds"
        }
    }

    fun setSoundCategory(context: android.content.Context, filename: String, category: String) {
        val prefs = context.getSharedPreferences(PREFS_NAME, android.content.Context.MODE_PRIVATE)
        prefs.edit().putString(PREFIX_CATEGORY + filename, category).apply()
    }
}

@OptIn(ExperimentalMaterial3Api::class)
