@OptIn(ExperimentalLayoutApi::class, ExperimentalMaterial3Api::class)
@Composable
fun WidgetAddValueDialog(
    habitId: Int,
    viewModel: HabitsViewModel,
    language: String,
    onDismiss: () -> Unit
) {
    val focusManager = LocalFocusManager.current
    val keyboardController = LocalSoftwareKeyboardController.current
    ClearFocusOnKeyboardDismiss()

    val selectedDate by viewModel.selectedDate.collectAsStateWithLifecycle()
    val logs by viewModel.allLogs.collectAsStateWithLifecycle()

    var habitToLog by remember { mutableStateOf<com.example.data.Habit?>(null) }
    var isLoaded by remember { mutableStateOf(false) }

    val context = androidx.compose.ui.platform.LocalContext.current

    LaunchedEffect(habitId) {
        try {
            val db = com.example.data.AppDatabase.getDatabase(context)
            val habit = db.habitDao().getHabitByIdSuspend(habitId)
            habitToLog = habit
        } catch (e: Exception) {
            e.printStackTrace()
        } finally {
            isLoaded = true
        }
    }

    if (!isLoaded) {
        // Wait for database loading, do not dismiss!
    } else if (habitToLog != null) {
        val existingLog = logs.find { it.habitId == habitToLog!!.id && it.date == selectedDate }
        val currentValue = existingLog?.value ?: 0f

        val hasTimer = remember(habitToLog) {
            val isMins = habitToLog!!.unit.lowercase() in listOf("minuten", "minutes", "min", "minute", "m")
            val isNumerical = habitToLog!!.type == "NUMBER" || habitToLog!!.type == "NUMERICAL" || (habitToLog!!.targetValue > 1f && habitToLog!!.type != "BINARY")
            isNumerical && isMins
        }

        var inputVal by remember(habitId, currentValue) {
            val target = habitToLog?.targetValue ?: 0f
            val displayVal = if (target <= 0f) 0f else target
            val formatted = if (displayVal <= 0f) "" else {
                if (displayVal % 1f == 0f) displayVal.toInt().toString() else displayVal.toString()
            }
            mutableStateOf(formatted)
        }

        val defaultMins = remember(habitToLog) {
            val target = habitToLog?.targetValue ?: 25f
            if (target % 1f == 0f) target.toInt().toString() else target.toString()
        }

        // Timer State variables
        var timerDurationMinutes by remember(habitId) { mutableStateOf(defaultMins) }
        var timerSecondsRemaining by remember(habitId) { 
            val mins = defaultMins.toFloatOrNull() ?: 25f
            mutableStateOf((mins * 60).toInt()) 
        }
        var initialTimerSeconds by remember(habitId) { 
            val mins = defaultMins.toFloatOrNull() ?: 25f
            mutableStateOf((mins * 60).toInt()) 
        }
        var isTimerRunning by remember { mutableStateOf(false) }
        var isEditingTimerDuration by remember { mutableStateOf(false) }
        var tempTimerInput by remember(habitId) { mutableStateOf(defaultMins) }

        // Audio State variables
        var importedAudios by remember { mutableStateOf<List<File>>(emptyList()) }
        var selectedAudioFile by remember { mutableStateOf<File?>(null) }
        var isAudioPickerExpanded by remember { mutableStateOf(false) }
        var audioSearchQuery by remember { mutableStateOf("") }
        var mediaPlayer by remember { mutableStateOf<MediaPlayer?>(null) }

        // Refresh audio function
        val refreshAudios = remember(context) {
            {
                val dir = File(context.filesDir, "audios")
                if (!dir.exists()) dir.mkdirs()
                importedAudios = dir.listFiles()?.filter { 
                    it.isFile && (it.extension.lowercase() in listOf("mp3", "m4a", "wav", "ogg", "aac")) 
                }?.sortedBy { it.name } ?: emptyList()
            }
        }

        LaunchedEffect(Unit) {
            refreshAudios()
        }

        LaunchedEffect(importedAudios) {
            if (selectedAudioFile == null) {
                val lastSelected = AudioSoundscapeManager.getLastSelectedAudio(context)
                if (lastSelected.isNotEmpty()) {
                    val matched = importedAudios.find { it.name == lastSelected }
                    if (matched != null) {
                        selectedAudioFile = matched
                    }
                }
            }
        }

        // File picker for audio import
        val audioPickerLauncher = rememberLauncherForActivityResult(
            contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
        ) { uri ->
            if (uri != null) {
                try {
                    val contentResolver = context.contentResolver
                    var fileName = "imported_audio_${System.currentTimeMillis()}.mp3"
                    contentResolver.query(uri, null, null, null, null)?.use { cursor ->
                        val nameIndex = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
                        if (nameIndex != -1 && cursor.moveToFirst()) {
                            val dispName = cursor.getString(nameIndex)
                            if (!dispName.isNullOrEmpty()) {
                                fileName = dispName
                            }
                        }
                    }
                    val destDir = File(context.filesDir, "audios")
                    if (!destDir.exists()) destDir.mkdirs()
                    val destFile = File(destDir, fileName)
                    contentResolver.openInputStream(uri)?.use { inputStream ->
                        destFile.outputStream().use { outputStream ->
                            inputStream.copyTo(outputStream)
                        }
                    }
                    refreshAudios()
                    selectedAudioFile = destFile
                    AudioSoundscapeManager.setLastSelectedAudio(context, destFile.name)
                } catch (e: Exception) {
                    e.printStackTrace()
                    android.widget.Toast.makeText(context, "Import failed", android.widget.Toast.LENGTH_SHORT).show()
                }
            }
        }

        // Set duration initially and when duration text changes
        LaunchedEffect(timerDurationMinutes) {
            val mins = timerDurationMinutes.toFloatOrNull() ?: 25f
            if (!isTimerRunning) {
                timerSecondsRemaining = (mins * 60).toInt()
                initialTimerSeconds = (mins * 60).toInt()
            }
        }

        // Ticker loop
        LaunchedEffect(isTimerRunning, timerSecondsRemaining) {
            if (isTimerRunning && timerSecondsRemaining > 0) {
                delay(1000L)
                timerSecondsRemaining--

                if (timerSecondsRemaining == 0) {
                    isTimerRunning = false
                    try {
                        val toneUri = android.media.RingtoneManager.getDefaultUri(android.media.RingtoneManager.TYPE_NOTIFICATION)
                        val ringtone = android.media.RingtoneManager.getRingtone(context, toneUri)
                        ringtone.play()
                    } catch (e: Exception) {
                        e.printStackTrace()
                    }

                    val totalSecondsElapsed = initialTimerSeconds - timerSecondsRemaining
                    val minutesToLog = Math.round(totalSecondsElapsed / 60f).toInt().coerceAtLeast(1)

                    viewModel.logNumericalHabit(habitToLog!!.id, selectedDate, currentValue + minutesToLog)

                    android.widget.Toast.makeText(
                        context,
                        if (language == "de") "Timer beendet! $minutesToLog Min. wurden eingetragen." else if (language == "ka") "ტაიმერი დასრულდა! $minutesToLog წთ შესულია." else "Timer finished! $minutesToLog min logged.",
                        android.widget.Toast.LENGTH_LONG
                    ).show()

                    onDismiss()
                }
            }
        }

        // Media player control
        LaunchedEffect(isTimerRunning, selectedAudioFile) {
            if (isTimerRunning && selectedAudioFile != null) {
                try {
                    mediaPlayer?.stop()
                    mediaPlayer?.release()

                    val mp = MediaPlayer().apply {
                        setDataSource(selectedAudioFile!!.absolutePath)
                        isLooping = true
                        prepare()
                        start()
                    }
                    mediaPlayer = mp
                } catch (e: Exception) {
                    e.printStackTrace()
                }
            } else {
                try {
                    mediaPlayer?.pause()
                } catch (e: Exception) {
                    e.printStackTrace()
                }
            }
        }

        DisposableEffect(Unit) {
            onDispose {
                try {
                    mediaPlayer?.stop()
                    mediaPlayer?.release()
                } catch (e: Exception) {
                    // ignored
                }
            }
        }

        val focusManager = LocalFocusManager.current
        val keyboardController = LocalSoftwareKeyboardController.current

        AlertDialog(
            onDismissRequest = onDismiss,
            containerColor = AppCard,
            title = {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = if (language == "de") "Eintrag: ${habitToLog!!.name}" else if (language == "ka") "ჟურნალი: ${habitToLog!!.name}" else "Log: ${habitToLog!!.name}",
                        color = TextPrimary,
                        style = MaterialTheme.typography.titleLarge
                    )
                    IconButton(
                        onClick = onDismiss,
                        modifier = Modifier.size(28.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Close,
                            contentDescription = "Close",
                            tint = TextSecondary,
                            modifier = Modifier.size(20.dp)
                        )
                    }
                }
            },
            text = {
                ClearFocusOnKeyboardDismiss()
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .pointerInput(Unit) {
                            detectTapGestures {
                                focusManager.clearFocus(force = true)
                                keyboardController?.hide()
                            }
                        },
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    if (hasTimer) {
                        // TIMER SECTION
                        val timeText = remember(timerSecondsRemaining) {
                            val displayMinutes = timerSecondsRemaining / 60
                            val displaySeconds = timerSecondsRemaining % 60
                            String.format(Locale.US, "%02d:%02d", displayMinutes, displaySeconds)
                        }
                        val progressFraction = if (initialTimerSeconds > 0) {
                            timerSecondsRemaining.toFloat() / initialTimerSeconds.toFloat()
                        } else {
                            1f
                        }



                        // REDESIGNED AUDIO FOCUS TIMER SECTION
                        val infiniteTransition = rememberInfiniteTransition(label = "timer_pulse")
                        val timerPulseAlpha by infiniteTransition.animateFloat(
                            initialValue = 0.3f,
                            targetValue = 0.85f,
                            animationSpec = infiniteRepeatable(
                                animation = tween(1200, easing = FastOutSlowInEasing),
                                repeatMode = RepeatMode.Reverse
                            ),
                            label = "timer_pulse_alpha"
                        )
                        val waveScale1 by infiniteTransition.animateFloat(
                            initialValue = 0.3f,
                            targetValue = 1.0f,
                            animationSpec = infiniteRepeatable(tween(400, easing = FastOutSlowInEasing), RepeatMode.Reverse),
                            label = "wave1"
                        )
                        val waveScale2 by infiniteTransition.animateFloat(
                            initialValue = 0.8f,
                            targetValue = 0.2f,
                            animationSpec = infiniteRepeatable(tween(500, easing = FastOutSlowInEasing), RepeatMode.Reverse),
                            label = "wave2"
                        )
                        val waveScale3 by infiniteTransition.animateFloat(
                            initialValue = 0.4f,
                            targetValue = 0.9f,
                            animationSpec = infiniteRepeatable(tween(450, easing = FastOutSlowInEasing), RepeatMode.Reverse),
                            label = "wave3"
                        )

                        Column(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            // Circular Clock View with Glowing Ring & Minute Ticks
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 4.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Box(
                                    modifier = Modifier.size(190.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    // Ambient Outer Pulse Glow when running
                                    if (isTimerRunning) {
                                        Box(
                                            modifier = Modifier
                                                .size(185.dp)
                                                .clip(CircleShape)
                                                .background(
                                                    Brush.radialGradient(
                                                        colors = listOf(
                                                            PrimaryViolet.copy(alpha = 0.35f * timerPulseAlpha),
                                                            PrimaryViolet.copy(alpha = 0.15f * timerPulseAlpha),
                                                            Color.Transparent
                                                        )
                                                    )
                                                )
                                        )
                                    }

                                    // Canvas Draw Ring & Ticks
                                    Box(
                                        contentAlignment = Alignment.Center,
                                        modifier = Modifier
                                            .size(160.dp)
                                            .drawWithCache {
                                                val strokeWidth = 8.dp.toPx()
                                                val activeColor = PrimaryViolet
                                                val inactiveColor = ProgressTrack
                                                val sweepAngle = 360f * progressFraction

                                                onDrawBehind {
                                                    val radius = size.minDimension / 2f - strokeWidth
                                                    val centerPoint = Offset(size.width / 2f, size.height / 2f)

                                                    // Track circle
                                                    drawCircle(
                                                        color = inactiveColor,
                                                        radius = radius,
                                                        style = Stroke(width = strokeWidth)
                                                    )

                                                    // Active progress arc with gradient
                                                    drawArc(
                                                        brush = Brush.sweepGradient(
                                                            colors = listOf(PrimaryViolet, PrimaryViolet)
                                                        ),
                                                        startAngle = -90f,
                                                        sweepAngle = sweepAngle,
                                                        useCenter = false,
                                                        style = Stroke(width = strokeWidth, cap = StrokeCap.Round)
                                                    )

                                                    // Draw 60 Radial Tick Marks
                                                    for (i in 0 until 60) {
                                                        val angleRad = Math.toRadians((i * 6 - 90).toDouble())
                                                        val isMajor = i % 5 == 0
                                                        val tickLength = if (isMajor) 8.dp.toPx() else 4.dp.toPx()
                                                        val innerR = radius - strokeWidth / 2f - 4.dp.toPx()
                                                        val outerR = innerR - tickLength

                                                        val startX = centerPoint.x + innerR * Math.cos(angleRad).toFloat()
                                                        val startY = centerPoint.y + innerR * Math.sin(angleRad).toFloat()
                                                        val endX = centerPoint.x + outerR * Math.cos(angleRad).toFloat()
                                                        val endY = centerPoint.y + outerR * Math.sin(angleRad).toFloat()

                                                        val tickProgress = (i * 6).toFloat()
                                                        val isPassed = tickProgress <= sweepAngle
                                                        drawLine(
                                                            color = if (isPassed) activeColor.copy(alpha = 0.8f) else AppBorder.copy(alpha = 0.5f),
                                                            start = Offset(startX, startY),
                                                            end = Offset(endX, endY),
                                                            strokeWidth = if (isMajor) 2.dp.toPx() else 1.dp.toPx()
                                                        )
                                                    }

                                                    // Endpoint Dot Indicator
                                                    if (progressFraction > 0.01f) {
                                                        val endAngleRad = Math.toRadians((sweepAngle - 90).toDouble())
                                                        val dotX = centerPoint.x + radius * Math.cos(endAngleRad).toFloat()
                                                        val dotY = centerPoint.y + radius * Math.sin(endAngleRad).toFloat()
                                                        drawCircle(
                                                            color = Color.White,
                                                            radius = strokeWidth / 1.4f,
                                                            center = Offset(dotX, dotY)
                                                        )
                                                        drawCircle(
                                                            color = PrimaryViolet,
                                                            radius = strokeWidth / 2.2f,
                                                            center = Offset(dotX, dotY)
                                                        )
                                                    }
                                                }
                                            }
                                    ) {
                                        Column(
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            verticalArrangement = Arrangement.Center,
                                            modifier = Modifier.padding(8.dp)
                                        ) {
                                            if (isEditingTimerDuration) {
                                                val focusRequester = remember { FocusRequester() }
                                                
                                                BasicTextField(
                                                    value = tempTimerInput,
                                                    onValueChange = { input ->
                                                        if (input.all { it.isDigit() } && input.length <= 4) {
                                                            tempTimerInput = input
                                                        }
                                                    },
                                                    keyboardOptions = KeyboardOptions(
                                                        keyboardType = KeyboardType.Number,
                                                        imeAction = ImeAction.Done
                                                    ),
                                                    keyboardActions = KeyboardActions(
                                                        onDone = {
                                                            val parsed = tempTimerInput.toIntOrNull() ?: timerDurationMinutes.toIntOrNull() ?: 25
                                                            timerDurationMinutes = parsed.toString()
                                                            isEditingTimerDuration = false
                                                        }
                                                    ),
                                                    textStyle = MaterialTheme.typography.titleLarge.copy(
                                                        color = TextPrimary,
                                                        textAlign = TextAlign.Center,
                                                        fontWeight = FontWeight.Bold,
                                                        fontSize = 26.sp
                                                    ),
                                                    cursorBrush = SolidColor(TextPrimary),
                                                    modifier = Modifier
                                                        .width(90.dp)
                                                        .focusRequester(focusRequester),
                                                    decorationBox = { innerTextField ->
                                                        Box(
                                                            contentAlignment = Alignment.Center,
                                                            modifier = Modifier.fillMaxWidth()
                                                        ) {
                                                            if (tempTimerInput.isEmpty()) {
                                                                Text(
                                                                    text = timerDurationMinutes,
                                                                    color = TextSecondary.copy(alpha = 0.5f),
                                                                    style = MaterialTheme.typography.titleLarge,
                                                                    fontWeight = FontWeight.Bold,
                                                                    fontSize = 26.sp,
                                                                    textAlign = TextAlign.Center
                                                                )
                                                            }
                                                            innerTextField()
                                                        }
                                                    }
                                                )
                                                
                                                LaunchedEffect(Unit) {
                                                    focusRequester.requestFocus()
                                                }
                                            } else {
                                                Text(
                                                    text = timeText,
                                                    style = MaterialTheme.typography.titleLarge,
                                                    color = TextPrimary,
                                                    fontWeight = FontWeight.ExtraBold,
                                                    fontSize = 32.sp,
                                                    letterSpacing = 1.sp,
                                                    modifier = Modifier.clickable(enabled = !isTimerRunning) {
                                                        tempTimerInput = ""
                                                        isEditingTimerDuration = true
                                                    }
                                                )
                                            }
                                        }
                                    }
                                }
                            }

                            // Control Pill Dock (Reset, Play/Pause, Finish/Log)
                            Surface(
                                color = AppCard,
                                shape = RoundedCornerShape(24.dp),
                                border = BorderStroke(1.dp, AppBorder),
                                modifier = Modifier.padding(horizontal = 12.dp)
                            ) {
                                Row(
                                    horizontalArrangement = Arrangement.spacedBy(20.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    modifier = Modifier.padding(horizontal = 18.dp, vertical = 8.dp)
                                ) {
                                    // Reset Button
                                    IconButton(
                                        onClick = {
                                            isTimerRunning = false
                                            val mins = timerDurationMinutes.toIntOrNull() ?: 25
                                            timerSecondsRemaining = mins * 60
                                            initialTimerSeconds = mins * 60
                                        },
                                        modifier = Modifier
                                            .size(40.dp)
                                            .background(ProgressTrack, CircleShape)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Refresh,
                                            contentDescription = "Reset",
                                            tint = TextPrimary,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }

                                    // Main Play/Pause Button
                                    Box(
                                        modifier = Modifier
                                            .size(52.dp)
                                            .clip(CircleShape)
                                            .background(
                                                Brush.linearGradient(
                                                    colors = if (isTimerRunning) {
                                                        listOf(Color(0xFFEF4444), Color(0xFFDC2626))
                                                    } else {
                                                        listOf(PrimaryViolet, PrimaryViolet.copy(alpha = 0.85f))
                                                    }
                                                )
                                            )
                                            .clickable {
                                                if (timerSecondsRemaining <= 0) {
                                                    val mins = timerDurationMinutes.toIntOrNull() ?: 25
                                                    timerSecondsRemaining = mins * 60
                                                    initialTimerSeconds = mins * 60
                                                }
                                                isTimerRunning = !isTimerRunning
                                            },
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = if (isTimerRunning) Icons.Default.Pause else Icons.Default.PlayArrow,
                                            contentDescription = if (isTimerRunning) "Pause" else "Play",
                                            tint = Color.White,
                                            modifier = Modifier.size(28.dp)
                                        )
                                    }

                                    val totalSecondsElapsed = initialTimerSeconds - timerSecondsRemaining
                                    val canLogElapsed = totalSecondsElapsed >= 1

                                    // Finish & Log Elapsed Button
                                    IconButton(
                                        onClick = {
                                            isTimerRunning = false
                                            val minutesToLog = Math.round(totalSecondsElapsed / 60f).toInt().coerceAtLeast(0)
                                            if (minutesToLog > 0) {
                                                viewModel.logNumericalHabit(habitToLog!!.id, selectedDate, currentValue + minutesToLog)
                                                android.widget.Toast.makeText(
                                                    context,
                                                    if (language == "de") "$minutesToLog Min. wurden eingetragen!" else if (language == "ka") "$minutesToLog წუთი შესულია!" else "$minutesToLog min logged!",
                                                    android.widget.Toast.LENGTH_SHORT
                                                ).show()
                                            } else {
                                                viewModel.logNumericalHabit(habitToLog!!.id, selectedDate, -1f)
                                                android.widget.Toast.makeText(
                                                    context,
                                                    if (language == "de") "Unter 30 Sek. vergangen. Als fehlgeschlagen markiert." else if (language == "ka") "30 წლამდე გავიდა. მონიშნულია წარუმატებლად." else "Under 30s elapsed. Marked as failed.",
                                                    android.widget.Toast.LENGTH_SHORT
                                                ).show()
                                            }
                                            onDismiss()
                                        },
                                        modifier = Modifier
                                            .size(40.dp)
                                            .background(
                                                if (canLogElapsed) SuccessGreen.copy(alpha = 0.25f) else ProgressTrack,
                                                CircleShape
                                            ),
                                        enabled = canLogElapsed
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Check,
                                            contentDescription = "Finish",
                                            tint = if (canLogElapsed) SuccessGreen else TextSecondary.copy(alpha = 0.4f),
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }
                                }
                            }

                            // Background Audio Selection (3 Recent Buttons + Expandable Search Function)
                            Column(
                                modifier = Modifier.fillMaxWidth(),
                                verticalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Text(
                                    text = if (language == "de") "Hintergrund-Audio" else if (language == "ka") "ფონის აუდიო" else "Background Audio",
                                    style = MaterialTheme.typography.bodyMedium,
                                    color = TextSecondary,
                                    fontWeight = FontWeight.SemiBold
                                )

                                // 1. TOP ROW: 3 RECENT SOUNDS BUTTONS WITH LABEL
                                val recentFileNames = remember(importedAudios, selectedAudioFile) {
                                    AudioSoundscapeManager.getRecentAudios(context)
                                }
                                val recentFiles = remember(recentFileNames, importedAudios) {
                                    val found = recentFileNames.mapNotNull { name -> importedAudios.find { it.name == name } }
                                    if (found.isNotEmpty()) found.take(3)
                                    else importedAudios.take(3)
                                }

                                // 2. SEARCH BAR, CLEAR & UPLOAD BUTTONS
                                val isActive = selectedAudioFile != null
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp),
                                    colors = CardDefaults.cardColors(
                                        containerColor = if (isActive) PrimaryViolet.copy(alpha = 0.1f) else AppCard
                                    ),
                                    border = BorderStroke(
                                        1.dp,
                                        if (isActive) PrimaryViolet.copy(alpha = 0.4f) else AppBorder
                                    )
                                ) {
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(horizontal = 12.dp, vertical = 10.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.SpaceBetween
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            modifier = Modifier.weight(1f)
                                        ) {
                                            Icon(
                                                imageVector = if (isActive) Icons.Default.VolumeUp else Icons.Default.VolumeOff,
                                                contentDescription = null,
                                                tint = if (isActive) PrimaryViolet else TextSecondary,
                                                modifier = Modifier.size(18.dp)
                                            )
                                            Spacer(modifier = Modifier.width(10.dp))
                                            Column {
                                                Text(
                                                    text = if (isActive) selectedAudioFile!!.nameWithoutExtension else (if (language == "de") "Kein Sound (Stumm)" else if (language == "ka") "ხმა არ არის (დადუმებული)" else "No Sound (Muted)"),
                                                    style = MaterialTheme.typography.bodyMedium,
                                                    color = TextPrimary,
                                                    fontWeight = FontWeight.Bold,
                                                    maxLines = 1,
                                                    overflow = TextOverflow.Ellipsis
                                                )
                                                Text(
                                                    text = if (isActive) (if (language == "de") "Aktiver Timer-Sound" else if (language == "ka") "აქტიური ტაიმერის ხმა" else "Active Timer Sound") else (if (language == "de") "Stummgeschaltet" else if (language == "ka") "დადუმდა" else "Muted"),
                                                    style = MaterialTheme.typography.labelSmall,
                                                    color = TextSecondary
                                                )
                                            }
                                        }

                                        if (isActive) {
                                            IconButton(
                                                onClick = {
                                                    selectedAudioFile = null
                                                    AudioSoundscapeManager.setLastSelectedAudio(context, "")
                                                    if (isTimerRunning) {
                                                        try {
                                                            mediaPlayer?.stop()
                                                            mediaPlayer?.release()
                                                            mediaPlayer = null
                                                        } catch (e: Exception) { e.printStackTrace() }
                                                    }
                                                },
                                                modifier = Modifier.size(32.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Close,
                                                    contentDescription = if (language == "de") "Sound stummschalten" else if (language == "ka") "ხმის დადუმება" else "Mute sound",
                                                    tint = Color(0xFFEF4444),
                                                    modifier = Modifier.size(18.dp)
                                                )
                                            }
                                        }
                                    }
                                }

                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    BasicTextField(
                                        value = audioSearchQuery,
                                        onValueChange = { 
                                            audioSearchQuery = it
                                            isAudioPickerExpanded = true
                                        },
                                        textStyle = TextStyle(color = TextPrimary, fontSize = 14.sp),
                                        singleLine = true,
                                        cursorBrush = SolidColor(PrimaryViolet),
                                        keyboardOptions = KeyboardOptions(imeAction = ImeAction.Search),
                                        keyboardActions = KeyboardActions(onSearch = { focusManager.clearFocus(force = true); keyboardController?.hide() }),
                                        modifier = Modifier
                                            .weight(1f)
                                            .onFocusChanged { 
                                                if (it.isFocused) {
                                                    isAudioPickerExpanded = true
                                                }
                                            },
                                        decorationBox = { innerTextField ->
                                            Row(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .background(AppCard, RoundedCornerShape(14.dp))
                                                    .border(1.dp, AppBorder, RoundedCornerShape(14.dp))
                                                    .padding(horizontal = 14.dp, vertical = 12.dp),
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Icon(Icons.Default.Search, contentDescription = null, tint = TextSecondary, modifier = Modifier.size(18.dp))
                                                Spacer(modifier = Modifier.width(8.dp))
                                                Box(modifier = Modifier.weight(1f), contentAlignment = Alignment.CenterStart) {
                                                    if (audioSearchQuery.isEmpty()) {
                                                        Text(
                                                            if (language == "de") "Sound suchen..." else if (language == "ka") "ხმის ძებნა..." else "Search sound...",
                                                            color = TextSecondary,
                                                            fontSize = 14.sp
                                                        )
                                                    }
                                                    innerTextField()
                                                }
                                                if (audioSearchQuery.isNotEmpty()) {
                                                    IconButton(onClick = { audioSearchQuery = "" }, modifier = Modifier.size(22.dp)) {
                                                        Icon(Icons.Default.Close, contentDescription = "Clear", tint = TextSecondary, modifier = Modifier.size(16.dp))
                                                    }
                                                }
                                                IconButton(onClick = { isAudioPickerExpanded = !isAudioPickerExpanded }, modifier = Modifier.size(22.dp)) {
                                                    Icon(
                                                        imageVector = if (isAudioPickerExpanded) Icons.Default.KeyboardArrowUp else Icons.Default.KeyboardArrowDown,
                                                        contentDescription = "Toggle List",
                                                        tint = TextSecondary,
                                                        modifier = Modifier.size(18.dp)
                                                    )
                                                }
                                            }
                                        }
                                    )

                                    IconButton(
                                        onClick = { audioPickerLauncher.launch("audio/*") },
                                        modifier = Modifier
                                            .size(44.dp)
                                            .background(PrimaryViolet, RoundedCornerShape(14.dp))
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Add,
                                            contentDescription = if (language == "de") "Sound hochladen" else if (language == "ka") "ატვირთეთ ხმა" else "Upload sound",
                                            tint = TextPrimary,
                                            modifier = Modifier.size(22.dp)
                                        )
                                    }
                                }

                                // 3. EXPANDABLE SEARCH RESULTS LIST
                                val showList = isAudioPickerExpanded || audioSearchQuery.isNotBlank()
                                AnimatedVisibility(visible = showList) {
                                    val filteredList = remember(importedAudios, audioSearchQuery) {
                                        importedAudios.filter { audioSearchQuery.isBlank() || it.name.contains(audioSearchQuery, ignoreCase = true) }
                                    }
                                    val dropdownRecentFiles = remember(recentFiles, audioSearchQuery) {
                                        if (audioSearchQuery.isBlank()) recentFiles else emptyList()
                                    }
                                    val dropdownOtherFiles = remember(filteredList, dropdownRecentFiles) {
                                        filteredList.filter { it !in dropdownRecentFiles }
                                    }

                                    Column(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .background(ProgressTrack, RoundedCornerShape(12.dp))
                                            .border(1.dp, AppBorder, RoundedCornerShape(12.dp))
                                            .padding(6.dp),
                                        verticalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        if (importedAudios.isEmpty()) {
                                            Column(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .padding(12.dp),
                                                horizontalAlignment = Alignment.CenterHorizontally,
                                                verticalArrangement = Arrangement.spacedBy(8.dp)
                                            ) {
                                                Text(
                                                    text = if (language == "de") "Noch keine eigenen Sounds hinzugefügt." else if (language == "ka") "მორგებული ხმები ჯერ არ არის დამატებული." else "No custom sounds added yet.",
                                                    color = TextPrimary,
                                                    fontWeight = FontWeight.SemiBold,
                                                    fontSize = 13.sp,
                                                    textAlign = TextAlign.Center
                                                )
                                                Text(
                                                    text = if (language == "de") "Du kannst eigene MP3, WAV oder M4A Dateien hochladen oder in den Einstellungen verwalten." else if (language == "ka") "შეგიძლიათ ატვირთოთ MP3, WAV ან M4A ფაილები ან მართოთ ისინი პარამეტრებში." else "You can upload MP3, WAV or M4A files or manage them in Settings.",
                                                    color = TextSecondary,
                                                    fontSize = 11.sp,
                                                    textAlign = TextAlign.Center
                                                )
                                            }
                                        } else if (filteredList.isEmpty()) {
                                            Text(
                                                text = if (language == "de") "Kein passender Sound gefunden" else if (language == "ka") "შესატყვისი ხმები ვერ მოიძებნა" else "No matching sounds found",
                                                color = TextSecondary,
                                                fontSize = 12.sp,
                                                modifier = Modifier.padding(8.dp)
                                            )
                                        } else {
                                            LazyColumn(
                                                verticalArrangement = Arrangement.spacedBy(4.dp),
                                                modifier = Modifier.heightIn(max = 160.dp)
                                            ) {
                                                items(filteredList) { file ->
                                                    val isSel = selectedAudioFile?.absolutePath == file.absolutePath
                                                    Surface(
                                                        onClick = {
                                                            selectedAudioFile = file
                                                            AudioSoundscapeManager.setLastSelectedAudio(context, file.name)
                                                            if (isTimerRunning) {
                                                                try {
                                                                    mediaPlayer?.stop()
                                                                    mediaPlayer?.release()
                                                                    mediaPlayer = MediaPlayer().apply {
                                                                        setDataSource(file.absolutePath)
                                                                        isLooping = true
                                                                        prepare()
                                                                        start()
                                                                    }
                                                                } catch (e: Exception) { e.printStackTrace() }
                                                            }
                                                            isAudioPickerExpanded = false
                                                        },
                                                        shape = RoundedCornerShape(6.dp),
                                                        color = if (isSel) PrimaryViolet.copy(alpha = 0.2f) else AppCard,
                                                        border = BorderStroke(0.5.dp, if (isSel) PrimaryViolet else AppBorder),
                                                        modifier = Modifier.fillMaxWidth()
                                                    ) {
                                                        Row(
                                                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 6.dp),
                                                            verticalAlignment = Alignment.CenterVertically,
                                                            horizontalArrangement = Arrangement.SpaceBetween
                                                        ) {
                                                            Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.weight(1f)) {
                                                                Icon(Icons.Default.MusicNote, contentDescription = null, tint = PrimaryViolet, modifier = Modifier.size(16.dp))
                                                                Spacer(modifier = Modifier.width(6.dp))
                                                                Text(
                                                                    text = file.nameWithoutExtension,
                                                                    style = MaterialTheme.typography.bodySmall,
                                                                    color = TextPrimary,
                                                                    fontSize = 12.sp,
                                                                    fontWeight = if (isSel) FontWeight.Bold else FontWeight.Normal,
                                                                    maxLines = 1,
                                                                    overflow = TextOverflow.Ellipsis
                                                                )
                                                            }
                                                            RadioButton(
                                                                selected = isSel,
                                                                onClick = {
                                                                    selectedAudioFile = file
                                                                    AudioSoundscapeManager.setLastSelectedAudio(context, file.name)
                                                                    if (isTimerRunning) {
                                                                        try {
                                                                            mediaPlayer?.stop()
                                                                            mediaPlayer?.release()
                                                                            mediaPlayer = MediaPlayer().apply {
                                                                                setDataSource(file.absolutePath)
                                                                                isLooping = true
                                                                                prepare()
                                                                                start()
                                                                            }
                                                                        } catch (e: Exception) { e.printStackTrace() }
                                                                    }
                                                                    isAudioPickerExpanded = false
                                                                },
                                                                colors = RadioButtonDefaults.colors(selectedColor = PrimaryViolet),
                                                                modifier = Modifier.size(18.dp)
                                                            )
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            
                            Spacer(modifier = Modifier.height(4.dp))
                        }
                    }

                    // COMPACT MANUAL INPUT & SUGGESTIONS SECTION
                    val suggestions = remember(habitToLog) {
                        val target = habitToLog?.targetValue ?: 0f
                        when {
                            habitToLog?.unit?.lowercase() in listOf("l", "liter", "liters") -> listOf(0.5f, 1.0f, 1.5f, 2.0f)
                            habitToLog?.unit?.lowercase() in listOf("ml") -> listOf(250f, 500f, 750f, 1000f)
                            habitToLog?.unit?.lowercase() in listOf("min", "minutes", "minuten") -> listOf(1f, 15f, 30f, 60f)
                            habitToLog?.unit?.lowercase() in listOf("h", "stunden", "hours") -> listOf(1f, 2f, 3f, 4f)
                            else -> {
                                if (target > 1f) {
                                    val half = target / 2f
                                    val halfSuggested = if (half % 1f == 0f) half else (Math.round(half * 10f) / 10f).toFloat()
                                    listOfNotNull(
                                        1f,
                                        if (halfSuggested > 1f && halfSuggested != target) halfSuggested else null,
                                        target
                                    ).distinct()
                                } else {
                                    listOf(1f, 2f, 5f)
                                }
                            }
                        }.distinct().filter { it > 0f }.take(4).sorted()
                    }

                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        Text(
                            text = if (language == "de") "Manuell eintragen (${habitToLog!!.unit}):" else if (language == "ka") "სახელმძღვანელო ჟურნალი ( ${habitToLog!!.unit} ):" else "Manual log (${habitToLog!!.unit}):",
                            color = TextSecondary,
                            style = MaterialTheme.typography.labelMedium,
                            fontWeight = FontWeight.SemiBold
                        )

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            BasicTextField(
                                value = inputVal,
                                onValueChange = { inputVal = it },
                                textStyle = TextStyle(color = TextPrimary, fontSize = 13.sp, fontWeight = FontWeight.Bold),
                                singleLine = true,
                                cursorBrush = SolidColor(PrimaryViolet),
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number, imeAction = ImeAction.Done),
                                keyboardActions = KeyboardActions(onDone = { focusManager.clearFocus(); keyboardController?.hide() }),
                                modifier = Modifier
                                    .width(72.dp)
                                    .testTag("manual_value_input"),
                                decorationBox = { innerTextField ->
                                    Box(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .background(PrimaryViolet.copy(alpha = 0.18f), RoundedCornerShape(8.dp))
                                            .border(1.5.dp, PrimaryViolet, RoundedCornerShape(8.dp))
                                            .padding(horizontal = 8.dp, vertical = 7.dp),
                                        contentAlignment = Alignment.CenterStart
                                    ) {
                                        if (inputVal.isEmpty()) {
                                            Text("0.0", color = TextSecondary.copy(alpha = 0.7f), fontSize = 13.sp)
                                        }
                                        innerTextField()
                                    }
                                }
                            )

                            Row(
                                modifier = Modifier.weight(1f),
                                horizontalArrangement = Arrangement.spacedBy(4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                suggestions.forEach { value ->
                                    val label = if (value % 1f == 0f) value.toInt().toString() else value.toString()
                                    val isSelected = inputVal == label
                                    Box(
                                        modifier = Modifier
                                            .weight(1f)
                                            .background(
                                                if (isSelected) PrimaryViolet else AppCard,
                                                RoundedCornerShape(8.dp)
                                            )
                                            .border(
                                                1.dp,
                                                if (isSelected) PrimaryViolet else AppBorder,
                                                RoundedCornerShape(8.dp)
                                            )
                                            .clickable {
                                                inputVal = label
                                            }
                                            .padding(vertical = 7.dp),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(
                                            text = label,
                                            color = if (isSelected) TextPrimary else TextSecondary,
                                            style = MaterialTheme.typography.bodySmall,
                                            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                                            fontSize = 12.sp,
                                            maxLines = 1
                                        )
                                    }
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(10.dp))

                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            OutlinedButton(
                                onClick = {
                                    viewModel.logNumericalHabit(habitToLog!!.id, selectedDate, 0f)
                                    onDismiss()
                                },
                                colors = ButtonDefaults.outlinedButtonColors(contentColor = HabitOrange),
                                border = androidx.compose.foundation.BorderStroke(1.dp, HabitOrange.copy(alpha = 0.5f)),
                                shape = RoundedCornerShape(12.dp),
                                modifier = Modifier
                                    .weight(1f)
                                    .height(42.dp)
                                    .testTag("dialog_reset_button")
                            ) {
                                Text(
                                    text = if (language == "de") "Reset" else if (language == "ka") "გადატვირთვა" else "Reset",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 13.sp,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis
                                )
                            }

                            OutlinedButton(
                                onClick = {
                                    viewModel.logNumericalHabit(habitToLog!!.id, selectedDate, -1f)
                                    onDismiss()
                                },
                                colors = ButtonDefaults.outlinedButtonColors(contentColor = FailedRed),
                                border = androidx.compose.foundation.BorderStroke(1.dp, FailedRed.copy(alpha = 0.5f)),
                                shape = RoundedCornerShape(12.dp),
                                modifier = Modifier
                                    .weight(1f)
                                    .height(42.dp)
                                    .testTag("dialog_fail_button")
                            ) {
                                Text(
                                    text = if (language == "de") "Fehlgeschlagen" else if (language == "ka") "ვერ მოხერხდა" else "Failed",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 13.sp,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis
                                )
                            }
                        }

                        Button(
                            colors = ButtonDefaults.buttonColors(containerColor = PrimaryViolet),
                            onClick = {
                                val fValue = inputVal.toFloatOrNull() ?: 0f
                                if (fValue <= 0f) {
                                    viewModel.logNumericalHabit(habitToLog!!.id, selectedDate, -1f)
                                } else {
                                    viewModel.logNumericalHabit(habitToLog!!.id, selectedDate, fValue)
                                }
                                onDismiss()
                            },
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(44.dp)
                                .testTag("dialog_save_button")
                        ) {
                            Text(
                                text = if (language == "de") "Speichern" else if (language == "ka") "შენახვა" else "Save",
                                color = TextPrimary,
                                fontWeight = FontWeight.Bold,
                                fontSize = 14.sp,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                        }
                    }
                }
            },
            confirmButton = {},
            dismissButton = null
        )
    } else {
        LaunchedEffect(Unit) {
            onDismiss()
        }
    }
}

// BOTTOM NAVIGATION
@Composable
fun HabitBottomNavigation(
    selectedTab: String,
    onTabSelected: (String) -> Unit,
    onAddClick: () -> Unit,
    language: String
) {
    val items = listOf(
        Triple("TODAY", if (language == "ka") "დღეს" else tr(language, "Heute", "Today"), Icons.Default.CalendarToday),
        Triple("STATS", if (language == "ka") "სტატ." else tr(language, "Statistik", "Stats"), Icons.Default.BarChart),
        Triple("PROFILE", if (language == "ka") "პროფ." else tr(language, "Profil", "Profile"), Icons.Default.Person)
    )

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .padding(start = 18.dp, end = 18.dp, bottom = 32.dp, top = 10.dp),
        contentAlignment = Alignment.Center
    ) {
        Surface(
            color = AppCard,
            shape = CircleShape,
            border = BorderStroke(1.dp, AppBorder),
            shadowElevation = 8.dp,
            tonalElevation = 0.dp
        ) {
            Row(
                modifier = Modifier
                    .padding(horizontal = if (language == "ka") 6.dp else 10.dp, vertical = 8.dp),
                horizontalArrangement = Arrangement.spacedBy(if (language == "ka") 4.dp else 6.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                items.forEach { (tabKey, label, icon) ->
                    val isSelected = selectedTab == tabKey
                    val navBgColor by animateColorAsState(
                        targetValue = if (isSelected) PrimaryViolet else Color.Transparent,
                        animationSpec = tween(220),
                        label = "navBg"
                    )
                    val navContentColor by animateColorAsState(
                        targetValue = if (isSelected) TextPrimary else TextSecondary,
                        animationSpec = tween(220),
                        label = "navContent"
                    )

                    val showLabel = isSelected || language != "ka"

                    Row(
                        modifier = Modifier
                            .testTag("nav_${tabKey.lowercase()}")
                            .clip(CircleShape)
                            .background(navBgColor)
                            .clickable { onTabSelected(tabKey) }
                            .padding(
                                horizontal = if (showLabel) (if (language == "ka") 10.dp else 12.dp) else 8.dp,
                                vertical = 10.dp
                            ),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(if (showLabel) (if (language == "ka") 4.dp else 6.dp) else 0.dp)
                    ) {
                        Icon(
                            imageVector = icon,
                            contentDescription = label,
                            tint = navContentColor,
                            modifier = Modifier.size(20.dp)
                        )
                        if (showLabel) {
                            Text(
                                text = label,
                                color = navContentColor,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                                style = MaterialTheme.typography.labelLarge.copy(
                                    fontWeight = FontWeight.Bold,
                                    fontSize = if (language == "ka") 11.sp else 13.sp
                                )
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun CalendarDayItem(
    dayStr: String,
    dayNum: String,
    dayName: String,
    isSelected: Boolean,
    onSelect: (String) -> Unit,
    isToday: Boolean,
    isFuture: Boolean,
    modifier: Modifier = Modifier,
    isEnabled: Boolean = true
) {
    val dayScale by animateFloatAsState(
        targetValue = if (isSelected) 1.05f else 1f,
        animationSpec = tween(120),
        label = "dayScale"
    )

    val weekdayColor = when {
        !isEnabled -> TextSecondary.copy(alpha = 0.3f)
        isSelected -> Color.White
        isToday -> PrimaryViolet
        isFuture -> TextSecondary.copy(alpha = 0.4f)
        else -> TextSecondary
    }

    val dateColor = when {
        !isEnabled -> TextSecondary.copy(alpha = 0.3f)
        isSelected -> Color.White
        isToday -> PrimaryViolet
        isFuture -> TextSecondary.copy(alpha = 0.4f)
        else -> TextPrimary
    }

    // Selected day gets the full pill background
    val bgModifier = if (isSelected) {
        Modifier
            .background(color = PrimaryViolet, shape = RoundedCornerShape(16.dp))
            .padding(vertical = 10.dp, horizontal = 4.dp)
    } else {
        Modifier
            .padding(vertical = 10.dp, horizontal = 4.dp)
    }

    Column(
        modifier = modifier
            .graphicsLayer {
                scaleX = dayScale
                scaleY = dayScale
            }
            .clickable(enabled = isEnabled) { onSelect(dayStr) }
            .then(bgModifier),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        // Weekday Name (e.g. MO)
        Text(
            text = dayName.uppercase(),
            style = MaterialTheme.typography.labelSmall,
            color = weekdayColor,
            fontWeight = FontWeight.Bold,
            fontSize = 11.sp
        )
        
        Spacer(modifier = Modifier.height(6.dp))

        // Date Number
        Text(
            text = dayNum,
            style = MaterialTheme.typography.titleMedium,
            color = dateColor,
            fontWeight = FontWeight.Bold,
            fontSize = 16.sp
        )
    }
}

fun getHabitProgressForDate(dateStr: String, habits: List<Habit>, logs: List<HabitLog>): Pair<Int, Int> {
    val activeHabits = habits.filter { isHabitActiveOnDate(it, dateStr) }
    if (activeHabits.isEmpty()) return 0 to 0

    val logsMap = logs.filter { it.date == dateStr }.associateBy { it.habitId }
    var completedCount = 0
    var nonPausedActiveCount = 0
    activeHabits.forEach { habit ->
        val log = logsMap[habit.id]
        val isPaused = log != null && log.isPaused
        if (!isPaused) {
            nonPausedActiveCount++
            var isCompleted = isLogCompleted(habit, log)
            if (!isCompleted && habit.frequency == "TIMES_WEEKLY") {
                val weeklyTargetCount = habit.specificDays.toIntOrNull() ?: 3
                val curDate = try { java.time.LocalDate.parse(dateStr) } catch (e: Exception) { java.time.LocalDate.now() }
                val startOf7Days = curDate.minusDays(6).toString()
                val endOf7Days = curDate.toString()
                val weeklyLoggedCount = logs.filter { l ->
                    l.habitId == habit.id && l.date >= startOf7Days && l.date <= endOf7Days && isLogCompleted(habit, l)
                }.size
                if (weeklyLoggedCount >= weeklyTargetCount) {
                    isCompleted = true
                }
            }
            if (isCompleted) {
                completedCount++
            }
        }
    }
    return completedCount to nonPausedActiveCount
}

fun getDayCombinedStatus(dateStr: String, habits: List<Habit>, logs: List<HabitLog>): String {
    val todayStr = java.time.LocalDate.now().toString()
    if (dateStr > todayStr) return "INACTIVE"

    val activeHabits = habits.filter { isHabitActiveOnDate(it, dateStr) }
    if (activeHabits.isEmpty()) return "INACTIVE"

    val logsMap = logs.filter { it.date == dateStr }.associateBy { it.habitId }
    
    var anyPending = false
    var anyFailed = false
    var anySuccess = false
    var anyPaused = false

    activeHabits.forEach { habit ->
        val log = logsMap[habit.id]
        val isWeeklyTargetReached = if (habit.frequency == "TIMES_WEEKLY") {
            val weeklyTargetCount = habit.specificDays.toIntOrNull() ?: 3
            val curDate = try { java.time.LocalDate.parse(dateStr) } catch (e: Exception) { java.time.LocalDate.now() }
            val startOf7Days = curDate.minusDays(6).toString()
            val endOf7Days = curDate.toString()
            val weeklyLoggedCount = logs.filter { l ->
                l.habitId == habit.id && l.date >= startOf7Days && l.date <= endOf7Days && isLogCompleted(habit, l)
            }.size
            weeklyLoggedCount >= weeklyTargetCount
        } else false

        val hStatus = getLogStatus(habit, log, dateStr, "1970-01-01", todayStr, isWeeklyTargetReached)

        if (hStatus == "PENDING") anyPending = true
        if (hStatus == "FAILED") anyFailed = true
        if (hStatus == "SUCCESS") anySuccess = true
        if (hStatus == "PAUSED") anyPaused = true
    }

    return when {
        anyPending -> "PENDING"
        anyFailed -> "FAILED"
        anySuccess -> "SUCCESS"
        anyPaused -> "PAUSED"
        else -> "SUCCESS"
    }
}

class InsightOption(
    val type: String,
    val text: String,
    val icon: androidx.compose.ui.graphics.vector.ImageVector,
    val color: Color,
    val onClick: (() -> Unit)? = null
)

private fun isInsightTypeInCooldown(context: Context, type: String, todayDateString: String): Boolean {
    val prefs = context.getSharedPreferences("habits_settings", Context.MODE_PRIVATE)
    val lastShown = prefs.getString("insight_cooldown_$type", null) ?: return false
    val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
    return try {
        val d1 = sdf.parse(lastShown)
        val d2 = sdf.parse(todayDateString)
        if (d1 != null && d2 != null) {
            val diffMs = d2.time - d1.time
            val diffDays = Math.round(diffMs / (1000f * 60 * 60 * 24)).toInt()
            diffDays < 10 && diffDays > 0
        } else false
    } catch (e: Exception) {
        false
    }
}

private fun recordInsightTypeShown(context: Context, type: String, todayDateString: String) {
    val prefs = context.getSharedPreferences("habits_settings", Context.MODE_PRIVATE)
    prefs.edit().putString("insight_cooldown_$type", todayDateString).apply()
}

@Composable
fun SmartInsightCard(
    language: String,
    userName: String,
    todayDateString: String,
    smartInsightDismissedDate: String,
    onDismiss: (String) -> Unit,
    perfectDaysStats: com.example.data.PerfectDaysStats,
    habitsWithStats: List<com.example.data.HabitStatModel>,
    allLogs: List<com.example.data.HabitLog>,
    allHabits: List<com.example.data.Habit>,
    dismissedReviews: Set<String> = emptySet(),
    onOpenMonthlyReview: (Int, Int) -> Unit = { _, _ -> },
    onOpenYearlyReview: (Int) -> Unit = {}
) {
    if (smartInsightDismissedDate == todayDateString) return

    val context = LocalContext.current

    val uniqueLoggedDays = remember(allLogs) {
        allLogs.filter { it.value > 0f && !it.isPaused }.map { it.date }.distinct().size
    }

    if (uniqueLoggedDays < 7) {
        Card(
            colors = CardDefaults.cardColors(containerColor = AppCard),
            border = BorderStroke(1.dp, AppBorder),
            shape = RoundedCornerShape(16.dp),
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 12.dp)
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .background(PrimaryViolet.copy(alpha = 0.15f), CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.Default.Lock,
                        contentDescription = "Locked",
                        tint = PrimaryViolet,
                        modifier = Modifier.size(20.dp)
                    )
                }

                Spacer(modifier = Modifier.width(16.dp))

                Column(modifier = Modifier.weight(1f)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = if (language == "de") "Smart Insights freischalten" else if (language == "ka") "განბლოკეთ Smart Insights" else "Unlock Smart Insights",
                            style = MaterialTheme.typography.labelMedium,
                            color = SecondaryViolet,
                            fontWeight = FontWeight.Bold
                        )
                        Text(
                            text = "$uniqueLoggedDays / 7 Tage",
                            style = MaterialTheme.typography.labelSmall,
                            color = TextSecondary
                        )
                    }

                    Spacer(modifier = Modifier.height(4.dp))

                    val remainingDays = 7 - uniqueLoggedDays
                    val infoText = if (language == "de") {
                        "Sammle noch $remainingDays ${if (remainingDays == 1) "Tag" else "Tage"} an Daten, um deine Smart Insights freizuschalten."
                    } else if (language == "ka") {
                        "შეაგროვეთ კიდევ $remainingDays ${if (remainingDays == 1) "დღის" else "დღის"} მონაცემი, რათა განბლოკოთ თქვენი Smart Insights."
                    } else {
                        "Collect $remainingDays more ${if (remainingDays == 1) "day" else "days"} of data to unlock your Smart Insights."
                    }
                    Text(
                        text = infoText,
                        style = MaterialTheme.typography.bodyMedium,
                        color = TextPrimary,
                        lineHeight = 20.sp
                    )

                    Spacer(modifier = Modifier.height(10.dp))

                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(6.dp)
                            .background(ProgressTrack, CircleShape)
                    ) {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth(fraction = (uniqueLoggedDays / 7.0f).coerceIn(0f, 1f))
                                .height(6.dp)
                                .background(PrimaryViolet, CircleShape)
                        )
                    }
                }
            }
        }
        return
    }

    val options = remember(allLogs, habitsWithStats, perfectDaysStats, language, userName, todayDateString, dismissedReviews) {
        val list = mutableListOf<InsightOption>()
        val greeting = if (userName.isNotBlank()) "Hey $userName, " else ""

        // 1. Action-Based Review Insight
        val cal = Calendar.getInstance()
        val curYear = cal.get(Calendar.YEAR)
        val curMonth = cal.get(Calendar.MONTH) + 1 // 1-12
        var prevYear = curYear
        var prevMonth = curMonth - 1
        if (prevMonth < 1) {
            prevMonth = 12
            prevYear -= 1
        }

        val monthlyKey = "monthly_${prevYear}_${prevMonth}"
        val yearlyKey = "yearly_${prevYear}"

        if (curMonth == 1 && yearlyKey !in dismissedReviews && !isInsightTypeInCooldown(context, "REVIEW_PROMPT", todayDateString)) {
            list.add(InsightOption(
                type = "REVIEW_PROMPT",
                text = if (language == "de") {
                    "${greeting}dein **Jahres-Review $prevYear** ist bereit! Öffne deine Zeitkapsel. ⏳"
                } else {
                    "${greeting}your **$prevYear yearly review** is ready! Open your time capsule. ⏳"
                },
                icon = Icons.Default.AutoAwesome,
                color = PrimaryViolet,
                onClick = { onOpenYearlyReview(prevYear) }
            ))
        } else if (monthlyKey !in dismissedReviews && !isInsightTypeInCooldown(context, "REVIEW_PROMPT", todayDateString)) {
            list.add(InsightOption(
                type = "REVIEW_PROMPT",
                text = if (language == "de") {
                    "${greeting}dein **Monats-Review** ist bereit! Öffne deine Zeitkapsel. ⏳"
                } else {
                    "${greeting}your **monthly review** is ready! Open your time capsule. ⏳"
                },
                icon = Icons.Default.HourglassTop,
                color = PrimaryViolet,
                onClick = { onOpenMonthlyReview(prevYear, prevMonth) }
            ))
        }

        // 2. Total completions
        if (!isInsightTypeInCooldown(context, "TOTAL_COMPLETIONS", todayDateString)) {
            val totalCompletions = allLogs.count { it.value > 0f && !it.isPaused }
            if (totalCompletions >= 10) {
                list.add(InsightOption(
                    type = "TOTAL_COMPLETIONS",
                    text = if (language == "de") {
                        "${greeting}du hast insgesamt bereits **$totalCompletions** Gewohnheiten erfolgreich absolviert! 🚀"
                    } else if (language == "ka") {
                        "${greeting} თქვენ წარმატებით დაასრულეთ ** $totalCompletions ** ჩვევები სულ! 🚀"
                    } else {
                        "${greeting}you have successfully completed **$totalCompletions** habits in total! 🚀"
                    },
                    icon = Icons.Default.CheckCircle,
                    color = SecondaryViolet
                ))
            }
        }

        // 3. Weekly volume
        if (!isInsightTypeInCooldown(context, "WEEKLY_VOLUME", todayDateString)) {
            val calendar = Calendar.getInstance()
            calendar.set(Calendar.DAY_OF_WEEK, calendar.firstDayOfWeek)
            val startOfWeekTime = calendar.timeInMillis
            val weeklyCompletions = allLogs.count { log ->
                log.value > 0f && !log.isPaused && log.timestamp >= startOfWeekTime
            }
            if (weeklyCompletions > 0) {
                list.add(InsightOption(
                    type = "WEEKLY_VOLUME",
                    text = if (language == "de") {
                        "${greeting}diese Woche hast du bereits **$weeklyCompletions** Abschlüsse geschafft. Ein fantastischer Rhythmus! ⚡"
                    } else if (language == "ka") {
                        "${greeting} თქვენ უკვე მიაღწიეთ ** $weeklyCompletions ** დასრულებებს ამ კვირაში. ფანტასტიკური რიტმი! ⚡"
                    } else {
                        "${greeting}you've already achieved **$weeklyCompletions** completions this week. A fantastic rhythm! ⚡"
                    },
                    icon = Icons.Default.Bolt,
                    color = PrimaryViolet
                ))
            }
        }

        // 4. Most active weekday
        if (!isInsightTypeInCooldown(context, "MOST_ACTIVE_DAY", todayDateString)) {
            val weekdayCompletionsMap = IntArray(8)
            val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
            allLogs.forEach { log ->
                if (log.value > 0f && !log.isPaused) {
                    try {
                        val dateVal: java.util.Date? = sdf.parse(log.date)
                        if (dateVal != null) {
                            val calDay = Calendar.getInstance()
                            calDay.time = dateVal
                            val dayOfWeek = calDay.get(Calendar.DAY_OF_WEEK)
                            if (dayOfWeek in 1..7) {
                                weekdayCompletionsMap[dayOfWeek]++
                            }
                        }
                    } catch (e: Exception) {}
                }
            }
            var maxDayIndex = -1
            var maxCount = 0
            for (i in 1..7) {
                if (weekdayCompletionsMap[i] > maxCount) {
                    maxCount = weekdayCompletionsMap[i]
                    maxDayIndex = i
                }
            }
            if (maxDayIndex != -1 && maxCount > 0) {
                val dayName = when (maxDayIndex) {
                    Calendar.MONDAY -> if (language == "de") "Montag" else if (language == "ka") "ორშაბათი" else "Monday"
                    Calendar.TUESDAY -> if (language == "de") "Dienstag" else if (language == "ka") "სამშაბათი" else "Tuesday"
                    Calendar.WEDNESDAY -> if (language == "de") "Mittwoch" else if (language == "ka") "ოთხშაბათი" else "Wednesday"
                    Calendar.THURSDAY -> if (language == "de") "Donnerstag" else if (language == "ka") "ხუთშაბათი" else "Thursday"
                    Calendar.FRIDAY -> if (language == "de") "Freitag" else if (language == "ka") "პარასკევი" else "Friday"
                    Calendar.SATURDAY -> if (language == "de") "Samstag" else if (language == "ka") "შაბათი" else "Saturday"
                    Calendar.SUNDAY -> if (language == "de") "Sonntag" else if (language == "ka") "კვირა" else "Sunday"
                    else -> ""
                }
                if (dayName.isNotEmpty()) {
                    list.add(InsightOption(
                        type = "MOST_ACTIVE_DAY",
                        text = if (language == "de") {
                            "${greeting}dein aktivster Wochentag ist der **$dayName** mit insgesamt **$maxCount** erfolgreichen Abschlüssen! 📈"
                        } else if (language == "ka") {
                        "${greeting} კვირის თქვენი ყველაზე აქტიური დღეა ** $dayName ** სულ ** $maxCount ** წარმატებული დასრულებებით! 📈"
                    } else {
                        "${greeting}your most active day of the week is **$dayName** with a total of **$maxCount** successful completions! 📈"
                    },
                        icon = Icons.Default.TrendingUp,
                        color = SuccessGreen
                    ))
                }
            }
        }

        // 5. Perfect days streak
        if (!isInsightTypeInCooldown(context, "PERFECT_DAYS_STREAK", todayDateString)) {
            val currentStreak = perfectDaysStats.currentStreak
            if (currentStreak >= 2) {
                list.add(InsightOption(
                    type = "PERFECT_DAYS_STREAK",
                    text = if (language == "de") {
                        "${greeting}du bist on fire! 🔥 Schon **$currentStreak** perfekte Tage in Folge. Lass uns diese Serie heute fortsetzen!"
                    } else if (language == "ka") {
                        "${greeting} შენ ხარ ცეცხლი! 🔥 ** $currentStreak ** ზედიზედ შესანიშნავი დღეები. მოდით გავაგრძელოთ ეს სერია დღეს!"
                    } else {
                        "${greeting}you are on fire! 🔥 **$currentStreak** perfect days in a row. Let's keep this streak going today!"
                    },
                    icon = Icons.Default.LocalFireDepartment,
                    color = HabitOrange
                ))
            }
        }

        // 6. Completion rate
        if (!isInsightTypeInCooldown(context, "COMPLETION_RATE", todayDateString)) {
            val completionRate = perfectDaysStats.totalCompletionRate
            if (completionRate >= 50) {
                list.add(InsightOption(
                    type = "COMPLETION_RATE",
                    text = if (language == "de") {
                        "${greeting}deine Gesamt-Erfolgsquote liegt bei extrem starken **$completionRate%**. Bleib weiter so fokussiert! 🎯"
                    } else if (language == "ka") {
                        "${greeting} თქვენი საერთო წარმატების მაჩვენებელი ძალიან ძლიერია ** $completionRate %**. გააგრძელე კონცენტრირება! 🎯"
                    } else {
                        "${greeting}your overall success rate is an extremely strong **$completionRate%**. Keep staying focused! 🎯"
                    },
                    icon = Icons.Default.TrackChanges,
                    color = HabitCyan
                ))
            }
        }

        // 7. Top performer
        if (!isInsightTypeInCooldown(context, "TOP_PERFORMER", todayDateString)) {
            val habitCompletionsMap = mutableMapOf<Int, Int>()
            allLogs.forEach { log ->
                if (log.value > 0f && !log.isPaused) {
                    habitCompletionsMap[log.habitId] = (habitCompletionsMap[log.habitId] ?: 0) + 1
                }
            }
            val maxHabitEntry = habitCompletionsMap.maxByOrNull { it.value }
            if (maxHabitEntry != null && maxHabitEntry.value >= 3) {
                val matchingHabit = allHabits.find { it.id == maxHabitEntry.key }
                if (matchingHabit != null) {
                    list.add(InsightOption(
                        type = "TOP_PERFORMER",
                        text = if (language == "de") {
                            "${greeting}dein absoluter Spitzenreiter ist **'${matchingHabit.name}'** mit bereits **${maxHabitEntry.value}** Abschlüssen! Tolle Leistung. 🟢"
                        } else if (language == "ka") {
                        "${greeting} თქვენი აბსოლუტური საუკეთესო შემსრულებელი არის **' ${matchingHabit.name} ' ** უკვე ** ${maxHabitEntry.value} ** დასრულებებით! დიდი სამუშაო. 🢢"
                    } else {
                        "${greeting}your absolute top performer is **'${matchingHabit.name}'** with already **${maxHabitEntry.value}** completions! Great job. 🟢"
                    },
                        icon = Icons.Default.Star,
                        color = HabitYellow
                    ))
                }
            }
        }

        // 8. High momentum
        if (!isInsightTypeInCooldown(context, "HIGH_MOMENTUM", todayDateString)) {
            val highMomentum = habitsWithStats.maxByOrNull { it.strength }
            if (highMomentum != null && highMomentum.strength >= 75) {
                list.add(InsightOption(
                    type = "HIGH_MOMENTUM",
                    text = if (language == "de") {
                        "${greeting}dein Habit **'${highMomentum.habit.name}'** hat eine fantastische Stärke von **${highMomentum.strength}%** erreicht! 💎"
                    } else if (language == "ka") {
                        "${greeting}შენმა ჩვევამ **'${highMomentum.habit.name}'** მიაღწია ფანტასტიკურ სიძლიერეს **${highMomentum.strength}%**! 💎"
                    } else {
                        "${greeting}your habit **'${highMomentum.habit.name}'** has reached a fantastic strength of **${highMomentum.strength}%**! 💎"
                    },
                    icon = Icons.Default.AutoAwesome,
                    color = PrimaryViolet
                ))
            }
        }

        // 9. Least active weekday (Constructive)
        if (!isInsightTypeInCooldown(context, "LEAST_ACTIVE_DAY", todayDateString)) {
            val weekdayCompletionsMap = IntArray(8)
            val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
            allLogs.forEach { log ->
                if (log.value > 0f && !log.isPaused) {
                    try {
                        val dateVal = sdf.parse(log.date)
                        if (dateVal != null) {
                            val calDay = Calendar.getInstance()
                            calDay.time = dateVal
                            val dayOfWeek = calDay.get(Calendar.DAY_OF_WEEK)
                            if (dayOfWeek in 1..7) {
                                weekdayCompletionsMap[dayOfWeek]++
                            }
                        }
                    } catch (e: Exception) {}
                }
            }
            var minDayIndex = -1
            var minCount = Int.MAX_VALUE
            var maxCount = 0
            for (i in 1..7) {
                if (weekdayCompletionsMap[i] > maxCount) maxCount = weekdayCompletionsMap[i]
                if (weekdayCompletionsMap[i] < minCount) {
                    minCount = weekdayCompletionsMap[i]
                    minDayIndex = i
                }
            }
            if (minDayIndex != -1 && maxCount >= 5) {
                val dayName = when (minDayIndex) {
                    Calendar.MONDAY -> tr(language, "Montag", "Monday")
                    Calendar.TUESDAY -> tr(language, "Dienstag", "Tuesday")
                    Calendar.WEDNESDAY -> tr(language, "Mittwoch", "Wednesday")
                    Calendar.THURSDAY -> tr(language, "Donnerstag", "Thursday")
                    Calendar.FRIDAY -> tr(language, "Freitag", "Friday")
                    Calendar.SATURDAY -> tr(language, "Samstag", "Saturday")
                    Calendar.SUNDAY -> tr(language, "Sonntag", "Sunday")
                    else -> ""
                }
                if (dayName.isNotEmpty()) {
                    list.add(InsightOption(
                        type = "LEAST_ACTIVE_DAY",
                        text = if (language == "de") {
                            "${greeting}am **$dayName** fällt dir das Abhaken noch am schwersten ($minCount Abschlüsse). Ein kleiner Schritt reicht schon aus, um deinen Rhythmus zu stärken! 💡"
                        } else if (language == "ka") {
                            "${greeting}დღეს **$dayName**-ს ჩვევების შესრულება შედარებით გიჭირს ($minCount შესრულება). პატარა ნაბიჯიც კი დაგეხმარება! 💡"
                        } else {
                            "${greeting}on **$dayName** you find it a bit harder to complete habits ($minCount completions). A small step today can help boost your momentum! 💡"
                        },
                        icon = Icons.Default.Lightbulb,
                        color = HabitOrange
                    ))
                }
            }
        }

        // 10. Lowest performing habit / Needs attention (Constructive)
        if (!isInsightTypeInCooldown(context, "LOWEST_PERFORMER", todayDateString)) {
            val activeHabits = habitsWithStats.filter { !it.habit.isArchived }
            if (activeHabits.size >= 2) {
                val lowestHabit = activeHabits.minByOrNull { it.strength }
                if (lowestHabit != null && lowestHabit.strength < 50) {
                    list.add(InsightOption(
                        type = "LOWEST_PERFORMER",
                        text = if (language == "de") {
                            "${greeting}dein Habit **'${lowestHabit.habit.name}'** könnte etwas zusätzliche Aufmerksamkeit gebrauchen (Stärke: **${lowestHabit.strength}%**). Wie wäre es heute mit einem kleinen Neustart? 🎯"
                        } else if (language == "ka") {
                            "${greeting}შენს ჩვევას **'${lowestHabit.habit.name}'** ცოტა მეტი ყურადღება სჭირდება (სიძლიერე: **${lowestHabit.strength}%**). მზად ხარ დღეს დასაბრუნებლად? 🎯"
                        } else {
                            "${greeting}your habit **'${lowestHabit.habit.name}'** could use a little extra attention (strength: **${lowestHabit.strength}%**). How about a fresh start today? 🎯"
                        },
                        icon = Icons.Default.TrendingDown,
                        color = HabitRed
                    ))
                }
            }
        }

        // 11. Month-over-Month comparison
        if (!isInsightTypeInCooldown(context, "MONTH_OVER_MONTH", todayDateString)) {
            val now = Calendar.getInstance()
            val currentMonth = now.get(Calendar.MONTH)
            val currentYear = now.get(Calendar.YEAR)
            
            val prevCal = Calendar.getInstance().apply {
                add(Calendar.MONTH, -1)
            }
            val prevMonth = prevCal.get(Calendar.MONTH)
            val prevYear = prevCal.get(Calendar.YEAR)
            
            val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
            var currMonthCount = 0
            var prevMonthCount = 0
            
            allLogs.forEach { log ->
                if (log.value > 0f && !log.isPaused) {
                    try {
                        val dateVal = sdf.parse(log.date)
                        if (dateVal != null) {
                            val logCal = Calendar.getInstance()
                            logCal.time = dateVal
                            if (logCal.get(Calendar.YEAR) == currentYear && logCal.get(Calendar.MONTH) == currentMonth) {
                                currMonthCount++
                            } else if (logCal.get(Calendar.YEAR) == prevYear && logCal.get(Calendar.MONTH) == prevMonth) {
                                prevMonthCount++
                            }
                        }
                    } catch (e: Exception) {}
                }
            }
            
            if (prevMonthCount > 0 || currMonthCount > 0) {
                list.add(InsightOption(
                    type = "MONTH_OVER_MONTH",
                    text = if (language == "de") {
                        if (currMonthCount >= prevMonthCount) {
                            "${greeting}diesen Monat hast du bereits **$currMonthCount** Abschlüsse geschafft (im Vormonat waren es **$prevMonthCount**). Du bist auf einem richtig guten Weg! 📈"
                        } else if (language == "ka") {
                        "${greeting} diesen Monat stehst du aktuell bei ** $currMonthCount ** Abschlüssen im Vergleich zu ** $prevMonthCount ** im Vormonat. Noch ist genug Zeit, um aufzuholen! 💪"
                    } else {
                        "${greeting}diesen Monat stehst du aktuell bei **$currMonthCount** Abschlüssen im Vergleich zu **$prevMonthCount** im Vormonat. Noch ist genug Zeit, um aufzuholen! 💪"
                    }
                    } else if (language == "ka") {
                        if (currMonthCount >= prevMonthCount) {
                            "${greeting}ამ თვეში უკვე **$currMonthCount** შესრულება გაქვს (გასულ თვეს: **$prevMonthCount**). შესანიშნავი პროგრესია! 📈"
                        } else {
                            "${greeting}ამ თვეში გაქვს **$currMonthCount** შესრულება (გასულ თვეს: **$prevMonthCount**). კიდევ გაქვს დრო წინსვლისთვის! 💪"
                        }
                    } else {
                        if (currMonthCount >= prevMonthCount) {
                            "${greeting}you've achieved **$currMonthCount** completions this month compared to **$prevMonthCount** last month. You're on a great trajectory! 📈"
                        } else {
                            "${greeting}you currently have **$currMonthCount** completions this month compared to **$prevMonthCount** last month. Plenty of time to catch up! 💪"
                        }
                    },
                    icon = Icons.Default.DateRange,
                    color = PrimaryViolet
                ))
            }
        }

        // 12. Week-over-Week comparison
        if (!isInsightTypeInCooldown(context, "WEEK_OVER_WEEK", todayDateString)) {
            val nowTime = System.currentTimeMillis()
            val oneWeekMillis = 7 * 24 * 60 * 60 * 1000L
            val twoWeeksMillis = 14 * 24 * 60 * 60 * 1000L
            
            val thisWeekCount = allLogs.count { log -> log.value > 0f && !log.isPaused && (nowTime - log.timestamp) <= oneWeekMillis }
            val prevWeekCount = allLogs.count { log -> log.value > 0f && !log.isPaused && (nowTime - log.timestamp) in (oneWeekMillis + 1)..twoWeeksMillis }
            
            if (thisWeekCount > 0 || prevWeekCount > 0) {
                list.add(InsightOption(
                    type = "WEEK_OVER_WEEK",
                    text = if (language == "de") {
                        "${greeting}in den letzten 7 Tagen hast du **$thisWeekCount** Abschlüsse verzeichnet, verglichen mit **$prevWeekCount** in der Vorwoche. ${if (thisWeekCount >= prevWeekCount) "Klasse Steigerung! 🚀" else "Bleib weiter am Ball! ⚡"}"
                    } else if (language == "ka") {
                        "${greeting}ბოლო 7 დღეში გაქვს **$thisWeekCount** შესრულება, წინა კვირის **$prevWeekCount**-თან შედარებით. ${if (thisWeekCount >= prevWeekCount) "შესანიშნავი ზრდაა! 🚀" else "არ გაჩერდე! ⚡"}"
                    } else {
                        "${greeting}in the last 7 days you logged **$thisWeekCount** completions, compared to **$prevWeekCount** the previous week. ${if (thisWeekCount >= prevWeekCount) "Great increase! 🚀" else "Keep staying on track! ⚡"}"
                    },
                    icon = Icons.Default.ShowChart,
                    color = SecondaryViolet
                ))
            }
        }

        // 13. Habit-specific improvement
        if (!isInsightTypeInCooldown(context, "HABIT_IMPROVEMENT", todayDateString)) {
            val nowTime = System.currentTimeMillis()
            val oneWeekMillis = 7 * 24 * 60 * 60 * 1000L
            val twoWeeksMillis = 14 * 24 * 60 * 60 * 1000L
            
            var bestHabit: com.example.data.Habit? = null
            var maxDiff = 0
            var bestThisWeek = 0
            var bestLastWeek = 0
            
            allHabits.filter { !it.isArchived }.forEach { habit ->
                val thisWeek = allLogs.count { it.habitId == habit.id && it.value > 0f && !it.isPaused && (nowTime - it.timestamp) <= oneWeekMillis }
                val lastWeek = allLogs.count { it.habitId == habit.id && it.value > 0f && !it.isPaused && (nowTime - it.timestamp) in (oneWeekMillis + 1)..twoWeeksMillis }
                val diff = thisWeek - lastWeek
                if (diff > maxDiff && thisWeek >= 2) {
                    maxDiff = diff
                    bestHabit = habit
                    bestThisWeek = thisWeek
                    bestLastWeek = lastWeek
                }
            }
            
            if (bestHabit != null) {
                val habitName = bestHabit!!.name
                list.add(InsightOption(
                    type = "HABIT_IMPROVEMENT",
                    text = if (language == "de") {
                        "${greeting}dein Habit **'$habitName'** läuft diese Woche spürbar besser als in der Vorwoche (**$bestThisWeek** vs. **$bestLastWeek** Abschlüsse)! 🎉"
                    } else if (language == "ka") {
                        "${greeting}შენი ჩვევა **'$habitName'** ამ კვირაში უკეთესად მიდის, ვიდრე გასულ კვირას (**$bestThisWeek** vs **$bestLastWeek** შესრულება)! 🎉"
                    } else {
                        "${greeting}your habit **'$habitName'** is going noticeably better this week than last week (**$bestThisWeek** vs **$bestLastWeek** completions)! 🎉"
                    },
                    icon = Icons.Default.ArrowUpward,
                    color = HabitGreen
                ))
            }
        }

        list
    }

    if (options.isEmpty()) return

    val selectedOption = options.find { it.type == "REVIEW_PROMPT" }
        ?: options[Math.abs(todayDateString.hashCode()) % options.size]

    LaunchedEffect(selectedOption.type, todayDateString) {
        recordInsightTypeShown(context, selectedOption.type, todayDateString)
    }

    val insightText = selectedOption.text
    val insightIcon = selectedOption.icon
    val iconColor = selectedOption.color

    var visible by remember { mutableStateOf(true) }

    AnimatedVisibility(
        visible = visible,
        enter = expandVertically(animationSpec = tween(500, easing = LinearOutSlowInEasing)) + fadeIn(animationSpec = tween(500)),
        exit = shrinkVertically(animationSpec = tween(500, easing = LinearOutSlowInEasing)) + fadeOut(animationSpec = tween(300))
    ) {
        Card(
            colors = CardDefaults.cardColors(containerColor = AppCard),
            border = BorderStroke(1.dp, iconColor.copy(alpha = 0.3f)),
            shape = RoundedCornerShape(16.dp),
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 12.dp)
                .then(
                    if (selectedOption.onClick != null) {
                        Modifier.clickable { selectedOption.onClick.invoke() }
                    } else Modifier
                )
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Icon Box
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .background(iconColor.copy(alpha = 0.15f), CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = insightIcon,
                        contentDescription = "Insight Icon",
                        tint = iconColor,
                        modifier = Modifier.size(20.dp)
                    )
                }

                Spacer(modifier = Modifier.width(16.dp))

                Column(modifier = Modifier.weight(1f)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = if (language == "de") "Smart Insight" else if (language == "ka") "ჭკვიანი ინსაითი" else "Smart Insight",
                            style = MaterialTheme.typography.labelMedium,
                            color = iconColor,
                            fontWeight = FontWeight.Bold
                        )

                        Box(
                            modifier = Modifier
                                .size(24.dp)
                                .clickable {
                                    visible = false
                                    onDismiss(todayDateString)
                                },
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Default.Close,
                                contentDescription = "Dismiss",
                                tint = TextSecondary,
                                modifier = Modifier.size(16.dp)
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(4.dp))

                    val annotatedText = remember(insightText) {
                        val parts = insightText.split("**")
                        buildAnnotatedString {
                            parts.forEachIndexed { index, part ->
                                if (index % 2 == 1) {
                                    withStyle(style = SpanStyle(fontWeight = FontWeight.Bold, color = TextPrimary)) {
                                        append(part)
                                    }
                                } else {
                                    append(part)
                                }
                            }
                        }
                    }

                    Text(
                        text = annotatedText,
                        style = MaterialTheme.typography.bodyMedium,
                        color = TextPrimary.copy(alpha = 0.85f),
                        lineHeight = 20.sp
                    )
                }
            }
        }
    }
}

// TODAY SCREEN
@Composable
fun TodayScreen(
    viewModel: HabitsViewModel,
    language: String,
    onAddClick: () -> Unit,
    onEditHabit: (Habit) -> Unit,
    showCreateFirstHabitHint: Boolean = false,
    onDismissFirstHabitHint: () -> Unit = {},
    listState: LazyListState = rememberLazyListState()
) {
    val selectedDate by viewModel.selectedDate.collectAsStateWithLifecycle()
    val weekStartCalendar by viewModel.currentWeekStart.collectAsStateWithLifecycle()
    val todayProgressTuple by viewModel.todayProgress.collectAsStateWithLifecycle()
    val dismissedReviews by viewModel.dismissedReviews.collectAsStateWithLifecycle()

    val activeHabitUiItemsForSelectedDate by viewModel.activeHabitUiItemsForSelectedDate.collectAsStateWithLifecycle()
    val minWeekStartMillis by viewModel.minWeekStartMillis.collectAsStateWithLifecycle()
    val minDateStr by viewModel.minDateStr.collectAsStateWithLifecycle()

    val vibrationEnabled by viewModel.vibrationEnabled.collectAsStateWithLifecycle()
    val accentColorName by viewModel.accentColorName.collectAsStateWithLifecycle()
    val hasOnboarded by viewModel.hasOnboarded.collectAsStateWithLifecycle()

    val todayDateString by viewModel.todayDateString.collectAsStateWithLifecycle()
    val perfectDaysStats by viewModel.perfectDaysStats.collectAsStateWithLifecycle()
    val smartInsightDismissedDate by viewModel.smartInsightDismissedDate.collectAsStateWithLifecycle()
    val habitsWithStats by viewModel.statsScreenData.collectAsStateWithLifecycle()
    val userName by viewModel.userName.collectAsStateWithLifecycle()
    val canPrevWeek by viewModel.canPrevWeek.collectAsStateWithLifecycle()
    val canNextWeek by viewModel.canNextWeek.collectAsStateWithLifecycle()
    val allLogs by viewModel.allLogs.collectAsStateWithLifecycle()
    val allHabits by viewModel.allHabits.collectAsStateWithLifecycle()

    val earliestHabitDateStr = remember(allHabits) {
        if (allHabits.isEmpty()) {
            val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
            sdf.format(java.util.Date())
        } else {
            val minStartMs = allHabits.map { 
                if (it.startDate > 946684800000L) it.startDate else it.createdAt 
            }.minOrNull() ?: System.currentTimeMillis()
            val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
            sdf.format(java.util.Date(minStartMs))
        }
    }

    val context = LocalContext.current
    val activity = context as? Activity

    var todayClickCount by remember { mutableStateOf(0) }
    var showSaskiaDialog by remember { mutableStateOf(false) }
    var longPressedHabit by remember { mutableStateOf<Habit?>(null) }
    var showDeleteConfirmHabit by remember { mutableStateOf<Habit?>(null) }
    var showArchiveConfirmHabit by remember { mutableStateOf<Habit?>(null) }
    var manualAddValueHabitId by remember { mutableStateOf<Int?>(null) }
    var isReorderMode by remember { mutableStateOf(false) }
    var originalSortOrders by remember { mutableStateOf<Map<Int, Int>?>(null) }

    val onToggleRemembered = remember(viewModel, selectedDate) {
        { habitId: Int, currentlyHasLog: Boolean ->
            viewModel.toggleBinaryHabit(habitId, selectedDate, currentlyHasLog)
        }
    }
    val onAddQuantityRemembered = remember(viewModel, selectedDate) {
        { habitId: Int, currentVal: Float, diff: Float ->
            val newVal = (currentVal + diff).coerceAtLeast(0f)
            viewModel.logNumericalHabit(habitId, selectedDate, newVal)
        }
    }
    val onSelectDayRemembered = remember(viewModel) {
        { dateStr: String ->
            viewModel.selectDate(dateStr)
        }
    }

    val currentWeekDaysData by viewModel.currentWeekDaysData.collectAsStateWithLifecycle()
    val formattedDisplayDate by viewModel.formattedDisplayDate.collectAsStateWithLifecycle()

    val allDailyNotes by viewModel.allDailyNotes.collectAsStateWithLifecycle()
    val currentNote = remember(allDailyNotes, selectedDate) {
        allDailyNotes.find { it.date == selectedDate }?.content ?: ""
    }
    var showDailyNoteDialog by remember { mutableStateOf(false) }

    val focusManager = androidx.compose.ui.platform.LocalFocusManager.current
    val keyboardController = androidx.compose.ui.platform.LocalSoftwareKeyboardController.current

    Box(
        modifier = Modifier
            .fillMaxSize()
            .pointerInput(Unit) {
                detectTapGestures(onTap = {
                    focusManager.clearFocus()
                    keyboardController?.hide()
                })
            }
    ) {
        LazyColumn(
            state = listState,
            modifier = Modifier
                .fillMaxSize()
                .background(AppBg)
                .padding(horizontal = 16.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
            contentPadding = PaddingValues(bottom = 140.dp, top = 28.dp)
        ) {
            item(key = "today_top_row") {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 12.dp)
                        .defaultMinSize(minHeight = 44.dp)
                ) {
                    // Top Left: Daily Note Button (Notizbuch)
                    Box(
                        modifier = Modifier
                            .size(44.dp)
                            .border(1.dp, AppBorder, RoundedCornerShape(12.dp))
                            .background(AppCard, RoundedCornerShape(12.dp))
                            .clickable { showDailyNoteDialog = true }
                            .align(Alignment.CenterStart)
                            .testTag("btn_daily_note"),
                        contentAlignment = Alignment.Center
                    ) {
                        ZettelMitStiftIcon(
                            modifier = Modifier.size(22.dp),
                            color = TextPrimary
                        )
                        if (currentNote.isNotEmpty()) {
                            Box(
                                modifier = Modifier
                                    .align(Alignment.TopEnd)
                                    .padding(top = 6.dp, end = 6.dp)
                                    .size(6.dp)
                                    .background(PrimaryViolet, CircleShape)
                            )
                        }
                    }

                    Text(
                        modifier = Modifier
                            .align(Alignment.Center)
                            .padding(horizontal = 48.dp)
                            .clickable(
                                interactionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() },
                                indication = null
                            ) {
                                todayClickCount++
                                if (todayClickCount >= 10) {
                                    viewModel.unlockSaskia()
                                    showSaskiaDialog = true
                                }
                            },
                        text = formattedDisplayDate,
                        style = MaterialTheme.typography.displayLarge,
                        color = TextPrimary,
                        fontWeight = FontWeight.Bold,
                        textAlign = TextAlign.Center
                    )

                    // Top Right Action Button: Add Habit (Balanced symmetrical layout)
                    Box(
                        modifier = Modifier
                            .size(44.dp)
                            .border(1.dp, AppBorder, RoundedCornerShape(12.dp))
                            .background(AppCard, RoundedCornerShape(12.dp))
                            .clickable {
                                onDismissFirstHabitHint()
                                onAddClick()
                            }
                            .align(Alignment.CenterEnd)
                            .testTag("btn_add_habit"),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.Add,
                            contentDescription = "Add Habit",
                            tint = TextPrimary,
                            modifier = Modifier.size(20.dp)
                        )
                    }
                }
            }

        item(key = "today_calendar_strip") {
            val coroutineScope = rememberCoroutineScope()

            val todayDate = remember(todayDateString) {
                try { java.time.LocalDate.parse(todayDateString) } catch (e: Exception) { java.time.LocalDate.now() }
            }
            val todayMonday = remember(todayDate) {
                todayDate.with(java.time.DayOfWeek.MONDAY)
            }
            val minMonday = remember(minWeekStartMillis, todayMonday) {
                if (minWeekStartMillis > 0) {
                    java.time.Instant.ofEpochMilli(minWeekStartMillis)
                        .atZone(java.time.ZoneId.systemDefault())
                        .toLocalDate()
                        .with(java.time.DayOfWeek.MONDAY)
                        .coerceAtMost(todayMonday)
                } else {
                    todayMonday.minusYears(1).with(java.time.DayOfWeek.MONDAY)
                }
            }

            val totalWeeks = remember(minMonday, todayMonday) {
                (java.time.temporal.ChronoUnit.WEEKS.between(minMonday, todayMonday).toInt() + 1).coerceAtLeast(1)
            }
            val maxPageIndex = totalWeeks - 1

            val currentWeekMonday = remember(weekStartCalendar) {
                java.time.Instant.ofEpochMilli(weekStartCalendar.timeInMillis)
                    .atZone(java.time.ZoneId.systemDefault())
                    .toLocalDate()
                    .with(java.time.DayOfWeek.MONDAY)
            }
            val currentWeekPageIndex = remember(minMonday, currentWeekMonday, maxPageIndex) {
                java.time.temporal.ChronoUnit.WEEKS.between(minMonday, currentWeekMonday).toInt().coerceIn(0, maxPageIndex)
            }

            val pagerState = key(minMonday, totalWeeks) {
                rememberPagerState(
                    initialPage = currentWeekPageIndex,
                    pageCount = { totalWeeks }
                )
            }

            var isUserSwiping by remember { mutableStateOf(false) }

            LaunchedEffect(pagerState.isScrollInProgress) {
                if (pagerState.isScrollInProgress) {
                    isUserSwiping = true
                }
            }

            // Sync from viewModel to pagerState when currentWeekStart changes outside (e.g. date picker / Heute)
            LaunchedEffect(currentWeekMonday, totalWeeks) {
                val targetPage = java.time.temporal.ChronoUnit.WEEKS.between(minMonday, currentWeekMonday).toInt().coerceIn(0, maxPageIndex)
                if (pagerState.currentPage != targetPage && !pagerState.isScrollInProgress && !isUserSwiping) {
                    pagerState.animateScrollToPage(targetPage)
                }
            }

            // Sync from pagerState to viewModel when settled page changes via swipe
            LaunchedEffect(pagerState.settledPage) {
                if (isUserSwiping) {
                    val pageMonday = minMonday.plusWeeks(pagerState.settledPage.toLong())
                    if (pageMonday != currentWeekMonday) {
                        val selLocalDate = try { java.time.LocalDate.parse(selectedDate) } catch (e: Exception) { todayDate }
                        val dayOffset = (selLocalDate.dayOfWeek.value - 1).coerceIn(0, 6)
                        var targetDate = pageMonday.plusDays(dayOffset.toLong())
                        if (targetDate > todayDate) targetDate = todayDate
                        val minLocalDate = try { java.time.LocalDate.parse(minDateStr) } catch (e: Exception) { todayDate }
                        if (targetDate < minLocalDate) targetDate = minLocalDate

                        viewModel.selectDateAndSyncWeek(targetDate.toString())
                    }
                    isUserSwiping = false
                }
            }

            val canSwipePrev = pagerState.currentPage > 0
            val canSwipeNext = pagerState.currentPage < maxPageIndex

            Column(
                modifier = Modifier.fillMaxWidth()
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    val prevInteractionSource = remember { MutableInteractionSource() }
                    val prevIsPressed by prevInteractionSource.collectIsPressedAsState()
                    val prevOffsetX by animateDpAsState(
                        targetValue = if (prevIsPressed) (-6).dp else 0.dp,
                        animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessLow),
                        label = "prev_week_offset"
                    )

                    IconButton(
                        onClick = {
                            if (canSwipePrev && pagerState.currentPage - 1 >= 0) {
                                coroutineScope.launch {
                                    pagerState.animateScrollToPage(pagerState.currentPage - 1)
                                }
                            }
                        },
                        enabled = canSwipePrev,
                        interactionSource = prevInteractionSource,
                        modifier = Modifier.size(36.dp).testTag("prev_week_button")
                    ) {
                        Icon(
                            imageVector = Icons.Default.ChevronLeft,
                            contentDescription = "Previous Week",
                            tint = if (canSwipePrev) (if (prevIsPressed) PrimaryViolet else TextPrimary) else TextPrimary.copy(alpha = 0.3f),
                            modifier = Modifier
                                .offset(x = prevOffsetX)
                                .size(24.dp)
                        )
                    }

                    HorizontalPager(
                        state = pagerState,
                        modifier = Modifier
                            .weight(1f)
                            .padding(bottom = 8.dp),
                        key = { page -> page }
                    ) { page ->
                        val pageMonday = remember(page, minMonday) { minMonday.plusWeeks(page.toLong()) }
                        val pageDays = remember(pageMonday) {
                            val dbFmt = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd", java.util.Locale.US)
                            val numFmt = java.time.format.DateTimeFormatter.ofPattern("d", java.util.Locale.GERMANY)
                            val nameFmt = java.time.format.DateTimeFormatter.ofPattern("E", java.util.Locale.GERMANY)
                            (0..6).map { i ->
                                val d = pageMonday.plusDays(i.toLong())
                                Triple(
                                    d.format(dbFmt),
                                    d.format(numFmt),
                                    d.format(nameFmt).uppercase(java.util.Locale.GERMANY).take(2)
                                )
                            }
                        }

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceEvenly,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            pageDays.forEach { (dayStr, dayNum, dayName) ->
                                val isSelected = dayStr == selectedDate
                                val isDayEnabled = dayStr >= minDateStr && dayStr >= earliestHabitDateStr
                                key(dayStr) {
                                    CalendarDayItem(
                                        dayStr = dayStr,
                                        dayNum = dayNum,
                                        dayName = dayName,
                                        isSelected = isSelected,
                                        onSelect = onSelectDayRemembered,
                                        isToday = dayStr == todayDateString,
                                        isFuture = dayStr > todayDateString,
                                        modifier = Modifier.weight(1f),
                                        isEnabled = isDayEnabled
                                    )
                                }
                            }
                        }
                    }

                    val nextInteractionSource = remember { MutableInteractionSource() }
                    val nextIsPressed by nextInteractionSource.collectIsPressedAsState()
                    val nextOffsetX by animateDpAsState(
                        targetValue = if (nextIsPressed) 6.dp else 0.dp,
                        animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessLow),
                        label = "next_week_offset"
                    )

                    IconButton(
                        onClick = {
                            if (canSwipeNext && pagerState.currentPage + 1 < pagerState.pageCount) {
                                coroutineScope.launch {
                                    pagerState.animateScrollToPage(pagerState.currentPage + 1)
                                }
                            }
                        },
                        enabled = canSwipeNext,
                        interactionSource = nextInteractionSource,
                        modifier = Modifier.size(36.dp).testTag("next_week_button")
                    ) {
                        Icon(
                            imageVector = Icons.Default.ChevronRight,
                            contentDescription = "Next Week",
                            tint = if (canSwipeNext) (if (nextIsPressed) PrimaryViolet else TextPrimary) else TextPrimary.copy(alpha = 0.3f),
                            modifier = Modifier
                                .offset(x = nextOffsetX)
                                .size(24.dp)
                        )
                    }
                }
            }
        }

        item(key = "today_progress_card") {
            val isPastDay = remember(selectedDate, todayDateString) {
                selectedDate < todayDateString
            }
            val (completed, total) = todayProgressTuple
            val fraction = remember(todayProgressTuple) {
                if (total > 0) completed.toFloat() / total else 0f
            }
            val progressText = remember(completed, total) { "$completed/$total" }

            var hasAnimatedTodayProgress by rememberSaveable { mutableStateOf(false) }
            val animFraction = remember { Animatable(if (hasAnimatedTodayProgress) fraction else 0f) }

            LaunchedEffect(fraction) {
                if (!hasAnimatedTodayProgress) {
                    animFraction.snapTo(0f)
                    animFraction.animateTo(
                        targetValue = fraction,
                        animationSpec = tween(durationMillis = 750, easing = FastOutSlowInEasing)
                    )
                    hasAnimatedTodayProgress = true
                } else {
                    animFraction.animateTo(
                        targetValue = fraction,
                        animationSpec = tween(durationMillis = 300, easing = FastOutSlowInEasing)
                    )
                }
            }
                val animatedFraction = animFraction.value
                val streakScale = remember { Animatable(1f) }
                var displayedStreak by remember { mutableStateOf(perfectDaysStats.currentStreak) }
                var hasAnimatedStreak by rememberSaveable(selectedDate) { mutableStateOf(fraction >= 1f) }
                
                LaunchedEffect(selectedDate, perfectDaysStats.currentStreak) {
                    if (fraction < 1.0f) {
                        displayedStreak = perfectDaysStats.currentStreak
                    } else {
                        if (hasAnimatedStreak) {
                            displayedStreak = perfectDaysStats.currentStreak
                        } else {
                            displayedStreak = (perfectDaysStats.currentStreak - 1).coerceAtLeast(0)
                        }
                    }
                }
                
                LaunchedEffect(fraction) {
                    if (fraction < 1.0f) {
                        hasAnimatedStreak = false
                    }
                }
                
                LaunchedEffect(animatedFraction) {
                    if (animatedFraction >= 1.0f && fraction >= 1.0f && total > 0 && !hasAnimatedStreak) {
                        hasAnimatedStreak = true
                        displayedStreak = perfectDaysStats.currentStreak
                        streakScale.animateTo(
                            targetValue = 1.22f,
                            animationSpec = spring(
                                dampingRatio = Spring.DampingRatioLowBouncy,
                                stiffness = Spring.StiffnessMedium
                            )
                        )
                        delay(350)
                        streakScale.animateTo(
                            targetValue = 1f,
                            animationSpec = tween(
                                durationMillis = 350,
                                easing = FastOutSlowInEasing
                            )
                        )
                    }
                }

                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 6.dp)
                ) {
                    val targetGlowColor = if (fraction >= 1.0f) SuccessGreen else MaterialTheme.colorScheme.primary
                    val progressGlowColor by animateColorAsState(
                        targetValue = targetGlowColor,
                        animationSpec = tween(durationMillis = 600, easing = FastOutSlowInEasing),
                        label = "progressGlowColorAnim"
                    )
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 6.dp)
                            .animatedGlowingBorder(progressGlowColor, 22.dp, 2.dp, progressGlowColor),
                        colors = CardDefaults.cardColors(containerColor = AppCard),
                        shape = RoundedCornerShape(22.dp)
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 14.dp, vertical = 14.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Surface(
                                modifier = Modifier
                                    .weight(1f)
                                    .height(36.dp),
                                color = AppCard,
                                shape = RoundedCornerShape(18.dp),
                                border = BorderStroke(1.dp, AppBorder)
                            ) {
                                Box(modifier = Modifier.fillMaxSize()) {
                                    if (animatedFraction > 0f) {
                                        Box(
                                            modifier = Modifier
                                                .fillMaxHeight()
                                                .fillMaxWidth(animatedFraction.coerceIn(0f, 1f))
                                                .background(SuccessGreen)
                                        )
                                    }

                                    Row(
                                        modifier = Modifier
                                            .fillMaxSize()
                                            .padding(horizontal = 14.dp),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text(
                                            text = if (language == "de") "Tagesfortschritt" else if (language == "ka") "ყოველდღიური პროგრესი" else "Daily Progress",
                                            style = MaterialTheme.typography.labelLarge,
                                            fontWeight = FontWeight.Bold,
                                            color = Color.White.copy(alpha = 0.85f)
                                        )
                                        Text(
                                            text = progressText,
                                            style = MaterialTheme.typography.labelLarge,
                                            fontWeight = FontWeight.Bold,
                                            color = Color.White
                                        )
                                    }
                                }
                            }
                            
                            Spacer(modifier = Modifier.width(10.dp))
                            
                            val badgeHorizontalPadding = when {
                                displayedStreak >= 100 -> 16.dp
                                displayedStreak >= 10 -> 14.dp
                                else -> 12.dp
                            }

                            Box(
                                modifier = Modifier
                                    .padding(horizontal = 4.dp)
                                    .scale(streakScale.value)
                            ) {
                                Surface(
                                    color = AppCard,
                                    shape = RoundedCornerShape(18.dp),
                                    border = BorderStroke(1.dp, if (fraction >= 1f) HabitOrange.copy(alpha = 0.5f) else AppBorder),
                                    modifier = Modifier
                                        .height(36.dp)
                                        .testTag("perfect_day_streak_badge")
                                ) {
                                    Row(
                                        modifier = Modifier.padding(horizontal = badgeHorizontalPadding),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Text(
                                            text = "🔥",
                                            fontSize = 14.sp
                                        )
                                        Text(
                                            text = "$displayedStreak",
                                            style = MaterialTheme.typography.titleSmall,
                                            fontWeight = FontWeight.Bold,
                                            color = if (fraction >= 1f) HabitOrange else TextSecondary
                                        )
                                    }
                                }
                            }
                        }
                    }
                
                SmartInsightCard(
                    language = language,
                    userName = userName,
                    todayDateString = todayDateString,
                    smartInsightDismissedDate = smartInsightDismissedDate,
                    onDismiss = { viewModel.dismissSmartInsight(it) },
                    perfectDaysStats = perfectDaysStats,
                    habitsWithStats = habitsWithStats,
                    allLogs = allLogs,
                    allHabits = allHabits,
                    dismissedReviews = dismissedReviews,
                    onOpenMonthlyReview = { year, month -> viewModel.setDeepLinkReviewMonth(year to month) },
                    onOpenYearlyReview = { year -> viewModel.setDeepLinkReviewYear(year) }
                )
            }
        }

        if (isReorderMode) {
            item(key = "today_reorder_banner") {
                Card(
                    colors = CardDefaults.cardColors(containerColor = PrimaryViolet.copy(alpha = 0.15f)),
                    border = BorderStroke(1.dp, PrimaryViolet.copy(alpha = 0.5f)),
                    shape = RoundedCornerShape(16.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 8.dp)
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 16.dp, vertical = 12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            modifier = Modifier.weight(1f)
                        ) {
                            Icon(
                                imageVector = Icons.Default.SwapVert,
                                contentDescription = null,
                                tint = PrimaryViolet,
                                modifier = Modifier.size(22.dp)
                            )
                            Text(
                                text = if (language == "de") "Reihenfolge anpassen" else if (language == "ka") "ჩვევების გადაკვეთა" else "Reorder Habits",
                                style = MaterialTheme.typography.titleMedium,
                                fontWeight = FontWeight.Bold,
                                color = TextPrimary,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                        }
                        
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            // Cancel Button
                            OutlinedButton(
                                onClick = {
                                    originalSortOrders?.let { savedOrders ->
                                        viewModel.revertHabitOrders(savedOrders)
                                    }
                                    isReorderMode = false
                                },
                                shape = RoundedCornerShape(10.dp),
                                border = BorderStroke(1.dp, FailedRed),
                                colors = ButtonDefaults.outlinedButtonColors(contentColor = FailedRed),
                                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Close,
                                    contentDescription = "Cancel",
                                    modifier = Modifier.size(16.dp)
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                Text(
                                    text = if (language == "de") "Abbrechen" else if (language == "ka") "გაუქმება" else "Cancel",
                                    fontWeight = FontWeight.Bold,
                                    style = MaterialTheme.typography.bodyMedium
                                )
                            }

                            // Done Button
                            Button(
                                onClick = { isReorderMode = false },
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = PrimaryViolet,
                                    contentColor = TextPrimary
                                ),
                                shape = RoundedCornerShape(10.dp),
                                contentPadding = PaddingValues(horizontal = 14.dp, vertical = 6.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Check,
                                    contentDescription = "Done",
                                    modifier = Modifier.size(16.dp)
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                Text(
                                    text = if (language == "de") "Fertig" else if (language == "ka") "შესრულებულია" else "Done",
                                    fontWeight = FontWeight.Bold,
                                    style = MaterialTheme.typography.bodyMedium
                                )
                            }
                        }
                    }
                }
            }
        }

        if (activeHabitUiItemsForSelectedDate.isEmpty()) {
            item(key = "today_habits_empty") {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 32.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Icon(
                            Icons.Default.AutoAwesome,
                            contentDescription = "No habits",
                            tint = TextSecondary,
                            modifier = Modifier.size(64.dp)
                        )
                        Spacer(modifier = Modifier.height(16.dp))
                        Text(
                            text = if (language == "de") "Noch keine Habits angelegt." else if (language == "ka") "ჯერ არ არის ჩვევები." else "No habits yet.",
                            style = MaterialTheme.typography.titleMedium,
                            color = TextPrimary,
                            fontWeight = FontWeight.Bold,
                            textAlign = TextAlign.Center
                        )
                        Spacer(modifier = Modifier.height(8.dp))
                        Text(
                            text = if (language == "de") {
                                "Tippe oben auf '+', um jederzeit eine Gewohnheit hinzuzufügen."
                            } else if (language == "ka") {
                        "შეეხეთ „+“-ს ზემოთ ჩვევის დასამატებლად ნებისმიერ დროს."
                    } else {
                        "Tap '+' above to add a habit anytime."
                    },
                            style = MaterialTheme.typography.bodyMedium,
                            color = TextSecondary,
                            textAlign = TextAlign.Center
                        )
                    }
                }
            }
} else {
            items(
                items = activeHabitUiItemsForSelectedDate, 
                key = { it.habit.id },
                contentType = { "HABIT_CARD" }
            ) { uiItem ->
                val currentHabit = uiItem.habit
                
                val onLongClickRemembered = remember(currentHabit.id) {
                    { habit: Habit -> longPressedHabit = habit }
                }

                val onToggleClick = remember(currentHabit.id, currentHabit.type, currentHabit.unit, onToggleRemembered) {
                    { habitId: Int, hasLog: Boolean ->
                        val isNumerical = currentHabit.type == "NUMBER" || currentHabit.type == "NUMERICAL" || (currentHabit.targetValue > 1f && currentHabit.type != "BINARY")
                        if (isNumerical) {
                            manualAddValueHabitId = habitId
                        } else {
                            onToggleRemembered(habitId, hasLog)
                        }
                    }
                }

                HabitItemRow(
                    modifier = Modifier.animateItem(),
                    habit = currentHabit,
                    currentValue = uiItem.currentValue,
                    isCompleted = uiItem.isCompleted,
                    isFailed = uiItem.isFailed,
                    isPaused = uiItem.isPaused,
                    hasLog = uiItem.hasLog,
                    onToggle = onToggleClick,
                    onAddQuantity = onAddQuantityRemembered,
                    onLongClick = onLongClickRemembered,
                    language = language,
                    vibrationEnabled = vibrationEnabled,
                    selectedDate = selectedDate,
                    isWeeklyTargetReached = uiItem.isWeeklyTargetReached,
                    weeklyLoggedCount = uiItem.weeklyLoggedCount,
                    weeklyTargetCount = uiItem.weeklyTargetCount,
                    streak = uiItem.streak,
                    isReorderMode = isReorderMode,
                    onMoveUp = { habitId -> viewModel.moveHabitUp(habitId) },
                    onMoveDown = { habitId -> viewModel.moveHabitDown(habitId) }
                )
            }
        }
    } // Close LazyColumn

    if (showDailyNoteDialog) {
        DailyNoteDialog(
            currentNote = currentNote,
            language = language,
            onDismiss = { showDailyNoteDialog = false },
            onSave = { noteText ->
                viewModel.saveDailyNote(selectedDate, noteText)
                showDailyNoteDialog = false
            }
        )
    }

    if (longPressedHabit != null) {
        val habit = longPressedHabit!!
        val isPausedOnSelectedDate = activeHabitUiItemsForSelectedDate.find { it.habit.id == habit.id }?.isPaused == true

        AlertDialog(
            onDismissRequest = { longPressedHabit = null },
            containerColor = AppCard,
            title = {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = habit.name,
                        color = TextPrimary,
                        style = MaterialTheme.typography.titleLarge,
                        modifier = Modifier.weight(1f),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                    IconButton(
                        onClick = { longPressedHabit = null },
                        modifier = Modifier.size(32.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Close,
                            contentDescription = "Close",
                            tint = TextSecondary,
                            modifier = Modifier.size(20.dp)
                        )
                    }
                }
            },
            text = {
                Column(
                    verticalArrangement = Arrangement.spacedBy(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        text = if (language == "de") {
                            "Wähle eine Aktion für diese Gewohnheit:"
                        } else if (language == "ka") {
                        "აირჩიეთ მოქმედება ამ ჩვევისთვის:"
                    } else {
                        "Choose an action for this habit:"
                    },
                        color = TextSecondary,
                        style = MaterialTheme.typography.bodyMedium,
                        modifier = Modifier.padding(bottom = 8.dp)
                    )

                    // Pausieren / Fortsetzen Action
                    Button(
                        onClick = {
                            viewModel.togglePauseHabit(habit.id)
                            longPressedHabit = null
                        },
                        colors = ButtonDefaults.buttonColors(
                            containerColor = if (isPausedOnSelectedDate) SuccessGreen else HabitOrange,
                            contentColor = AppBg
                        ),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.fillMaxWidth().height(48.dp)
                    ) {
                        Icon(
                            imageVector = if (isPausedOnSelectedDate) Icons.Default.PlayArrow else Icons.Default.Pause,
                            contentDescription = null,
                            modifier = Modifier.size(20.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = if (isPausedOnSelectedDate) {
                                if (language == "de") "Skippen beenden" else if (language == "ka") "განაახლეთ ჩვევა" else "Resume Habit"
                            } else {
                                if (language == "de") "Heute skippen" else if (language == "ka") "გამოტოვეთ დღეს" else "Skip today"
                            },
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.bodyLarge
                        )
                    }

                    // Bearbeiten Action
                    Button(
                        onClick = {
                            val habitToEdit = habit
                            longPressedHabit = null
                            onEditHabit(habitToEdit)
                        },
                        colors = ButtonDefaults.buttonColors(
                            containerColor = PrimaryViolet,
                            contentColor = TextPrimary
                        ),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.fillMaxWidth().height(48.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Edit,
                            contentDescription = null,
                            modifier = Modifier.size(18.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = if (language == "de") "Bearbeiten" else if (language == "ka") "რედაქტირება" else "Edit",
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.bodyLarge
                        )
                    }

                    // Reorder Action
                    Button(
                        onClick = {
                            longPressedHabit = null
                            val habitsList = activeHabitUiItemsForSelectedDate.map { it.habit }
                            originalSortOrders = habitsList.associate { it.id to it.sortOrder }
                            isReorderMode = true
                        },
                        colors = ButtonDefaults.buttonColors(
                            containerColor = AppBorder,
                            contentColor = TextPrimary
                        ),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.fillMaxWidth().height(48.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.SwapVert,
                            contentDescription = null,
                            modifier = Modifier.size(20.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = if (language == "de") "Reihenfolge ändern" else if (language == "ka") "გადააკეთეთ ჩვევები" else "Reorder habits",
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.bodyLarge
                        )
                    }

                    // Archivieren Action
                    Button(
                        onClick = {
                            val habitToArchive = habit
                            longPressedHabit = null
                            showArchiveConfirmHabit = habitToArchive
                        },
                        colors = ButtonDefaults.buttonColors(
                            containerColor = HabitOrange,
                            contentColor = Color.White
