            confirmButton = {}
        )
    }

    if (showDeleteConfirmHabit != null) {
        AlertDialog(
            onDismissRequest = { showDeleteConfirmHabit = null },
            containerColor = AppCard,
            title = { Text(text = if (language == "de") "Habit löschen?" else if (language == "ka") "წაშალოთ ჩვევა?" else "Delete Habit?") },
            text = { Text(text = if (language == "de") "Möchtest du diese Gewohnheit wirklich unwiderruflich löschen?" else if (language == "ka") "დარწმუნებული ხართ, რომ გსურთ სამუდამოდ წაშალოთ ეს ჩვევა?" else "Are you sure you want to delete this habit permanently?") },
            confirmButton = {
                TextButton(
                    onClick = {
                        val habit = showDeleteConfirmHabit!!
                        viewModel.deleteHabit(habit)
                        showDeleteConfirmHabit = null
                        Toast.makeText(
                            context,
                            if (language == "de") "Gewohnheit gelöscht" else if (language == "ka") "ჩვევა წაშლილია" else "Habit deleted",
                            Toast.LENGTH_SHORT
                        ).show()
                    }
                ) {
                    Text(if (language == "de") "Löschen" else if (language == "ka") "წაშლა" else "Delete", color = ErrorRed)
                }
            },
            dismissButton = {
                TextButton(onClick = { showDeleteConfirmHabit = null }) {
                    Text(if (language == "de") "Abbrechen" else if (language == "ka") "გაუქმება" else "Cancel", color = TextSecondary)
                }
            }
        )
    }

    if (showArchiveConfirmHabit != null) {
        AlertDialog(
            onDismissRequest = { showArchiveConfirmHabit = null },
            containerColor = AppCard,
            title = { Text(text = if (language == "de") "Gewohnheit archivieren?" else if (language == "ka") "არქივის ჩვევა?" else "Archive Habit?") },
            text = { Text(text = if (language == "de") "Möchtest du diese Gewohnheit archivieren? Sie wird vom Dashboard und den Statistiken ausgeblendet, kann aber in den Einstellungen jederzeit wieder reaktiviert werden." else if (language == "ka") "გსურთ დაარქივოთ ეს ჩვევა? ის დამალული იქნება საინფორმაციო დაფისა და სტატისტიკისგან, მაგრამ მისი ხელახალი გააქტიურება ნებისმიერ დროს შესაძლებელია პარამეტრებში." else "Do you want to archive this habit? It will be hidden from the dashboard and stats, but can be reactivated at any time in settings.") },
            confirmButton = {
                TextButton(
                    onClick = {
                        val habit = showArchiveConfirmHabit!!
                        viewModel.archiveHabit(habit)
                        showArchiveConfirmHabit = null
                        Toast.makeText(
                            context,
                            if (language == "de") "Gewohnheit archiviert" else if (language == "ka") "ჩვევა დაარქივებულია" else "Habit archived",
                            Toast.LENGTH_SHORT
                        ).show()
                    }
                ) {
                    Text(if (language == "de") "Archivieren" else if (language == "ka") "არქივი" else "Archive", color = HabitOrange)
                }
            },
            dismissButton = {
                TextButton(onClick = { showArchiveConfirmHabit = null }) {
                    Text(if (language == "de") "Abbrechen" else if (language == "ka") "გაუქმება" else "Cancel", color = TextSecondary)
                }
            }
        )
    }

    if (manualAddValueHabitId != null) {
        WidgetAddValueDialog(
            habitId = manualAddValueHabitId!!,
            viewModel = viewModel,
            language = language,
            onDismiss = { manualAddValueHabitId = null }
        )
    }

    if (showCreateFirstHabitHint && activeHabitUiItemsForSelectedDate.isEmpty()) {
        CreateFirstHabitArrowHint(
            language = language
        )
    }

    if (showSaskiaDialog) {
        Dialog(onDismissRequest = { showSaskiaDialog = false }) {
            Surface(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                color = AppCard,
                border = BorderStroke(1.dp, PrimaryViolet.copy(alpha = 0.5f)),
                shape = RoundedCornerShape(24.dp)
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(24.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Box(
                        modifier = Modifier
                            .size(60.dp)
                            .background(Color(0xFFE91E63).copy(alpha = 0.15f), CircleShape),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.Favorite,
                            contentDescription = "Heart",
                            tint = Color(0xFFE91E63),
                            modifier = Modifier.size(32.dp)
                        )
                    }

                    Spacer(modifier = Modifier.height(16.dp))

                    Text(
                        text = "„An Saskia – danke, dass du an meiner Seite bist, heute und an jedem weiteren Tag.“",
                        style = MaterialTheme.typography.titleMedium.copy(
                            fontStyle = androidx.compose.ui.text.font.FontStyle.Italic,
                            fontWeight = FontWeight.Medium
                        ),
                        color = TextPrimary,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.padding(horizontal = 8.dp)
                    )

                    Spacer(modifier = Modifier.height(20.dp))

                    Button(
                        onClick = { showSaskiaDialog = false },
                        colors = ButtonDefaults.buttonColors(containerColor = PrimaryViolet),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Text(
                            text = if (language == "de") "Schließen ❤️" else if (language == "ka") "დახურეთ ❤️" else "Close ❤️",
                            color = Color.White,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            }
        }
    }
} // Close parent Box
}

@Composable
fun CreateFirstHabitArrowHint(
    language: String
) {
    val infiniteTransition = rememberInfiniteTransition(label = "pulse_arrow")
    val animOffsetY by infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = -8f,
        animationSpec = infiniteRepeatable(
            animation = tween(550, easing = FastOutSlowInEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "arrow_offset"
    )

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .padding(top = 70.dp, end = 20.dp),
        contentAlignment = Alignment.TopEnd
    ) {
        Column(
            horizontalAlignment = Alignment.End
        ) {
            // Arrow pointing straight UP directly at the '+' button above
            Box(
                modifier = Modifier
                    .width(44.dp)
                    .offset(y = animOffsetY.dp),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.Default.ArrowUpward,
                    contentDescription = null,
                    tint = PrimaryViolet,
                    modifier = Modifier.size(28.dp)
                )
            }

            Spacer(modifier = Modifier.height(2.dp))

            Surface(
                color = PrimaryViolet,
                shape = RoundedCornerShape(16.dp),
                shadowElevation = 10.dp,
                border = BorderStroke(1.5.dp, SecondaryViolet),
                modifier = Modifier.widthIn(max = 280.dp)
            ) {
                Column(
                    modifier = Modifier.padding(14.dp),
                    horizontalAlignment = Alignment.Start
                ) {
                    Text(
                        text = if (language == "de") "Erstelle deine erste Gewohnheit!" else if (language == "ka") "შექმენი შენი პირველი ჩვევა!" else "Create your first habit!",
                        style = MaterialTheme.typography.titleSmall,
                        color = Color.White,
                        fontWeight = FontWeight.Bold
                    )

                    Spacer(modifier = Modifier.height(4.dp))

                    Text(
                        text = if (language == "de") "Tippe oben rechts auf das '+'-Symbol" else if (language == "ka") "შეეხეთ \"+\" ხატულას ზედა მარჯვენა კუთხეში" else "Tap the '+' icon at the top right",
                        style = MaterialTheme.typography.bodySmall,
                        color = Color.White.copy(alpha = 0.9f)
                    )
                }
            }
        }
    }
}

object FeedbackHelper {
    fun init(context: android.content.Context) {}

    fun playCompletionFeedback(context: android.content.Context, vibrationEnabled: Boolean = true) {
        if (vibrationEnabled) {
            try {
                val vibrator = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                    val vm = context.getSystemService(android.content.Context.VIBRATOR_MANAGER_SERVICE) as? android.os.VibratorManager
                    vm?.defaultVibrator
                } else {
                    @Suppress("DEPRECATION")
                    context.getSystemService(android.content.Context.VIBRATOR_SERVICE) as? android.os.Vibrator
                }
                if (vibrator?.hasVibrator() == true) {
                    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.Q) {
                        vibrator.vibrate(android.os.VibrationEffect.createPredefined(android.os.VibrationEffect.EFFECT_TICK))
                    } else if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
                        vibrator.vibrate(android.os.VibrationEffect.createOneShot(18, 40))
                    } else {
                        @Suppress("DEPRECATION")
                        vibrator.vibrate(18)
                    }
                }
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
fun HabitItemRow(
    modifier: Modifier = Modifier,
    habit: Habit,
    currentValue: Float,
    isCompleted: Boolean,
    isFailed: Boolean,
    isPaused: Boolean,
    hasLog: Boolean,
    onToggle: (Int, Boolean) -> Unit,
    onAddQuantity: (Int, Float, Float) -> Unit,
    onLongClick: (Habit) -> Unit,
    language: String,
    vibrationEnabled: Boolean = true,
    selectedDate: String = "",
    isWeeklyTargetReached: Boolean = false,
    weeklyLoggedCount: Int = 0,
    weeklyTargetCount: Int = 0,
    streak: Int = 0,
    isReorderMode: Boolean = false,
    onMoveUp: ((Int) -> Unit)? = null,
    onMoveDown: ((Int) -> Unit)? = null
) {
    val context = LocalContext.current
    val habitColor = HabitIconMapping.getColor(habit.color)

    val animatedBgColor by animateColorAsState(
        targetValue = when {
            isPaused -> PausedBg
            isCompleted -> SuccessBg
            isFailed -> FailedBg
            habit.frequency == "TIMES_WEEKLY" && isWeeklyTargetReached -> SuccessBg
            else -> AppCard
        },
        animationSpec = tween(120),
        label = "bgColor"
    )
    val animatedBorderColor by animateColorAsState(
        targetValue = when {
            isPaused -> HabitOrange
            isCompleted -> SuccessGreen
            isFailed -> FailedRed
            habit.frequency == "TIMES_WEEKLY" && isWeeklyTargetReached -> SuccessGreen
            else -> AppBorder
        },
        animationSpec = tween(120),
        label = "borderColor"
    )

    val checkboxScale by animateFloatAsState(
        targetValue = if (isPaused || isCompleted || isFailed || (habit.frequency == "TIMES_WEEKLY" && isWeeklyTargetReached)) 1.05f else 1.0f,
        animationSpec = tween(100),
        label = "checkboxScale"
    )

    val isNumerical = habit.type == "NUMBER" || habit.type == "NUMERICAL" || (habit.targetValue > 1f && habit.type != "BINARY")
    val targetVal = if (habit.targetValue > 0f) habit.targetValue else 1f
    val progressRatio = if (isNumerical) (currentValue / targetVal).coerceIn(0f, 1f) else if (isCompleted) 1f else 0f
    val animatedProgressRatio by animateFloatAsState(
        targetValue = progressRatio,
        animationSpec = tween(durationMillis = 350, easing = FastOutSlowInEasing),
        label = "progressRatio"
    )

    var lastDate by remember(habit.id) { mutableStateOf(selectedDate) }
    var wasCompleted by remember(habit.id, selectedDate) { mutableStateOf(isCompleted) }
    var isDateChange by remember(selectedDate) { mutableStateOf(true) }
    val completionAnim = remember { Animatable(0f) }
    val coroutineScope = rememberCoroutineScope()
    var isDragging by remember { mutableStateOf(false) }
    var lastSwapTimestamp by remember { mutableLongStateOf(0L) }
    val dragOffsetY = remember { Animatable(0f) }
    val dragScale by animateFloatAsState(
        targetValue = if (isDragging) 1.04f else 1f,
        animationSpec = spring(stiffness = Spring.StiffnessMediumLow),
        label = "dragScale"
    )
    val cardShadowElevation by animateDpAsState(
        targetValue = if (isDragging) 12.dp else 0.dp,
        label = "shadowElevation"
    )
    val dragZIndex = if (isDragging) 1000f else 0f

    val triggerUserFeedback = {
        FeedbackHelper.playCompletionFeedback(context, vibrationEnabled)
        coroutineScope.launch {
            completionAnim.snapTo(0f)
            completionAnim.animateTo(
                targetValue = 1f,
                animationSpec = tween(durationMillis = 650, easing = FastOutSlowInEasing)
            )
        }
    }

    val handleUserToggle = {
        if (!isNumerical && !isCompleted && !isFailed) {
            triggerUserFeedback()
        }
        onToggle(habit.id, hasLog)
    }

    val handleUserAddQuantity = {
        if (!isCompleted) {
            val step = if (habit.clickIncrement > 0f) habit.clickIncrement else 1f
            if (currentValue + step >= targetVal) {
                triggerUserFeedback()
            }
            onAddQuantity(habit.id, currentValue, step)
        }
    }

    LaunchedEffect(isCompleted, selectedDate) {
        lastDate = selectedDate
        wasCompleted = isCompleted
        isDateChange = false
    }

    val popProgress = completionAnim.value
    val cardScale = 1f + if (popProgress > 0f && popProgress < 1f) {
        0.025f * kotlin.math.sin(popProgress * Math.PI.toFloat())
    } else 0f

    val extraPopScale = if (popProgress > 0f && popProgress < 1f) {
        0.35f * kotlin.math.sin(popProgress * Math.PI.toFloat())
    } else 0f
    val popRotation = if (popProgress > 0f && popProgress < 1f) {
        (1f - popProgress) * -25f
    } else 0f

    Card(
        colors = CardDefaults.cardColors(containerColor = Color.Transparent),
        shape = RoundedCornerShape(16.dp),
        modifier = modifier
            .fillMaxWidth()
            .zIndex(dragZIndex)
            .graphicsLayer {
                scaleX = cardScale * dragScale
                scaleY = cardScale * dragScale
                translationY = dragOffsetY.value
                shadowElevation = cardShadowElevation.toPx()
            }
            .drawBehind {
                // 1. Draw animated background
                drawRoundRect(
                    color = animatedBgColor,
                    cornerRadius = androidx.compose.ui.geometry.CornerRadius(16.dp.toPx(), 16.dp.toPx())
                )

                // 1b. Glowing pulse & shine across the whole card on completion
                if (popProgress > 0f && popProgress < 1f) {
                    val glowAlpha = 0.38f * kotlin.math.sin(popProgress * Math.PI.toFloat())
                    drawRoundRect(
                        brush = Brush.horizontalGradient(
                            colors = listOf(
                                SuccessGreen.copy(alpha = glowAlpha),
                                Color(0xFFFFD54F).copy(alpha = glowAlpha * 0.6f),
                                SuccessGreen.copy(alpha = glowAlpha)
                            )
                        ),
                        cornerRadius = androidx.compose.ui.geometry.CornerRadius(16.dp.toPx(), 16.dp.toPx())
                    )
                }

                // 2. Draw animated or gradient border
                val brush = when {
                    isPaused -> {
                        Brush.linearGradient(
                            colors = listOf(
                                HabitOrange,
                                HabitOrange.copy(alpha = 0.4f),
                                HabitOrange
                            )
                        )
                    }
                    isCompleted -> {
                        Brush.linearGradient(
                            colors = listOf(
                                SuccessGreen,
                                SuccessGreen.copy(alpha = 0.4f),
                                SuccessGreen
                            )
                        )
                    }
                    isFailed -> {
                        Brush.linearGradient(
                            colors = listOf(
                                FailedRed,
                                FailedRed.copy(alpha = 0.4f),
                                FailedRed
                            )
                        )
                    }
                    else -> {
                        SolidColor(animatedBorderColor)
                    }
                }

                val strokeWidth = if (popProgress > 0f && popProgress < 1f) {
                    (1.dp.toPx() + 2.dp.toPx() * kotlin.math.sin(popProgress * Math.PI.toFloat()))
                } else {
                    1.dp.toPx()
                }
                drawRoundRect(
                    brush = brush,
                    cornerRadius = androidx.compose.ui.geometry.CornerRadius(16.dp.toPx(), 16.dp.toPx()),
                    style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeWidth)
                )
            }
            .let { m ->
                if (isReorderMode) {
                    m.pointerInput(habit.id) {
                        detectVerticalDragGestures(
                            onDragStart = {
                                isDragging = true
                                coroutineScope.launch {
                                    dragOffsetY.snapTo(0f)
                                }
                            },
                            onDragEnd = {
                                isDragging = false
                                coroutineScope.launch {
                                    dragOffsetY.animateTo(
                                        0f,
                                        animationSpec = spring(
                                            dampingRatio = Spring.DampingRatioMediumBouncy,
                                            stiffness = Spring.StiffnessLow
                                        )
                                    )
                                }
                            },
                            onDragCancel = {
                                isDragging = false
                                coroutineScope.launch {
                                    dragOffsetY.animateTo(
                                        0f,
                                        animationSpec = spring(
                                            dampingRatio = Spring.DampingRatioNoBouncy,
                                            stiffness = Spring.StiffnessMedium
                                        )
                                    )
                                }
                            },
                            onVerticalDrag = { change, dragAmount ->
                                change.consume()
                                val currentOffset = dragOffsetY.value + dragAmount
                                coroutineScope.launch {
                                    dragOffsetY.snapTo(currentOffset)
                                }
                                val now = System.currentTimeMillis()
                                val threshold = 76.dp.toPx()
                                val rowShift = 82.dp.toPx()
                                if (now - lastSwapTimestamp > 280L) {
                                    if (currentOffset < -threshold) {
                                        lastSwapTimestamp = now
                                        onMoveUp?.invoke(habit.id)
                                        coroutineScope.launch {
                                            dragOffsetY.snapTo(currentOffset + rowShift)
                                        }
                                    } else if (currentOffset > threshold) {
                                        lastSwapTimestamp = now
                                        onMoveDown?.invoke(habit.id)
                                        coroutineScope.launch {
                                            dragOffsetY.snapTo(currentOffset - rowShift)
                                        }
                                    }
                                }
                            }
                        )
                    }
                } else {
                    m.combinedClickable(
                        onClick = { handleUserToggle() },
                        onLongClick = { onLongClick(habit) }
                    )
                }
            }
            .testTag("habit_card_${habit.id}")
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.weight(1f)
            ) {
                Box(
                    modifier = Modifier
                        .size(48.dp)
                        .graphicsLayer {
                            scaleX = checkboxScale
                            scaleY = checkboxScale
                        }
                        .background(habitColor.copy(alpha = 0.15f), CircleShape)
                        .border(1.dp, habitColor.copy(alpha = 0.5f), CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = HabitIconMapping.getIcon(habit.icon),
                        contentDescription = habit.name,
                        tint = habitColor,
                        modifier = Modifier.size(24.dp)
                    )
                }

                Spacer(modifier = Modifier.width(16.dp))

                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = habit.name,
                        style = MaterialTheme.typography.titleMedium,
                        color = TextPrimary,
                        fontWeight = FontWeight.Bold,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )

                    val subtitleText = if (isPaused) {
                        if (language == "de") "Skipped" else if (language == "ka") "გამოტოვებული" else "Skipped"
                    } else if (habit.frequency == "TIMES_WEEKLY") {
                        "$weeklyLoggedCount/$weeklyTargetCount " + (if (language == "de") "in 7 Tagen" else if (language == "ka") "7 დღეში" else "in 7 days")
                    } else if (isNumerical) {
                        val displayValue = if (isFailed) 0f else currentValue
                        val formattedVal = if (displayValue % 1f == 0f) displayValue.toInt().toString() else displayValue.toString()
                        val formattedTarget = if (habit.targetValue % 1f == 0f) habit.targetValue.toInt().toString() else habit.targetValue.toString()
                        val unitStr = if (habit.unit.isNotBlank()) " ${habit.unit}" else ""
                        "$formattedVal / $formattedTarget$unitStr"
                    } else {
                        if (isCompleted) {
                            if (language == "de") "Erledigt" else if (language == "ka") "დასრულებული" else "Completed"
                        } else if (isFailed) {
                            if (language == "de") "Fehlgeschlagen" else if (language == "ka") "ვერ მოხერხდა" else "Failed"
                        } else {
                            ""
                        }
                    }

                    Spacer(modifier = Modifier.height(2.dp))
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        // Streak always first on second line
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(2.dp)
                        ) {
                            Text(
                                text = "🔥",
                                style = MaterialTheme.typography.labelMedium
                            )
                            Text(
                                text = "$streak",
                                style = MaterialTheme.typography.labelMedium,
                                fontWeight = FontWeight.Bold,
                                color = HabitOrange
                            )
                        }

                        if (subtitleText.isNotBlank()) {
                            Text(
                                text = "•",
                                style = MaterialTheme.typography.labelMedium,
                                color = TextSecondary.copy(alpha = 0.5f)
                            )
                            Text(
                                text = subtitleText,
                                style = if (isNumerical && !isPaused) MaterialTheme.typography.labelLarge else MaterialTheme.typography.bodyMedium,
                                fontWeight = if (isNumerical && !isPaused) FontWeight.Bold else FontWeight.Medium,
                                color = when {
                                    isPaused -> HabitOrange
                                    isCompleted -> SuccessGreen
                                    isFailed -> FailedRed
                                    habit.frequency == "TIMES_WEEKLY" && isWeeklyTargetReached -> SuccessGreen
                                    else -> if (isNumerical) habitColor else TextSecondary
                                },
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                        }
                    }
                }
            }

            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                if (isReorderMode) {
                    Icon(
                        imageVector = Icons.Default.DragHandle,
                        contentDescription = "Drag Handle",
                        tint = TextSecondary,
                        modifier = Modifier
                            .size(24.dp)
                            .padding(end = 4.dp)
                    )
                } else {
                    // Status Checkbox (zum schnellen Abhaken/Zurücksetzen bzw. um 1 Erhöhen für Zahlenbasiert)
                    Box(
                        modifier = Modifier
                            .size(36.dp)
                        .graphicsLayer {
                            scaleX = checkboxScale + extraPopScale
                            scaleY = checkboxScale + extraPopScale
                            rotationZ = popRotation
                        }
                        .drawBehind {
                            if (popProgress > 0f && popProgress < 1f) {
                                // 1. Expanding glowing halo ring
                                val haloRadius = (size.width / 2f) + (36.dp.toPx() * popProgress)
                                val haloAlpha = (1f - popProgress) * 0.75f
                                drawCircle(
                                    color = SuccessGreen.copy(alpha = haloAlpha),
                                    radius = haloRadius,
                                    style = androidx.compose.ui.graphics.drawscope.Stroke(
                                        width = 2.5.dp.toPx() * (1f - popProgress)
                                    )
                                )

                                // 2. Sparkling particle dots burst
                                val particleCount = 6
                                for (i in 0 until particleCount) {
                                    val angle = i * (360f / particleCount) * (Math.PI / 180.0)
                                    val dist = 32.dp.toPx() * popProgress
                                    val px = (size.width / 2f) + (kotlin.math.cos(angle) * dist).toFloat()
                                    val py = (size.height / 2f) + (kotlin.math.sin(angle) * dist).toFloat()
                                    val pAlpha = (1f - popProgress) * 0.9f
                                    val pRadius = 3.dp.toPx() * (1f - popProgress)
                                    val pColor = if (i % 2 == 0) SuccessGreen else Color(0xFFFFD54F)

                                    drawCircle(
                                        color = pColor.copy(alpha = pAlpha),
                                        radius = pRadius,
                                        center = androidx.compose.ui.geometry.Offset(px, py)
                                    )
                                }
                            }

                            // 3. Circular Progress Ring for numerical / quantity habits
                            if (isNumerical && !isCompleted && !isPaused && !isFailed) {
                                val strokeWidthPx = 3.dp.toPx()
                                val inset = strokeWidthPx / 2f
                                val arcSize = androidx.compose.ui.geometry.Size(size.width - strokeWidthPx, size.height - strokeWidthPx)

                                // Base track ring
                                drawArc(
                                    color = habitColor.copy(alpha = 0.25f),
                                    startAngle = 0f,
                                    sweepAngle = 360f,
                                    useCenter = false,
                                    topLeft = androidx.compose.ui.geometry.Offset(inset, inset),
                                    size = arcSize,
                                    style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeWidthPx)
                                )

                                // Active progress arc closing up to goal
                                if (animatedProgressRatio > 0f) {
                                    drawArc(
                                        color = habitColor,
                                        startAngle = -90f,
                                        sweepAngle = 360f * animatedProgressRatio,
                                        useCenter = false,
                                        topLeft = androidx.compose.ui.geometry.Offset(inset, inset),
                                        size = arcSize,
                                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                                            width = strokeWidthPx,
                                            cap = androidx.compose.ui.graphics.StrokeCap.Round
                                        )
                                    )
                                }
                            }
                        }
                        .background(
                            when {
                                isPaused -> HabitOrange
                                isCompleted -> SuccessGreen
                                isFailed -> FailedRed
                                habit.frequency == "TIMES_WEEKLY" && isWeeklyTargetReached -> SuccessGreen.copy(alpha = 0.15f)
                                isNumerical -> habitColor.copy(alpha = 0.12f)
                                else -> Color.Transparent
                            }, 
                            CircleShape
                        )
                        .border(
                            width = 2.dp,
                            color = when {
                                isPaused -> HabitOrange
                                isCompleted -> SuccessGreen
                                isFailed -> FailedRed
                                habit.frequency == "TIMES_WEEKLY" && isWeeklyTargetReached -> SuccessGreen
                                isNumerical -> Color.Transparent
                                else -> TextSecondary.copy(alpha = 0.5f)
                            },
                            shape = CircleShape
                        )
                        .clickable(enabled = !isPaused) {
                            if (isNumerical) {
                                handleUserAddQuantity()
                            } else {
                                handleUserToggle()
                            }
                        },
                    contentAlignment = Alignment.Center
                ) {
                    when {
                        isPaused -> {
                            Icon(Icons.Default.Pause, contentDescription = "Paused", tint = TextPrimary, modifier = Modifier.size(16.dp))
                        }
                        isCompleted -> {
                            Icon(Icons.Default.Check, contentDescription = "Completed", tint = TextPrimary, modifier = Modifier.size(18.dp))
                        }
                        isFailed -> {
                            Icon(Icons.Default.Close, contentDescription = "Failed", tint = TextPrimary, modifier = Modifier.size(16.dp))
                        }
                        habit.frequency == "TIMES_WEEKLY" && isWeeklyTargetReached -> {
                            Icon(Icons.Default.Check, contentDescription = "Weekly Target Reached", tint = SuccessGreen, modifier = Modifier.size(18.dp))
                        }
                        isNumerical -> {
                            Icon(
                                imageVector = Icons.Default.Add,
                                contentDescription = "Increment",
                                tint = habitColor,
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }
                }
            }
        }
    }
}
}

// STATS SCREEN
@Composable
fun StatsScreen(
    viewModel: HabitsViewModel,
    language: String,
    onAddClick: () -> Unit,
    onHabitClick: (Int) -> Unit,
    onOverallClick: () -> Unit,
    listState: LazyListState = rememberLazyListState()
) {
    val strength by viewModel.totalStrength.collectAsStateWithLifecycle()
    val longestStreak by viewModel.longestStreakOfAll.collectAsStateWithLifecycle()
    val habitsWithStats by viewModel.statsScreenData.collectAsStateWithLifecycle()
    val todayProgressTuple by viewModel.todayProgress.collectAsStateWithLifecycle()
    val perfectDaysStats by viewModel.perfectDaysStats.collectAsStateWithLifecycle()

    val selectedDate by viewModel.selectedDate.collectAsStateWithLifecycle()
    val weekStartCalendar by viewModel.currentWeekStart.collectAsStateWithLifecycle()
    val minWeekStartMillis by viewModel.minWeekStartMillis.collectAsStateWithLifecycle()
    val minDateStr by viewModel.minDateStr.collectAsStateWithLifecycle()
    val currentWeekDaysData by viewModel.currentWeekDaysData.collectAsStateWithLifecycle()
    val formattedDisplayDate by viewModel.formattedDisplayDate.collectAsStateWithLifecycle()

    val todayDateString by viewModel.todayDateString.collectAsStateWithLifecycle()
    val canPrevWeek by viewModel.canPrevWeek.collectAsStateWithLifecycle()
    val canNextWeek by viewModel.canNextWeek.collectAsStateWithLifecycle()
    val statsDayNamesAndNumbers by viewModel.statsDayNamesAndNumbers.collectAsStateWithLifecycle()

    val allDailyNotes by viewModel.allDailyNotes.collectAsStateWithLifecycle()
    val currentNote = remember(allDailyNotes, selectedDate) {
        allDailyNotes.find { it.date == selectedDate }?.content ?: ""
    }

    var showDailyNoteDialog by remember { mutableStateOf(false) }

    val onSelectDayRemembered = remember(viewModel) {
        { dateStr: String ->
            viewModel.selectDate(dateStr)
        }
    }

    var activeExplanation by remember { mutableStateOf<Pair<String, String>?>(null) }

    val isPastDay = remember(selectedDate, todayDateString) {
        selectedDate < todayDateString
    }

    val encouragementText = remember(todayProgressTuple, language) {
        getEncouragementText(todayProgressTuple.first, todayProgressTuple.second, language)
    }

    val onStatItemClick = remember(onHabitClick) {
        { habitId: Int ->
            onHabitClick(habitId)
        }
    }

    val allHabits by viewModel.allHabits.collectAsStateWithLifecycle()
    val allLogs by viewModel.allLogs.collectAsStateWithLifecycle()

    var selectedReviewYear by remember { mutableStateOf<Int?>(null) }
    var selectedReviewMonth by remember { mutableStateOf<Pair<Int, Int>?>(null) }
    var showReviewArchive by remember { mutableStateOf(false) }
    var showReviewExplanation by remember { mutableStateOf(false) }

    val deepLinkReviewMonth by viewModel.deepLinkReviewMonth.collectAsStateWithLifecycle()
    val deepLinkReviewYear by viewModel.deepLinkReviewYear.collectAsStateWithLifecycle()

    LaunchedEffect(deepLinkReviewMonth) {
        deepLinkReviewMonth?.let {
            selectedReviewMonth = it
            viewModel.setDeepLinkReviewMonth(null)
        }
    }

    LaunchedEffect(deepLinkReviewYear) {
        deepLinkReviewYear?.let {
            selectedReviewYear = it
            viewModel.setDeepLinkReviewYear(null)
        }
    }
    val currentYear = remember { Calendar.getInstance().get(Calendar.YEAR) }
    val availableYears = remember(allLogs, currentYear) {
        val logYears = allLogs.mapNotNull {
            if (it.date.length >= 4) it.date.substring(0, 4).toIntOrNull() else null
        }
        logYears.filter { y -> y < currentYear }
            .distinct()
            .sortedDescending()
    }

    val currentYearMonth = remember {
        val cal = Calendar.getInstance()
        val y = cal.get(Calendar.YEAR)
        val m = cal.get(Calendar.MONTH) + 1 // 1-indexed
        y to m
    }
    val availableMonths = remember(allLogs, currentYearMonth) {
        val logMonths = allLogs.mapNotNull { log ->
            if (log.date.length >= 7) {
                val parts = log.date.split("-")
                if (parts.size >= 2) {
                    val y = parts[0].toIntOrNull()
                    val m = parts[1].toIntOrNull()
                    if (y != null && m != null) {
                        y to m
                    } else null
                } else null
            } else null
        }
        val cal = Calendar.getInstance()
        val cY = cal.get(Calendar.YEAR)
        val cM = cal.get(Calendar.MONTH) + 1 // 1-indexed
        
        // A month is only available if it's strictly in the past (before current year/month)
        logMonths.filter { (y, m) -> 
            y < cY || (y == cY && m < cM)
        }.distinct()
        .sortedWith(compareByDescending<Pair<Int, Int>> { it.first }.thenByDescending { it.second })
    }

    val shortDayNames = statsDayNamesAndNumbers.first
    val dayNumbers = statsDayNamesAndNumbers.second

    var showRewardsOverview by remember { mutableStateOf(false) }

    Box(modifier = Modifier.fillMaxSize()) {
        LazyColumn(
            state = listState,
            modifier = Modifier
                .fillMaxSize()
                .background(AppBg)
                .padding(horizontal = 16.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
            contentPadding = PaddingValues(bottom = 140.dp, top = 28.dp)
        ) {
            item(key = "stats_top_row") {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 12.dp)
                        .defaultMinSize(minHeight = 44.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Box(
                        modifier = Modifier
                            .align(Alignment.CenterStart)
                            .size(44.dp)
                            .border(1.dp, AppBorder, RoundedCornerShape(12.dp))
                            .background(AppCard, RoundedCornerShape(12.dp))
                            .clickable { showRewardsOverview = true }
                            .testTag("btn_rewards_overview"),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.Star,
                            contentDescription = "Rewards",
                            tint = TextPrimary,
                            modifier = Modifier.size(20.dp)
                        )
                    }

                    Text(
                        text = if (language == "de") "Statistiken" else if (language == "ka") "სტატისტიკა" else "Statistics",
                        style = MaterialTheme.typography.displayLarge,
                        color = TextPrimary,
                        fontWeight = FontWeight.Bold,
                        textAlign = TextAlign.Center
                    )

                    Box(
                        modifier = Modifier
                            .align(Alignment.CenterEnd)
                            .size(44.dp)
                            .border(1.dp, AppBorder, RoundedCornerShape(12.dp))
                            .background(AppCard, RoundedCornerShape(12.dp))
                            .clickable { showReviewArchive = true }
                            .testTag("btn_review_archive"),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.AutoAwesome,
                            contentDescription = "Rückblicke",
                            tint = TextPrimary,
                            modifier = Modifier.size(20.dp)
                        )
                    }
                }
            }

            // Subheading: Overall Statistiken
            item {
                Text(
                    text = if (language == "de") "Overall Statistiken" else if (language == "ka") "საერთო სტატისტიკა" else "Overall Statistics",
                    style = MaterialTheme.typography.titleMedium,
                    color = TextPrimary,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 4.dp, bottom = 4.dp)
                )
            }

            // Beautifully designed Overall Statistics Card with enlarged semi-circle gauge
            item {
                var hasAnimatedTodayStrength by rememberSaveable { mutableStateOf(false) }
                val animStrength = remember { Animatable(if (hasAnimatedTodayStrength) strength.toFloat() else 0f) }

                LaunchedEffect(strength) {
                    if (!hasAnimatedTodayStrength) {
                        animStrength.snapTo(0f)
                        animStrength.animateTo(
                            targetValue = strength.toFloat(),
                            animationSpec = tween(durationMillis = 750, easing = FastOutSlowInEasing)
                        )
                        hasAnimatedTodayStrength = true
                    } else {
                        animStrength.animateTo(
                            targetValue = strength.toFloat(),
                            animationSpec = tween(durationMillis = 300, easing = FastOutSlowInEasing)
                        )
                    }
                }
                val animatedStrength = animStrength.value
                val sweepAngleVal = (animatedStrength / 100f) * 360f
                val ringColor = remember(strength) {
                    when {
                        strength < 35 -> HabitRed
                        strength < 70 -> HabitYellow
                        else -> SuccessGreen
                    }
                }
                val strengthLabel = remember(strength, language) { getStrengthLabel(strength, language) }

                val overallInteractionSource = remember { MutableInteractionSource() }
                val overallIsPressed by overallInteractionSource.collectIsPressedAsState()
                val overallArrowOffsetX by animateDpAsState(
                    targetValue = if (overallIsPressed) 8.dp else 0.dp,
                    animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessLow),
                    label = "overall_arrow_offset"
                )
                val overallArrowScale by animateFloatAsState(
                    targetValue = if (overallIsPressed) 1.25f else 1.0f,
                    animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessLow),
                    label = "overall_arrow_scale"
                )

                Card(
                    colors = CardDefaults.cardColors(containerColor = AppCard),
                    shape = RoundedCornerShape(22.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .border(width = 1.dp, color = AppBorder, shape = RoundedCornerShape(22.dp))
                        .clickable(
                            interactionSource = overallInteractionSource,
                            indication = ripple(),
                            onClick = onOverallClick
                        )
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(18.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.KeyboardArrowRight,
                            contentDescription = "Details",
                            tint = if (overallIsPressed) PrimaryViolet else TextSecondary,
                            modifier = Modifier
                                .align(Alignment.TopEnd)
                                .offset(x = overallArrowOffsetX)
                                .scale(overallArrowScale)
                                .size(24.dp)
                        )

                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(150.dp)
                                .padding(top = 8.dp),
                            contentAlignment = Alignment.BottomCenter
                        ) {
                            val sweepHalfVal = (animatedStrength / 100f) * 180f
                            Canvas(
                                modifier = Modifier
                                    .width(290.dp)
                                    .height(150.dp)
                            ) {
                                val strokeWidth = 18.dp.toPx()
                                val stroke = Stroke(width = strokeWidth, cap = StrokeCap.Round)
                                val topLeft = Offset(strokeWidth / 2, strokeWidth / 2)
                                val arcSize = Size(size.width - strokeWidth, (size.height * 2) - strokeWidth)

                                drawArc(
                                    color = ProgressTrack,
                                    startAngle = 180f,
                                    sweepAngle = 180f,
                                    useCenter = false,
                                    topLeft = topLeft,
                                    size = arcSize,
                                    style = stroke
                                )

                                if (sweepHalfVal > 0f) {
                                    drawArc(
                                        color = ringColor,
                                        startAngle = 180f,
                                        sweepAngle = sweepHalfVal,
                                        useCenter = false,
                                        topLeft = topLeft,
                                        size = arcSize,
                                        style = stroke
                                    )
                                }
                            }

                            Column(
                                horizontalAlignment = Alignment.CenterHorizontally,
                                modifier = Modifier.padding(bottom = 12.dp)
                            ) {
                                Text(
                                    text = "${animatedStrength.toInt()}",
                                    style = MaterialTheme.typography.displayLarge,
                                    fontWeight = FontWeight.ExtraBold,
                                    color = TextPrimary
                                )
                                if (strengthLabel.isNotBlank()) {
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = strengthLabel,
                                        style = MaterialTheme.typography.titleSmall,
                                        fontWeight = FontWeight.Bold,
                                        color = ringColor
                                    )
                                }
                            }
                        }
                    }
                }
            }

            // Subheading 2: Habits im Detail
            item {
                Text(
                    text = if (language == "de") "Habits im Detail" else if (language == "ka") "ჩვევები დეტალურად" else "Habits in Detail",
                    style = MaterialTheme.typography.titleMedium,
                    color = TextPrimary,
                    fontWeight = FontWeight.Bold,
                    textAlign = TextAlign.Start,
                    modifier = Modifier.fillMaxWidth().padding(top = 10.dp, bottom = 2.dp)
                )
            }

            if (habitsWithStats.isEmpty()) {
                item {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 16.dp),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Text(
                            text = if (language == "de") "Keine Gewohnheiten verfügbar" else if (language == "ka") "არ არის ხელმისაწვდომი ჩვევები" else "No habits available",
                            style = MaterialTheme.typography.bodyLarge,
                            color = TextSecondary,
                            textAlign = TextAlign.Center
                        )
                        Spacer(modifier = Modifier.height(12.dp))
                        Button(
                            onClick = onAddClick,
                            colors = ButtonDefaults.buttonColors(containerColor = PrimaryViolet),
                            shape = RoundedCornerShape(12.dp),
                            contentPadding = PaddingValues(horizontal = 20.dp, vertical = 10.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.Add,
                                contentDescription = null,
                                tint = Color.White,
                                modifier = Modifier.size(18.dp)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(
                                text = if (language == "de") "Gewohnheit erstellen" else if (language == "ka") "შექმენი ჩვევა" else "Create Habit",
                                style = MaterialTheme.typography.labelLarge,
                                color = Color.White,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                }
            } else {
                items(
                    items = habitsWithStats, 
                    key = { it.habit.id },
                    contentType = { "STAT_CARD" } // FIX: Jetpack Compose recycelt jetzt auch die Statistik-Karten beim Scrollen!
                ) { model ->
                    HabitStatItem(
                        model = model,
                        shortDayNames = shortDayNames,
                        dayNumbers = dayNumbers,
                        language = language,
                        onClick = onStatItemClick
                    )
                }
            }
        } // Close LazyColumn

        if (activeExplanation != null) {
            ExplanationDialog(
                title = activeExplanation!!.first,
                explanation = activeExplanation!!.second,
                onDismiss = { activeExplanation = null }
            )
        }

        if (showDailyNoteDialog) {
            DailyNoteDialog(
                currentNote = currentNote,
                language = language,
                onDismiss = { showDailyNoteDialog = false },
                onSave = { noteText ->
                    viewModel.saveDailyNote(selectedDate, noteText)
                    showDailyNoteDialog = false
                }
            )
        }

        if (selectedReviewYear != null) {
            YearlyReviewDialog(
                year = selectedReviewYear!!,
                allHabits = allHabits,
                allLogs = allLogs,
                language = language,
                viewModel = viewModel,
                onDismiss = { selectedReviewYear = null }
            )
        }

        if (selectedReviewMonth != null) {
            MonthlyReviewDialog(
                year = selectedReviewMonth!!.first,
                month = selectedReviewMonth!!.second,
                allHabits = allHabits,
                allLogs = allLogs,
                language = language,
                viewModel = viewModel,
                onDismiss = { selectedReviewMonth = null }
            )
        }

        if (showRewardsOverview) {
            RewardsOverviewSheet(
                viewModel = viewModel,
                language = language,
                onDismiss = { showRewardsOverview = false }
            )
        }

        if (showReviewExplanation) {
            ExplanationDialog(
                title = if (language == "de") "Rückblicke & Berichte" else if (language == "ka") "მიმოხილვები და ანგარიშები" else "Reviews & Reports",
                explanation = if (language == "de") 
                    """Rückblicke sind Zusammenfassungen deiner Gewohnheiten.

• Sie werden immer am 1. Tag des Folgemonats bzw. Folgejahres freigeschaltet.
• Der Score ist der Durchschnitt aller Habit-Stärken zu diesem Zeitpunkt.
• Du kannst Monats- und Jahresrückblicke einzeln in den Einstellungen aktivieren."""
                else 
                    """Reviews are summaries of your habit progress.

• They are unlocked on the 1st day of the following month or year.
• The score is the average of all habit strengths at that time.
• You can toggle Monthly and Yearly reviews independently in settings.""",
                onDismiss = { showReviewExplanation = false }
            )
        }
        
        ReviewArchiveDialog(
            showReviewArchive = showReviewArchive,
            availableYears = availableYears,
            availableMonths = availableMonths,
            allHabits = allHabits,
            allLogs = allLogs,
            language = language,
            onShowReviewExplanation = { showReviewExplanation = true },
            onSelectReviewMonth = { (y, m) ->
                selectedReviewMonth = y to m
                showReviewArchive = false
            },
            onSelectReviewYear = { y ->
                selectedReviewYear = y
                showReviewArchive = false
            },
            onDismiss = { showReviewArchive = false }
        )
} // Close parent Box
}

@Composable
fun HabitStatItem(
    model: HabitStatModel,
    shortDayNames: List<String>,
    dayNumbers: List<String>,
    language: String,
    onClick: (Int) -> Unit,
    onToggleDay: ((Int, String) -> Unit)? = null
) {
    val habit = model.habit
    val strength = model.strength
    val habitColor = HabitIconMapping.getColor(habit.color)

    val interactionSource = remember { MutableInteractionSource() }
    val isPressed by interactionSource.collectIsPressedAsState()

    val arrowOffsetX by animateDpAsState(
        targetValue = if (isPressed) 8.dp else 0.dp,
        animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessLow),
        label = "habit_stat_arrow_offset"
    )
    val arrowScale by animateFloatAsState(
        targetValue = if (isPressed) 1.25f else 1.0f,
        animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessLow),
        label = "habit_stat_arrow_scale"
    )

    Card(
        colors = CardDefaults.cardColors(containerColor = AppCard),
        shape = RoundedCornerShape(16.dp),
        modifier = Modifier
            .fillMaxWidth()
            .border(1.dp, AppBorder, RoundedCornerShape(16.dp))
            .clickable(
                interactionSource = interactionSource,
                indication = ripple(),
                onClick = { onClick(habit.id) }
            )
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Box(
                        modifier = Modifier
                            .size(36.dp)
                            .background(habitColor.copy(alpha = 0.15f), CircleShape)
                            .border(1.dp, habitColor.copy(alpha = 0.3f), CircleShape),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = HabitIconMapping.getIcon(habit.icon),
                            contentDescription = habit.name,
                            tint = habitColor,
                            modifier = Modifier.size(18.dp)
                        )
                    }
                    Spacer(modifier = Modifier.width(12.dp))
                    Column {
                        Text(
                            text = habit.name,
                            style = MaterialTheme.typography.titleMedium,
                            color = TextPrimary,
                            fontWeight = FontWeight.Bold
                        )
                        Text(
                            text = if (language == "de") "Stärke: $strength" else if (language == "ka") "სიძლიერე: $strength" else "Strength: $strength",
                            style = MaterialTheme.typography.bodyMedium,
                            color = TextSecondary
                        )
                    }
                }

                Icon(
                    imageVector = Icons.Default.KeyboardArrowRight,
                    contentDescription = "View Details",
                    tint = if (isPressed) PrimaryViolet else TextSecondary,
                    modifier = Modifier
                        .offset(x = arrowOffsetX)
                        .scale(arrowScale)
                        .size(24.dp)
                )
            }

            Spacer(modifier = Modifier.height(16.dp))

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                for (i in 0 until 7) {
                    val dayName = shortDayNames.getOrElse(i) { "" }
                    val dayNum = dayNumbers.getOrElse(i) { "" }
                    val status = model.past7DaysStatuses.getOrElse(i) { "INACTIVE" }
                    val dateStr = model.past7DaysDates.getOrNull(i)
                    val cellColor = when (status) {
                        "SUCCESS" -> SuccessGreen
                        "FAILED" -> ErrorRed
                        "PENDING" -> HabitYellow
                        "PAUSED" -> PrimaryViolet.copy(alpha = 0.15f)
                        else -> PrimaryViolet.copy(alpha = 0.15f)
                    }

                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        modifier = Modifier.then(
                            if (dateStr != null && onToggleDay != null) {
                                Modifier.clickable {
                                    onToggleDay(habit.id, dateStr)
                                }
                            } else Modifier
                        )
                    ) {
                        Text(
                            text = dayName,
                            style = MaterialTheme.typography.labelSmall,
                            color = TextSecondary,
                            fontSize = 9.sp
                        )
                        Spacer(modifier = Modifier.height(4.dp))
                        Box(
                            modifier = Modifier
                                .size(24.dp)
                                .clip(RoundedCornerShape(6.dp))
                                .background(cellColor),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = dayNum,
                                style = MaterialTheme.typography.labelSmall,
                                color = if (status == "SUCCESS" || status == "FAILED" || status == "PENDING") AppBg else TextPrimary,
                                fontWeight = FontWeight.Bold,
                                fontSize = 10.sp
                            )
                        }
                    }
                }
            }
        }
    }
}

// HABIT DETAIL SCREEN
@Composable
fun HabitDetailScreen(
    habit: Habit,
    state: HabitDetailUiState?,
    viewModel: HabitsViewModel,
    language: String,
    onBack: () -> Unit
) {
    val context = LocalContext.current
    ClearFocusOnKeyboardDismiss()
    val currentStreak = state?.currentStreak ?: 0
    val longestStreak = state?.longestStreak ?: 0
    val strength = state?.strength ?: 0

    val thisWeekCount = state?.thisWeekCount ?: 0
    val thisMonthCount = state?.thisMonthCount ?: 0
    val thisYearCount = state?.thisYearCount ?: 0
    val totalCount = state?.totalCount ?: 0

    val allDailyNotes by viewModel.allDailyNotes.collectAsStateWithLifecycle()
    var showDeleteConfirm by remember { mutableStateOf(false) }
    var activeExplanation by remember { mutableStateOf<Pair<String, String>?>(null) }

    Box(modifier = Modifier.fillMaxSize().background(AppBg)) {
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(horizontal = 16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp),
            contentPadding = PaddingValues(bottom = 40.dp, top = 84.dp)
        ) {

        // Strength score card
        item(key = "detail_strength") {
            val habitColor = remember(habit.color) { HabitIconMapping.getColor(habit.color) }
            var hasAnimatedDetailStrength by rememberSaveable(habit.id) { mutableStateOf(false) }
            val animStrength = remember(habit.id) { Animatable(if (hasAnimatedDetailStrength) strength.toFloat() else 0f) }

            LaunchedEffect(strength, habit.id) {
                if (!hasAnimatedDetailStrength) {
                    animStrength.snapTo(0f)
                    animStrength.animateTo(
                        targetValue = strength.toFloat(),
                        animationSpec = tween(durationMillis = 750, easing = FastOutSlowInEasing)
                    )
                    hasAnimatedDetailStrength = true
                } else {
                    animStrength.animateTo(
                        targetValue = strength.toFloat(),
                        animationSpec = tween(durationMillis = 300, easing = FastOutSlowInEasing)
                    )
                }
            }
            val animatedStrength = animStrength.value
            val sweepAngleVal = (animatedStrength / 100f) * 360f
            val strengthText = "${animatedStrength.toInt()}"
            val strengthLabel = remember(strength, language) { getStrengthLabel(strength, language) }
            val strengthColor = remember(strength) {
                when {
                    strength < 35 -> HabitRed
                    strength < 70 -> HabitYellow
                    else -> SuccessGreen
                }
            }

            Card(
                colors = CardDefaults.cardColors(containerColor = AppCard),
                shape = RoundedCornerShape(20.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .border(width = 1.dp, color = strengthColor.copy(alpha = 0.5f), shape = RoundedCornerShape(20.dp))
            ) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(14.dp)
                ) {
                    Box(modifier = Modifier.align(Alignment.TopEnd)) {
                        InfoIconButton(
                            title = if (language == "de") "Stärke-Wert" else if (language == "ka") "სიძლიერის ქულა" else "Strength Score",
                            explanation = if (language == "de") {
                                "Die gewichtete Stärke dieser Gewohnheit (0-100) basierend auf den letzten 30 Tagen. Neuere Einträge werden etwas stärker gewichtet, sodass sich dein Score schneller erholen kann. Ausstehende Aufgaben für den heutigen Tag reduzieren den Score nicht, solange sie unmarkiert bleiben."
                            } else {
                                "The strength score of this habit (0-100) based on the last 30 days. Recent entries carry slightly more weight, allowing your score to recover faster. Pending tasks for today do not reduce your score as long as they remain unmarked."
                            },
                            onClick = { t, e -> activeExplanation = t to e }
                        )
                    }

                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 12.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        // Circular Gauge
                        Box(
                            contentAlignment = Alignment.Center,
                            modifier = Modifier
                                .size(84.dp)
                                .drawWithCache {
                                    val strokeWidth = 8.dp.toPx()
                                    val stroke = Stroke(width = strokeWidth, cap = StrokeCap.Round)
                                    onDrawBehind {
                                        drawArc(
                                            color = ProgressTrack,
                                            startAngle = -90f,
                                            sweepAngle = 360f,
                                            useCenter = false,
                                            style = stroke
                                        )
                                        drawArc(
                                            color = strengthColor,
                                            startAngle = -90f,
                                            sweepAngle = sweepAngleVal,
                                            useCenter = false,
                                            style = stroke
                                        )
                                    }
                                }
                        ) {
                            Text(
                                text = strengthText,
                                style = MaterialTheme.typography.titleLarge,
                                fontSize = 24.sp,
                                color = TextPrimary,
                                fontWeight = FontWeight.ExtraBold
                            )
                        }

                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(2.dp)
                        ) {
                            Text(
                                text = if (language == "de") "GEWOHNHEITS-STÄRKE" else if (language == "ka") "ჩვევის სიძლიერე" else "HABIT STRENGTH",
                                style = MaterialTheme.typography.labelSmall,
                                color = TextSecondary,
                                fontWeight = FontWeight.Bold,
                                letterSpacing = 0.5.sp
                            )
                            Text(
                                text = strengthLabel,
                                style = MaterialTheme.typography.bodyLarge,
                                color = strengthColor,
                                fontWeight = FontWeight.ExtraBold
                            )
                        }
                    }
                }
            }
        }

        // Description card (direkt unter dem Stärke-Feld)
        if (habit.description.isNotBlank()) {
            item(key = "detail_description") {
                Card(
                    colors = CardDefaults.cardColors(containerColor = AppCard),
                    shape = RoundedCornerShape(20.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .border(1.dp, AppBorder, RoundedCornerShape(20.dp))
                ) {
                    Column(modifier = Modifier.padding(16.dp)) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(32.dp)
                                    .background(PrimaryViolet.copy(alpha = 0.15f), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Description,
                                    contentDescription = "Beschreibung",
                                    tint = PrimaryViolet,
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                            Text(
                                text = if (language == "de") "BESCHREIBUNG" else if (language == "ka") "აღწერა" else "DESCRIPTION",
                                style = MaterialTheme.typography.labelMedium,
                                color = TextSecondary,
                                fontWeight = FontWeight.Bold,
                                letterSpacing = 0.5.sp
                            )
                        }
                        Spacer(modifier = Modifier.height(10.dp))
                        Text(
                            text = habit.description,
                            style = MaterialTheme.typography.bodyMedium,
                            color = TextPrimary,
                            lineHeight = 20.sp
                        )
                    }
                }
            }
        }

        // Streaks cards (Two separate individual cards)
        item(key = "detail_streaks") {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                // Current streak card
                Card(
                    colors = CardDefaults.cardColors(containerColor = AppCard),
                    shape = RoundedCornerShape(20.dp),
                    modifier = Modifier
                        .weight(1f)
                        .border(1.dp, if (currentStreak > 0) PrimaryViolet.copy(alpha = 0.5f) else AppBorder, RoundedCornerShape(20.dp))
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp)
                    ) {
                        // Info icon placed in the top right corner
                        Box(modifier = Modifier.align(Alignment.TopEnd)) {
                            InfoIconButton(
                                title = if (language == "de") "Aktueller Streak" else if (language == "ka") "მიმდინარე სტრიქონი" else "Current Streak",
                                explanation = if (language == "de") {
                                    "Die Anzahl der aufeinanderfolgenden Tage, an denen du diese Gewohnheit bis heute erfolgreich abgeschlossen hast."
                                } else if (language == "ka") {
                        "ზედიზედ რამდენი დღე დაასრულეთ ეს ჩვევა დღემდე."
                    } else {
                        "The number of consecutive days you have completed this habit up to today."
                    },
                                onClick = { t, e -> activeExplanation = t to e }
                            )
                        }

                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 10.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(44.dp)
                                    .background(PrimaryViolet.copy(alpha = 0.15f), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Whatshot,
                                    contentDescription = "Current streak",
                                    tint = PrimaryViolet,
                                    modifier = Modifier.size(24.dp)
                                )
                            }
                            
                            Text(
                                text = if (language == "de") "Aktuelle Serie" else if (language == "ka") "მიმდინარე სერი" else "Current streak",
                                style = MaterialTheme.typography.labelLarge,
                                color = TextSecondary,
                                fontWeight = FontWeight.Bold,
                                textAlign = TextAlign.Center,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                            
                            Text(
                                text = if (language == "de") "$currentStreak ${if (currentStreak == 1) "Tag" else "Tage"}" else "$currentStreak ${if (currentStreak == 1) "Day" else "Days"}",
                                style = MaterialTheme.typography.headlineMedium,
                                fontSize = 22.sp,
                                color = TextPrimary,
                                fontWeight = FontWeight.ExtraBold,
                                textAlign = TextAlign.Center
                            )
                        }
                    }
                }

                // Best/longest streak card
                Card(
                    colors = CardDefaults.cardColors(containerColor = AppCard),
                    shape = RoundedCornerShape(20.dp),
                    modifier = Modifier
                        .weight(1f)
                        .border(1.dp, if (longestStreak > 0) PrimaryViolet.copy(alpha = 0.5f) else AppBorder, RoundedCornerShape(20.dp))
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp)
                    ) {
                        // Info icon placed in the top right corner
                        Box(modifier = Modifier.align(Alignment.TopEnd)) {
                            InfoIconButton(
                                title = if (language == "de") "Längster Streak" else if (language == "ka") "ყველაზე გრძელი სერია" else "Longest Streak",
                                explanation = if (language == "de") {
                                    "Deine historische Bestleistung an aufeinanderfolgenden Tagen, an denen du diese Gewohnheit abgeschlossen hast."
                                } else if (language == "ka") {
                        "თქვენი უმაღლესი ისტორიული ჩანაწერი ზედიზედ დღეებში ამ ჩვევის დასრულების შესახებ."
                    } else {
                        "Your highest historical record of consecutive days completing this habit."
                    },
                                onClick = { t, e -> activeExplanation = t to e }
                            )
                        }

                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 10.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(44.dp)
                                    .background(PrimaryViolet.copy(alpha = 0.15f), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Default.EmojiEvents,
                                    contentDescription = "Longest streak",
                                    tint = PrimaryViolet,
                                    modifier = Modifier.size(24.dp)
                                )
                            }
                            
                            Text(
                                text = if (language == "de") "Beste Serie" else if (language == "ka") "საუკეთესო სერია" else "Best streak",
                                style = MaterialTheme.typography.labelLarge,
                                color = TextSecondary,
                                fontWeight = FontWeight.Bold,
                                textAlign = TextAlign.Center,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                            
                            Text(
                                text = if (language == "de") "$longestStreak ${if (longestStreak == 1) "Tag" else "Tage"}" else "$longestStreak ${if (longestStreak == 1) "Day" else "Days"}",
                                style = MaterialTheme.typography.headlineMedium,
                                fontSize = 22.sp,
                                color = TextPrimary,
                                fontWeight = FontWeight.ExtraBold,
                                textAlign = TextAlign.Center
                            )
                        }
                    }
                }
            }
        }

        // Target Performance Card (Only shown for numerical habits!)
        if (habit.type == "NUMBER" || habit.type == "NUMERICAL") {
            item(key = "detail_target_performance") {
                HabitTargetSection(
                    state = state,
                    language = language
                )
            }
        }

        // Calendar Grid Card
        item(key = "detail_calendar") {
            Card(
                colors = CardDefaults.cardColors(containerColor = AppCard),
                shape = RoundedCornerShape(16.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .border(1.dp, AppBorder, RoundedCornerShape(16.dp))
            ) {
                Column(modifier = Modifier.padding(12.dp)) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier.fillMaxWidth().padding(bottom = 10.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(26.dp)
                                .background(PrimaryViolet.copy(alpha = 0.18f), CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Default.DateRange,
                                contentDescription = "Calendar",
                                tint = PrimaryViolet,
                                modifier = Modifier.size(16.dp)
                            )
                        }
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = if (language == "de") "KALENDER" else if (language == "ka") "კალენდარი" else "CALENDAR",
                            style = MaterialTheme.typography.labelSmall,
                            color = TextSecondary,
                            fontWeight = FontWeight.Bold
                        )
                        Spacer(modifier = Modifier.width(4.dp))
                        InfoIconButton(
                            title = if (language == "de") "Kalender-Historie" else if (language == "ka") "კალენდრის ისტორია" else "Calendar History",
                            explanation = if (language == "de") {
                                "Bietet eine vollständige Monatsübersicht deiner Abschlüsse. Grün steht für erfolgreiche Tage, Rot für fehlgeschlagene Tage, Gelb für ausstehende Tage und Dunkelgrau für inaktive Tage oder Pausen."
                            } else if (language == "ka") {
                        "გთავაზობთ თქვენი დასრულებების სრულ ყოველთვიურ მიმოხილვას. მწვანე წარმოადგენს წარმატებულ დღეს, წითელი წარმოადგენს წარუმატებელ დღეს, ყვითელი/ქარვისფერი წარმოადგენს მომლოდინე ჟურნალს, ხოლო მუქი ნაცრისფერი მიუთითებს არააქტიურ/დასვენების დღეებზე."
                    } else {
                        "Provides a full monthly overview of your completions. Green represents a successful day, red represents a failed day, yellow/amber represents a pending log, and dark grey indicates inactive/rest days."
                    },
                            onClick = { t, e -> activeExplanation = t to e }
                        )
                        Spacer(modifier = Modifier.weight(1f))
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.padding(end = 4.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.TouchApp,
                                contentDescription = null,
                                tint = TextSecondary.copy(alpha = 0.7f),
                                modifier = Modifier.size(14.dp)
                            )
                            Spacer(modifier = Modifier.width(4.dp))
                            Text(
                                text = if (language == "de") "Interaktiv" else if (language == "ka") "ინტერაქტიული" else "Interactive",
                                style = MaterialTheme.typography.labelSmall,
                                color = TextSecondary.copy(alpha = 0.7f),
                                fontWeight = FontWeight.Medium
                            )
                        }
                    }

                    val habitColor = HabitIconMapping.getColor(habit.color)
                    CalendarMonthGrid(
                        gridRows = state?.calendarGridRows ?: emptyList(),
                        monthName = state?.monthName ?: "",
                        habitColor = habitColor,
                        language = language,
                        canPrevMonth = state?.canPrevMonth ?: true,
                        canNextMonth = state?.canNextMonth ?: true,
                        onPrevMonth = { viewModel.navigateCalendarMonth(-1) },
                        onNextMonth = { viewModel.navigateCalendarMonth(1) },
                        onDayClick = { dateStr ->
                            viewModel.toggleBinaryHabit(habit.id, dateStr, false)
                        }
                    )
                }
            }
        }

        // Overall Success Rate Card (Donut Chart)
        item(key = "detail_success_rate") {
            var selectedTimeframeIndex by rememberSaveable(habit.id) { mutableIntStateOf(0) }
            val allLogs by viewModel.allLogs.collectAsStateWithLifecycle()

            val stats = remember(habit, allLogs, selectedTimeframeIndex) {
                calculateHabitSuccessStatsForPeriod(
                    habit = habit,
                    logs = allLogs,
                    periodIndex = selectedTimeframeIndex
                )
            }

            SuccessRateCard(
                title = if (language == "de") "Erfolgsquote" else if (language == "ka") "წარმატების მაჩვენებელი" else "Success Rate",
                doneCount = stats.doneCount,
                missedCount = stats.missedCount,
                skippedCount = stats.skippedCount,
                pendingCount = stats.pendingCount,
                language = language,
                infoTitle = if (language == "de") "Erfolgsquote" else if (language == "ka") "წარმატების მაჩვენებელი" else "Success Rate",
                infoExplanation = if (language == "de") {
                    "Aufschlüsselung aller aktiven Tage im gewählten Zeitraum nach Status: Erreicht, Gescheitert, Skipped und Ausstehend."
                } else if (language == "ka") {
                        "არჩეულ პერიოდში ყველა დაგეგმილი დღის დაყოფა სტატუსის მიხედვით: დასრულებული, გამოტოვებული, გამოტოვებული და მომლოდინე."
                    } else {
                        "Breakdown of all scheduled days in the selected period by status: Done, Missed, Skipped, and Pending."
                    },
                onInfoClick = { t, e -> activeExplanation = t to e },
                showTimeframeSelector = true,
                selectedTimeframeIndex = selectedTimeframeIndex,
                onTimeframeSelected = { selectedTimeframeIndex = it }
            )
        }

        // 6. Habit Score Trend Card (Line Chart)
        item(key = "detail_score_trend") {
            val allLogs by viewModel.allLogs.collectAsStateWithLifecycle()
            HabitScoreTrendCard(
                habit = habit,
                logs = allLogs,
                language = language,
                onInfoClick = { t, e -> activeExplanation = t to e }
            )
        }

        // 7. Completion Volume Progression Card (Bar Chart)
        item(key = "detail_volume_progression") {
            val allLogs by viewModel.allLogs.collectAsStateWithLifecycle()
            HabitVolumeProgressionCard(
                habit = habit,
                logs = allLogs,
                language = language,
                onInfoClick = { t, e -> activeExplanation = t to e }
            )
        }

        // Weekday Frequency Section (For ALL habits!)
        item(key = "detail_frequency") {
            WeekdayFrequencySection(
                weekdayStats = state?.weekdayStats ?: emptyList(),
                gridData = state?.weekdayGridData ?: emptyList(),
                weeksWithMonthLabels = state?.weeksWithMonthLabels ?: emptyList(),
                language = language,
                onInfoClick = { t, e -> activeExplanation = t to e },
                allDailyNotes = allDailyNotes
            )
        }
    }

    if (showDeleteConfirm) {
        AlertDialog(
            onDismissRequest = { showDeleteConfirm = false },
            title = { Text(text = if (language == "de") "Habit löschen?" else if (language == "ka") "წაშალოთ ჩვევა?" else "Delete Habit?") },
            text = { Text(text = if (language == "de") "Möchtest du diese Gewohnheit wirklich unwiderruflich löschen?" else if (language == "ka") "დარწმუნებული ხართ, რომ გსურთ სამუდამოდ წაშალოთ ეს ჩვევა?" else "Are you sure you want to delete this habit permanently?") },
            confirmButton = {
                TextButton(
                    onClick = {
                        viewModel.deleteHabit(habit)
                        showDeleteConfirm = false
                        Toast.makeText(
                            context,
                            if (language == "de") "Gewohnheit gelöscht" else if (language == "ka") "ჩვევა წაშლილია" else "Habit deleted",
                            Toast.LENGTH_SHORT
                        ).show()
                    },
                    colors = ButtonDefaults.textButtonColors(contentColor = ErrorRed)
                ) {
                    Text(if (language == "de") "Löschen" else if (language == "ka") "წაშლა" else "Delete")
                }
            },
            dismissButton = {
                TextButton(onClick = { showDeleteConfirm = false }) {
                    Text(text = if (language == "de") "Abbrechen" else if (language == "ka") "გაუქმება" else "Cancel")
                }
            }
        )
    }

    if (activeExplanation != null) {
        ExplanationDialog(
            title = activeExplanation!!.first,
            explanation = activeExplanation!!.second,
            onDismiss = { activeExplanation = null }
        )
    }

    // Floating Header Overlay with vertical gradient fade-out
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(84.dp)
            .background(
                Brush.verticalGradient(
                    colors = listOf(
                        AppBg,
                        AppBg,
                        AppBg.copy(alpha = 0.9f),
                        AppBg.copy(alpha = 0.5f),
                        Color.Transparent
                    )
                )
            )
            .align(Alignment.TopCenter)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(start = 16.dp, top = 16.dp, end = 16.dp, bottom = 8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            ModernBackButton(onClick = onBack)
            Spacer(modifier = Modifier.width(16.dp))
            Text(
                text = habit.name,
                style = MaterialTheme.typography.displayMedium,
                color = TextPrimary,
                fontWeight = FontWeight.Bold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.weight(1f)
            )
        }
    }
}
}

@SuppressLint("NewApi")
@Composable
fun WeekdayFrequencySection(
    weekdayStats: List<Triple<Int, Int, Int>>,
    gridData: List<List<Pair<java.time.LocalDate, String>>>,
    weeksWithMonthLabels: List<String>,
    language: String,
    onInfoClick: (String, String) -> Unit,
    allDailyNotes: List<com.example.data.DailyNote> = emptyList()
) {
    val daysAbbr = if (language == "de") {
        listOf("Mo", "Di", "Mi", "Do", "Fr", "Sa", "So")
    } else {
        listOf("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
    }

    Card(
        colors = CardDefaults.cardColors(containerColor = AppCard),
        shape = RoundedCornerShape(20.dp),
        modifier = Modifier
            .fillMaxWidth()
            .border(1.dp, AppBorder, RoundedCornerShape(20.dp))
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            // Header
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.fillMaxWidth()
            ) {
                Box(
                    modifier = Modifier
                        .size(26.dp)
                        .background(PrimaryViolet.copy(alpha = 0.18f), CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.Default.Equalizer,
                        contentDescription = "Frequency",
                        tint = PrimaryViolet,
                        modifier = Modifier.size(16.dp)
                    )
                }
                Spacer(modifier = Modifier.width(8.dp))
                Text(
                    text = if (language == "de") "WOCHENTAGS-FREQUENZ" else if (language == "ka") "კვირის სიხშირე" else "WEEKDAY FREQUENCY",
                    style = MaterialTheme.typography.labelSmall,
                    color = TextSecondary,
                    fontWeight = FontWeight.Bold
                )
                Spacer(modifier = Modifier.width(4.dp))
                InfoIconButton(
                    title = if (language == "de") "Wochentags-Frequenz" else if (language == "ka") "სამუშაო დღეების სიხშირე" else "Weekday Frequency",
                    explanation = if (language == "de") {
                        "Zeigt, an welchen Wochentagen du diese Gewohnheit historisch am häufigsten abgeschlossen hast. Je heller der Kreis, desto höher die Erfolgsquote."
                    } else {
                        "Shows on which weekdays you have historically completed this habit most often. The brighter the circle, the higher your completion rate."
                    },
                    onClick = onInfoClick
                )
            }

            Spacer(modifier = Modifier.height(16.dp))

            // 1. Horizontal circles for each of the 7 weekdays
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                weekdayStats.forEach { (index, completed, pct) ->
                    val dayName = daysAbbr[index]
                    val circleBgColor = when {
                        pct == 0 -> ProgressTrack
                        pct <= 25 -> PrimaryViolet.copy(alpha = 0.15f)
                        pct <= 50 -> PrimaryViolet.copy(alpha = 0.40f)
                        pct <= 75 -> PrimaryViolet.copy(alpha = 0.70f)
                        else -> PrimaryViolet
                    }
                    val textColor = if (pct > 50) Color.White else TextPrimary

                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(36.dp)
                                .clip(CircleShape)
                                .background(circleBgColor)
                                .border(1.dp, if (pct == 0) AppBorder else PrimaryViolet.copy(alpha = 0.5f), CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = dayName.take(2),
                                style = MaterialTheme.typography.labelSmall,
                                color = textColor,
                                fontWeight = FontWeight.Bold,
                                fontSize = 10.sp
                            )
                        }
                        Text(
                            text = "$pct%",
                            style = MaterialTheme.typography.labelSmall,
                            color = TextSecondary,
                            fontSize = 9.sp,
                            fontWeight = FontWeight.Medium
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(24.dp))

            // 2. Git-style Weekly Heatmap (Last 15 Weeks)
            Text(
                text = if (language == "de") "AKTIVITÄT (LETZTE 15 WOCHEN)" else if (language == "ka") "აქტივობა (ბოლო 15 კვირა)" else "ACTIVITY (LAST 15 WEEKS)",
                style = MaterialTheme.typography.labelSmall,
                color = TextSecondary,
                fontWeight = FontWeight.Bold,
                fontSize = 10.sp,
                modifier = Modifier.padding(bottom = 8.dp)
            )

            Column(modifier = Modifier.fillMaxWidth()) {
                // 7 weekday rows with background line and evenly spaced circles
                for (dayIndex in 0 until 7) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 4.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier.weight(1f),
                            contentAlignment = Alignment.CenterStart
                        ) {
                            // Subtle background line for track
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(1.dp)
                                    .background(AppBorder.copy(alpha = 0.4f))
                            )

                            // Row of circles for each week
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                gridData.forEach { weekDays ->
                                    val cell = weekDays[dayIndex]
                                    val dateStr = cell.first.toString()
                                    val status = cell.second
                                    val hasNote = remember(allDailyNotes, dateStr) {
                                        allDailyNotes.any { it.date == dateStr && it.content.isNotBlank() }
                                    }
                                    
                                    val isSuccess = status == "SUCCESS"
                                    val size = if (isSuccess) 14.dp else 4.dp
                                    val color = when (status) {
                                        "SUCCESS" -> PrimaryViolet
                                        "FAILED" -> ProgressTrack
                                        else -> ProgressTrack.copy(alpha = 0.3f)
                                    }

                                    Box(
                                        modifier = Modifier.size(14.dp),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .size(size)
                                                .background(color, CircleShape)
                                        )
                                    }
                                }
                            }
                        }

                        Spacer(modifier = Modifier.width(12.dp))

                        // Weekday label on the right side
                        Box(
                            modifier = Modifier.width(28.dp),
                            contentAlignment = Alignment.CenterEnd
                        ) {
                            Text(
                                text = daysAbbr[dayIndex].take(2),
                                style = MaterialTheme.typography.labelSmall,
                                color = TextSecondary,
                                fontSize = 9.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(8.dp))

                // 3. Month labels row aligned beautifully with the week columns above
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(
                        modifier = Modifier.weight(1f),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        gridData.forEachIndexed { index, _ ->
                            val label = weeksWithMonthLabels[index]
                            Box(
                                modifier = Modifier.width(14.dp),
                                contentAlignment = Alignment.CenterStart
                            ) {
                                if (label.isNotEmpty()) {
                                    Text(
                                        text = label,
                                        style = MaterialTheme.typography.labelSmall,
                                        color = TextSecondary,
                                        fontSize = 8.sp,
                                        fontWeight = FontWeight.Bold,
                                        maxLines = 1,
                                        softWrap = false,
                                        modifier = Modifier.wrapContentWidth(unbounded = true, align = Alignment.Start)
                                    )
                                }
                            }
                        }
                    }
                    Spacer(modifier = Modifier.width(40.dp)) // Matches 12.dp spacer + 28.dp label
                }
            }
        }
    }
}

@Composable
fun HabitTargetSection(
    state: HabitDetailUiState?,
    language: String
) {
    val stats = state?.targetStats ?: return
    val habit = state.habit

    Card(
        colors = CardDefaults.cardColors(containerColor = AppCard),
        shape = RoundedCornerShape(20.dp),
        modifier = Modifier
            .fillMaxWidth()
            .border(1.dp, AppBorder, RoundedCornerShape(20.dp))
    ) {
        Column(modifier = Modifier.padding(20.dp)) {
            // Header
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.padding(bottom = 16.dp)
            ) {
                Box(
                    modifier = Modifier
                        .size(26.dp)
                        .background(PrimaryViolet.copy(alpha = 0.18f), CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.Default.Adjust,
                        contentDescription = "Target",
                        tint = PrimaryViolet,
                        modifier = Modifier.size(16.dp)
                    )
                }
                Spacer(modifier = Modifier.width(8.dp))
                Text(
                    text = if (language == "de") "ZIERLEISTUNG (ZIEL)" else if (language == "ka") "მიზნობრივი შესრულება" else "TARGET PERFORMANCE",
                    style = MaterialTheme.typography.labelSmall,
                    color = TextSecondary,
                    fontWeight = FontWeight.Bold
                )
            }

            // Today, Week, Month, Year rows (omit Quarter)
            val periodLabels = if (language == "de") {
                listOf("Heute", "Woche", "Monat", "Jahr")
            } else {
                listOf("Today", "Week", "Month", "Year")
            }

            val periodStatsList = listOf(
                stats.today,
                stats.week,
                stats.month,
                stats.year
            )

            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                periodLabels.zip(periodStatsList).forEach { (label, periodStat) ->
                    TargetProgressRow(
                        label = label,
                        actual = periodStat.actualValue,
                        target = periodStat.targetValue,
                        isNumerical = periodStat.isNumerical,
                        unit = habit.unit,
                        language = language
                    )
                }
            }
        }
    }
}

@Composable
fun TargetProgressRow(
    label: String,
    actual: Float,
    target: Float,
    isNumerical: Boolean,
    unit: String,
    language: String
) {
    Column(
        modifier = Modifier.fillMaxWidth()
    ) {
        val progressFraction = remember(actual, target) {
            if (target > 0f) (actual / target).coerceIn(0f, 1f) else 0f
        }
        var hasAnimatedTargetRow by rememberSaveable(actual, target) { mutableStateOf(false) }
        val animFraction = remember { Animatable(if (hasAnimatedTargetRow) progressFraction else 0f) }

        LaunchedEffect(progressFraction) {
            if (!hasAnimatedTargetRow) {
                animFraction.snapTo(0f)
                animFraction.animateTo(
                    targetValue = progressFraction,
                    animationSpec = tween(durationMillis = 700, easing = FastOutSlowInEasing)
                )
                hasAnimatedTargetRow = true
            } else {
                animFraction.animateTo(
                    targetValue = progressFraction,
                    animationSpec = tween(durationMillis = 300, easing = FastOutSlowInEasing)
                )
            }
        }
        val animatedProgressFraction = animFraction.value
        val hasOverachieved = remember(actual, target) {
            target > 0f && actual > target
        }

        val formattedActual = remember(actual) {
            if (actual % 1f == 0f) actual.toInt().toString() else String.format(Locale.US, "%.1f", actual)
        }
        val formattedTarget = remember(target) {
            if (target % 1f == 0f) target.toInt().toString() else String.format(Locale.US, "%.1f", target)
        }
        val unitSuffix = remember(isNumerical, unit) {
            if (isNumerical && unit.isNotEmpty()) " $unit" else ""
        }

        // Row 1: Period label and Value text
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            // Period label (e.g. Heute, Woche, etc.)
            Text(
                text = label,
                style = MaterialTheme.typography.bodyMedium,
                color = TextSecondary,
                fontWeight = FontWeight.Bold
            )

            // Value text
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text(
                    text = "$formattedActual$unitSuffix",
                    style = MaterialTheme.typography.bodyMedium,
                    color = TextPrimary,
                    fontWeight = FontWeight.Bold
                )

                if (target > 0f) {
                    val formattedDiff = remember(actual, target) {
                        val diff = actual - target
                        if (diff % 1f == 0f) diff.toInt().toString() else String.format(Locale.US, "%.1f", diff)
                    }
                    val targetLabel = remember(language, formattedTarget, unitSuffix) {
                        if (language == "de") " / Ziel: $formattedTarget$unitSuffix" else if (language == "ka") "/ სამიზნე: $formattedTarget $unitSuffix" else " / Target: $formattedTarget$unitSuffix"
                    }

                    Text(
                        text = buildAnnotatedString {
                            append(targetLabel)
                            if (hasOverachieved) {
                                withStyle(style = SpanStyle(color = Color(0xFF4ADE80), fontWeight = FontWeight.Bold)) {
                                    append(" (+$formattedDiff$unitSuffix)")
                                }
                            }
                        },
                        style = MaterialTheme.typography.bodySmall,
                        color = TextSecondary,
                        fontWeight = FontWeight.Medium,
                        modifier = Modifier.padding(start = 4.dp)
                    )
                } else {
                    Text(
                        text = if (language == "de") " (Kein Ziel)" else if (language == "ka") "(სამიზნე არ არის)" else " (No Target)",
                        style = MaterialTheme.typography.bodySmall,
                        color = TextSecondary,
                        fontWeight = FontWeight.Normal,
                        modifier = Modifier.padding(start = 4.dp)
                    )
                }
            }
        }

        Spacer(modifier = Modifier.height(6.dp))

        // Row 2: Progress bar
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(10.dp)
                .clip(RoundedCornerShape(5.dp))
                .background(AppBorder)
        ) {
            // Progress bar (colored portion)
            Box(
                modifier = Modifier
                    .fillMaxHeight()
                    .fillMaxWidth(if (animatedProgressFraction > 0f) animatedProgressFraction else 0.001f)
                    .clip(RoundedCornerShape(5.dp))
                    .background(
                        if (hasOverachieved) {
                            Brush.horizontalGradient(
                                colors = listOf(PrimaryViolet, SuccessGreen)
                            )
                        } else {
                            SolidColor(PrimaryViolet)
                        }
                    )
            )
        }
    }
}

// Data model and helpers for Trends & Progression
data class TrendPoint(
    val label: String,
    val score: Float,
    val completions: Int
)

fun getWeekOfYear(date: java.time.LocalDate): Int {
    val cal = java.util.Calendar.getInstance()
    cal.set(date.year, date.monthValue - 1, date.dayOfMonth)
    return cal.get(java.util.Calendar.WEEK_OF_YEAR)
}

fun getHabitStartLocalDate(habit: Habit): java.time.LocalDate {
    val validStartMillis = if (habit.startDate > 946684800000L) habit.startDate else habit.createdAt
    return try {
        java.time.Instant.ofEpochMilli(validStartMillis).atZone(java.time.ZoneId.systemDefault()).toLocalDate()
    } catch (e: Exception) {
        java.time.LocalDate.of(2024, 1, 1)
    }
}

fun calculateHabitAverageScoreInRange(
    habit: Habit,
    logs: List<HabitLog>,
    startDate: java.time.LocalDate,
    endDate: java.time.LocalDate
): Float {
    if (startDate.isAfter(endDate)) return 0f
    val today = java.time.LocalDate.now()
    val actualEnd = if (endDate.isAfter(today)) today else endDate
    
    val habitStartDate = getHabitStartLocalDate(habit)
    val effectiveStart = if (startDate.isBefore(habitStartDate)) habitStartDate else startDate

    if (effectiveStart.isAfter(actualEnd)) return 0f

    val totalDays = java.time.temporal.ChronoUnit.DAYS.between(effectiveStart, actualEnd) + 1
    if (totalDays <= 0) return 0f

    val step = if (totalDays > 180) 5L else 1L
    var sum = 0f
    var count = 0
    var curr = effectiveStart
    while (!curr.isAfter(actualEnd)) {
        sum += calculateHabitStrengthOnDate(habit, logs, curr.toString()).toFloat()
        count++
        curr = curr.plusDays(step)
    }
    return if (count > 0) (sum / count).coerceIn(0f, 100f) else 0f
}

fun calculateOverallAverageScoreInRange(
    activeHabits: List<Habit>,
    allLogs: List<HabitLog>,
    startDate: java.time.LocalDate,
    endDate: java.time.LocalDate
): Float {
    if (activeHabits.isEmpty() || startDate.isAfter(endDate)) return 0f
    val today = java.time.LocalDate.now()
    val actualEnd = if (endDate.isAfter(today)) today else endDate
    if (startDate.isAfter(actualEnd)) return 0f

    val habitsWithStart = activeHabits.map { habit ->
        habit to getHabitStartLocalDate(habit)
    }

    val earliestHabitStart = habitsWithStart.minOfOrNull { it.second } ?: startDate
    val effectiveStart = if (startDate.isBefore(earliestHabitStart)) earliestHabitStart else startDate

    if (effectiveStart.isAfter(actualEnd)) return 0f

    val totalDays = java.time.temporal.ChronoUnit.DAYS.between(effectiveStart, actualEnd) + 1
    if (totalDays <= 0) return 0f

    val step = if (totalDays > 180) 7L else 1L
    var sum = 0f
    var count = 0
    var curr = effectiveStart
    while (!curr.isAfter(actualEnd)) {
        val currDate = curr
        val habitsOnCurr = habitsWithStart.filter { !it.second.isAfter(currDate) }.map { it.first }
        if (habitsOnCurr.isNotEmpty()) {
            val dateStr = currDate.toString()
            val dailyAvg = habitsOnCurr.map { calculateHabitStrengthOnDate(it, allLogs, dateStr) }.average().toFloat()
            sum += dailyAvg
            count++
        }
        curr = curr.plusDays(step)
    }
    return if (count > 0) (sum / count).coerceIn(0f, 100f) else 0f
}

fun calculateHabitTrendPoints(
    habit: Habit,
    logs: List<HabitLog>,
    timeframeIndex: Int
): List<TrendPoint> {
    val today = java.time.LocalDate.now()
    val points = mutableListOf<TrendPoint>()

    when (timeframeIndex) {
        0 -> { // Weekly
            for (i in 5 downTo 0) {
                val weekStart = today.minusWeeks(i.toLong()).with(java.time.temporal.TemporalAdjusters.previousOrSame(java.time.DayOfWeek.MONDAY))
                val weekEnd = weekStart.plusDays(6)
                val score = calculateHabitAverageScoreInRange(habit, logs, weekStart, weekEnd)
                val weekNum = getWeekOfYear(weekStart)
                val label = "KW$weekNum"
                points.add(TrendPoint(label, score, 0))
            }
        }
        1 -> { // Monthly
            for (i in 5 downTo 0) {
                val monthDate = today.minusMonths(i.toLong())
                val startOfMonth = monthDate.withDayOfMonth(1)
                val endOfMonth = monthDate.withDayOfMonth(monthDate.lengthOfMonth())
                val score = calculateHabitAverageScoreInRange(habit, logs, startOfMonth, endOfMonth)
                val monthName = monthDate.month.getDisplayName(java.time.format.TextStyle.SHORT, java.util.Locale.getDefault())
                points.add(TrendPoint(monthName, score, 0))
            }
        }
        2 -> { // Yearly
            for (i in 3 downTo 0) {
                val yearDate = today.minusYears(i.toLong())
                val startOfYear = yearDate.withDayOfYear(1)
                val endOfYear = yearDate.withDayOfYear(yearDate.lengthOfYear())
                val score = calculateHabitAverageScoreInRange(habit, logs, startOfYear, endOfYear)
                val yearLabel = yearDate.year.toString()
                points.add(TrendPoint(yearLabel, score, 0))
            }
        }
    }
    return points
}

fun calculateOverallTrendPoints(
    allHabits: List<Habit>,
    allLogs: List<HabitLog>,
    timeframeIndex: Int
): List<TrendPoint> {
    val today = java.time.LocalDate.now()
    val points = mutableListOf<TrendPoint>()
    val activeHabits = allHabits.filter { !it.isArchived }

    if (activeHabits.isEmpty()) {
        val labels = when (timeframeIndex) {
            0 -> (5 downTo 0).map { i ->
                val weekStart = today.minusWeeks(i.toLong()).with(java.time.temporal.TemporalAdjusters.previousOrSame(java.time.DayOfWeek.MONDAY))
                "KW${getWeekOfYear(weekStart)}"
            }
            1 -> (5 downTo 0).map { i ->
                today.minusMonths(i.toLong()).month.getDisplayName(java.time.format.TextStyle.SHORT, java.util.Locale.getDefault())
            }
            else -> (3 downTo 0).map { i ->
                today.minusYears(i.toLong()).year.toString()
            }
        }
        return labels.map { TrendPoint(it, 0f, 0) }
    }

    when (timeframeIndex) {
        0 -> { // Weekly
            for (i in 5 downTo 0) {
                val weekStart = today.minusWeeks(i.toLong()).with(java.time.temporal.TemporalAdjusters.previousOrSame(java.time.DayOfWeek.MONDAY))
                val weekEnd = weekStart.plusDays(6)
                val score = calculateOverallAverageScoreInRange(activeHabits, allLogs, weekStart, weekEnd)
                val weekNum = getWeekOfYear(weekStart)
                val label = "KW$weekNum"
                points.add(TrendPoint(label, score, 0))
            }
        }
        1 -> { // Monthly
            for (i in 5 downTo 0) {
                val monthDate = today.minusMonths(i.toLong())
                val startOfMonth = monthDate.withDayOfMonth(1)
                val endOfMonth = monthDate.withDayOfMonth(monthDate.lengthOfMonth())
                val score = calculateOverallAverageScoreInRange(activeHabits, allLogs, startOfMonth, endOfMonth)
                val monthName = monthDate.month.getDisplayName(java.time.format.TextStyle.SHORT, java.util.Locale.getDefault())
                points.add(TrendPoint(monthName, score, 0))
            }
        }
        2 -> { // Yearly
            for (i in 3 downTo 0) {
                val yearDate = today.minusYears(i.toLong())
                val startOfYear = yearDate.withDayOfYear(1)
                val endOfYear = yearDate.withDayOfYear(yearDate.lengthOfYear())
                val score = calculateOverallAverageScoreInRange(activeHabits, allLogs, startOfYear, endOfYear)
                val yearLabel = yearDate.year.toString()
                points.add(TrendPoint(yearLabel, score, 0))
            }
        }
    }
    return points
}

fun calculateOverallVolumePoints(
    allHabits: List<Habit>,
    allLogs: List<HabitLog>,
    timeframeIndex: Int
): List<TrendPoint> {
    val today = java.time.LocalDate.now()
    val points = mutableListOf<TrendPoint>()
    val activeHabits = allHabits.filter { !it.isArchived }

    if (activeHabits.isEmpty()) {
        val labels = when (timeframeIndex) {
            0 -> (5 downTo 0).map { i ->
                val weekStart = today.minusWeeks(i.toLong()).with(java.time.temporal.TemporalAdjusters.previousOrSame(java.time.DayOfWeek.MONDAY))
                "KW${getWeekOfYear(weekStart)}"
            }
            1 -> (5 downTo 0).map { i ->
                today.minusMonths(i.toLong()).month.getDisplayName(java.time.format.TextStyle.SHORT, java.util.Locale.getDefault())
            }
            else -> (3 downTo 0).map { i ->
                today.minusYears(i.toLong()).year.toString()
            }
        }
        return labels.map { TrendPoint(it, 0f, 0) }
    }

    when (timeframeIndex) {
        0 -> { // Weekly (Last 6 weeks)
            for (i in 5 downTo 0) {
                val weekStart = today.minusWeeks(i.toLong()).with(java.time.temporal.TemporalAdjusters.previousOrSame(java.time.DayOfWeek.MONDAY))
                val weekEnd = weekStart.plusDays(6)
                
                var totalCompletions = 0
                activeHabits.forEach { habit ->
                    val habitLogs = allLogs.filter { it.habitId == habit.id }
                    habitLogs.forEach { log ->
                        val logDate = try { java.time.LocalDate.parse(log.date) } catch (e: Exception) { null }
                        if (logDate != null && !logDate.isBefore(weekStart) && !logDate.isAfter(weekEnd)) {
                            if (com.example.data.isLogCompleted(habit, log)) {
                                totalCompletions++
                            }
                        }
                    }
                }
                
                val weekNum = getWeekOfYear(weekStart)
                val label = "KW$weekNum"
                points.add(TrendPoint(label, 0f, totalCompletions))
            }
        }
        1 -> { // Monthly (Last 6 months)
            for (i in 5 downTo 0) {
                val monthDate = today.minusMonths(i.toLong())
                val startOfMonth = monthDate.withDayOfMonth(1)
                val endOfMonth = monthDate.withDayOfMonth(monthDate.lengthOfMonth())
                
                var totalCompletions = 0
                activeHabits.forEach { habit ->
                    val habitLogs = allLogs.filter { it.habitId == habit.id }
                    habitLogs.forEach { log ->
                        val logDate = try { java.time.LocalDate.parse(log.date) } catch (e: Exception) { null }
                        if (logDate != null && !logDate.isBefore(startOfMonth) && !logDate.isAfter(endOfMonth)) {
                            if (com.example.data.isLogCompleted(habit, log)) {
                                totalCompletions++
                            }
                        }
                    }
                }
                
                val monthName = monthDate.month.getDisplayName(java.time.format.TextStyle.SHORT, java.util.Locale.getDefault())
                points.add(TrendPoint(monthName, 0f, totalCompletions))
            }
        }
        2 -> { // Yearly (Last 4 years)
            for (i in 3 downTo 0) {
                val yearDate = today.minusYears(i.toLong())
                val startOfYear = yearDate.withDayOfYear(1)
                val endOfYear = yearDate.withDayOfYear(yearDate.lengthOfYear())
                
                var totalCompletions = 0
                activeHabits.forEach { habit ->
                    val habitLogs = allLogs.filter { it.habitId == habit.id }
                    habitLogs.forEach { log ->
                        val logDate = try { java.time.LocalDate.parse(log.date) } catch (e: Exception) { null }
                        if (logDate != null && !logDate.isBefore(startOfYear) && !logDate.isAfter(endOfYear)) {
                            if (com.example.data.isLogCompleted(habit, log)) {
                                totalCompletions++
                            }
                        }
                    }
                }
                
                val yearLabel = yearDate.year.toString()
                points.add(TrendPoint(yearLabel, 0f, totalCompletions))
            }
        }
    }
    return points
}

