@Composable
fun TimeframeSelectorPills(
    selectedTimeframeIndex: Int,
    onTimeframeSelected: (Int) -> Unit,
    language: String,
    modifier: Modifier = Modifier,
    customLabels: List<String>? = null
) {
    val labels = customLabels ?: if (language == "de") {
        listOf("Diese Woche", "Diesen Monat", "Dieses Jahr", "Gesamt")
    } else {
        listOf("This Week", "This Month", "This Year", "Total")
    }

    Row(
        modifier = modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(12.dp))
            .background(Color.White.copy(alpha = 0.05f))
            .border(1.dp, AppBorder.copy(alpha = 0.5f), RoundedCornerShape(12.dp))
            .padding(3.dp),
        horizontalArrangement = Arrangement.spacedBy(2.dp)
    ) {
        labels.forEachIndexed { index, label ->
            val isSelected = selectedTimeframeIndex == index
            Box(
                modifier = Modifier
                    .weight(1f)
                    .clip(RoundedCornerShape(10.dp))
                    .background(if (isSelected) Color(0xFF3A3A44) else Color.Transparent)
                    .clickable { onTimeframeSelected(index) }
                    .padding(vertical = 8.dp),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = label,
                    style = MaterialTheme.typography.labelSmall,
                    fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                    color = if (isSelected) TextPrimary else TextSecondary,
                    fontSize = 10.5.sp,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
        }
    }
}

