@Composable
fun ScoreTrendLineChart(
    points: List<TrendPoint>,
    modifier: Modifier = Modifier
) {
    if (points.isEmpty()) return

    var selectedPointIndex by remember(points) { mutableStateOf<Int?>(null) }

    Column(modifier = modifier.fillMaxWidth()) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(180.dp)
                .padding(vertical = 8.dp)
        ) {
            Canvas(
                modifier = Modifier
                    .fillMaxSize()
                    .pointerInput(points) {
                        detectTapGestures { offset ->
                            val paddingLeft = 32.dp.toPx()
                            val paddingBottom = 24.dp.toPx()
                            val graphWidth = size.width - paddingLeft
                            val graphHeight = size.height - paddingBottom
                            val stepX = if (points.size > 1) graphWidth / (points.size - 1) else graphWidth

                            val clickedIndex = points.mapIndexed { idx, pt ->
                                val x = paddingLeft + (idx * stepX)
                                val y = graphHeight - (pt.score.coerceIn(0f, 100f) / 100f * graphHeight)
                                val distance = Math.hypot((offset.x - x).toDouble(), (offset.y - y).toDouble())
                                idx to distance
                            }.minByOrNull { it.second }

                            if (clickedIndex != null && clickedIndex.second < 40.dp.toPx()) {
                                selectedPointIndex = clickedIndex.first
                            } else {
                                selectedPointIndex = null
                            }
                        }
                    }
            ) {
                val width = size.width
                val height = size.height
                val paddingLeft = 32.dp.toPx()
                val paddingBottom = 24.dp.toPx()
                val graphWidth = width - paddingLeft
                val graphHeight = height - paddingBottom

                val gridStep = graphHeight / 4f
                for (i in 0..4) {
                    val y = graphHeight - (i * gridStep)
                    drawLine(
                        color = AppBorder.copy(alpha = 0.5f),
                        start = Offset(paddingLeft, y),
                        end = Offset(width, y),
                        strokeWidth = 1.dp.toPx(),
                        pathEffect = PathEffect.dashPathEffect(floatArrayOf(10f, 10f), 0f)
                    )
                }

                val stepX = if (points.size > 1) graphWidth / (points.size - 1) else graphWidth
                val pathPoints = points.mapIndexed { idx, pt ->
                    val x = paddingLeft + (idx * stepX)
                    val y = graphHeight - (pt.score.coerceIn(0f, 100f) / 100f * graphHeight)
                    Offset(x, y)
                }

                if (pathPoints.size > 1) {
                    val linePath = Path().apply {
                        moveTo(pathPoints[0].x, pathPoints[0].y)
                        for (i in 1 until pathPoints.size) {
                            val prev = pathPoints[i - 1]
                            val curr = pathPoints[i]
                            val controlX1 = prev.x + (curr.x - prev.x) / 2f
                            val controlY1 = prev.y
                            val controlX2 = prev.x + (curr.x - prev.x) / 2f
                            val controlY2 = curr.y
                            cubicTo(controlX1, controlY1, controlX2, controlY2, curr.x, curr.y)
                        }
                    }

                    val fillPath = Path().apply {
                        addPath(linePath)
                        lineTo(pathPoints.last().x, graphHeight)
                        lineTo(pathPoints.first().x, graphHeight)
                        close()
                    }

                    drawPath(
                        path = fillPath,
                        brush = Brush.verticalGradient(
                            colors = listOf(
                                PrimaryViolet.copy(alpha = 0.35f),
                                PrimaryViolet.copy(alpha = 0.02f)
                            ),
                            startY = 0f,
                            endY = graphHeight
                        )
                    )

                    drawPath(
                        path = linePath,
                        color = PrimaryViolet,
                        style = Stroke(width = 3.dp.toPx(), cap = StrokeCap.Round)
                    )
                }

                pathPoints.forEachIndexed { _, pt ->
                    drawCircle(
                        color = AppBg,
                        radius = 5.dp.toPx(),
                        center = pt
                    )
                    drawCircle(
                        color = PrimaryViolet,
                        radius = 3.5.dp.toPx(),
                        center = pt
                    )
                }

                selectedPointIndex?.let { idx ->
                    if (idx in pathPoints.indices && idx in points.indices) {
                        val pt = pathPoints[idx]
                        val trendPoint = points[idx]
                        val text = "${trendPoint.score.toInt()}"
                    
                    val paint = android.graphics.Paint().apply {
                        color = android.graphics.Color.WHITE
                        textSize = 34f
                        textAlign = android.graphics.Paint.Align.CENTER
                        isAntiAlias = true
                        isFakeBoldText = true
                    }
                    val bgPaint = android.graphics.Paint().apply {
                        color = PrimaryViolet.toArgb()
                        isAntiAlias = true
                    }

                    val textBounds = android.graphics.Rect()
                    paint.getTextBounds(text, 0, text.length, textBounds)
                    
                    val tooltipWidth = textBounds.width() + 40f
                    val tooltipHeight = textBounds.height() + 24f
                    
                    val rect = android.graphics.RectF(
                        pt.x - tooltipWidth / 2f,
                        pt.y - tooltipHeight - 35f,
                        pt.x + tooltipWidth / 2f,
                        pt.y - 15f
                    )
                    
                    drawContext.canvas.nativeCanvas.drawRoundRect(
                        rect, 16f, 16f, bgPaint
                    )

                    val path = android.graphics.Path().apply {
                        moveTo(pt.x - 12f, pt.y - 16f)
                        lineTo(pt.x + 12f, pt.y - 16f)
                        lineTo(pt.x, pt.y - 6f)
                        close()
                    }
                    drawContext.canvas.nativeCanvas.drawPath(path, bgPaint)

                    drawContext.canvas.nativeCanvas.drawText(
                        text,
                        pt.x,
                        pt.y - (tooltipHeight / 2f) - 25f + (textBounds.height() / 2f),
                        paint
                    )
                }
            }
        }

            Column(
                modifier = Modifier
                    .fillMaxHeight()
                    .padding(bottom = 24.dp),
                verticalArrangement = Arrangement.SpaceBetween
            ) {
                listOf("100", "75", "50", "25", "0").forEach { pct ->
                    Text(
                        text = pct,
                        style = MaterialTheme.typography.labelSmall,
                        color = TextSecondary.copy(alpha = 0.7f),
                        fontSize = 9.sp
                    )
                }
            }
        }

        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(start = 32.dp),
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            points.forEach { pt ->
                Text(
                    text = pt.label,
                    style = MaterialTheme.typography.labelSmall,
                    color = TextSecondary,
                    fontSize = 10.sp,
                    fontWeight = FontWeight.Medium,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.weight(1f)
                )
            }
        }
    }
}

@Composable
fun CompletionsBarChart(
    points: List<TrendPoint>,
    habitColor: Color,
    modifier: Modifier = Modifier
) {
    if (points.isEmpty()) return
    val maxCount = remember(points) { (points.maxOfOrNull { it.completions } ?: 1).coerceAtLeast(1) }

    Column(modifier = modifier.fillMaxWidth()) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(160.dp)
                .padding(top = 10.dp, bottom = 4.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.Bottom
        ) {
            points.forEach { pt ->
                val ratio = pt.completions.toFloat() / maxCount.toFloat()
                Column(
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxHeight(),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Bottom
                ) {
                    if (pt.completions > 0) {
                        Text(
                            text = "${pt.completions}",
                            style = MaterialTheme.typography.labelSmall,
                            color = TextPrimary,
                            fontWeight = FontWeight.Bold,
                            fontSize = 11.sp
                        )
                        Spacer(modifier = Modifier.height(4.dp))
                    }
                    Box(
                        modifier = Modifier
                            .fillMaxWidth(0.55f)
                            .fillMaxHeight(ratio.coerceAtLeast(0.05f))
                            .clip(RoundedCornerShape(topStart = 6.dp, topEnd = 6.dp))
                            .background(
                                if (pt.completions > 0) habitColor else Color.White.copy(alpha = 0.06f)
                            )
                    )
                }
            }
        }

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            points.forEach { pt ->
                Text(
                    text = pt.label,
                    style = MaterialTheme.typography.labelSmall,
                    color = TextSecondary,
                    fontSize = 10.sp,
                    fontWeight = FontWeight.Medium,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.weight(1f)
                )
            }
        }
    }
}

