@Composable
fun OverallStatsScreen(
    viewModel: HabitsViewModel,
    language: String,
    onBack: () -> Unit,
    onNavigateToToday: () -> Unit
) {
    val strength by viewModel.totalStrength.collectAsStateWithLifecycle()
    val habitsWithStats by viewModel.statsScreenData.collectAsStateWithLifecycle()
    val perfectDaysStats by viewModel.perfectDaysStats.collectAsStateWithLifecycle()
    val profileStats by viewModel.profileStats.collectAsStateWithLifecycle()
    val selectedDate by viewModel.selectedDate.collectAsStateWithLifecycle()
    val allHabits by viewModel.allHabits.collectAsStateWithLifecycle()
    val allLogs by viewModel.allLogs.collectAsStateWithLifecycle()
    val overallCalData by viewModel.overallCalendarData.collectAsStateWithLifecycle()
    val allDailyNotes by viewModel.allDailyNotes.collectAsStateWithLifecycle()

    val heatmapMonthOffset by viewModel.heatmapMonthOffset.collectAsStateWithLifecycle()
    val heatmapCanPrevMonth by viewModel.heatmapCanPrevMonth.collectAsStateWithLifecycle()
    val heatmapCanNextMonth by viewModel.heatmapCanNextMonth.collectAsStateWithLifecycle()
    val heatmapMonthNameAndYear by viewModel.heatmapMonthNameAndYear.collectAsStateWithLifecycle()
    val heatmapMonthGridData by viewModel.heatmapMonthGridData.collectAsStateWithLifecycle()
    val heatmapYearGridData by viewModel.heatmapYearGridData.collectAsStateWithLifecycle()
    val heatmapYearMonthLabels by viewModel.heatmapYearMonthLabels.collectAsStateWithLifecycle()

    val selectedHeatmapCell by viewModel.selectedHeatmapCell.collectAsStateWithLifecycle()
    val heatmapViewMode by viewModel.heatmapViewMode.collectAsStateWithLifecycle()
    val activeCell by viewModel.activeHeatmapCell.collectAsStateWithLifecycle()
    val formattedDate by viewModel.formattedActiveCellDate.collectAsStateWithLifecycle()

    var activeExplanation by remember { mutableStateOf<Pair<String, String>?>(null) }
    var selectedReviewYear by remember { mutableStateOf<Int?>(null) }
    var selectedReviewMonth by remember { mutableStateOf<Pair<Int, Int>?>(null) }
    var showReviewArchive by remember { mutableStateOf(false) }
    var showReviewExplanation by remember { mutableStateOf(false) }
    val isNYReviewWindow = remember { isNewYearReviewPeriod() }

    val currentYear = remember { Calendar.getInstance().get(Calendar.YEAR) }
    val availableYears = remember(allLogs, currentYear) {
        val logYears = allLogs.mapNotNull {
            if (it.date.length >= 4) it.date.substring(0, 4).toIntOrNull() else null
        }
        logYears.filter { y -> y < currentYear }
            .distinct()
            .sortedDescending()
    }

    val currentYearMonth = remember {
        val cal = Calendar.getInstance()
        val y = cal.get(Calendar.YEAR)
        val m = cal.get(Calendar.MONTH) + 1 // 1-indexed
        y to m
    }
    val availableMonths = remember(allLogs, currentYearMonth) {
        val logMonths = allLogs.mapNotNull { log ->
            if (log.date.length >= 7) {
                val parts = log.date.split("-")
                if (parts.size >= 2) {
                    val y = parts[0].toIntOrNull()
                    val m = parts[1].toIntOrNull()
                    if (y != null && m != null) {
                        y to m
                    } else null
                } else null
            } else null
        }
        val cal = Calendar.getInstance()
        val cY = cal.get(Calendar.YEAR)
        val cM = cal.get(Calendar.MONTH) + 1 // 1-indexed
        
        // A month is only available if it's strictly in the past (before current year/month)
        logMonths.filter { (y, m) -> 
            y < cY || (y == cY && m < cM)
        }.distinct()
        .sortedWith(compareByDescending<Pair<Int, Int>> { it.first }.thenByDescending { it.second })
    }

    Box(modifier = Modifier.fillMaxSize().background(AppBg)) {
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(horizontal = 16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp),
            contentPadding = PaddingValues(bottom = 140.dp, top = 84.dp)
        ) {
            // Yearly Review Banner (Shown strictly during New Year period)
            if (isNYReviewWindow) {
                item(key = "yearly_review_banner") {
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(20.dp),
                    color = Color.Transparent
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(
                                Brush.horizontalGradient(
                                    colors = listOf(
                                        PrimaryViolet,
                                        Color(0xFF8B5CF6),
                                        Color(0xFF6D28D9)
                                    )
                                ),
                                shape = RoundedCornerShape(20.dp)
                            )
                            .border(1.dp, Color.White.copy(alpha = 0.25f), RoundedCornerShape(20.dp))
                            .padding(18.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Surface(
                                        color = Color.White.copy(alpha = 0.2f),
                                        shape = CircleShape
                                    ) {
                                        Text(
                                            text = "✨ " + (if (language == "de") "RÜCKBLICK $currentYear" else if (language == "ka") "$currentYear მიმოხილვა" else "$currentYear REVIEW"),
                                            style = MaterialTheme.typography.labelSmall,
                                            color = Color.White,
                                            fontWeight = FontWeight.Bold,
                                            modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp)
                                        )
                                    }
                                }
                                Spacer(modifier = Modifier.height(8.dp))
                                Text(
                                    text = if (language == "de") "Dein Jahresrückblick $currentYear" else if (language == "ka") "თქვენი $currentYear ამბავი" else "Your $currentYear Story",
                                    style = MaterialTheme.typography.titleLarge,
                                    color = Color.White,
                                    fontWeight = FontWeight.ExtraBold
                                )
                                Spacer(modifier = Modifier.height(2.dp))
                                Text(
                                    text = if (language == "de")
                                        "Highlights, Statistiken & Star-Gewohnheiten entdecken"
                                    else if (language == "ka") "აღმოაჩინეთ თქვენი მაჩვენებლები, სტატისტიკა და ვარსკვლავების ჩვევები" else "Discover your highlights, stats & star habits",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = Color.White.copy(alpha = 0.85f)
                                )
                            }

                            Spacer(modifier = Modifier.width(12.dp))

                            Button(
                                onClick = { selectedReviewYear = currentYear },
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = Color.White,
                                    contentColor = PrimaryViolet
                                ),
                                shape = RoundedCornerShape(12.dp),
                                elevation = ButtonDefaults.buttonElevation(defaultElevation = 2.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.PlayArrow,
                                    contentDescription = "Play",
                                    tint = PrimaryViolet,
                                    modifier = Modifier.size(16.dp)
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                Text(
                                    text = if (language == "de") "Starten" else if (language == "ka") "თამაში" else "Play",
                                    fontWeight = FontWeight.Bold,
                                    color = PrimaryViolet
                                )
                            }
                        }
                    }
                }
            }
            }

            // 1. Overall Account Strength Gauge
            item(key = "overall_strength") {
                var hasAnimatedStatsStrength by rememberSaveable { mutableStateOf(false) }
                val animStrength = remember { Animatable(if (hasAnimatedStatsStrength) strength.toFloat() else 0f) }

                LaunchedEffect(strength) {
                    if (!hasAnimatedStatsStrength) {
                        animStrength.snapTo(0f)
                        animStrength.animateTo(
                            targetValue = strength.toFloat(),
                            animationSpec = tween(durationMillis = 800, easing = FastOutSlowInEasing)
                        )
                        hasAnimatedStatsStrength = true
                    } else {
                        animStrength.animateTo(
                            targetValue = strength.toFloat(),
                            animationSpec = tween(durationMillis = 300, easing = FastOutSlowInEasing)
                        )
                    }
                }
                val animatedStrength = animStrength.value
                val sweepAngleVal = (animatedStrength / 100f) * 360f
                val ringColor = remember(strength) {
                    when {
                        strength < 35 -> HabitRed
                        strength < 70 -> HabitYellow
                        else -> SuccessGreen
                    }
                }

                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 8.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    // Title and info button above the semi-circle gauge
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 6.dp, start = 16.dp, end = 16.dp),
                        horizontalArrangement = Arrangement.Center,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Spacer(modifier = Modifier.width(32.dp))
                        Text(
                            text = if (language == "de") "GESAMT-STÄRKE" else if (language == "ka") "საერთო სიძლიერე" else "OVERALL STRENGTH",
                            style = MaterialTheme.typography.labelSmall,
                            color = TextSecondary,
                            fontWeight = FontWeight.Bold,
                            fontSize = 11.sp
                        )
                        Spacer(modifier = Modifier.width(4.dp))
                        InfoIconButton(
                            title = if (language == "de") "Gesamt-Stärke Score" else if (language == "ka") "სიძლიერის საერთო ქულა" else "Overall Strength Score",
                            explanation = if (language == "de") {
                                "Der Durchschnitt der Stärke-Scores (0-100) all deiner aktiven Gewohnheiten. Der Score jeder Gewohnheit basiert auf den letzten 30 Tagen, wobei jüngere Einträge leicht höher gewichtet werden und heute noch ausstehende Aufgaben den Score nicht reduzieren."
                            } else {
                                "The average strength score (0-100) of all your active habits. Each habit's score is based on the last 30 days, with recent entries weighted slightly higher. Pending tasks for today do not reduce the score."
                            },
                            onClick = { t, e -> activeExplanation = t to e },
                            modifier = Modifier.size(28.dp)
                        )
                    }

                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(155.dp)
                            .padding(top = 4.dp),
                        contentAlignment = Alignment.BottomCenter
                    ) {
                        val sweepHalfVal = (animatedStrength / 100f) * 180f
                        Canvas(
                            modifier = Modifier
                                .width(290.dp)
                                .height(150.dp)
                        ) {
                            val strokeWidth = 18.dp.toPx()
                            val stroke = Stroke(width = strokeWidth, cap = StrokeCap.Round)
                            val topLeft = Offset(strokeWidth / 2, strokeWidth / 2)
                            val arcSize = Size(size.width - strokeWidth, (size.height * 2) - strokeWidth)

                            drawArc(
                                color = ProgressTrack,
                                startAngle = 180f,
                                sweepAngle = 180f,
                                useCenter = false,
                                topLeft = topLeft,
                                size = arcSize,
                                style = stroke
                            )

                            if (sweepHalfVal > 0f) {
                                drawArc(
                                    color = ringColor,
                                    startAngle = 180f,
                                    sweepAngle = sweepHalfVal,
                                    useCenter = false,
                                    topLeft = topLeft,
                                    size = arcSize,
                                    style = stroke
                                )
                            }
                        }

                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            modifier = Modifier.padding(bottom = 8.dp)
                        ) {
                            Text(
                                text = "${animatedStrength.toInt()}",
                                style = MaterialTheme.typography.headlineLarge,
                                fontSize = 32.sp,
                                fontWeight = FontWeight.ExtraBold,
                                color = TextPrimary
                            )
                            val strLabel = getStrengthLabel(strength, language)
                            if (strLabel.isNotBlank()) {
                                Text(
                                    text = strLabel,
                                    style = MaterialTheme.typography.titleSmall,
                                    fontWeight = FontWeight.Bold,
                                    color = ringColor
                                )
                            }
                        }
                    }
                }
            }

            // 2. Account Streaks (Current Streak & Best Streak)
            item(key = "overall_account_streaks_grid") {
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Card(
                        colors = CardDefaults.cardColors(containerColor = AppCard),
                        shape = RoundedCornerShape(20.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .border(
                                1.dp,
                                PrimaryViolet.copy(alpha = if (perfectDaysStats.currentStreak > 0) 0.6f else 0.4f),
                                RoundedCornerShape(20.dp)
                            )
                    ) {
                        Column(modifier = Modifier.padding(16.dp)) {
                            // Header Row
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(28.dp)
                                        .background(PrimaryViolet.copy(alpha = 0.15f), CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.EmojiEvents,
                                        contentDescription = "Perfect Days",
                                        tint = PrimaryViolet,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = if (language == "de") "PERFEKTE TAGE" else if (language == "ka") "იდეალური დღეები" else "PERFECT DAYS",
                                    style = MaterialTheme.typography.labelSmall,
                                    color = TextSecondary,
                                    fontWeight = FontWeight.Bold
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                InfoIconButton(
                                    title = if (language == "de") "Perfekte Tage" else if (language == "ka") "იდეალური დღეები" else "Perfect Days",
                                    explanation = if (language == "de") {
                                        "Übersicht über deine perfekten Tage, an denen du alle aktiven Gewohnheiten erfolgreich abgeschlossen hast."
                                    } else if (language == "ka") {
                        "თქვენი სრულყოფილი დღეების მიმოხილვა, სადაც წარმატებით დაასრულეთ ყველა აქტიური ჩვევა."
                    } else {
                        "Overview of your perfect days where you successfully completed all active habits."
                    },
                                    onClick = { t, e -> activeExplanation = t to e }
                                )
                            }

                            Spacer(modifier = Modifier.height(16.dp))

                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(
                                    modifier = Modifier.weight(1f),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    Text(
                                        text = perfectDaysStats.totalPerfectDays.toString(),
                                        style = MaterialTheme.typography.headlineMedium,
                                        color = TextPrimary,
                                        fontWeight = FontWeight.ExtraBold
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = if (language == "de") "Gesamt" else if (language == "ka") "სულ" else "Total",
                                        style = MaterialTheme.typography.labelMedium,
                                        color = TextSecondary
                                    )
                                }

                                Column(
                                    modifier = Modifier.weight(1f),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    Text(
                                        text = perfectDaysStats.currentStreak.toString(),
                                        style = MaterialTheme.typography.headlineMedium,
                                        color = TextPrimary,
                                        fontWeight = FontWeight.ExtraBold
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = if (language == "de") "Aktueller Streak" else if (language == "ka") "მიმდინარე სტრიქონი" else "Current Streak",
                                        style = MaterialTheme.typography.labelMedium,
                                        color = TextSecondary
                                    )
                                }

                                Column(
                                    modifier = Modifier.weight(1f),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    Text(
                                        text = perfectDaysStats.perfectDaysStreak.toString(),
                                        style = MaterialTheme.typography.headlineMedium,
                                        color = TextPrimary,
                                        fontWeight = FontWeight.ExtraBold
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = if (language == "de") "Längster Streak" else if (language == "ka") "საუკეთესო სერია" else "Best Streak",
                                        style = MaterialTheme.typography.labelMedium,
                                        color = TextSecondary
                                    )
                                }
                            }
                        }
                    }
                }
            }
            // 3. Activity Heatmap Card (GitHub-style, with date check-in navigation!)
            item(key = "overall_calendar") {
                Card(
                    colors = CardDefaults.cardColors(containerColor = AppCard),
                    shape = RoundedCornerShape(20.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .border(1.dp, AppBorder, RoundedCornerShape(20.dp))
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp)
                    ) {
                        // Header info row
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(bottom = 16.dp),
                            horizontalArrangement = Arrangement.Start
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Box(
                                    modifier = Modifier
                                        .size(28.dp)
                                        .background(PrimaryViolet.copy(alpha = 0.18f), CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.DateRange,
                                        contentDescription = "Calendar",
                                        tint = PrimaryViolet,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = if (language == "de") "AKTIVITÄTS-HEATMAP" else if (language == "ka") "აქტივობა სითბოს რუკა" else "ACTIVITY HEATMAP",
                                    style = MaterialTheme.typography.labelSmall,
                                    color = TextSecondary,
                                    fontWeight = FontWeight.Bold
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                InfoIconButton(
                                    title = if (language == "de") "Aktivitäts-Heatmap" else if (language == "ka") "აქტივობის სითბოს რუკა" else "Activity Heatmap",
                                    explanation = if (language == "de") {
                                        "Zeigt deinen täglichen Gewohnheitsfortschritt für den ausgewählten Zeitraum, ähnlich wie das GitHub-Beitragssystem. Dunklere grüne Felder stehen für eine höhere Anzahl an abgeschlossenen Gewohnheiten an dem Tag."
                                    } else if (language == "ka") {
                        "აჩვენებს თქვენი ყოველდღიური ჩვევების დასრულების პროგრესს არჩეული დროის განმავლობაში, სტილიზებული GitHub-ის წვლილის დაფის მსგავსად. მუქი მწვანე კვადრატები წარმოადგენს იმ დღეს დასრულებული ჩვევების უფრო მაღალ თანაფარდობას."
                    } else {
                        "Shows your daily habit completion progress for the selected timeframe, styled like GitHub's contribution board. Darker green squares represent a higher ratio of completed habits on that day."
                    },
                                    onClick = { t, e -> activeExplanation = t to e }
                                )
                                Spacer(modifier = Modifier.weight(1f))
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    modifier = Modifier.padding(end = 8.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.TouchApp,
                                        contentDescription = null,
                                        tint = TextSecondary.copy(alpha = 0.7f),
                                        modifier = Modifier.size(14.dp)
                                    )
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text(
                                        text = if (language == "de") "Interaktiv" else if (language == "ka") "ინტერაქტიული" else "Interactive",
                                        style = MaterialTheme.typography.labelSmall,
                                        color = TextSecondary.copy(alpha = 0.7f),
                                        fontWeight = FontWeight.Medium
                                    )
                                }
                            }
                        }

                        // --- YEAR VIEW (Horizontal Scrollable 24-Weeks GitHub board, scaled up!) ---
                        val yearGridData = heatmapYearGridData
                        val yearMonthLabels = heatmapYearMonthLabels

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.Center,
                            verticalAlignment = Alignment.Top
                        ) {
                            // 1. Fixed Weekday Labels Column on the left
                            Column(
                                verticalArrangement = Arrangement.spacedBy(4.dp),
                                modifier = Modifier.padding(top = 22.dp, end = 8.dp)
                            ) {
                                val weekdays = if (language == "de") {
                                    listOf("Mo", "Di", "Mi", "Do", "Fr", "Sa", "So")
                                } else {
                                    listOf("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
                                }
                                weekdays.forEach { dayLabel ->
                                    Box(
                                        modifier = Modifier.height(18.dp),
                                        contentAlignment = Alignment.CenterEnd
                                    ) {
                                        Text(
                                            text = dayLabel,
                                            style = MaterialTheme.typography.labelSmall,
                                            color = TextSecondary,
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }

                            // 2. Horizontally scrollable Content containing Month labels and Week columns
                            val scrollState = rememberScrollState()
                            
                            LaunchedEffect(yearGridData) {
                                scrollState.animateScrollTo(scrollState.maxValue)
                            }

                            Column(
                                modifier = Modifier
                                    .weight(1f)
                                    .horizontalScroll(scrollState)
                            ) {
                                // Month Labels Row
                                Row(
                                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    modifier = Modifier.height(18.dp)
                                ) {
                                    for (index in 0 until 24) {
                                        val label = yearMonthLabels.firstOrNull { it.first == index }
                                        Box(
                                            modifier = Modifier.width(18.dp),
                                            contentAlignment = Alignment.CenterStart
                                        ) {
                                            if (label != null) {
                                                Text(
                                                    text = label.second,
                                                    style = MaterialTheme.typography.labelSmall,
                                                    color = TextSecondary,
                                                    fontSize = 10.sp,
                                                    maxLines = 1,
                                                    softWrap = false,
                                                    modifier = Modifier.wrapContentWidth(unbounded = true, align = Alignment.Start)
                                                )
                                            }
                                        }
                                    }
                                }

                                // Weeks Columns Row
                                Row(
                                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    yearGridData.forEach { weekDays ->
                                        Column(
                                            verticalArrangement = Arrangement.spacedBy(4.dp),
                                            horizontalAlignment = Alignment.CenterHorizontally
                                        ) {
                                            weekDays.forEach { cell ->
                                                val ratio = if (cell.total > 0) cell.completed.toFloat() / cell.total.toFloat() else -1f
                                                val bgColor = when {
                                                    cell.isOutOfRange -> Color.Transparent
                                                    cell.isFuture -> AppCard
                                                    ratio < 0f -> ProgressTrack
                                                    ratio == 0f -> ProgressTrack
                                                    ratio <= 0.25f -> PrimaryViolet.copy(alpha = 0.15f)
                                                    ratio <= 0.5f -> PrimaryViolet.copy(alpha = 0.40f)
                                                    ratio <= 0.75f -> PrimaryViolet.copy(alpha = 0.70f)
                                                    else -> PrimaryViolet
                                                }
                                                
                                                val isSelectedSquare = activeCell?.dateStr == cell.dateStr
                                                val isTodayBorder = cell.isToday
                                                val hasNote = remember(allDailyNotes, cell.dateStr) {
                                                    allDailyNotes.any { it.date == cell.dateStr && it.content.isNotBlank() }
                                                }
                                                
                                                Box(
                                                    modifier = Modifier
                                                        .size(18.dp)
                                                        .background(bgColor, RoundedCornerShape(4.dp))
                                                        .then(
                                                            if (isSelectedSquare) {
                                                                Modifier.border(2.dp, PrimaryViolet, RoundedCornerShape(4.dp))
                                                            } else if (isTodayBorder) {
                                                                Modifier.border(1.dp, PrimaryViolet.copy(alpha = 0.5f), RoundedCornerShape(4.dp))
                                                            } else Modifier
                                                        )
                                                        .clickable(enabled = !cell.isOutOfRange) {
                                                            viewModel.selectHeatmapCell(cell)
                                                        },
                                                    contentAlignment = Alignment.Center
                                                ) {
                                                    if (hasNote && !cell.isOutOfRange) {
                                                        Box(
                                                            modifier = Modifier
                                                                .align(Alignment.TopEnd)
                                                                .padding(top = 2.dp, end = 2.dp)
                                                                .size(4.dp)
                                                                .background(PrimaryViolet, CircleShape)
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // Heatmap Horizontal Legend (GitHub-style)
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(top = 16.dp),
                            horizontalArrangement = Arrangement.End,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = if (language == "de") "Weniger " else if (language == "ka") "ნაკლები" else "Less ",
                                style = MaterialTheme.typography.labelSmall,
                                color = TextSecondary,
                                fontSize = 11.sp
                            )
                            
                            listOf(
                                ProgressTrack,
                                PrimaryViolet.copy(alpha = 0.15f),
                                PrimaryViolet.copy(alpha = 0.40f),
                                PrimaryViolet.copy(alpha = 0.70f),
                                PrimaryViolet
                            ).forEach { color ->
                                Box(
                                    modifier = Modifier
                                        .padding(horizontal = 2.dp)
                                        .size(12.dp)
                                        .background(color, RoundedCornerShape(3.dp))
                                )
                            }
                            
                            Text(
                                text = if (language == "de") " Mehr" else if (language == "ka") "მეტი" else " More",
                                style = MaterialTheme.typography.labelSmall,
                                color = TextSecondary,
                                fontSize = 11.sp
                            )
                        }

                        // Tapped cell details container
                        val cell = activeCell
                        if (cell != null) {
                            Spacer(modifier = Modifier.height(16.dp))
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(AppCard, RoundedCornerShape(12.dp))
                                    .border(1.dp, AppBorder, RoundedCornerShape(12.dp))
                                    .padding(12.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = formattedDate,
                                        style = MaterialTheme.typography.labelSmall,
                                        color = TextSecondary,
                                        fontWeight = FontWeight.Bold
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    val statusText = when {
                                        cell.isFuture -> {
                                            if (language == "de") "Zukünftiger Tag" else if (language == "ka") "მომავლის დღე" else "Future day"
                                        }
                                        cell.total == 0 -> {
                                            if (language == "de") "Keine Gewohnheiten an diesem Tag" else if (language == "ka") "არანაირი აქტიური ჩვევა ამ დღეს" else "No habits active on this day"
                                        }
                                        else -> {
                                            val pct = (cell.completed.toFloat() / cell.total.toFloat() * 100).toInt()
                                            if (language == "de") {
                                                "${cell.completed} von ${cell.total} Gewohnheiten abgeschlossen ($pct%)"
                                            } else {
                                                "${cell.completed} of ${cell.total} habits completed ($pct%)"
                                            }
                                        }
                                    }
                                    Text(
                                        text = statusText,
                                        style = MaterialTheme.typography.bodyMedium,
                                        color = if (cell.total > 0 && cell.completed == cell.total) SuccessGreen else TextPrimary,
                                        fontWeight = FontWeight.Bold
                                    )
                                }
                                
                                if (!cell.isFuture) {
                                    val cellInteractionSource = remember { MutableInteractionSource() }
                                    val cellIsPressed by cellInteractionSource.collectIsPressedAsState()
                                    val cellArrowOffsetX by animateDpAsState(
                                        targetValue = if (cellIsPressed) 6.dp else 0.dp,
                                        animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessLow),
                                        label = "cell_arrow_offset"
                                    )

                                    TextButton(
                                        onClick = {
                                            viewModel.selectDateAndSyncWeek(cell.dateStr)
                                            onNavigateToToday()
                                        },
                                        interactionSource = cellInteractionSource,
                                        colors = ButtonDefaults.textButtonColors(contentColor = PrimaryViolet)
                                    ) {
                                        Text(
                                            text = if (language == "de") "Anzeigen" else if (language == "ka") "ხედი" else "View",
                                            fontWeight = FontWeight.Bold,
                                            style = MaterialTheme.typography.bodyMedium
                                        )
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Icon(
                                            imageVector = Icons.Default.ChevronRight,
                                            contentDescription = "Go to date",
                                            modifier = Modifier
                                                .offset(x = cellArrowOffsetX)
                                                .size(16.dp)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // 3. Focus Highlights (Row with 2 Cards: "Läuft super" & "Braucht Fokus")
            item(key = "overall_focus_habits") {
                val bottomHabits = remember(habitsWithStats) {
                    val lowStrength = habitsWithStats.filter { it.strength < 60 }.sortedBy { it.strength }
                    if (lowStrength.isNotEmpty()) {
                        lowStrength.take(2)
                    } else if (habitsWithStats.size > 2) {
                        habitsWithStats.filter { it.strength < 100 }.sortedBy { it.strength }.take(2)
                    } else {
                        emptyList()
                    }
                }
                val topHabits = remember(habitsWithStats, bottomHabits) {
                    val bottomIds = bottomHabits.map { it.habit.id }.toSet()
                    habitsWithStats
                        .filter { it.habit.id !in bottomIds }
                        .sortedByDescending { it.strength }
                        .take(2)
                }

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(IntrinsicSize.Max),
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    // "Läuft super" card
                    Card(
                        colors = CardDefaults.cardColors(containerColor = AppCard),
                        shape = RoundedCornerShape(16.dp),
                        modifier = Modifier
                            .weight(1f)
                            .fillMaxHeight()
                            .border(1.dp, SuccessGreen.copy(alpha = 0.3f), RoundedCornerShape(16.dp))
                    ) {
                        Column(modifier = Modifier.padding(14.dp)) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(28.dp)
                                        .background(SuccessGreen.copy(alpha = 0.18f), CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.TrendingUp,
                                        contentDescription = "Great performance",
                                        tint = SuccessGreen,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(
                                    text = if (language == "de") "Läuft super" else if (language == "ka") "მშვენივრად აკეთებს" else "Doing great",
                                    style = MaterialTheme.typography.labelSmall,
                                    fontSize = 11.sp,
                                    color = TextSecondary,
                                    fontWeight = FontWeight.Bold,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                InfoIconButton(
                                    title = if (language == "de") "Läuft super" else if (language == "ka") "მშვენივრად აკეთებს" else "Doing great",
                                    explanation = if (language == "de") {
                                        "Deine 2 Gewohnheiten mit der höchsten historischen Erfolgsquote (Stärke)."
                                    } else if (language == "ka") {
                        "თქვენი 2 ჩვევა უმაღლესი ისტორიული დასრულების სიძლიერით."
                    } else {
                        "Your 2 habits with the highest historical completion strength."
                    },
                                    onClick = { t, e -> activeExplanation = t to e }
                                )
                            }
                            Spacer(modifier = Modifier.height(12.dp))
                            if (topHabits.isEmpty()) {
                                Text(
                                    text = if (language == "de") "Keine Daten" else if (language == "ka") "მონაცემები არ არის" else "No data",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = TextSecondary
                                )
                            } else {
                                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                                    topHabits.forEach { stat ->
                                        val habitColor = remember(stat.habit.color) { HabitIconMapping.getColor(stat.habit.color) }
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            Box(
                                                modifier = Modifier
                                                    .size(24.dp)
                                                    .background(habitColor.copy(alpha = 0.2f), CircleShape)
                                                    .border(1.dp, habitColor, CircleShape),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Icon(
                                                    imageVector = HabitIconMapping.getIcon(stat.habit.icon),
                                                    contentDescription = null,
                                                    tint = habitColor,
                                                    modifier = Modifier.size(12.dp)
                                                )
                                            }
                                            Spacer(modifier = Modifier.width(8.dp))
                                            Text(
                                                text = stat.habit.name,
                                                style = MaterialTheme.typography.bodyMedium,
                                                color = TextPrimary,
                                                fontWeight = FontWeight.Medium,
                                                maxLines = 1,
                                                overflow = TextOverflow.Ellipsis,
                                                modifier = Modifier.weight(1f)
                                            )
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Text(
                                                text = "${stat.strength}%",
                                                style = MaterialTheme.typography.bodyMedium,
                                                color = SuccessGreen,
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }

                    // "Braucht Fokus" card
                    Card(
                        colors = CardDefaults.cardColors(containerColor = AppCard),
                        shape = RoundedCornerShape(16.dp),
                        modifier = Modifier
                            .weight(1f)
                            .fillMaxHeight()
                            .border(1.dp, ErrorRed.copy(alpha = 0.3f), RoundedCornerShape(16.dp))
                    ) {
                        Column(modifier = Modifier.padding(14.dp)) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(28.dp)
                                        .background(ErrorRed.copy(alpha = 0.18f), CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.TrendingDown,
                                        contentDescription = "Needs focus",
                                        tint = ErrorRed,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(
                                    text = if (language == "de") "Braucht Fokus" else if (language == "ka") "ფოკუსირება სჭირდება" else "Needs focus",
                                    style = MaterialTheme.typography.labelSmall,
                                    fontSize = 11.sp,
                                    color = TextSecondary,
                                    fontWeight = FontWeight.Bold,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                InfoIconButton(
                                    title = if (language == "de") "Braucht Fokus" else if (language == "ka") "ფოკუსირება სჭირდება" else "Needs focus",
                                    explanation = if (language == "de") {
                                        "Deine Gewohnheiten unter 100%, die noch Aufmerksamkeit benötigen."
                                    } else if (language == "ka") {
                        "თქვენი ჩვევები 100%-ზე ნაკლებია, რომლებსაც ყურადღება სჭირდებათ."
                    } else {
                        "Your habits below 100% completion that need attention."
                    },
                                    onClick = { t, e -> activeExplanation = t to e }
                                )
                            }
                            Spacer(modifier = Modifier.height(12.dp))
                            if (bottomHabits.isEmpty()) {
                                Text(
                                    text = if (language == "de") "Alles im grünen Bereich! 🎉" else if (language == "ka") "ყველა გზაზეა! 🎉" else "All on track! 🎉",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = TextSecondary
                                )
                            } else {
                                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                                    bottomHabits.forEach { stat ->
                                        val habitColor = remember(stat.habit.color) { HabitIconMapping.getColor(stat.habit.color) }
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            Box(
                                                modifier = Modifier
                                                    .size(24.dp)
                                                    .background(habitColor.copy(alpha = 0.2f), CircleShape)
                                                    .border(1.dp, habitColor, CircleShape),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Icon(
                                                    imageVector = HabitIconMapping.getIcon(stat.habit.icon),
                                                    contentDescription = null,
                                                    tint = habitColor,
                                                    modifier = Modifier.size(12.dp)
                                                )
                                            }
                                            Spacer(modifier = Modifier.width(8.dp))
                                            Text(
                                                text = stat.habit.name,
                                                style = MaterialTheme.typography.bodyMedium,
                                                color = TextPrimary,
                                                fontWeight = FontWeight.Medium,
                                                maxLines = 1,
                                                overflow = TextOverflow.Ellipsis,
                                                modifier = Modifier.weight(1f)
                                            )
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Text(
                                                text = "${stat.strength}%",
                                                style = MaterialTheme.typography.bodyMedium,
                                                color = ErrorRed,
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // 4. Overall Success Rate Card (Donut Chart + Timeframe Switcher Tabs)
            item(key = "overall_success_rate") {
                var selectedTimeframeIndex by rememberSaveable { mutableIntStateOf(0) }
                val overallStats = remember(allHabits, allLogs, selectedTimeframeIndex) {
                    calculateOverallSuccessStats(allHabits, allLogs, selectedTimeframeIndex)
                }

                SuccessRateCard(
                    title = if (language == "de") "Gesamt-Erfolgsquote" else if (language == "ka") "საერთო წარმატების მაჩვენებელი" else "Overall Success Rate",
                    doneCount = overallStats.doneCount,
                    missedCount = overallStats.missedCount,
                    skippedCount = overallStats.skippedCount,
                    pendingCount = overallStats.pendingCount,
                    language = language,
                    infoTitle = if (language == "de") "Gesamt-Erfolgsquote" else if (language == "ka") "საერთო წარმატების მაჩვენებელი" else "Overall Success Rate",
                    infoExplanation = if (language == "de") {
                        "Gesamte Aufschlüsselung aller absolvierten Gewohnheitstage nach Status: Erreicht, Gescheitert, Skipped und Ausstehend."
                    } else if (language == "ka") {
                        "ყველა დაგეგმილი ჩვევის დღეების საერთო დაყოფა სტატუსის მიხედვით: დასრულებული, გამოტოვებული, გამოტოვებული და მომლოდინე."
                    } else {
                        "Overall breakdown of all scheduled habit days by status: Done, Missed, Skipped, and Pending."
                    },
                    onInfoClick = { t, e -> activeExplanation = t to e },
                    showTimeframeSelector = true,
                    selectedTimeframeIndex = selectedTimeframeIndex,
                    onTimeframeSelected = { selectedTimeframeIndex = it }
                )
            }

            // 6. Overall Score Trend Card (Line Chart)
            item(key = "overall_score_trend") {
                OverallScoreTrendCard(
                    allHabits = allHabits,
                    allLogs = allLogs,
                    language = language,
                    onInfoClick = { t, e -> activeExplanation = t to e }
                )
            }

            // 7. Overall Volume Progression Card (Bar Chart)
            item(key = "overall_volume_progression") {
                OverallVolumeProgressionCard(
                    allHabits = allHabits,
                    allLogs = allLogs,
                    language = language,
                    onInfoClick = { t, e -> activeExplanation = t to e }
                )
            }
        }

        if (activeExplanation != null) {
            ExplanationDialog(
                title = activeExplanation!!.first,
                explanation = activeExplanation!!.second,
                onDismiss = { activeExplanation = null }
            )
        }

        if (selectedReviewYear != null) {
            YearlyReviewDialog(
                year = selectedReviewYear!!,
                allHabits = allHabits,
                allLogs = allLogs,
                language = language,
                viewModel = viewModel,
                onDismiss = { selectedReviewYear = null }
            )
        }

        if (selectedReviewMonth != null) {
            MonthlyReviewDialog(
                year = selectedReviewMonth!!.first,
                month = selectedReviewMonth!!.second,
                allHabits = allHabits,
                allLogs = allLogs,
                language = language,
                viewModel = viewModel,
                onDismiss = { selectedReviewMonth = null }
            )
        }

        if (showReviewExplanation) {
            ExplanationDialog(
                title = if (language == "de") "Rückblicke & Berichte" else if (language == "ka") "მიმოხილვები და ანგარიშები" else "Reviews & Reports",
                explanation = if (language == "de") 
                    """Rückblicke sind Zusammenfassungen deiner Gewohnheiten.

• Sie werden immer am 1. Tag des Folgemonats bzw. Folgejahres freigeschaltet.
• Der Score ist der Durchschnitt aller Habit-Stärken zu diesem Zeitpunkt.
• Du kannst Monats- und Jahresrückblicke einzeln in den Einstellungen aktivieren."""
                else 
                    """Reviews are summaries of your habit progress.

• They are unlocked on the 1st day of the following month or year.
• The score is the average of all habit strengths at that time.
• You can toggle Monthly and Yearly reviews independently in settings.""",
                onDismiss = { showReviewExplanation = false }
            )
        }
        
        ReviewArchiveDialog(
            showReviewArchive = showReviewArchive,
            availableYears = availableYears,
            availableMonths = availableMonths,
            allHabits = allHabits,
            allLogs = allLogs,
            language = language,
            onShowReviewExplanation = { showReviewExplanation = true },
            onSelectReviewMonth = { (y, m) ->
                selectedReviewMonth = y to m
                showReviewArchive = false
            },
            onSelectReviewYear = { y ->
                selectedReviewYear = y
                showReviewArchive = false
            },
            onDismiss = { showReviewArchive = false }
        )

        // Floating Header Overlay with vertical gradient fade-out
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(84.dp)
                .background(
                    Brush.verticalGradient(
                        colors = listOf(
                            AppBg,
                            AppBg,
                            AppBg.copy(alpha = 0.9f),
                            AppBg.copy(alpha = 0.5f),
                            Color.Transparent
                        )
                    )
                )
                .align(Alignment.TopCenter)
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(start = 16.dp, top = 16.dp, end = 16.dp, bottom = 8.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                ModernBackButton(onClick = onBack)
                Spacer(modifier = Modifier.width(16.dp))
                Text(
                    text = if (language == "de") "Gesamt-Statistiken" else if (language == "ka") "საერთო სტატისტიკა" else "Overall Statistics",
                    style = MaterialTheme.typography.displayMedium,
                    color = TextPrimary,
                    fontWeight = FontWeight.Bold,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f)
                )
            }
        }
    }
}

data class SuccessRateStats(
    val doneCount: Int = 0,
    val missedCount: Int = 0,
    val skippedCount: Int = 0,
    val pendingCount: Int = 0,
    val totalCount: Int = 0
)

fun calculateHabitSuccessStatsForPeriod(
    habit: Habit,
    logs: List<HabitLog>,
    periodIndex: Int // 0 = Week, 1 = Month, 2 = Year, 3 = Total
): SuccessRateStats {
    val today = java.time.LocalDate.now()
    val todayStr = today.toString()

    val validStartMillis = if (habit.startDate > 946684800000L) habit.startDate else habit.createdAt
    val rawHabitStartDate = java.time.Instant.ofEpochMilli(validStartMillis.coerceAtLeast(946684800000L)).atZone(java.time.ZoneId.systemDefault()).toLocalDate()
    val habitStartDate = if (rawHabitStartDate.isBefore(today.minusYears(5))) today.minusYears(5) else rawHabitStartDate
    val startSdfStr = habitStartDate.toString()

    val startDate = when (periodIndex) {
        0 -> { // This Week
            val dayOfWeek = today.dayOfWeek.value
            val weekStart = today.minusDays((dayOfWeek - 1).toLong())
            if (weekStart.isBefore(habitStartDate)) habitStartDate else weekStart
        }
        1 -> { // This Month
            val monthStart = today.withDayOfMonth(1)
            if (monthStart.isBefore(habitStartDate)) habitStartDate else monthStart
        }
        2 -> { // This Year
            val yearStart = today.withDayOfYear(1)
            if (yearStart.isBefore(habitStartDate)) habitStartDate else yearStart
        }
        else -> habitStartDate
    }

    if (startDate.isAfter(today)) {
        return SuccessRateStats()
    }

    val habitLogs = logs.filter { it.habitId == habit.id }
    val logsByDate = habitLogs.associateBy { it.date }

    var done = 0
    var missed = 0
    var skipped = 0
    var pending = 0

    var current = startDate
    while (!current.isAfter(today)) {
        val dateStr = current.toString()
        if (isHabitActiveOnDate(habit, dateStr)) {
            val log = logsByDate[dateStr]
            val status = getLogStatus(habit, log, dateStr, startSdfStr, todayStr)
            when (status) {
                "SUCCESS" -> done++
                "FAILED" -> missed++
                "PAUSED" -> skipped++
                "PENDING" -> pending++
            }
        }
        current = current.plusDays(1)
    }

    val total = done + missed + skipped + pending
    return SuccessRateStats(done, missed, skipped, pending, total)
}

fun calculateOverallSuccessStats(
    allHabits: List<Habit>,
    allLogs: List<HabitLog>,
    periodIndex: Int = 0 // 0 = Week, 1 = Month, 2 = Year, 3 = Total
): SuccessRateStats {
    val today = java.time.LocalDate.now()
    val todayStr = today.toString()
    val activeHabits = allHabits.filter { !it.isArchived }

    if (activeHabits.isEmpty()) return SuccessRateStats()

    val logsMap = allLogs.groupBy { it.habitId to it.date }

    var done = 0
    var missed = 0
    var skipped = 0
    var pending = 0

    activeHabits.forEach { habit ->
        val validStartMillis = if (habit.startDate > 946684800000L) habit.startDate else habit.createdAt
        val rawHabitStartDate = java.time.Instant.ofEpochMilli(validStartMillis.coerceAtLeast(946684800000L)).atZone(java.time.ZoneId.systemDefault()).toLocalDate()
        val habitStartDate = if (rawHabitStartDate.isBefore(today.minusYears(5))) today.minusYears(5) else rawHabitStartDate
        val startSdfStr = habitStartDate.toString()

        val startDate = when (periodIndex) {
            0 -> { // This Week
                val dayOfWeek = today.dayOfWeek.value
                val weekStart = today.minusDays((dayOfWeek - 1).toLong())
                if (weekStart.isBefore(habitStartDate)) habitStartDate else weekStart
            }
            1 -> { // This Month
                val monthStart = today.withDayOfMonth(1)
                if (monthStart.isBefore(habitStartDate)) habitStartDate else monthStart
            }
            2 -> { // This Year
                val yearStart = today.withDayOfYear(1)
                if (yearStart.isBefore(habitStartDate)) habitStartDate else yearStart
            }
            else -> habitStartDate
        }

        if (!startDate.isAfter(today)) {
            var current = startDate
            while (!current.isAfter(today)) {
                val dateStr = current.toString()
                if (isHabitActiveOnDate(habit, dateStr)) {
                    val log = logsMap[habit.id to dateStr]?.firstOrNull()
                    val status = getLogStatus(habit, log, dateStr, startSdfStr, todayStr)
                    when (status) {
                        "SUCCESS" -> done++
                        "FAILED" -> missed++
                        "PAUSED" -> skipped++
                        "PENDING" -> pending++
                    }
                }
                current = current.plusDays(1)
            }
        }
    }

    val total = done + missed + skipped + pending
    return SuccessRateStats(done, missed, skipped, pending, total)
}

@Composable
fun SuccessRateCard(
    title: String,
    doneCount: Int,
    missedCount: Int,
    skippedCount: Int,
    pendingCount: Int,
    language: String,
    infoTitle: String,
    infoExplanation: String,
    onInfoClick: (String, String) -> Unit,
    showTimeframeSelector: Boolean = false,
    selectedTimeframeIndex: Int = 0,
    onTimeframeSelected: (Int) -> Unit = {}
) {
    val totalCount = doneCount + missedCount + skippedCount + pendingCount
    val donePct = if (totalCount > 0) ((doneCount.toFloat() / totalCount.toFloat()) * 100f).roundToInt() else 0
    val missedPct = if (totalCount > 0) ((missedCount.toFloat() / totalCount.toFloat()) * 100f).roundToInt() else 0
    val skippedPct = if (totalCount > 0) ((skippedCount.toFloat() / totalCount.toFloat()) * 100f).roundToInt() else 0
    val pendingPct = if (totalCount > 0) ((pendingCount.toFloat() / totalCount.toFloat()) * 100f).roundToInt() else 0

    val animProgress = remember { Animatable(0f) }
    LaunchedEffect(doneCount, missedCount, skippedCount, pendingCount, selectedTimeframeIndex) {
        animProgress.snapTo(0f)
        animProgress.animateTo(
            targetValue = 1f,
            animationSpec = tween(durationMillis = 700, easing = FastOutSlowInEasing)
        )
    }
    val animatedFactor = animProgress.value

    Card(
        colors = CardDefaults.cardColors(containerColor = AppCard),
        shape = RoundedCornerShape(20.dp),
        modifier = Modifier
            .fillMaxWidth()
            .border(1.dp, AppBorder, RoundedCornerShape(20.dp))
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Header Row
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Box(
                        modifier = Modifier
                            .size(28.dp)
                            .background(PrimaryViolet.copy(alpha = 0.18f), CircleShape),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.CheckCircle,
                            contentDescription = "Success Rate",
                            tint = PrimaryViolet,
                            modifier = Modifier.size(16.dp)
                        )
                    }
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = title.uppercase(Locale.getDefault()),
                        style = MaterialTheme.typography.labelSmall,
                        color = TextSecondary,
                        fontWeight = FontWeight.Bold
                    )
                    Spacer(modifier = Modifier.width(4.dp))
                    InfoIconButton(
                        title = infoTitle,
                        explanation = infoExplanation,
                        onClick = onInfoClick
                    )
                }
            }

            // Timeframe Selector Row (if enabled)
            if (showTimeframeSelector) {
                Spacer(modifier = Modifier.height(14.dp))
                TimeframeSelectorPills(
                    selectedTimeframeIndex = selectedTimeframeIndex,
                    onTimeframeSelected = onTimeframeSelected,
                    language = language
                )
            }

            Spacer(modifier = Modifier.height(18.dp))

            // Ring Canvas + Center Content
            Box(
                modifier = Modifier.size(180.dp),
                contentAlignment = Alignment.Center
            ) {
                val ringTrackColor = ProgressTrack
                val doneColor = SuccessGreen
                val missedColor = HabitRed
                val skippedColor = Color(0xFFF97316)
                val pendingColor = Color(0xFFFACC15)

                Canvas(modifier = Modifier.fillMaxSize()) {
                    val strokeWidth = 16.dp.toPx()
                    val stroke = Stroke(width = strokeWidth, cap = StrokeCap.Round)
                    val topLeft = Offset(strokeWidth / 2, strokeWidth / 2)
                    val arcSize = Size(size.width - strokeWidth, size.height - strokeWidth)

                    if (totalCount == 0) {
                        drawArc(
                            color = ringTrackColor,
                            startAngle = -90f,
                            sweepAngle = 360f,
                            useCenter = false,
                            topLeft = topLeft,
                            size = arcSize,
                            style = stroke
                        )
                    } else {
                        val activeValues = listOf(
                            doneCount to doneColor,
                            missedCount to missedColor,
                            skippedCount to skippedColor,
                            pendingCount to pendingColor
                        ).filter { it.first > 0 }

                        val activeCount = activeValues.size
                        val gapAngle = if (activeCount > 1) 6f else 0f
                        val totalGapAngle = activeCount * gapAngle
                        val availableAngle = (360f - totalGapAngle) * animatedFactor

                        var currentStartAngle = -90f

                        activeValues.forEach { (count, color) ->
                            val sweep = (count.toFloat() / totalCount.toFloat()) * availableAngle
                            if (sweep > 0f) {
                                drawArc(
                                    color = color,
                                    startAngle = currentStartAngle,
                                    sweepAngle = sweep,
                                    useCenter = false,
                                    topLeft = topLeft,
                                    size = arcSize,
                                    style = stroke
                                )
                                currentStartAngle += sweep + gapAngle
                            }
                        }
                    }
                }

                // Center Information
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    Box(
                        modifier = Modifier
                            .size(24.dp)
                            .background(SuccessGreen.copy(alpha = 0.18f), CircleShape),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.Check,
                            contentDescription = "Success",
                            tint = SuccessGreen,
                            modifier = Modifier.size(14.dp)
                        )
                    }
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = "$donePct%",
                        style = MaterialTheme.typography.headlineLarge,
                        fontSize = 26.sp,
                        fontWeight = FontWeight.Bold,
                        color = TextPrimary
                    )
                    Spacer(modifier = Modifier.height(2.dp))
                    Text(
                        text = if (language == "de") "$doneCount von $totalCount" else if (language == "ka") "$doneCount $totalCount -დან" else "$doneCount of $totalCount",
                        style = MaterialTheme.typography.labelMedium,
                        fontWeight = FontWeight.SemiBold,
                        color = TextSecondary
                    )
                }
            }

            Spacer(modifier = Modifier.height(20.dp))

            // 4 Summary Metrics Cards at the bottom
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(6.dp)
            ) {
                // 1. Done
                MetricPillBox(
                    modifier = Modifier.weight(1f),
                    icon = Icons.Default.CheckCircle,
                    iconTint = SuccessGreen,
                    bgColor = SuccessGreen.copy(alpha = 0.12f),
                    value = "$donePct%",
                    count = doneCount,
                    label = if (language == "de") "Erreicht" else if (language == "ka") "შესრულებულია" else "Done"
                )

                // 2. Missed
                MetricPillBox(
                    modifier = Modifier.weight(1f),
                    icon = Icons.Default.Close,
                    iconTint = HabitRed,
                    bgColor = HabitRed.copy(alpha = 0.12f),
                    value = "$missedPct%",
                    count = missedCount,
                    label = if (language == "de") "Gescheitert" else if (language == "ka") "გაუშვა" else "Missed"
                )

                // 3. Skipped
                MetricPillBox(
                    modifier = Modifier.weight(1f),
                    icon = Icons.Default.FastForward,
                    iconTint = Color(0xFFF97316),
                    bgColor = Color(0xFFF97316).copy(alpha = 0.12f),
                    value = "$skippedPct%",
                    count = skippedCount,
                    label = if (language == "de") "Skipped" else if (language == "ka") "გამოტოვებული" else "Skipped"
                )

                // 4. Pending
                MetricPillBox(
                    modifier = Modifier.weight(1f),
                    icon = Icons.Default.Schedule,
                    iconTint = Color(0xFFFACC15),
                    bgColor = Color(0xFFFACC15).copy(alpha = 0.12f),
                    value = "$pendingPct%",
                    count = pendingCount,
                    label = if (language == "de") "Ausstehend" else if (language == "ka") "მომლოდინე" else "Pending"
                )
            }
        }
    }
}

@Composable
fun MetricPillBox(
    modifier: Modifier = Modifier,
    icon: ImageVector,
    iconTint: Color,
    bgColor: Color,
    value: String,
    count: Int,
    label: String
) {
    Surface(
        modifier = modifier,
        color = Color.White.copy(alpha = 0.03f),
        shape = RoundedCornerShape(14.dp),
        border = BorderStroke(1.dp, AppBorder.copy(alpha = 0.5f))
    ) {
        Column(
            modifier = Modifier.padding(vertical = 12.dp, horizontal = 2.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            Box(
                modifier = Modifier
                    .size(24.dp)
                    .background(bgColor, CircleShape),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = icon,
                    contentDescription = label,
                    tint = iconTint,
                    modifier = Modifier.size(13.dp)
                )
            }
            Spacer(modifier = Modifier.height(6.dp))
            Text(
                text = "$count",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.ExtraBold,
                color = TextPrimary,
                fontSize = 16.sp
            )
            Text(
                text = value,
                style = MaterialTheme.typography.labelSmall,
                fontWeight = FontWeight.Bold,
                color = iconTint,
                fontSize = 11.sp
            )
            Spacer(modifier = Modifier.height(2.dp))
            Text(
                text = label,
                style = MaterialTheme.typography.labelSmall,
                color = TextSecondary,
                fontSize = 10.sp,
                fontWeight = FontWeight.Medium,
                maxLines = 1
            )
        }
    }
}

