@Composable
fun CalendarDayCell(
    dayNum: String,
    status: String,
    habitColor: Color,
    modifier: Modifier = Modifier,
    onCellClick: (() -> Unit)? = null
) {
    val bgColor = when (status) {
        "SUCCESS" -> SuccessGreen
        "FAILED" -> ErrorRed
        "PENDING" -> Color(0xFFFACC15)
        "PAUSED" -> Color(0xFFF97316)
        else -> Color.White.copy(alpha = 0.03f) // Completely neutral dark grey background without any purple/lila tint
    }
    val textColor = when (status) {
        "SUCCESS", "FAILED", "PENDING", "PAUSED" -> AppBg
        else -> if (status == "INACTIVE") TextSecondary.copy(alpha = 0.4f) else TextPrimary
    }

    Box(
        modifier = modifier
            .padding(4.dp)
            .clip(RoundedCornerShape(8.dp))
            .background(bgColor)
            .then(if (onCellClick != null) Modifier.clickable { onCellClick() } else Modifier),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = dayNum,
            style = MaterialTheme.typography.bodyMedium,
            color = textColor,
            fontWeight = FontWeight.Bold
        )
    }
}

@Composable
fun CalendarMonthGrid(
    gridRows: List<List<CalendarCellState?>>,
    monthName: String,
    habitColor: Color,
    language: String,
    canPrevMonth: Boolean,
    canNextMonth: Boolean,
    onPrevMonth: () -> Unit,
    onNextMonth: () -> Unit,
    onDayClick: ((String) -> Unit)? = null
) {
    Column {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(bottom = 12.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(
                onClick = onPrevMonth,
                enabled = canPrevMonth
            ) {
                Icon(
                    imageVector = Icons.Default.ChevronLeft,
                    contentDescription = "Previous Month",
                    tint = if (canPrevMonth) TextSecondary else TextSecondary.copy(alpha = 0.3f)
                )
            }
            Text(
                text = monthName,
                style = MaterialTheme.typography.titleMedium,
                color = TextPrimary,
                fontWeight = FontWeight.Bold
            )
            IconButton(
                onClick = onNextMonth,
                enabled = canNextMonth
            ) {
                Icon(
                    imageVector = Icons.Default.ChevronRight,
                    contentDescription = "Next Month",
                    tint = if (canNextMonth) TextSecondary else TextSecondary.copy(alpha = 0.3f)
                )
            }
        }

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            val shortDayNames = if (language == "de") listOf("MO", "DI", "MI", "DO", "FR", "SA", "SO") else listOf("MO", "TU", "WE", "TH", "FR", "SA", "SU")
            shortDayNames.forEach {
                key(it) {
                    Text(
                        text = it,
                        style = MaterialTheme.typography.labelSmall,
                        color = TextSecondary,
                        modifier = Modifier.weight(1f),
                        textAlign = TextAlign.Center,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        }

        Spacer(modifier = Modifier.height(8.dp))

        gridRows.forEach { row ->
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                for (c in 0 until 7) {
                    val cell = if (c < row.size) row[c] else null
                    if (cell != null) {
                        key(cell.id) {
                            CalendarDayCell(
                                dayNum = cell.dayNum,
                                status = cell.status,
                                habitColor = habitColor,
                                onCellClick = if (onDayClick != null && cell.id.isNotBlank()) { { onDayClick(cell.id) } } else null,
                                modifier = Modifier.weight(1f).aspectRatio(1f)
                            )
                        }
                    } else {
                        Spacer(modifier = Modifier.weight(1f))
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        // Legende (Erreicht, Gescheitert, Ausstehend, Pausiert) - Screen-resilient 2x2 centered grid
        Column(
            modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceEvenly,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.weight(1f),
                    horizontalArrangement = Arrangement.Center
                ) {
                    Box(
                        modifier = Modifier
                            .size(10.dp)
                            .clip(CircleShape)
                            .background(SuccessGreen)
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(text = if (language == "de") "Erreicht" else if (language == "ka") "დასრულებული" else "Completed", style = MaterialTheme.typography.labelSmall, color = TextSecondary)
                }
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.weight(1f),
                    horizontalArrangement = Arrangement.Center
                ) {
                    Box(
                        modifier = Modifier
                            .size(10.dp)
                            .clip(CircleShape)
                            .background(ErrorRed)
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(text = if (language == "de") "Gescheitert" else if (language == "ka") "ვერ მოხერხდა" else "Failed", style = MaterialTheme.typography.labelSmall, color = TextSecondary)
                }
            }
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceEvenly,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.weight(1f),
                    horizontalArrangement = Arrangement.Center
                ) {
                    Box(
                        modifier = Modifier
                            .size(10.dp)
                            .clip(CircleShape)
                            .background(HabitYellow)
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(text = if (language == "de") "Ausstehend" else if (language == "ka") "მომლოდინე" else "Pending", style = MaterialTheme.typography.labelSmall, color = TextSecondary)
                }
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.weight(1f),
                    horizontalArrangement = Arrangement.Center
                ) {
                    Box(
                        modifier = Modifier
                            .size(10.dp)
                            .clip(CircleShape)
                            .background(HabitOrange)
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(text = if (language == "de") "Skipped" else if (language == "ka") "გამოტოვებული" else "Skipped", style = MaterialTheme.typography.labelSmall, color = TextSecondary)
                }
            }
        }
    }
}

@Immutable
data class MilestoneItem(
    val target: Int,
    val isUnlocked: Boolean,
    val text: String
)

data class RankTier(
    val nameDe: String,
    val nameEn: String,
    val color: Color,
    val icon: ImageVector
)

fun getRankTierForTarget(target: Int): RankTier {
    return when (target) {
        7 -> RankTier("Holz", "Wood", Color(0xFF8B5A2B), Icons.Default.Terrain)
        14 -> RankTier("Bronze", "Bronze", Color(0xFFCD7F32), Icons.Default.WorkspacePremium)
        30 -> RankTier("Silber", "Silver", Color(0xFFC0C0C0), Icons.Default.WorkspacePremium)
        60 -> RankTier("Gold", "Gold", Color(0xFFFFD700), Icons.Default.EmojiEvents)
        100 -> RankTier("Platin", "Platinum", Color(0xFFE5E4E2), Icons.Default.MilitaryTech)
        180 -> RankTier("Diamant", "Diamond", Color(0xFF00E5FF), Icons.Default.Diamond)
        270 -> RankTier("Rubin", "Ruby", Color(0xFFFF1744), Icons.Default.OfflineBolt)
        365 -> RankTier("Meister", "Master", Color(0xFFD500F9), Icons.Default.AutoAwesome)
        500 -> RankTier("Legende", "Legend", Color(0xFFFF9100), Icons.Default.Stars)
        1000 -> RankTier("Unreal", "Unreal", Color(0xFF76FF03), Icons.Default.Whatshot)
        else -> RankTier("Rang", "Rank", Color.White, Icons.Default.EmojiEvents)
    }
}

@Composable
fun MilestoneBadge(milestone: MilestoneItem, language: String) {
    val rank = getRankTierForTarget(milestone.target)
    val color = if (milestone.isUnlocked) rank.color else TextSecondary.copy(alpha = 0.3f)
    val context = LocalContext.current
    val rankName = if (language == "de") rank.nameDe else rank.nameEn

    val scale by animateFloatAsState(
        targetValue = if (milestone.isUnlocked) 1.1f else 1.0f,
        animationSpec = spring(
            dampingRatio = Spring.DampingRatioMediumBouncy,
            stiffness = Spring.StiffnessLow
        ),
        label = "milestone_scale"
    )

    var showConfetti by remember { mutableStateOf(false) }

    Box(
        contentAlignment = Alignment.Center,
        modifier = Modifier.padding(vertical = 4.dp)
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Box(
                modifier = Modifier
                    .size(50.dp)
                    .graphicsLayer {
                        scaleX = scale
                        scaleY = scale
                    }
                    .clickable {
                        if (milestone.isUnlocked) {
                            showConfetti = true
                            Toast.makeText(
                                context,
                                if (language == "de") "Erreicht: $rankName!" else if (language == "ka") "განბლოკილია: $rankName !" else "Unlocked: $rankName!",
                                Toast.LENGTH_SHORT
                            ).show()
                        } else {
                            Toast.makeText(
                                context,
                                if (language == "de") "Noch gesperrt: $rankName (${milestone.target} Tage)" else if (language == "ka") "ჩაკეტილი: $rankName ( ${milestone.target} დღე)" else "Locked: $rankName (${milestone.target} days)",
                                Toast.LENGTH_SHORT
                            ).show()
                        }
                    },
                contentAlignment = Alignment.Center
            ) {
                val tierStr = when (milestone.target) {
                    7 -> "WOOD"
                    14 -> "BRONZE"
                    30 -> "SILVER"
                    60 -> "GOLD"
                    100 -> "PLATINUM"
                    180 -> "DIAMOND"
                    270 -> "RUBY"
                    365 -> "MASTER"
                    500 -> "LEGEND"
                    1000 -> "UNREAL"
                    else -> "WOOD"
                }

                AchievementBadge(
                    type = "STREAK",
                    tier = tierStr,
                    isUnlocked = milestone.isUnlocked,
                    modifier = Modifier.fillMaxSize()
                )

                if (!milestone.isUnlocked) {
                    Box(
                        modifier = Modifier
                            .size(18.dp)
                            .background(AppCard, CircleShape)
                            .border(1.5.dp, TextSecondary.copy(alpha = 0.4f), CircleShape)
                            .align(Alignment.BottomEnd),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.Lock,
                            contentDescription = "Locked",
                            tint = TextSecondary,
                            modifier = Modifier.size(10.dp)
                        )
                    }
                }
            }
            Spacer(modifier = Modifier.height(6.dp))
            Text(
                text = milestone.text,
                style = MaterialTheme.typography.bodySmall,
                color = if (milestone.isUnlocked) TextPrimary else TextSecondary,
                fontWeight = FontWeight.Bold
            )
        }

        if (showConfetti && milestone.isUnlocked) {
            ConfettiAnimation(
                onFinished = { showConfetti = false }
            )
        }
    }
}

@Composable
fun StreakMilestonesCard(longestStreak: Int, language: String) {
    val milestoneTargets = remember { listOf(7, 14, 30, 60, 100, 180, 270, 365, 500, 1000) }
    val items = remember(longestStreak) {
        milestoneTargets.map { target ->
            MilestoneItem(
                target = target,
                isUnlocked = longestStreak >= target,
                text = "$target"
            )
        }
    }

    Card(
        colors = CardDefaults.cardColors(containerColor = AppCard),
        shape = RoundedCornerShape(20.dp),
        modifier = Modifier
            .fillMaxWidth()
            .border(1.dp, AppBorder, RoundedCornerShape(20.dp))
    ) {
        Column(modifier = Modifier.padding(20.dp)) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.padding(bottom = 16.dp)
            ) {
                Icon(
                    imageVector = Icons.Default.MilitaryTech,
                    contentDescription = "Milestones",
                    tint = PrimaryViolet,
                    modifier = Modifier.size(20.dp)
                )
                Spacer(modifier = Modifier.width(8.dp))
                Text(
                    text = if (language == "de") "ERFOLGSSTRÄHNE" else if (language == "ka") "სტრიქის ეტაპები" else "STREAK MILESTONES",
                    style = MaterialTheme.typography.labelSmall,
                    color = TextSecondary,
                    fontWeight = FontWeight.Bold
                )
            }

            Column(
                modifier = Modifier.fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                val chunks = items.chunked(5)
                chunks.forEach { rowItems ->
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        rowItems.forEach { milestone ->
                            Box(modifier = Modifier.weight(1f), contentAlignment = Alignment.Center) {
                                MilestoneBadge(milestone = milestone, language = language)
                            }
                        }
                    }
                }
            }
        }
    }
}

// SETTINGS SCREEN
@Composable
fun SettingsScreen(
    viewModel: HabitsViewModel,
    language: String,
    initialSubpage: String? = null,
    onBack: () -> Unit
) {
    val context = LocalContext.current
    val backupFolderUri by viewModel.backupFolderUri.collectAsStateWithLifecycle()
    val syncStatus by viewModel.syncStatus.collectAsStateWithLifecycle()
    val vibrationEnabled by viewModel.vibrationEnabled.collectAsStateWithLifecycle()
    val accentColorName by viewModel.accentColorName.collectAsStateWithLifecycle()
    val darkModeEnabled by viewModel.darkModeEnabled.collectAsStateWithLifecycle()
    val infoCardsEnabled by viewModel.infoCardsEnabled.collectAsStateWithLifecycle()
    val reviewNotificationsEnabled by viewModel.reviewNotificationsEnabled.collectAsStateWithLifecycle()
    val insightNotificationsEnabled by viewModel.insightNotificationsEnabled.collectAsStateWithLifecycle()
    val monthlyReviewEnabled by viewModel.monthlyReviewEnabled.collectAsStateWithLifecycle()
    val yearlyReviewEnabled by viewModel.yearlyReviewEnabled.collectAsStateWithLifecycle()

    val userName by viewModel.userName.collectAsStateWithLifecycle()
    val profileImageUri by viewModel.profileImageUri.collectAsStateWithLifecycle()
    val isSaskiaUnlocked by viewModel.isSaskiaUnlocked.collectAsStateWithLifecycle()

    var selectedSubpage by rememberSaveable { mutableStateOf<String?>(initialSubpage) }
    BackHandler(enabled = selectedSubpage != null) {
        selectedSubpage = null
    }
    var showWipeConfirm by remember { mutableStateOf(false) }
    var showArchivedList by remember { mutableStateOf(false) }

    var importedAudios by remember { mutableStateOf<List<File>>(emptyList()) }
    var selectedAudioFile by remember { mutableStateOf<File?>(null) }
    var showAudioDialog by remember { mutableStateOf(false) }

    val profileImagePickerLauncherSettings = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.GetContent()
    ) { uri ->
        if (uri != null) {
            try {
                val file = File(context.filesDir, "profile_avatar.jpg")
                context.contentResolver.openInputStream(uri)?.use { input ->
                    file.outputStream().use { output ->
                        input.copyTo(output)
                    }
                }
                viewModel.updateProfileImageUri(android.net.Uri.fromFile(file).toString())
                Toast.makeText(
                    context,
                    if (language == "de") "Profilbild aktualisiert" else if (language == "ka") "პროფილის სურათი განახლდა" else "Profile picture updated",
                    Toast.LENGTH_SHORT
                ).show()
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
    }

    val refreshAudios = remember(context) {
        {
            val dir = File(context.filesDir, "audios")
            if (!dir.exists()) dir.mkdirs()
            importedAudios = dir.listFiles()?.filter { 
                it.isFile && (it.extension.lowercase() in listOf("mp3", "m4a", "wav", "ogg", "aac")) 
            }?.sortedBy { it.name } ?: emptyList()

            val savedName = AudioSoundscapeManager.getLastSelectedAudio(context)
            selectedAudioFile = if (savedName.isNotEmpty()) {
                importedAudios.find { it.name == savedName }
            } else {
                null
            }
        }
    }

    LaunchedEffect(Unit) {
        refreshAudios()
    }

    val audioPickerLauncherSettings = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.GetContent()
    ) { uri ->
        if (uri != null) {
            try {
                val contentResolver = context.contentResolver
                var fileName = "imported_audio_${System.currentTimeMillis()}.mp3"
                contentResolver.query(uri, null, null, null, null)?.use { cursor ->
                    val nameIndex = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
                    if (nameIndex != -1 && cursor.moveToFirst()) {
                        val dispName = cursor.getString(nameIndex)
                        if (!dispName.isNullOrEmpty()) {
                            fileName = dispName
                        }
                    }
                }
                val destDir = File(context.filesDir, "audios")
                if (!destDir.exists()) destDir.mkdirs()
                val destFile = File(destDir, fileName)
                contentResolver.openInputStream(uri)?.use { inputStream ->
                    destFile.outputStream().use { outputStream ->
                        inputStream.copyTo(outputStream)
                    }
                }
                refreshAudios()
                selectedAudioFile = destFile
                AudioSoundscapeManager.setLastSelectedAudio(context, destFile.name)
            } catch (e: Exception) {
                e.printStackTrace()
                Toast.makeText(context, "Import failed", Toast.LENGTH_SHORT).show()
            }
        }
    }

    if (showArchivedList) {
        BackHandler(enabled = true) {
            showArchivedList = false
        }
        val archivedHabits by viewModel.archivedHabits.collectAsStateWithLifecycle()
        var showDeleteConfirmInArchive by remember { mutableStateOf<Habit?>(null) }

        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(AppBg)
        ) {
            LazyColumn(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(horizontal = 16.dp)
                    .navigationBarsPadding(),
                verticalArrangement = Arrangement.spacedBy(12.dp),
                contentPadding = PaddingValues(bottom = 32.dp)
            ) {
                // Spacer for floating header
                item {
                    Spacer(modifier = Modifier.height(84.dp))
                }

                // Description
                item {
                    Text(
                        text = if (language == "de") {
                            "Archivierte Gewohnheiten sind pausiert und werden nicht im Dashboard oder in Statistiken angezeigt. Du kannst sie jederzeit wieder aktivieren."
                        } else {
                            "Archived habits are paused and do not appear in the dashboard or statistics. You can reactivate them at any time."
                        },
                        style = MaterialTheme.typography.bodyMedium,
                        color = TextSecondary,
                        modifier = Modifier.padding(bottom = 16.dp, start = 8.dp, end = 8.dp)
                    )
                }

                if (archivedHabits.isEmpty()) {
                    item {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(300.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = if (language == "de") "Keine archivierten Gewohnheiten." else if (language == "ka") "არქივირებული ჩვევები." else "No archived habits.",
                                style = MaterialTheme.typography.bodyLarge,
                                color = TextSecondary,
                                textAlign = TextAlign.Center
                            )
                        }
                    }
                } else {
                    items(archivedHabits, key = { it.id }) { habit ->
                        val habitColor = remember(habit.color) { HabitIconMapping.getColor(habit.color) }
                        Card(
                            colors = CardDefaults.cardColors(containerColor = AppCard),
                            shape = RoundedCornerShape(16.dp),
                            modifier = Modifier
                                .fillMaxWidth()
                                .border(1.dp, AppBorder, RoundedCornerShape(16.dp))
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(16.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    modifier = Modifier.weight(1f)
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(40.dp)
                                            .background(habitColor.copy(alpha = 0.15f), CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = HabitIconMapping.getIcon(habit.icon),
                                            contentDescription = null,
                                            tint = habitColor,
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }
                                    Spacer(modifier = Modifier.width(12.dp))
                                    Column {
                                        Text(
                                            text = habit.name,
                                            style = MaterialTheme.typography.titleMedium,
                                            color = TextPrimary,
                                            fontWeight = FontWeight.Bold
                                        )
                                        Text(
                                            text = habit.category,
                                            style = MaterialTheme.typography.bodySmall,
                                            color = TextSecondary
                                        )
                                    }
                                }

                                Row(
                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    // Reaktivieren Button
                                    IconButton(
                                        onClick = {
                                            viewModel.unarchiveHabit(habit)
                                            Toast.makeText(
                                                context,
                                                if (language == "de") "${habit.name} reaktiviert" else if (language == "ka") "${habit.name} ხელახლა გააქტიურებულია" else "${habit.name} reactivated",
                                                Toast.LENGTH_SHORT
                                            ).show()
                                        },
                                        modifier = Modifier
                                            .size(36.dp)
                                            .background(ProgressTrack, CircleShape)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Refresh,
                                            contentDescription = "Restore",
                                            tint = SuccessGreen,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }

                                    // Löschen Button
                                    IconButton(
                                        onClick = { showDeleteConfirmInArchive = habit },
                                        modifier = Modifier
                                            .size(36.dp)
                                            .background(ProgressTrack, CircleShape)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Delete,
                                            contentDescription = "Delete",
                                            tint = ErrorRed,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Floating Header Overlay with vertical gradient fade-out
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(84.dp)
                    .background(
                        Brush.verticalGradient(
                            colors = listOf(
                                AppBg,
                                AppBg,
                                AppBg.copy(alpha = 0.9f),
                                AppBg.copy(alpha = 0.5f),
                                Color.Transparent
                            )
                        )
                    )
                    .align(Alignment.TopCenter)
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(start = 16.dp, top = 16.dp, end = 16.dp, bottom = 8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    ModernBackButton(
                        onClick = { showArchivedList = false },
                        testTag = "archive_back_button"
                    )
                    Spacer(modifier = Modifier.width(16.dp))
                    Text(
                        text = if (language == "de") "Archiv" else if (language == "ka") "არქივი" else "Archive",
                        style = MaterialTheme.typography.displayMedium,
                        color = TextPrimary,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        }

        if (showDeleteConfirmInArchive != null) {
            AlertDialog(
                onDismissRequest = { showDeleteConfirmInArchive = null },
                containerColor = AppCard,
                title = { Text(text = if (language == "de") "Gewohnheit endgültig löschen?" else if (language == "ka") "სამუდამოდ წაშალოთ ჩვევა?" else "Delete Habit Permanently?") },
                text = { Text(text = if (language == "de") "Möchtest du '${showDeleteConfirmInArchive?.name}' wirklich unwiderruflich löschen? Alle Verlaufsdaten gehen verloren." else if (language == "ka") "დარწმუნებული ხართ, რომ გსურთ სამუდამოდ წაშალოთ \" ${showDeleteConfirmInArchive?.name} \"? ყველა თვალთვალის ისტორია დაიკარგება." else "Are you sure you want to delete '${showDeleteConfirmInArchive?.name}' permanently? All tracking history will be lost.") },
                confirmButton = {
                    TextButton(
                        onClick = {
                            val h = showDeleteConfirmInArchive!!
                            viewModel.deleteHabit(h)
                            showDeleteConfirmInArchive = null
                            Toast.makeText(
                                context,
                                if (language == "de") "Gewohnheit gelöscht" else if (language == "ka") "ჩვევა წაშლილია" else "Habit deleted",
                                Toast.LENGTH_SHORT
                            ).show()
                        }
                    ) {
                        Text(if (language == "de") "Löschen" else if (language == "ka") "წაშლა" else "Delete", color = ErrorRed)
                    }
                },
                dismissButton = {
                    TextButton(onClick = { showDeleteConfirmInArchive = null }) {
                        Text(if (language == "de") "Abbrechen" else if (language == "ka") "გაუქმება" else "Cancel", color = TextSecondary)
                    }
                }
            )
        }
    } else {

    val folderLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.OpenDocumentTree()
    ) { uri ->
        if (uri != null) {
            try {
                val takeFlags: Int = Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION
                context.contentResolver.takePersistableUriPermission(uri, takeFlags)
            } catch (e: Exception) {
                e.printStackTrace()
            }
            viewModel.saveBackupFolderUri(uri.toString())
        }
    }

    val fileLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.OpenDocument()
    ) { uri ->
        if (uri != null) {
            try {
                context.contentResolver.openInputStream(uri)?.use { inputStream ->
                    val jsonStr = inputStream.bufferedReader().use { it.readText() }
                    viewModel.triggerManualRestore(jsonStr)
                }
            } catch (e: Exception) {
                Toast.makeText(context, "Error reading backup file", Toast.LENGTH_SHORT).show()
            }
        }
    }

