                                }

                                Button(
                                    onClick = { fileLauncher.launch(arrayOf("application/json", "*/*")) },
                                    colors = ButtonDefaults.buttonColors(containerColor = ProgressTrack),
                                    modifier = Modifier.weight(1f),
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Icon(Icons.Default.Restore, contentDescription = "Restore", modifier = Modifier.size(18.dp))
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text(tr(language, "Einspielen", "Restore"))
                                }
                            }

                            if (syncStatus != null) {
                                Spacer(modifier = Modifier.height(10.dp))
                                Text(
                                    text = syncStatus ?: "",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = SuccessGreen,
                                    fontWeight = FontWeight.Bold,
                                    modifier = Modifier.clickable { viewModel.clearSyncStatus() }
                                )
                            }
                        }

                        Spacer(modifier = Modifier.height(16.dp))
                        HorizontalDivider(color = AppBorder, thickness = 1.dp)
                        Spacer(modifier = Modifier.height(16.dp))

                        // Danger Zone / Wipe All Data
                        Column {
                            Text(
                                text = tr(language, "Gefahrenbereich", "Danger Zone"),
                                style = MaterialTheme.typography.bodyMedium,
                                color = ErrorRed,
                                fontWeight = FontWeight.Bold
                            )
                            Text(
                                text = tr(language, "Hiermit werden alle Gewohnheiten unwiderruflich gelöscht.", "This permanently deletes all habits and tracking history."),
                                style = MaterialTheme.typography.bodySmall,
                                color = TextSecondary,
                                modifier = Modifier.padding(bottom = 10.dp)
                            )
                            Button(
                                onClick = { showWipeConfirm = true },
                                colors = ButtonDefaults.buttonColors(containerColor = ErrorRed),
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Icon(Icons.Default.DeleteForever, contentDescription = "Wipe", modifier = Modifier.size(18.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(tr(language, "Alles löschen", "Wipe All Data"))
                            }
                        }
                    }
                }
            }
        }
    }
}

        // Floating Header Overlay with vertical gradient fade-out
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(84.dp)
                .background(
                    Brush.verticalGradient(
                        colors = listOf(
                            AppBg,
                            AppBg,
                            AppBg.copy(alpha = 0.9f),
                            AppBg.copy(alpha = 0.5f),
                            Color.Transparent
                        )
                    )
                )
                .align(Alignment.TopCenter)
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(start = 16.dp, top = 16.dp, end = 16.dp, bottom = 8.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                ModernBackButton(
                    onClick = {
                        if (selectedSubpage != null) {
                            selectedSubpage = null
                        } else {
                            onBack()
                        }
                    },
                    testTag = "settings_back_button"
                )
                Spacer(modifier = Modifier.width(16.dp))
                val headerTitle = when (selectedSubpage) {
                    "profile" -> tr(language, "Profil & Konto", "Profile & Account")
                    "appearance" -> tr(language, "Erscheinungsbild & Sprache", "Appearance & Language")
                    "notifications" -> tr(language, "Benachrichtigungen", "Notifications")
                    "audio" -> tr(language, "Töne & Entspannung", "Audio & Soundscapes")
                    "data" -> tr(language, "Daten, Sicherung & Archiv", "Data, Backup & Archive")
                    "about" -> tr(language, "Support & Über die App", "Support & About")
                    else -> tr(language, "Einstellungen", "Settings")
                }
                Text(
                    text = headerTitle,
                    style = MaterialTheme.typography.displayMedium,
                    color = TextPrimary,
                    fontWeight = FontWeight.Bold
                )
            }
        }
    }

    if (showWipeConfirm) {
        AlertDialog(
            onDismissRequest = { showWipeConfirm = false },
            title = { Text(text = if (language == "de") "ALLE DATEN LÖSCHEN?" else if (language == "ka") "წაშალოთ ყველა მონაცემი?" else "WIPE ALL DATA?") },
            text = { Text(text = if (language == "de") "Möchtest du wirklich alle angelegten Gewohnheiten und Log-Einträge restlos entfernen? Das kann nicht rückgängig gemacht werden!" else if (language == "ka") "დარწმუნებული ხართ, რომ გსურთ სამუდამოდ გაასუფთავოთ ყველა ჩვევა და ისტორიული პროგრესი? ამ მოქმედების გაუქმება შეუძლებელია!" else "Are you sure you want to clear all habits and historic progress permanently? This action cannot be undone!") },
            confirmButton = {
                Button(
                    onClick = {
                        viewModel.wipeAllData()
                        showWipeConfirm = false
                        Toast.makeText(
                            context,
                            if (language == "de") "Alle Daten gelöscht" else if (language == "ka") "ყველა მონაცემი წაშლილია" else "All data wiped",
                            Toast.LENGTH_SHORT
                        ).show()
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = ErrorRed)
                ) {
                    Text(if (language == "de") "Ja, Löschen" else if (language == "ka") "დიახ, Wipe" else "Yes, Wipe")
                }
            },
            dismissButton = {
                TextButton(onClick = { showWipeConfirm = false }) {
                    Text(if (language == "de") "Abbrechen" else if (language == "ka") "გაუქმება" else "Cancel")
                }
            }
        )
    }

    if (showAudioDialog) {
        AudioSoundscapeDialog(
            language = language,
            importedAudios = importedAudios,
            selectedAudioFile = selectedAudioFile,
            onSelectAudio = { file ->
                selectedAudioFile = file
                AudioSoundscapeManager.setLastSelectedAudio(context, file?.name ?: "")
                showAudioDialog = false
            },
            onImportAudioClick = {
                try {
                    audioPickerLauncherSettings.launch("audio/*")
                } catch (e: Exception) {
                    e.printStackTrace()
                }
            },
            onDeleteAudioClick = { file ->
                try {
                    if (file.exists()) {
                        file.delete()
                        refreshAudios()
                        if (selectedAudioFile?.absolutePath == file.absolutePath) {
                            selectedAudioFile = null
                            AudioSoundscapeManager.setLastSelectedAudio(context, "")
                        }
                    }
                } catch (e: Exception) {
                    e.printStackTrace()
                }
            },
            onDismiss = { showAudioDialog = false }
        )
    }
    }
}

// CREATE HABIT SCREEN
@OptIn(ExperimentalLayoutApi::class)
@Composable
fun CreateHabitScreen(
    language: String,
    onDismiss: () -> Unit,
    onSave: (name: String, isNegative: Boolean, category: String, icon: String, color: String, type: String, unit: String, target: Float, clickIncrement: Float, freq: String, startMs: Long, specificDays: String, reminderEnabled: Boolean, reminderHour: Int, reminderMinute: Int, customReminders: String, description: String, milestoneRewards: List<com.example.data.MilestoneReward>) -> Unit,
    editingHabit: Habit? = null
) {
    BackHandler {
        onDismiss()
    }
    var isNegative by remember(editingHabit?.id) { mutableStateOf(editingHabit?.isNegative ?: false) } // Aufbauen = false, Abgewöhnen = true
    var activeExplanation by remember(editingHabit?.id) { mutableStateOf<Pair<String, String>?>(null) }
    var name by remember(editingHabit?.id) { mutableStateOf(editingHabit?.name ?: "") }
    var description by remember(editingHabit?.id) { mutableStateOf(editingHabit?.description ?: "") }
    var milestoneRewards by remember(editingHabit?.id) { mutableStateOf<List<com.example.data.MilestoneReward>>(emptyList()) }
    var nameError by remember(editingHabit?.id) { mutableStateOf(false) }
    val scrollState = rememberScrollState()
    val coroutineScope = rememberCoroutineScope()
    var category by remember(editingHabit?.id) { mutableStateOf(editingHabit?.category ?: (if (language == "de") "Allgemein" else if (language == "ka") "გენერალი" else "General")) }
    var selectedIcon by remember(editingHabit?.id) { mutableStateOf(editingHabit?.icon ?: "sparkle") }
    var selectedColor by remember(editingHabit?.id) { mutableStateOf(editingHabit?.color ?: "purple") }
    var type by remember(editingHabit?.id) { mutableStateOf(editingHabit?.type ?: "BINARY") } // "BINARY" or "NUMBER"
    var unit by remember(editingHabit?.id) { mutableStateOf(editingHabit?.unit ?: (if (language == "de") "Minuten" else if (language == "ka") "წუთები" else "Minutes")) }
    var selectedChip by remember(editingHabit?.id, unit) {
        val standardUnitsDe = listOf("Minuten", "Liter", "ml", "km", "Stunden", "Mal")
        val standardUnitsEn = listOf("Minutes", "Liters", "ml", "km", "Hours", "Times")
        val initialChip = when {
            unit.isEmpty() -> if (language == "de") "Minuten" else if (language == "ka") "წუთები" else "Minutes"
            language == "de" && unit in standardUnitsDe -> unit
            language != "de" && unit in standardUnitsEn -> unit
            unit.lowercase() in listOf("minuten", "minutes", "min") -> if (language == "de") "Minuten" else if (language == "ka") "წუთები" else "Minutes"
            unit.lowercase() in listOf("liter", "liters", "l") -> if (language == "de") "Liter" else if (language == "ka") "ლიტრი" else "Liters"
            unit.lowercase() == "ml" -> "ml"
            unit.lowercase() == "km" -> "km"
            unit.lowercase() in listOf("stunden", "hours", "h") -> if (language == "de") "Stunden" else if (language == "ka") "საათები" else "Hours"
            unit.lowercase() in listOf("mal", "times") -> if (language == "de") "Mal" else if (language == "ka") "ჯერ" else "Times"
            else -> if (language == "de") "Anderes..." else if (language == "ka") "მორგებული..." else "Custom..."
        }
        mutableStateOf(initialChip)
    }
    var targetValueStr by remember(editingHabit?.id) { 
        mutableStateOf(editingHabit?.let { if (it.targetValue % 1f == 0f) it.targetValue.toInt().toString() else it.targetValue.toString() } ?: "1") 
    }
    var clickIncrementStr by remember(editingHabit?.id) {
        mutableStateOf(editingHabit?.let { if (it.clickIncrement % 1f == 0f) it.clickIncrement.toInt().toString() else it.clickIncrement.toString() } ?: "1")
    }
    var frequency by remember(editingHabit?.id) { mutableStateOf(editingHabit?.frequency ?: "DAILY") }
    var timesWeekly by remember(editingHabit?.id) {
        val initialTimes = if (editingHabit?.frequency == "TIMES_WEEKLY") {
            editingHabit.specificDays.toIntOrNull() ?: 3
        } else {
            3
        }
        mutableStateOf(initialTimes)
    }
    var specificDaysSet by remember(editingHabit?.id) {
        val initialSet = editingHabit?.specificDays
            ?.split(",")
            ?.mapNotNull { it.trim().toIntOrNull() }
            ?.toSet() ?: emptySet()
        mutableStateOf(initialSet)
    }
    var reminderEnabled by remember(editingHabit?.id) { mutableStateOf(editingHabit?.reminderEnabled ?: false) }
    var remindersList by remember(editingHabit?.id) {
        val list = mutableListOf<String>()
        if (editingHabit != null && editingHabit.reminderEnabled) {
            list.add(String.format(java.util.Locale.US, "%02d:%02d", editingHabit.reminderHour, editingHabit.reminderMinute))
            val initialStr = editingHabit.customReminders ?: ""
            if (initialStr.isNotEmpty()) {
                list.addAll(initialStr.split(",").filter { it.isNotEmpty() })
            }
        }
        mutableStateOf(list.distinct().sorted())
    }
    var reminderToEditTime by remember(editingHabit?.id) { mutableStateOf<String?>(null) }
    var showAddCustomDialog by remember(editingHabit?.id) { mutableStateOf(false) }
    
    // Default start date is today or habit's startDate (cleared to midnight for new habits so they start today!)
    val initialDateMillis = remember(editingHabit?.id) {
        if (editingHabit != null) {
            editingHabit.startDate
        } else {
            java.time.LocalDate.now()
                .atStartOfDay(java.time.ZoneId.systemDefault())
                .toInstant()
                .toEpochMilli()
        }
    }
    var startDateMillis by remember(initialDateMillis) { mutableStateOf(initialDateMillis) }
    var showDatePicker by remember(editingHabit?.id) { mutableStateOf(false) }

    val formattedStartDate = remember(startDateMillis) {
        val localDate = java.time.Instant.ofEpochMilli(startDateMillis)
            .atZone(java.time.ZoneId.systemDefault())
            .toLocalDate()
        val formatter = java.time.format.DateTimeFormatter.ofPattern("d. MMMM yyyy", java.util.Locale.GERMANY)
        localDate.format(formatter)
    }

    val nameFocusRequester = remember { FocusRequester() }
    val keyboardController = androidx.compose.ui.platform.LocalSoftwareKeyboardController.current
    LaunchedEffect(Unit) {
        kotlinx.coroutines.delay(200)
        nameFocusRequester.requestFocus()
        keyboardController?.show()
    }

    val focusManager = androidx.compose.ui.platform.LocalFocusManager.current
    ClearFocusOnKeyboardDismiss()

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background)
            .pointerInput(Unit) {
                detectTapGestures(onTap = {
                    focusManager.clearFocus()
                    keyboardController?.hide()
                })
            }
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .navigationBarsPadding()
                .imePadding()
                .verticalScroll(scrollState)
                .padding(horizontal = 24.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Spacer(modifier = Modifier.height(84.dp))
            
            // Name field directly
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                Text(
                    text = if (language == "de") "Name der Gewohnheit" else if (language == "ka") "ჩვევის სახელი" else "Habit Name",
                    style = MaterialTheme.typography.titleLarge,
                    color = TextPrimary,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.padding(start = 4.dp)
                )
                OutlinedTextField(
                    value = name,
                    onValueChange = { 
                        name = it
                        if (it.isNotBlank()) {
                            nameError = false
                        }
                    },
                    placeholder = { Text(if (language == "de") "z.B. Meditieren, Laufen, Lesen..." else if (language == "ka") "მაგ., მედიტაცია, სირბილი, კითხვა..." else "e.g., Meditate, Running, Reading...") },
                    isError = nameError,
                    supportingText = {
                        if (nameError) {
                            Text(
                                text = if (language == "de") "Bitte gib einen Namen ein" else if (language == "ka") "გთხოვთ შეიყვანოთ სახელი" else "Please enter a name",
                                color = FailedRed,
                                style = MaterialTheme.typography.labelSmall
                            )
                        }
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .focusRequester(nameFocusRequester)
                        .testTag("habit_name_input"),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = PrimaryViolet,
                        unfocusedBorderColor = AppBorder,
                        errorBorderColor = FailedRed,
                        errorCursorColor = FailedRed,
                        errorSupportingTextColor = FailedRed,
                        focusedContainerColor = AppCard,
                        unfocusedContainerColor = AppCard,
                        errorContainerColor = FailedRed.copy(alpha = 0.08f)
                    ),
                    shape = RoundedCornerShape(16.dp),
                    singleLine = true,
                    leadingIcon = {
                        Icon(
                            imageVector = Icons.Default.Edit,
                            contentDescription = null,
                            tint = if (name.isNotBlank()) PrimaryViolet else TextSecondary,
                            modifier = Modifier.size(20.dp)
                        )
                    }
                )
            }

            // Description field (optional)
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                Text(
                    text = if (language == "de") "Beschreibung (optional)" else if (language == "ka") "აღწერა (სურვილისამებრ)" else "Description (optional)",
                    style = MaterialTheme.typography.titleLarge,
                    color = TextPrimary,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.padding(start = 4.dp)
                )
                OutlinedTextField(
                    value = description,
                    onValueChange = { description = it },
                    placeholder = { Text(if (language == "de") "z.B. Notizen, Motivation oder Regeln..." else if (language == "ka") "მაგ. შენიშვნები, მოტივაცია თუ წესები..." else "e.g. Notes, motivation or rules...") },
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("habit_description_input"),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = PrimaryViolet,
                        unfocusedBorderColor = AppBorder,
                        focusedContainerColor = AppCard,
                        unfocusedContainerColor = AppCard
                    ),
                    shape = RoundedCornerShape(16.dp),
                    minLines = 1,
                    maxLines = 4,
                    leadingIcon = {
                        Icon(
                            imageVector = Icons.Default.Description,
                            contentDescription = null,
                            tint = if (description.isNotBlank()) PrimaryViolet else TextSecondary,
                            modifier = Modifier.size(20.dp)
                        )
                    }
                )
            }

                // Goal Segment (Aufbauen / Abgewöhnen)
                Column(
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = if (language == "de") "Ziel" else if (language == "ka") "მიზანი" else "Goal",
                            style = MaterialTheme.typography.titleLarge,
                            color = TextPrimary,
                            fontWeight = FontWeight.Bold
                        )
                        Spacer(modifier = Modifier.width(6.dp))
                        InfoIconButton(
                            title = if (language == "de") "Gewohnheitstyp" else if (language == "ka") "ჩვევის ტიპი" else "Habit Type",
                            explanation = if (language == "de") {
                                "Aufbauende Gewohnheit: Perfekt für neue Routinen (z.B. Sport, Meditation). Jeder Log erhöht deinen Fortschritt bis zum Tagesziel.\n\nAbgewöhnende Gewohnheit: Perfekt um schlechte Angewohnheiten loszuwerden (z.B. Rauchen). Standardmäßig als 'Erfolgreich' markiert, solange du dein Limit nicht überschreitest."
                            } else {
                                "Building Habit: Ideal for establishing new routines (e.g., exercise, meditation). Each log increases progress toward your daily goal.\n\nQuitting Habit: Ideal for breaking bad habits (e.g., smoking). Marked as 'Successful' by default as long as you stay within limits."
                            },
                            onClick = { t, e -> activeExplanation = t to e }
                        )
                    }

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Button(
                            onClick = { isNegative = false },
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (!isNegative) PrimaryViolet else ProgressTrack
                            ),
                            modifier = Modifier.weight(1f).height(46.dp),
                            shape = RoundedCornerShape(12.dp),
                            contentPadding = PaddingValues(0.dp)
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(Icons.Default.ArrowUpward, contentDescription = "Build Up", modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(if (language == "de") "Aufbauen" else if (language == "ka") "აშენება" else "Build", style = MaterialTheme.typography.titleSmall)
                            }
                        }

                        Button(
                            onClick = { isNegative = true },
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (isNegative) PrimaryViolet else ProgressTrack
                            ),
                            modifier = Modifier.weight(1f).height(46.dp),
                            shape = RoundedCornerShape(12.dp),
                            contentPadding = PaddingValues(0.dp)
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(Icons.Default.ArrowDownward, contentDescription = "Quit Down", modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(if (language == "de") "Abgewöhnen" else if (language == "ka") "თავი დაანებე" else "Quit", style = MaterialTheme.typography.titleSmall)
                            }
                        }
                    }
                }

                // Customize Visuals (Icons & Colors)
                Column(
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Text(
                        text = if (language == "de") "Aussehen anpassen" else if (language == "ka") "Visuals-ის მორგება" else "Customize Visuals",
                        style = MaterialTheme.typography.titleLarge,
                        color = TextPrimary,
                        fontWeight = FontWeight.Bold
                    )

                    // Icon selector
                    Text(
                        text = if (language == "de") "Icon auswählen" else if (language == "ka") "აირჩიეთ ხატულა" else "Select Icon",
                        style = MaterialTheme.typography.labelMedium,
                        color = TextSecondary,
                        fontWeight = FontWeight.Medium
                    )

                    val activeColor = HabitIconMapping.getColor(selectedColor)
                    var selectedCategoryId by remember { mutableStateOf("all") }

                    LazyRow(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        items(HabitIconMapping.categories) { cat ->
                            val isCatSelected = selectedCategoryId == cat.id
                            FilterChip(
                                selected = isCatSelected,
                                onClick = { selectedCategoryId = cat.id },
                                label = {
                                    Text(
                                        text = if (language == "de") cat.nameDe else cat.nameEn,
                                        style = MaterialTheme.typography.labelSmall,
                                        fontWeight = if (isCatSelected) FontWeight.Bold else FontWeight.Normal
                                    )
                                },
                                colors = FilterChipDefaults.filterChipColors(
                                    selectedContainerColor = activeColor.copy(alpha = 0.25f),
                                    selectedLabelColor = TextPrimary,
                                    containerColor = ProgressTrack,
                                    labelColor = TextSecondary
                                ),
                                border = FilterChipDefaults.filterChipBorder(
                                    enabled = true,
                                    selected = isCatSelected,
                                    selectedBorderColor = activeColor,
                                    borderColor = AppBorder,
                                    borderWidth = 1.dp,
                                    selectedBorderWidth = 1.5.dp
                                ),
                                shape = RoundedCornerShape(20.dp)
                            )
                        }
                    }

                    val filteredIcons = remember(selectedCategoryId) {
                        if (selectedCategoryId == "all") {
                            HabitIconMapping.iconList
                        } else {
                            val cat = HabitIconMapping.categories.find { it.id == selectedCategoryId }
                            val keys = cat?.keys ?: emptyList()
                            HabitIconMapping.iconList.filter { keys.contains(it.first) }
                        }
                    }

                    val nestedScrollConnection = remember {
                        object : NestedScrollConnection {
                            override fun onPostScroll(
                                consumed: Offset,
                                available: Offset,
                                source: NestedScrollSource
                            ): Offset {
                                return available
                            }

                            override suspend fun onPostFling(
                                consumed: Velocity,
                                available: Velocity
                            ): Velocity {
                                return available
                            }
                        }
                    }

                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(210.dp)
                            .background(AppCard, RoundedCornerShape(16.dp))
                            .border(1.dp, AppBorder, RoundedCornerShape(16.dp))
                            .padding(8.dp)
                    ) {
                        LazyVerticalGrid(
                            columns = GridCells.Adaptive(minSize = 48.dp),
                            horizontalArrangement = Arrangement.spacedBy(10.dp),
                            verticalArrangement = Arrangement.spacedBy(10.dp),
                            modifier = Modifier
                                .fillMaxSize()
                                .nestedScroll(nestedScrollConnection)
                        ) {
                            items(filteredIcons) { (key, _) ->
                                val isSelected = selectedIcon == key
                                var showTooltip by remember { mutableStateOf(false) }

                                Box(
                                    modifier = Modifier
                                        .size(48.dp)
                                        .background(
                                            if (isSelected) activeColor.copy(alpha = 0.2f) else ProgressTrack,
                                            RoundedCornerShape(12.dp)
                                        )
                                        .border(
                                            width = if (isSelected) 2.dp else 1.dp,
                                            color = if (isSelected) activeColor else AppBorder,
                                            shape = RoundedCornerShape(12.dp)
                                        )
                                        .pointerInput(key) {
                                            detectTapGestures(
                                                onTap = { selectedIcon = key },
                                                onLongPress = { showTooltip = true }
                                            )
                                        },
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = HabitIconMapping.getIcon(key),
                                        contentDescription = key,
                                        tint = if (isSelected) activeColor else TextSecondary,
                                        modifier = Modifier.size(24.dp)
                                    )

                                    if (showTooltip) {
                                        val density = androidx.compose.ui.platform.LocalDensity.current
                                        val offsetInPx = with(density) { -52.dp.roundToPx() }
                                        androidx.compose.ui.window.Popup(
                                            alignment = Alignment.TopCenter,
                                            offset = androidx.compose.ui.unit.IntOffset(0, offsetInPx),
                                            onDismissRequest = { showTooltip = false }
                                        ) {
                                            Card(
                                                colors = CardDefaults.cardColors(containerColor = AppCard),
                                                shape = RoundedCornerShape(8.dp),
                                                modifier = Modifier
                                                    .border(1.dp, AppBorder, RoundedCornerShape(8.dp))
                                                    .widthIn(max = 200.dp)
                                            ) {
                                                Text(
                                                    text = getIconLabel(key, language),
                                                    color = TextPrimary,
                                                    style = MaterialTheme.typography.labelLarge.copy(fontSize = 11.sp),
                                                    fontWeight = FontWeight.Bold,
                                                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                                                    textAlign = TextAlign.Center
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(4.dp))

                    // Color selector dots
                    Text(
                        text = if (language == "de") "Farbe auswählen" else if (language == "ka") "აირჩიეთ ფერი" else "Select Color",
                        style = MaterialTheme.typography.labelMedium,
                        color = TextSecondary,
                        fontWeight = FontWeight.Medium
                    )

                    com.example.ui.components.ColorPaletteSelector(
                        selectedColorKey = selectedColor,
                        onColorSelected = { selectedColor = it },
                        language = language
                    )
                }

                // Type Toggle (Ja/Nein vs Zahlenbasiert)
                Column(
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = if (language == "de") "Art der Messung" else if (language == "ka") "გაზომვის ტიპი" else "Measurement Type",
                            style = MaterialTheme.typography.titleLarge,
                            color = TextPrimary,
                            fontWeight = FontWeight.Bold
                        )
                        Spacer(modifier = Modifier.width(6.dp))
                        InfoIconButton(
                            title = if (language == "de") "Art der Messung" else if (language == "ka") "გაზომვის ტიპი" else "Measurement Type",
                            explanation = if (language == "de") {
                                "Ja / Nein: Ideal für einfache Gewohnheiten (z.B. Vitamine einnehmen, Bett machen).\n\nZahlenbasiert: Perfekt für Gewohnheiten, bei denen du eine Menge oder Dauer tracken willst (z.B. 2 Liter trinken, 30 Minuten lesen)."
                            } else if (language == "ka") {
                        "დიახ / არა: იდეალურია მარტივი ჩვევებისთვის, რომლებსაც ან აკეთებთ ან არ აკეთებთ (მაგ., ვიტამინების მიღება, საწოლის გასწორება).\n\nციფრული: იდეალურია ჩვევებისთვის, სადაც გსურთ თვალყური ადევნოთ რაოდენობას ან ხანგრძლივობას (მაგ., დალიეთ 2 ლიტრი, წაიკითხეთ 30 წუთი)."
                    } else {
                        "Yes / No: Perfect for simple habits that you either do or don't (e.g., take vitamins, make bed).\n\nNumeric: Perfect for habits where you want to track a quantity or duration (e.g., drink 2 liters, read for 30 minutes)."
                    },
                            onClick = { t, e -> activeExplanation = t to e }
                        )
                    }

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Button(
                            onClick = { type = "BINARY" },
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (type == "BINARY") PrimaryViolet else ProgressTrack
                            ),
                            modifier = Modifier.weight(1f).height(46.dp),
                            shape = RoundedCornerShape(12.dp),
                            contentPadding = PaddingValues(0.dp)
                        ) {
                            Text(if (language == "de") "Ja / Nein" else if (language == "ka") "დიახ / არა" else "Yes / No", style = MaterialTheme.typography.titleSmall)
                        }

                        Button(
                            onClick = { type = "NUMBER" },
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (type == "NUMBER") PrimaryViolet else ProgressTrack
                            ),
                            modifier = Modifier.weight(1f).height(46.dp),
                            shape = RoundedCornerShape(12.dp),
                            contentPadding = PaddingValues(0.dp)
                        ) {
                            Text(if (language == "de") "Zahlenbasiert" else if (language == "ka") "რიცხვითი" else "Numeric", style = MaterialTheme.typography.titleSmall)
                        }
                    }
                }

                if (type == "NUMBER") {
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Text(
                            text = if (language == "de") "Einheit auswählen" else if (language == "ka") "აირჩიეთ ერთეული" else "Select Unit",
                            style = MaterialTheme.typography.bodyMedium,
                            color = TextSecondary,
                            fontWeight = FontWeight.SemiBold
                        )

                        val standardUnits = if (language == "de") {
                            listOf("Minuten", "Liter", "ml", "km", "Stunden", "Mal", "Anderes...")
                        } else {
                            listOf("Minutes", "Liters", "ml", "km", "Hours", "Times", "Custom...")
                        }

                        val row1 = standardUnits.take(4)
                        val row2 = standardUnits.drop(4)

                        Column(
                            modifier = Modifier.fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                row1.forEach { standardUnit ->
                                    val isSelected = selectedChip == standardUnit
                                    Button(
                                        onClick = { 
                                            selectedChip = standardUnit
                                            if (standardUnit != "Anderes..." && standardUnit != "Custom...") {
                                                unit = standardUnit
                                            } else {
                                                unit = ""
                                            }
                                        },
                                        colors = ButtonDefaults.buttonColors(
                                            containerColor = if (isSelected) PrimaryViolet else ProgressTrack,
                                            contentColor = if (isSelected) TextPrimary else TextSecondary
                                        ),
                                        modifier = Modifier.weight(1f).height(44.dp),
                                        shape = RoundedCornerShape(12.dp),
                                        contentPadding = PaddingValues(0.dp)
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.Center
                                        ) {
                                            if (standardUnit.lowercase() in listOf("minuten", "minutes")) {
                                                Icon(
                                                    imageVector = Icons.Default.Timer,
                                                    contentDescription = null,
                                                    tint = if (isSelected) TextPrimary else TextSecondary,
                                                    modifier = Modifier.size(16.dp)
                                                )
                                                Spacer(modifier = Modifier.width(4.dp))
                                            }
                                            Text(
                                                text = standardUnit,
                                                style = MaterialTheme.typography.titleSmall.copy(fontSize = 12.sp),
                                                maxLines = 1,
                                                overflow = TextOverflow.Ellipsis
                                            )
                                        }
                                    }
                                }
                            }

                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                row2.forEach { standardUnit ->
                                    val isSelected = selectedChip == standardUnit
                                    Button(
                                        onClick = { 
                                            selectedChip = standardUnit
                                            if (standardUnit != "Anderes..." && standardUnit != "Custom...") {
                                                unit = standardUnit
                                            } else {
                                                unit = ""
                                            }
                                        },
                                        colors = ButtonDefaults.buttonColors(
                                            containerColor = if (isSelected) PrimaryViolet else ProgressTrack,
                                            contentColor = if (isSelected) TextPrimary else TextSecondary
                                        ),
                                        modifier = Modifier.weight(1f).height(44.dp),
                                        shape = RoundedCornerShape(12.dp),
                                        contentPadding = PaddingValues(0.dp)
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.Center
                                        ) {
                                            Text(
                                                text = standardUnit,
                                                style = MaterialTheme.typography.titleSmall.copy(fontSize = 12.sp),
                                                maxLines = 1,
                                                overflow = TextOverflow.Ellipsis
                                            )
                                        }
                                    }
                                }
                            }
                        }

                        Row(
                            modifier = Modifier.fillMaxWidth().padding(top = 4.dp),
                            horizontalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            if (selectedChip == "Anderes..." || selectedChip == "Custom...") {
                                OutlinedTextField(
                                    value = unit,
                                    onValueChange = { unit = it },
                                    label = { Text(tr(language, "Eigene Einheit", "Custom Unit")) },
                                    placeholder = { Text(tr(language, "z. B. Tassen", "e.g. cups")) },
                                    modifier = Modifier.weight(1f),
                                    singleLine = true,
                                    colors = OutlinedTextFieldDefaults.colors(
                                        focusedBorderColor = PrimaryViolet,
                                        unfocusedBorderColor = AppBorder,
                                        focusedContainerColor = AppCard,
                                        unfocusedContainerColor = AppCard,
                                        focusedLabelColor = PrimaryViolet,
                                        focusedTextColor = TextPrimary,
                                        unfocusedTextColor = TextPrimary
                                    )
                                )
                            }

                            OutlinedTextField(
                                value = targetValueStr,
                                onValueChange = { targetValueStr = it },
                                label = { Text(tr(language, "Tagesziel", "Daily Target")) },
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                modifier = Modifier.weight(1f),
                                singleLine = true,
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedBorderColor = PrimaryViolet,
                                    unfocusedBorderColor = AppBorder,
                                    focusedContainerColor = AppCard,
                                    unfocusedContainerColor = AppCard,
                                    focusedLabelColor = PrimaryViolet,
                                    focusedTextColor = TextPrimary,
                                    unfocusedTextColor = TextPrimary
                                )
                            )

                            OutlinedTextField(
                                value = clickIncrementStr,
                                onValueChange = { clickIncrementStr = it },
                                label = { Text(tr(language, "Erhöhung / Klick", "Click Increment")) },
                                placeholder = { Text("1") },
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                modifier = Modifier.weight(1f),
                                singleLine = true,
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedBorderColor = PrimaryViolet,
                                    unfocusedBorderColor = AppBorder,
                                    focusedContainerColor = AppCard,
                                    unfocusedContainerColor = AppCard,
                                    focusedLabelColor = PrimaryViolet,
                                    focusedTextColor = TextPrimary,
                                    unfocusedTextColor = TextPrimary
                                )
                            )
                        }
                    }
                }

                // Frequency Selector
                Column(
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Text(
                        text = if (language == "de") "Häufigkeit" else if (language == "ka") "სიხშირე" else "Frequency",
                        style = MaterialTheme.typography.titleLarge,
                        color = TextPrimary,
                        fontWeight = FontWeight.Bold
                    )

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        val freqOptions = listOf(
                            "DAILY" to (if (language == "de") "Täglich" else if (language == "ka") "ყოველდღიური" else "Daily"),
                            "TIMES_WEEKLY" to (if (language == "de") "X mal/Wo" else if (language == "ka") "X ჯერ / კვირა" else "X times/Wk"),
                            "SPECIFIC" to (if (language == "de") "Tage" else if (language == "ka") "დღეები" else "Days")
                        )
                        freqOptions.forEach { (key, label) ->
                            val isSelected = frequency == key
                            Button(
                                onClick = { 
                                    frequency = key 
                                    if (key == "SPECIFIC" && specificDaysSet.isEmpty()) {
                                        specificDaysSet = setOf(1, 2, 3, 4, 5, 6, 7)
                                    }
                                },
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = if (isSelected) PrimaryViolet else ProgressTrack,
                                    contentColor = if (isSelected) TextPrimary else TextSecondary
                                ),
                                modifier = Modifier.weight(1f).height(44.dp),
                                shape = RoundedCornerShape(12.dp),
                                contentPadding = PaddingValues(0.dp)
                            ) {
                                Text(label, style = MaterialTheme.typography.titleSmall, maxLines = 1)
                            }
                        }
                    }

                    if (frequency == "TIMES_WEEKLY") {
                        Spacer(modifier = Modifier.height(4.dp))
                        Row(
                            modifier = Modifier.fillMaxWidth().padding(horizontal = 4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            (1..7).forEach { num ->
                                val isSelected = timesWeekly == num
                                Box(
                                    modifier = Modifier
                                        .size(42.dp)
                                        .background(
                                            color = if (isSelected) SuccessGreen else ProgressTrack,
                                            shape = CircleShape
                                        )
                                        .clickable {
                                            timesWeekly = num
                                        },
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = num.toString(),
                                        style = MaterialTheme.typography.bodyMedium,
                                        fontWeight = FontWeight.Bold,
                                        color = if (isSelected) AppBg else TextPrimary
                                    )
                                }
                            }
                        }
                        if (LocalInfoCardsEnabled.current) {
                            Spacer(modifier = Modifier.height(10.dp))
                            Surface(
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp),
                                color = PrimaryViolet.copy(alpha = 0.12f),
                                border = BorderStroke(1.dp, PrimaryViolet.copy(alpha = 0.3f))
                            ) {
                                Row(
                                    modifier = Modifier.padding(12.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Info,
                                        contentDescription = "Info",
                                        tint = PrimaryViolet,
                                        modifier = Modifier.size(20.dp)
                                    )
                                    Spacer(modifier = Modifier.width(10.dp))
                                    Text(
                                        text = if (language == "de")
                                            "Flexibler 7-Tage-Zeitraum: Das Wochenziel zählt deine Abschlüsse der letzten 7 Tage (rollierend) – nicht starr von Montag bis Sonntag."
                                        else if (language == "ka") "მოქნილი 7 დღიანი ფანჯარა: თქვენი ყოველკვირეული სამიზნე ითვლის დასრულებებს ბოლო 7 დღის განმავლობაში (მოძრავი) - არა მკაცრად ორშაბათიდან კვირამდე." else "Flexible 7-day window: Your weekly target counts completions over the last 7 days (rolling) — not strictly Monday to Sunday.",
                                        style = MaterialTheme.typography.bodySmall,
                                        color = TextPrimary
                                    )
                                }
                            }
                        }
                    }

                    if (frequency == "SPECIFIC") {
                        Spacer(modifier = Modifier.height(4.dp))
                        Row(
                            modifier = Modifier.fillMaxWidth().padding(horizontal = 4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            val weekdays = if (language == "de") {
                                listOf("Mo", "Di", "Mi", "Do", "Fr", "Sa", "So")
                            } else {
                                listOf("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
                            }
                            weekdays.forEachIndexed { index, dayName ->
                                val dayNum = index + 1
                                val isSelected = specificDaysSet.contains(dayNum)
                                Box(
                                    modifier = Modifier
                                        .size(42.dp)
                                        .background(
                                            color = if (isSelected) SuccessGreen else ProgressTrack,
                                            shape = CircleShape
                                        )
                                        .clickable {
                                            specificDaysSet = if (isSelected) {
                                                specificDaysSet - dayNum
                                            } else {
                                                specificDaysSet + dayNum
                                            }
                                        },
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = dayName.take(2),
                                        style = MaterialTheme.typography.bodyMedium,
                                        fontWeight = FontWeight.Bold,
                                        color = if (isSelected) AppBg else TextPrimary
                                    )
                                }
                            }
                        }
                    }
                }

                // Daily Reminder Section
                val reminderEnabled = remindersList.isNotEmpty()
                Card(
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant),
                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.5f)),
                    shape = RoundedCornerShape(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(modifier = Modifier.padding(14.dp)) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(
                                    imageVector = Icons.Default.Notifications,
                                    contentDescription = "Notification",
                                    tint = PrimaryViolet,
                                    modifier = Modifier.size(20.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = if (language == "de") "Erinnerung" else if (language == "ka") "შეხსენება" else "Reminder",
                                    style = MaterialTheme.typography.titleMedium,
                                    color = MaterialTheme.colorScheme.onSurface,
                                    fontWeight = FontWeight.Bold
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                InfoIconButton(
                                    title = if (language == "de") "Erinnerung" else if (language == "ka") "შეხსენება" else "Reminder",
                                    explanation = if (language == "de") {
                                        "Richte dir Benachrichtigungen ein, um zur gewünschten Uhrzeit an deine Gewohnheit erinnert zu werden."
                                    } else {
                                        "Set up notifications so you get reminded of your habit at your desired time."
                                    },
                                    onClick = { t, e -> activeExplanation = t to e },
                                    modifier = Modifier.size(32.dp)
                                )
                            }
                        }

                        Spacer(modifier = Modifier.height(10.dp))

                        Column(
                            modifier = Modifier.fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            if (remindersList.isNotEmpty()) {
                                remindersList.forEach { reminderTime ->
                                    Card(
                                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.3f)),
                                        shape = RoundedCornerShape(10.dp),
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clickable {
                                                reminderToEditTime = reminderTime
                                                showAddCustomDialog = true
                                            }
                                    ) {
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(horizontal = 16.dp, vertical = 12.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                Icon(
                                                    imageVector = Icons.Default.Notifications,
                                                    contentDescription = "Time Icon",
                                                    tint = PrimaryViolet,
                                                    modifier = Modifier.size(20.dp)
                                                )
                                                Spacer(modifier = Modifier.width(12.dp))
                                                Text(
                                                    text = reminderTime,
                                                    style = MaterialTheme.typography.titleMedium,
                                                    fontWeight = FontWeight.Bold,
                                                    color = MaterialTheme.colorScheme.onSurface
                                                )
                                            }
                                            
                                            IconButton(
                                                onClick = {
                                                    remindersList = remindersList.filter { it != reminderTime }
                                                },
                                                modifier = Modifier.size(36.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Delete,
                                                    contentDescription = "Delete Reminder",
                                                    tint = FailedRed,
                                                    modifier = Modifier.size(20.dp)
                                                )
                                            }
                                        }
                                    }
                                }
                            }

                            // Add Button
                            OutlinedButton(
                                onClick = {
                                    reminderToEditTime = null
                                    showAddCustomDialog = true
                                },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(44.dp),
                                shape = RoundedCornerShape(10.dp),
                                border = BorderStroke(1.dp, PrimaryViolet.copy(alpha = 0.5f)),
                                colors = ButtonDefaults.outlinedButtonColors(contentColor = PrimaryViolet)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Add,
                                    contentDescription = "Add Reminder Icon",
                                    modifier = Modifier.size(18.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = if (language == "de") "Erinnerung hinzufügen" else if (language == "ka") "დაამატეთ შეხსენება" else "Add Reminder",
                                    fontWeight = FontWeight.Bold,
                                    style = MaterialTheme.typography.titleSmall
                                )
                            }
                        }
                    }
                }

                // Milestone Rewards Section
                var showAddRewardDialog by remember { mutableStateOf(false) }

                Card(
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant),
                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.5f)),
                    shape = RoundedCornerShape(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(modifier = Modifier.padding(14.dp)) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(
                                    imageVector = Icons.Default.Star,
                                    contentDescription = "Milestone Rewards",
                                    tint = PrimaryViolet,
                                    modifier = Modifier.size(20.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = if (language == "de") "Meilenstein-Belohnungen" else if (language == "ka") "Milestone ჯილდოები" else "Milestone Rewards",
                                    style = MaterialTheme.typography.titleMedium,
                                    color = MaterialTheme.colorScheme.onSurface,
                                    fontWeight = FontWeight.Bold
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                InfoIconButton(
                                    title = if (language == "de") "Meilenstein-Belohnungen" else if (language == "ka") "Milestone ჯილდოები" else "Milestone Rewards",
                                    explanation = if (language == "de") {
                                        "Setze dir persönliche Belohnungen für das Erreichen von Meilensteinen (z. B. 30 Tage Serie oder eine bestimmte Trophäe). Sobald du das Ziel erreichst, wird die Belohnung freigeschaltet!"
                                    } else if (language == "ka") {
                        "დააწესეთ პირადი ჯილდოები ეტაპების მიღწევისთვის (მაგ. 30-დღიანი სერია ან კონკრეტული თასი). მას შემდეგ რაც მიაღწევთ მიზანს, ჯილდო იხსნება!"
                    } else {
                        "Set personal rewards for reaching milestones (e.g. 30-day streak or a specific trophy). Once you reach the target, the reward unlocks!"
                    },
                                    onClick = { t, e -> activeExplanation = t to e },
                                    modifier = Modifier.size(32.dp)
                                )
                            }
                        }

                        Spacer(modifier = Modifier.height(10.dp))

                        Column(
                            modifier = Modifier.fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            if (milestoneRewards.isNotEmpty()) {
                                milestoneRewards.forEachIndexed { index, reward ->
                                    Card(
                                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.3f)),
                                        shape = RoundedCornerShape(10.dp),
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(horizontal = 16.dp, vertical = 12.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Column(modifier = Modifier.weight(1f)) {
                                                Text(
                                                    text = reward.rewardText,
                                                    style = MaterialTheme.typography.titleMedium,
                                                    color = MaterialTheme.colorScheme.onSurface,
                                                    fontWeight = FontWeight.Bold
                                                )
                                                val condText = when (reward.conditionType) {
                                                    "STREAK" -> if (language == "de") "${reward.conditionValue} Tage Serie" else if (language == "ka") "${reward.conditionValue} დღის სტრიქონი" else "${reward.conditionValue} Day Streak"
                                                    "COMPLETIONS" -> if (language == "de") "${reward.conditionValue} Erledigungen" else if (language == "ka") "${reward.conditionValue} დასრულებები" else "${reward.conditionValue} Completions"
                                                    "TROPHY_COUPLED" -> {
                                                        val tr = STANDARD_TROPHIES.find { it.id == reward.trophyId }
                                                        if (tr != null) {
                                                            if (language == "de") "Trophäe: ${tr.titleDe}" else if (language == "ka") "ტროფი: ${tr.titleEn}" else "Trophy: ${tr.titleEn}"
                                                        } else {
                                                            reward.trophyId ?: ""
                                                        }
                                                    }
                                                    else -> ""
                                                }
                                                if (condText.isNotEmpty()) {
                                                    Text(
                                                        text = condText,
                                                        style = MaterialTheme.typography.bodySmall,
                                                        color = MaterialTheme.colorScheme.onSurfaceVariant
                                                    )
                                                }
                                            }
                                            IconButton(
                                                onClick = {
                                                    milestoneRewards = milestoneRewards.filterIndexed { i, _ -> i != index }
                                                },
                                                modifier = Modifier.size(36.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Delete,
                                                    contentDescription = "Delete Reward",
                                                    tint = FailedRed,
                                                    modifier = Modifier.size(20.dp)
                                                )
                                            }
                                        }
                                    }
                                }
                            }

                            OutlinedButton(
                                onClick = { showAddRewardDialog = true },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(44.dp),
                                shape = RoundedCornerShape(10.dp),
                                border = BorderStroke(1.dp, PrimaryViolet.copy(alpha = 0.5f)),
                                colors = ButtonDefaults.outlinedButtonColors(contentColor = PrimaryViolet)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Add,
                                    contentDescription = "Add Reward Icon",
                                    modifier = Modifier.size(18.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = if (language == "de") "Belohnung hinzufügen" else if (language == "ka") "დაამატე ჯილდო" else "Add Reward",
                                    fontWeight = FontWeight.Bold,
                                    style = MaterialTheme.typography.titleSmall
                                )
                            }
                        }
                    }
                }
                
                if (showAddRewardDialog) {
                    AddMilestoneRewardDialog(
                        language = language,
                        onDismiss = {
                            showAddRewardDialog = false
                        },
                        onAdd = { reward ->
                            milestoneRewards = milestoneRewards + reward
                            showAddRewardDialog = false
                        }
                    )
                }

                // Start Date Trigger Card
                Card(
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant),
                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.5f)),
                    shape = RoundedCornerShape(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(modifier = Modifier.padding(14.dp)) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(
                                    imageVector = Icons.Default.DateRange,
                                    contentDescription = "Start Date Icon",
                                    tint = PrimaryViolet,
                                    modifier = Modifier.size(20.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = if (language == "de") "Startdatum" else if (language == "ka") "დაწყების თარიღი" else "Start Date",
                                    style = MaterialTheme.typography.titleMedium,
                                    color = MaterialTheme.colorScheme.onSurface,
                                    fontWeight = FontWeight.Bold
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                InfoIconButton(
                                    title = if (language == "de") "Startdatum" else if (language == "ka") "დაწყების თარიღი" else "Start Date",
                                    explanation = if (language == "de") {
                                        "Legt fest, ab welchem Tag die Gewohnheit aktiv ist. Frühere Tage vor dem Startdatum werden in Serien und Statistiken nicht als unvollständig gewertet."
                                    } else if (language == "ka") {
                        "ადგენს დღეს, საიდანაც ჩვევა გააქტიურდება. დაწყების თარიღამდე დღეები არ ჩაითვლება გამოტოვებულად სტრიქონებში და სტატისტიკაში."
                    } else {
                        "Sets the day from which the habit becomes active. Days prior to the start date won't count as missed in streaks and stats."
                    },
                                    onClick = { t, e -> activeExplanation = t to e },
                                    modifier = Modifier.size(32.dp)
                                )
                            }
                        }

                        Spacer(modifier = Modifier.height(10.dp))

                        Card(
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.3f)),
                            shape = RoundedCornerShape(10.dp),
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    showDatePicker = !showDatePicker
                                    if (showDatePicker) {
                                        coroutineScope.launch {
                                            kotlinx.coroutines.delay(150)
                                            scrollState.animateScrollTo(scrollState.maxValue)
                                        }
                                    }
                                }
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 16.dp, vertical = 12.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = formattedStartDate,
                                    style = MaterialTheme.typography.titleMedium,
                                    color = MaterialTheme.colorScheme.onSurface,
                                    fontWeight = FontWeight.Bold
                                )
                                Icon(
                                    imageVector = Icons.Default.KeyboardArrowDown,
                                    contentDescription = "Open Date Picker",
                                    tint = MaterialTheme.colorScheme.onSurfaceVariant,
                                    modifier = Modifier.size(20.dp)
                                )
                            }
                        }
                    }
                }

                if (showDatePicker) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(MaterialTheme.colorScheme.surfaceVariant, RoundedCornerShape(12.dp))
                            .border(1.dp, MaterialTheme.colorScheme.outline, RoundedCornerShape(12.dp))
                            .padding(12.dp)
                    ) {
                        SimpleDatePickerView(
                            initialTimeMs = startDateMillis,
                            onDateSelected = {
                                startDateMillis = it
                                showDatePicker = false
                            }
                        )
                    }
                }

                // Action buttons (Erstellen/Speichern, Abbrechen)
                Row(
                    modifier = Modifier.fillMaxWidth().padding(top = 8.dp, bottom = 20.dp),
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Button(
                        onClick = onDismiss,
                        colors = ButtonDefaults.buttonColors(containerColor = ProgressTrack),
                        modifier = Modifier
                            .weight(1f)
                            .height(50.dp),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Text(
                            text = if (language == "de") "Abbrechen" else if (language == "ka") "გაუქმება" else "Cancel",
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.titleMedium,
                            color = TextSecondary
                        )
                    }

                    val buttonText = if (editingHabit != null) {
                        if (language == "de") "Speichern" else if (language == "ka") "შენახვა" else "Save"
                    } else {
                        if (language == "de") "Erstellen" else if (language == "ka") "შექმნა" else "Create"
                    }

                    Button(
                        onClick = {
                            if (name.isNotBlank()) {
                                val targetVal = targetValueStr.toFloatOrNull() ?: 1f
                                val clickIncrementVal = clickIncrementStr.toFloatOrNull() ?: 1f
                                val specDays = when (frequency) {
                                    "SPECIFIC" -> specificDaysSet.sorted().joinToString(",")
                                    "TIMES_WEEKLY" -> timesWeekly.toString()
                                    else -> ""
                                }
                                
                                // Map Unified remindersList back to database variables
                                val firstReminder = remindersList.firstOrNull() ?: "18:00"
                                val firstParts = firstReminder.split(":")
                                val firstHour = firstParts.getOrNull(0)?.toIntOrNull() ?: 18
                                val firstMin = firstParts.getOrNull(1)?.toIntOrNull() ?: 0
                                
                                val restReminders = if (remindersList.size > 1) remindersList.drop(1) else emptyList()
                                val customRemindersStr = restReminders.joinToString(",")
                                
                                onSave(
                                    name, isNegative, category, selectedIcon, selectedColor, type, unit, targetVal, clickIncrementVal, 
                                    frequency, startDateMillis, specDays, reminderEnabled, firstHour, firstMin, customRemindersStr, description, milestoneRewards
                                )
                            } else {
                                nameError = true
                                coroutineScope.launch {
                                    scrollState.animateScrollTo(0)
                                }
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = PrimaryViolet),
                        modifier = Modifier
                            .weight(1.2f)
                            .height(50.dp)
                            .testTag("save_habit_button"),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Text(
                            text = buttonText,
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.titleMedium,
                            color = TextPrimary
                        )
                    }
                }
            }

        if (activeExplanation != null) {
            ExplanationDialog(
                title = activeExplanation!!.first,
                explanation = activeExplanation!!.second,
                onDismiss = { activeExplanation = null }
            )
        }

        if (showAddCustomDialog) {
            AddCustomReminderDialog(
                language = language,
                initialTime = reminderToEditTime,
                onDismiss = {
                    showAddCustomDialog = false
                    reminderToEditTime = null
                    if (remindersList.isEmpty()) {
                        reminderEnabled = false
                    }
                },
                onConfirm = { hour, min ->
                    val formatted = String.format(java.util.Locale.US, "%02d:%02d", hour, min)
                    if (reminderToEditTime != null) {
                        remindersList = (remindersList.filter { it != reminderToEditTime } + formatted).distinct().sorted()
                    } else {
                        if (formatted !in remindersList) {
                            remindersList = (remindersList + formatted).sorted()
                        }
                    }
                    reminderToEditTime = null
                    showAddCustomDialog = false
                    reminderEnabled = true
                }
            )
        }

        // Floating Header Overlay with vertical gradient fade-out
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(84.dp)
                .background(
                    Brush.verticalGradient(
                        colors = listOf(
                            AppBg,
                            AppBg,
                            AppBg.copy(alpha = 0.9f),
                            AppBg.copy(alpha = 0.5f),
                            Color.Transparent
                        )
                    )
                )
                .align(Alignment.TopCenter)
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(start = 20.dp, top = 16.dp, end = 24.dp, bottom = 12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                ModernBackButton(
                    onClick = onDismiss,
                    testTag = "create_back_button"
                )
                Spacer(modifier = Modifier.width(16.dp))
                Text(
                    text = if (editingHabit != null) {
                        if (language == "de") "Gewohnheit bearbeiten" else if (language == "ka") "ჩვევის რედაქტირება" else "Edit Habit"
                    } else {
                        if (language == "de") "Neue Gewohnheit" else if (language == "ka") "ახალი ჩვევა" else "New Habit"
                    },
                    style = MaterialTheme.typography.displayMedium,
                    color = TextPrimary,
                    fontWeight = FontWeight.Bold,
                    textAlign = TextAlign.Start,
                    modifier = Modifier.padding(bottom = 4.dp)
                )
            }
        }
    }
}

data class StandardTrophyOption(
    val id: String,
    val type: String,
    val tier: String,
    val titleDe: String,
    val titleEn: String,
    val descDe: String,
    val descEn: String
)

val STANDARD_TROPHIES = listOf(
    StandardTrophyOption("COMP_10", "COMPLETIONS", "COMP_10", "10 Abschlüsse", "10 Completions", "Insgesamt 10 Gewohnheits-Abschlüsse erreichen", "Achieve 10 total completions"),
    StandardTrophyOption("COMP_50", "COMPLETIONS", "COMP_50", "50 Abschlüsse", "50 Completions", "Insgesamt 50 Gewohnheits-Abschlüsse erreichen", "Achieve 50 total completions"),
    StandardTrophyOption("COMP_200", "COMPLETIONS", "COMP_200", "200 Abschlüsse", "200 Completions", "Insgesamt 200 Gewohnheits-Abschlüsse erreichen", "Achieve 200 total completions"),
    StandardTrophyOption("COMP_500", "COMPLETIONS", "COMP_500", "500 Abschlüsse", "500 Completions", "Insgesamt 500 Gewohnheits-Abschlüsse erreichen", "Achieve 500 total completions"),
    StandardTrophyOption("WOOD", "STREAK", "WOOD", "7 Tage Serie (Holz)", "7-Day Streak (Wood)", "Eine 7-Tage-Serie erreichen", "Achieve a 7-day streak"),
    StandardTrophyOption("BRONZE", "STREAK", "BRONZE", "14 Tage Serie (Bronze)", "14-Day Streak (Bronze)", "Eine 14-Tage-Serie erreichen", "Achieve a 14-day streak"),
    StandardTrophyOption("SILVER", "STREAK", "SILVER", "30 Tage Serie (Silber)", "30-Day Streak (Silver)", "Eine 30-Tage-Serie erreichen", "Achieve a 30-day streak"),
    StandardTrophyOption("GOLD", "STREAK", "GOLD", "100 Tage Serie (Gold)", "100-Day Streak (Gold)", "Eine 100-Tage-Serie erreichen", "Achieve a 100-day streak"),
    StandardTrophyOption("PERF_7", "PERFECT_DAYS", "PERF_7", "7 perfekte Tage", "7 Perfect Days", "7 perfekte Tage am Stück", "7 consecutive perfect days"),
    StandardTrophyOption("PERF_30", "PERFECT_DAYS", "PERF_30", "30 perfekte Tage", "30 Perfect Days", "30 perfekte Tage am Stück", "30 consecutive perfect days"),
    StandardTrophyOption("PERF_100", "PERFECT_DAYS", "PERF_100", "100 perfekte Tage", "100 Perfect Days", "100 perfekte Tage am Stück", "100 consecutive perfect days")
)

@Composable
fun AddMilestoneRewardDialog(
    language: String,
    onDismiss: () -> Unit,
    onAdd: (com.example.data.MilestoneReward) -> Unit
) {
    var rewardText by remember { mutableStateOf("") }
    var conditionType by remember { mutableStateOf("STREAK") }
    var conditionValueStr by remember { mutableStateOf("") }
    
    var mode by remember { mutableStateOf("TROPHY") } // "TROPHY" or "CUSTOM"
    var selectedTrophyId by remember { mutableStateOf("WOOD") }
    
    val scrollState = rememberScrollState()

    AlertDialog(
        onDismissRequest = onDismiss,
        containerColor = AppCard,
        title = {
            Text(
                text = tr(language, "Belohnung definieren", "Define Reward"),
                style = MaterialTheme.typography.titleLarge,
                fontWeight = FontWeight.Bold,
                color = TextPrimary
            )
        },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(16.dp), modifier = Modifier.verticalScroll(scrollState)) {
                
                OutlinedTextField(
                    value = rewardText,
                    onValueChange = { rewardText = it },
                    label = { Text(tr(language, "Belohnung (z.B. Neues Buch)", "Reward (e.g., New Book)"), color = TextSecondary) },
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = PrimaryViolet,
                        unfocusedBorderColor = AppBorder,
                        focusedContainerColor = Color(0xFF3A3A44),
                        unfocusedContainerColor = Color(0xFF3A3A44),
                        focusedTextColor = TextPrimary,
                        unfocusedTextColor = TextPrimary
                    ),
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                )

                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    FilterChip(
                        selected = mode == "TROPHY",
                        onClick = { mode = "TROPHY" },
                        label = { Text(tr(language, "Trophäe", "Trophy")) },
                        colors = FilterChipDefaults.filterChipColors(
                            selectedContainerColor = PrimaryViolet,
                            selectedLabelColor = Color.White
                        )
                    )
                    FilterChip(
                        selected = mode == "CUSTOM",
                        onClick = { mode = "CUSTOM" },
                        label = { Text(tr(language, "Manuell", "Manual")) },
                        colors = FilterChipDefaults.filterChipColors(
                            selectedContainerColor = PrimaryViolet,
                            selectedLabelColor = Color.White
                        )
                    )
                }
                
                if (mode == "CUSTOM") {
                    Text(
                        text = tr(language, "Bedingung:", "Condition:"),
                        color = TextPrimary,
                        fontWeight = FontWeight.Bold
                    )
                    
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        FilterChip(
                            selected = conditionType == "STREAK",
                            onClick = { conditionType = "STREAK" },
                            label = { Text(tr(language, "Streak (Tage)", "Streak (Days)")) },
                            colors = FilterChipDefaults.filterChipColors(
                                selectedContainerColor = PrimaryViolet,
                                selectedLabelColor = Color.White
                            )
                        )
                        FilterChip(
                            selected = conditionType == "COMPLETIONS",
                            onClick = { conditionType = "COMPLETIONS" },
                            label = { Text(tr(language, "Gesamt (Mal)", "Total (Times)")) },
                            colors = FilterChipDefaults.filterChipColors(
                                selectedContainerColor = PrimaryViolet,
                                selectedLabelColor = Color.White
                            )
                        )
                    }
                    
                    OutlinedTextField(
                        value = conditionValueStr,
                        onValueChange = { conditionValueStr = it.filter { ch -> ch.isDigit() } },
                        label = { Text(tr(language, "Ziel-Wert", "Target Value"), color = TextSecondary) },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = PrimaryViolet,
                            unfocusedBorderColor = AppBorder,
                            focusedContainerColor = Color(0xFF3A3A44),
                            unfocusedContainerColor = Color(0xFF3A3A44),
                            focusedTextColor = TextPrimary,
                            unfocusedTextColor = TextPrimary
                        ),
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp)
                    )
                } else {
                    Text(
                        text = tr(language, "Gewohnheitsspezifische Trophäe:", "Habit Trophy:"),
                        color = TextPrimary,
                        fontWeight = FontWeight.Bold
                    )
                    
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(max = 260.dp)
                            .verticalScroll(rememberScrollState()),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        STANDARD_TROPHIES.filter { it.type == "STREAK" }.forEach { trophy ->
                            val isSelected = selectedTrophyId == trophy.id
                            Card(
                                colors = CardDefaults.cardColors(
                                    containerColor = if (isSelected) PrimaryViolet.copy(alpha = 0.2f) else AppBg
                                ),
                                border = BorderStroke(
                                    1.dp,
                                    if (isSelected) PrimaryViolet else AppBorder
                                ),
                                shape = RoundedCornerShape(12.dp),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { selectedTrophyId = trophy.id }
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(10.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    AchievementBadge(
                                        type = trophy.type,
                                        tier = trophy.tier,
                                        isUnlocked = true,
                                        modifier = Modifier.size(36.dp)
                                    )
                                    Spacer(modifier = Modifier.width(12.dp))
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(
                                            text = if (language == "de") trophy.titleDe else trophy.titleEn,
                                            style = MaterialTheme.typography.titleSmall,
                                            fontWeight = FontWeight.Bold,
                                            color = TextPrimary
                                        )
                                        Text(
                                            text = if (language == "de") trophy.descDe else trophy.descEn,
                                            style = MaterialTheme.typography.bodySmall,
                                            color = TextSecondary
                                        )
                                    }
                                    if (isSelected) {
                                        Icon(
                                            imageVector = Icons.Default.CheckCircle,
                                            contentDescription = "Selected",
                                            tint = PrimaryViolet,
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    if (rewardText.isNotBlank()) {
                        if (mode == "CUSTOM" && conditionValueStr.isNotBlank()) {
                            val condVal = conditionValueStr.toIntOrNull() ?: 1
                            onAdd(com.example.data.MilestoneReward(
                                habitId = 0,
                                rewardText = rewardText.trim(),
                                conditionType = conditionType,
                                conditionValue = condVal
                            ))
                        } else if (mode == "TROPHY") {
                            onAdd(com.example.data.MilestoneReward(
                                habitId = 0,
                                rewardText = rewardText.trim(),
                                conditionType = "TROPHY_COUPLED",
                                conditionValue = 0,
                                trophyId = selectedTrophyId
                            ))
                        }
                    }
                },
                colors = ButtonDefaults.buttonColors(containerColor = PrimaryViolet),
                enabled = rewardText.isNotBlank() && (mode == "TROPHY" || conditionValueStr.isNotBlank())
            ) {
                Text(if (language == "de") "Hinzufügen" else if (language == "ka") "დამატება" else "Add", fontWeight = FontWeight.Bold)
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text(if (language == "de") "Abbrechen" else if (language == "ka") "გაუქმება" else "Cancel", color = TextSecondary)
            }
        }
    )
}

@Composable
fun AddCustomReminderDialog(
    language: String,
    initialTime: String? = null,
    onDismiss: () -> Unit,
    onConfirm: (hour: Int, minute: Int) -> Unit
) {
    var hour by remember {
        val parsedHour = initialTime?.split(":")?.getOrNull(0)?.toIntOrNull()
        mutableStateOf(parsedHour ?: 12)
    }
    var minute by remember {
        val parsedMin = initialTime?.split(":")?.getOrNull(1)?.toIntOrNull()
        mutableStateOf(parsedMin ?: 0)
    }
    
    var hourStr by remember(hour) { mutableStateOf(hour.toString()) }
    var minuteStr by remember(minute) { mutableStateOf(minute.toString().padStart(2, '0')) }

    AlertDialog(
        onDismissRequest = onDismiss,
        containerColor = AppCard,
        title = {
            Text(
                text = if (language == "de") "Erinnerung hinzufügen" else if (language == "ka") "დაამატეთ შეხსენება" else "Add Reminder",
                color = TextPrimary,
                style = MaterialTheme.typography.titleMedium
            )
        },
        text = {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 12.dp),
                horizontalArrangement = Arrangement.spacedBy(16.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Hour TextField
                Column(
                    modifier = Modifier.weight(1f)
                ) {
                    Text(
                        text = if (language == "de") "Stunde (0-23)" else if (language == "ka") "საათი (0-23)" else "Hour (0-23)",
                        style = MaterialTheme.typography.labelSmall,
                        color = TextSecondary,
                        modifier = Modifier.padding(bottom = 4.dp)
                    )
                    OutlinedTextField(
                        value = hourStr,
                        onValueChange = { input ->
                            val filtered = input.filter { it.isDigit() }
                            if (filtered.isEmpty()) {
                                hourStr = ""
                                hour = 0
                            } else {
                                val parsed = filtered.toIntOrNull()
                                if (parsed != null && parsed in 0..23) {
                                    hourStr = filtered
                                    hour = parsed
                                }
                            }
                        },
                        placeholder = { Text("12", color = TextSecondary.copy(alpha = 0.5f)) },
                        keyboardOptions = KeyboardOptions(
                            keyboardType = KeyboardType.Number,
                            imeAction = ImeAction.Next
                        ),
                        textStyle = MaterialTheme.typography.bodyLarge.copy(color = TextPrimary),
                        singleLine = true,
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = PrimaryViolet,
                            unfocusedBorderColor = AppBorder,
                            focusedContainerColor = Color(0xFF3A3A44),
                            unfocusedContainerColor = Color(0xFF3A3A44)
                        ),
                        shape = RoundedCornerShape(8.dp),
                        modifier = Modifier.fillMaxWidth()
                    )
                }

                Text(
                    text = ":",
                    color = TextPrimary,
                    fontWeight = FontWeight.Bold,
                    style = MaterialTheme.typography.titleLarge,
                    modifier = Modifier.padding(top = 20.dp)
                )

                // Minute TextField
                Column(
                    modifier = Modifier.weight(1f)
                ) {
                    Text(
                        text = if (language == "de") "Minute (0-59)" else if (language == "ka") "წუთი (0-59)" else "Minute (0-59)",
                        style = MaterialTheme.typography.labelSmall,
                        color = TextSecondary,
                        modifier = Modifier.padding(bottom = 4.dp)
                    )
                    OutlinedTextField(
                        value = minuteStr,
                        onValueChange = { input ->
                            val filtered = input.filter { it.isDigit() }
                            if (filtered.isEmpty()) {
                                minuteStr = ""
                                minute = 0
                            } else {
                                val parsed = filtered.toIntOrNull()
                                if (parsed != null && parsed in 0..59) {
                                    minuteStr = filtered
                                    minute = parsed
                                }
                            }
                        },
                        placeholder = { Text("00", color = TextSecondary.copy(alpha = 0.5f)) },
                        keyboardOptions = KeyboardOptions(
                            keyboardType = KeyboardType.Number,
                            imeAction = ImeAction.Done
                        ),
                        textStyle = MaterialTheme.typography.bodyLarge.copy(color = TextPrimary),
                        singleLine = true,
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = PrimaryViolet,
                            unfocusedBorderColor = AppBorder,
                            focusedContainerColor = Color(0xFF3A3A44),
                            unfocusedContainerColor = Color(0xFF3A3A44)
                        ),
                        shape = RoundedCornerShape(8.dp),
                        modifier = Modifier.fillMaxWidth()
                    )
                }
            }
        },
        confirmButton = {
            Button(
                colors = ButtonDefaults.buttonColors(containerColor = PrimaryViolet),
                onClick = { onConfirm(hour, minute) }
            ) {
                Text(if (language == "de") "Hinzufügen" else if (language == "ka") "დამატება" else "Add", color = TextPrimary)
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text(if (language == "de") "Abbrechen" else if (language == "ka") "გაუქმება" else "Cancel", color = TextSecondary)
            }
        }
    )
}

// COMPACT CUSTOM DATE PICKER
@Composable
fun SimpleDatePickerView(initialTimeMs: Long, onDateSelected: (Long) -> Unit) {
    val initialDate = remember(initialTimeMs) {
        java.time.Instant.ofEpochMilli(initialTimeMs)
            .atZone(java.time.ZoneId.systemDefault())
            .toLocalDate()
    }
    var currentMonth by remember { mutableStateOf(initialDate.monthValue) } // 1..12
    var currentYear by remember { mutableStateOf(initialDate.year) }

    val monthNames = remember {
        listOf("", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
    }

    val yearMonth = remember(currentMonth, currentYear) {
        java.time.YearMonth.of(currentYear, currentMonth)
    }
    val firstDayOfMonth = remember(yearMonth) {
        yearMonth.atDay(1)
    }
    val offset = remember(firstDayOfMonth) {
        (firstDayOfMonth.dayOfWeek.value - 1) // 0 is Monday, ..., 6 is Sunday
    }
    val maxDays = remember(yearMonth) {
        yearMonth.lengthOfMonth()
    }

    val gridItems = remember(offset, maxDays) {
        val list = mutableListOf<Int?>()
        for (i in 0 until offset) {
            list.add(null)
        }
        for (i in 1..maxDays) {
            list.add(i)
        }
        list
    }

    Column {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(
                onClick = {
                    if (currentMonth == 1) {
                        currentMonth = 12
                        currentYear--
                    } else {
                        currentMonth--
                    }
                }
            ) {
                Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Prev Month", tint = MaterialTheme.colorScheme.onSurface)
            }

            Text(
                text = "${monthNames[currentMonth]} $currentYear",
                style = MaterialTheme.typography.titleMedium,
                color = MaterialTheme.colorScheme.onSurface,
                fontWeight = FontWeight.Bold
            )

            IconButton(
                onClick = {
                    if (currentMonth == 12) {
                        currentMonth = 1
                        currentYear++
                    } else {
                        currentMonth++
                    }
                }
            ) {
                Icon(Icons.AutoMirrored.Filled.ArrowForward, contentDescription = "Next Month", tint = MaterialTheme.colorScheme.onSurface)
            }
        }

        Spacer(modifier = Modifier.height(10.dp))

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            listOf("M", "T", "W", "T", "F", "S", "S").forEach {
                Text(
                    text = it,
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.weight(1f),
                    textAlign = TextAlign.Center,
                    fontWeight = FontWeight.Bold
                )
            }
        }

        Spacer(modifier = Modifier.height(6.dp))

        val rowItems = remember(gridItems) { gridItems.chunked(7) }
        rowItems.forEach { week ->
            Row(modifier = Modifier.fillMaxWidth()) {
                for (c in 0 until 7) {
                    val day = if (c < week.size) week[c] else null
                    if (day != null) {
                        val isSelected = initialDate.dayOfMonth == day &&
                                initialDate.monthValue == currentMonth &&
                                initialDate.year == currentYear

                        Box(
                            modifier = Modifier
                                .weight(1f)
                                .aspectRatio(1f)
                                .padding(2.dp)
                                .clip(CircleShape)
                                .background(if (isSelected) PrimaryViolet else Color.Transparent)
                                .clickable {
                                    val localDate = java.time.LocalDate.of(currentYear, currentMonth, day)
                                    val epochMs = localDate.atStartOfDay(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli()
                                    onDateSelected(epochMs)
                                },
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = day.toString(),
                                style = MaterialTheme.typography.bodyMedium,
                                color = if (isSelected) Color.White else MaterialTheme.colorScheme.onSurface,
                                fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal
                            )
                        }
                    } else {
                        Spacer(modifier = Modifier.weight(1f))
                    }
                }
            }
        }
    }
}

