            InfoIconButton(
                title = explanationTitle,
                explanation = explanationText,
                onClick = onInfoClick
            )
        }
    }
}

@Composable
fun HabitStreakAchievementCard(
    habitName: String,
    habitColor: Color,
    habitIcon: String,
    longestStreak: Int,
    language: String
) {
    val context = LocalContext.current
    val targets = listOf(7, 14, 30, 100)
    val tiers = listOf("WOOD", "BRONZE", "SILVER", "GOLD")
    val tierNamesDe = listOf("Holz-Streak", "Bronze-Streak", "Silber-Streak", "Gold-Streak")
    val tierNamesEn = listOf("Wood Streak", "Bronze Streak", "Silver Streak", "Gold Streak")

    Card(
        colors = CardDefaults.cardColors(containerColor = AppCard),
        shape = RoundedCornerShape(16.dp),
        modifier = Modifier
            .fillMaxWidth()
            .border(1.dp, AppBorder, RoundedCornerShape(16.dp))
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            // Habit Name and Category Icon
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.fillMaxWidth()
            ) {
                Box(
                    modifier = Modifier
                        .size(36.dp)
                        .background(habitColor.copy(alpha = 0.15f), CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = HabitIconMapping.getIcon(habitIcon),
                        contentDescription = null,
                        tint = habitColor,
                        modifier = Modifier.size(18.dp)
                    )
                }
                Spacer(modifier = Modifier.width(12.dp))
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = habitName,
                        style = MaterialTheme.typography.titleMedium,
                        color = TextPrimary,
                        fontWeight = FontWeight.Bold
                    )
                    Text(
                        text = if (language == "de") "Beste Serie: $longestStreak Tage" else if (language == "ka") "ყველაზე გრძელი სერია: $longestStreak დღეები" else "Longest Streak: $longestStreak Days",
                        style = MaterialTheme.typography.bodySmall,
                        color = TextSecondary
                    )
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Progress bar to next streak milestone
            val nextTargetIndex = when {
                longestStreak < 7 -> 0
                longestStreak < 14 -> 1
                longestStreak < 30 -> 2
                longestStreak < 100 -> 3
                else -> -1
            }

            val (labelText, progressFraction, percent) = if (nextTargetIndex != -1) {
                val prevTarget = if (nextTargetIndex == 0) 0 else targets[nextTargetIndex - 1]
                val nextTarget = targets[nextTargetIndex]
                val targetName = if (language == "de") {
                    listOf("Holz-Serie", "Bronze-Serie", "Silber-Serie", "Gold-Serie")[nextTargetIndex]
                } else {
                    listOf("Wood Streak", "Bronze Streak", "Silver Streak", "Gold Streak")[nextTargetIndex]
                }
                
                val range = nextTarget - prevTarget
                val earned = longestStreak - prevTarget
                val fraction = (earned.toFloat() / range.toFloat()).coerceIn(0f, 1f)
                val pct = (fraction * 100).toInt()
                
                val label = if (language == "de") {
                    "Weg zur $targetName (${longestStreak}/${nextTarget} Tage)"
                } else if (language == "ka") {
                        "გზა $targetName -მდე ( ${longestStreak} / ${nextTarget} დღეები)"
                    } else {
                        "Path to $targetName (${longestStreak}/${nextTarget} Days)"
                    }
                Triple(label, fraction, pct)
            } else {
                val label = if (language == "de") {
                    "Gold-Serie meisterhaft erreicht! 🎉"
                } else if (language == "ka") {
                        "ოქროს ზოლი დაეუფლა! 🎉"
                    } else {
                        "Gold Streak mastered! 🎉"
                    }
                Triple(label, 1f, 100)
            }

            var hasAnimatedStreakProgress by rememberSaveable(habitName) { mutableStateOf(false) }
            val animStreakFraction = remember { Animatable(if (hasAnimatedStreakProgress) progressFraction else 0f) }

            LaunchedEffect(progressFraction) {
                if (!hasAnimatedStreakProgress) {
                    animStreakFraction.snapTo(0f)
                    animStreakFraction.animateTo(
                        targetValue = progressFraction,
                        animationSpec = tween(durationMillis = 700, easing = FastOutSlowInEasing)
                    )
                    hasAnimatedStreakProgress = true
                } else {
                    animStreakFraction.animateTo(
                        targetValue = progressFraction,
                        animationSpec = tween(durationMillis = 300, easing = FastOutSlowInEasing)
                    )
                }
            }
            val animatedStreakFraction = animStreakFraction.value

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = labelText,
                    style = MaterialTheme.typography.bodySmall,
                    color = TextSecondary
                )
                Text(
                    text = "${(animatedStreakFraction * 100).toInt()}%",
                    style = MaterialTheme.typography.bodySmall,
                    color = TextSecondary,
                    fontWeight = FontWeight.Bold
                )
            }
            Spacer(modifier = Modifier.height(4.dp))
            LinearProgressIndicator(
                progress = { animatedStreakFraction },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(6.dp)
                    .clip(RoundedCornerShape(3.dp)),
                color = habitColor,
                trackColor = ProgressTrack.copy(alpha = 0.5f)
            )

            Spacer(modifier = Modifier.height(16.dp))

            // Row of Badges
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceEvenly
            ) {
                targets.forEachIndexed { idx, target ->
                    val isUnlocked = longestStreak >= target
                    val tierStr = tiers[idx]
                    val badgeTitle = if (language == "de") tierNamesDe[idx] else tierNamesEn[idx]

                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        modifier = Modifier
                            .weight(1f)
                            .clickable {
                                if (isUnlocked) {
                                    Toast.makeText(
                                        context,
                                        if (language == "de") "Freigeschaltet: $badgeTitle ($target Tage)!" else if (language == "ka") "განბლოკილია: $badgeTitle ( $target დღე)!" else "Unlocked: $badgeTitle ($target days)!",
                                        Toast.LENGTH_SHORT
                                    ).show()
                                } else {
                                    Toast.makeText(
                                        context,
                                        if (language == "de") "Noch gesperrt: $badgeTitle ($target Tage benötigt, aktuell: $longestStreak)" else if (language == "ka") "ჩაკეტილი: $badgeTitle (საჭიროა $target დღე, მიმდინარე: $longestStreak )" else "Locked: $badgeTitle ($target days required, current: $longestStreak)",
                                        Toast.LENGTH_SHORT
                                    ).show()
                                }
                            }
                    ) {
                        Box(
                            modifier = Modifier.size(44.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            AchievementBadge(
                                type = "STREAK",
                                tier = tierStr,
                                isUnlocked = isUnlocked,
                                modifier = Modifier.fillMaxSize()
                            )
                            if (!isUnlocked) {
                                Box(
                                    modifier = Modifier
                                        .size(16.dp)
                                        .background(AppCard, CircleShape)
                                        .border(1.dp, TextSecondary.copy(alpha = 0.4f), CircleShape)
                                        .align(Alignment.BottomEnd),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Lock,
                                        contentDescription = "Locked",
                                        tint = TextSecondary,
                                        modifier = Modifier.size(9.dp)
                                    )
                                }
                            }
                        }
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            text = if (language == "de") "${target} Tage" else if (language == "ka") "${target} დღეები" else "${target} Days",
                            style = MaterialTheme.typography.labelSmall,
                            color = if (isUnlocked) TextPrimary else TextSecondary.copy(alpha = 0.6f),
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            }
        }
    }
}

@Composable
fun GlobalAchievementCard(
    type: String, // "COMPLETIONS" or "PERFECT_DAYS"
    tier: String, // "COMP_10", etc.
    title: String,
    description: String,
    targetValue: Int,
    currentValue: Int,
    isUnlocked: Boolean,
    language: String
) {
    val borderTint = when (tier) {
        "COMP_10" -> Color(0xFF4CAF50)
        "COMP_50" -> Color(0xFF2196F3)
        "COMP_200" -> Color(0xFF9C27B0)
        "COMP_500" -> Color(0xFFFF5722)
        "PERF_7" -> Color(0xFF00BCD4)
        "PERF_30" -> Color(0xFFE91E63)
        "PERF_100" -> Color(0xFFFFD700)
        else -> Color(0xFFFFD700)
    }

    Card(
        colors = CardDefaults.cardColors(
            containerColor = if (isUnlocked) AppCard else AppCard.copy(alpha = 0.6f)
        ),
        shape = RoundedCornerShape(16.dp),
        modifier = Modifier
            .fillMaxWidth()
            .border(
                width = 1.dp,
                color = if (isUnlocked) borderTint.copy(alpha = 0.4f) else AppBorder.copy(alpha = 0.4f),
                shape = RoundedCornerShape(16.dp)
            )
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            AchievementBadge(
                type = type,
                tier = tier,
                isUnlocked = isUnlocked,
                modifier = Modifier.size(52.dp)
            )

            Spacer(modifier = Modifier.width(16.dp))

            Column(modifier = Modifier.weight(1f)) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = title,
                        style = MaterialTheme.typography.titleMedium,
                        color = if (isUnlocked) TextPrimary else TextPrimary.copy(alpha = 0.6f),
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier.weight(1f)
                    )
                    if (isUnlocked) {
                        Text(
                            text = if (language == "de") "Freigeschaltet" else if (language == "ka") "განბლოკილია" else "Unlocked",
                            style = MaterialTheme.typography.labelSmall,
                            color = SuccessGreen,
                            fontWeight = FontWeight.Bold,
                            modifier = Modifier.padding(start = 4.dp)
                        )
                    }
                }
                Spacer(modifier = Modifier.height(4.dp))
                Text(
                    text = description,
                    style = MaterialTheme.typography.bodyMedium,
                    color = if (isUnlocked) TextSecondary else TextSecondary.copy(alpha = 0.5f)
                )

                if (!isUnlocked) {
                    Spacer(modifier = Modifier.height(10.dp))
                    val progressFraction = if (targetValue > 0) {
                        (currentValue.toFloat() / targetValue).coerceIn(0f, 1f)
                    } else 0f

                    var hasAnimatedAchieveProgress by rememberSaveable(title) { mutableStateOf(false) }
                    val animAchieveFraction = remember { Animatable(if (hasAnimatedAchieveProgress) progressFraction else 0f) }

                    LaunchedEffect(progressFraction) {
                        if (!hasAnimatedAchieveProgress) {
                            animAchieveFraction.snapTo(0f)
                            animAchieveFraction.animateTo(
                                targetValue = progressFraction,
                                animationSpec = tween(durationMillis = 700, easing = FastOutSlowInEasing)
                            )
                            hasAnimatedAchieveProgress = true
                        } else {
                            animAchieveFraction.animateTo(
                                targetValue = progressFraction,
                                animationSpec = tween(durationMillis = 300, easing = FastOutSlowInEasing)
                            )
                        }
                    }
                    val animatedAchieveFraction = animAchieveFraction.value

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = if (language == "de") {
                                "Fortschritt: $currentValue / $targetValue"
                            } else if (language == "ka") {
                        "პროგრესი: $currentValue / $targetValue"
                    } else {
                        "Progress: $currentValue / $targetValue"
                    },
                            style = MaterialTheme.typography.bodySmall,
                            color = TextSecondary.copy(alpha = 0.7f)
                        )
                        Text(
                            text = "${(animatedAchieveFraction * 100).toInt()}%",
                            style = MaterialTheme.typography.bodySmall,
                            color = TextSecondary.copy(alpha = 0.7f),
                            fontWeight = FontWeight.Bold
                        )
                    }
                    Spacer(modifier = Modifier.height(6.dp))
                    LinearProgressIndicator(
                        progress = { animatedAchieveFraction },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(6.dp)
                            .clip(RoundedCornerShape(3.dp)),
                        color = borderTint.copy(alpha = 0.6f),
                        trackColor = ProgressTrack.copy(alpha = 0.5f)
                    )
                }
            }
        }
    }
}

@Composable
fun ProfileScreen(
    viewModel: HabitsViewModel,
    language: String,
    onSettingsClick: (String?) -> Unit,
    listState: LazyListState = rememberLazyListState()
) {
    val habits by viewModel.allHabits.collectAsStateWithLifecycle()
    val allLogs by viewModel.allLogs.collectAsStateWithLifecycle()
    val profileStats by viewModel.profileStats.collectAsStateWithLifecycle()
    val perfectDaysState by viewModel.perfectDaysStats.collectAsStateWithLifecycle()
    val perfectDaysStreak = perfectDaysState.perfectDaysStreak
    val currentPerfectStreak = perfectDaysState.currentStreak

    val userName by viewModel.userName.collectAsStateWithLifecycle()
    val profileImageUri by viewModel.profileImageUri.collectAsStateWithLifecycle()

    var showEditNameDialog by remember { mutableStateOf(false) }
    var tempUserName by remember(userName) { mutableStateOf(userName) }
    var showProfileShareDialog by remember { mutableStateOf(false) }

    val context = LocalContext.current
    val profileImagePickerLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.GetContent()
    ) { uri ->
        if (uri != null) {
            try {
                val file = java.io.File(context.filesDir, "profile_avatar.jpg")
                context.contentResolver.openInputStream(uri)?.use { input ->
                    file.outputStream().use { output ->
                        input.copyTo(output)
                    }
                }
                viewModel.updateProfileImageUri(android.net.Uri.fromFile(file).toString())
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
    }

    var activeExplanation by remember { mutableStateOf<Pair<String, String>?>(null) }
    var selectedTab by rememberSaveable { mutableIntStateOf(0) } // 0 = Freigeschaltet, 1 = Alle Erfolge

    val totalGlobalCompletions = profileStats.totalGlobalCompletions
    val unlockedCompletions = profileStats.unlockedCompletions
    val unlockedPerfectDays = profileStats.unlockedPerfectDays

    val habitStreaksList = remember(profileStats.habitStreaks) {
        profileStats.habitStreaks.map { streakInfo ->
            val habit = streakInfo.habit
            val longestStreak = streakInfo.longestStreak
            val hColor = HabitIconMapping.getColor(habit.color)
            val hIcon = habit.icon
            Triple(habit, longestStreak, Pair(hColor, hIcon))
        }
    }

    val totalUnlockedCount = profileStats.totalUnlockedCount
    val totalPossibleCount = profileStats.totalPossibleCount

    val globalCompletionsAchievements = remember(totalGlobalCompletions, language) {
        listOf(
            Achievement(
                type = "COMPLETIONS",
                tier = "COMP_10",
                title = if (language == "de") "Erster Schritt" else if (language == "ka") "პირველი ნაბიჯი" else "First Step",
                description = if (language == "de") "Trage insgesamt 10 Erledigungen ein." else if (language == "ka") "დაარეგისტრირეთ სულ 10 დასრულება ყველა ჩვევაში." else "Log a total of 10 completions across all habits.",
                targetValue = 10,
                currentValue = totalGlobalCompletions,
                isUnlocked = totalGlobalCompletions >= 10
            ),
            Achievement(
                type = "COMPLETIONS",
                tier = "COMP_50",
                title = if (language == "de") "Gewohnheits-Routine" else if (language == "ka") "ჩვევების რუტინა" else "Habit Routine",
                description = if (language == "de") "Trage insgesamt 50 Erledigungen ein." else if (language == "ka") "დაარეგისტრირეთ სულ 50 დასრულება ყველა ჩვევაში." else "Log a total of 50 completions across all habits.",
                targetValue = 50,
                currentValue = totalGlobalCompletions,
                isUnlocked = totalGlobalCompletions >= 50
            ),
            Achievement(
                type = "COMPLETIONS",
                tier = "COMP_200",
                title = if (language == "de") "Eiserner Wille" else if (language == "ka") "რკინის ნება" else "Iron Will",
                description = if (language == "de") "Trage insgesamt 200 Erledigungen ein." else if (language == "ka") "დაარეგისტრირეთ სულ 200 დასრულება ყველა ჩვევაში." else "Log a total of 200 completions across all habits.",
                targetValue = 200,
                currentValue = totalGlobalCompletions,
                isUnlocked = totalGlobalCompletions >= 200
            ),
            Achievement(
                type = "COMPLETIONS",
                tier = "COMP_500",
                title = if (language == "de") "Lebensstil-Transformation" else if (language == "ka") "ცხოვრების წესის ტრანსფორმაცია" else "Lifestyle Transformation",
                description = if (language == "de") "Trage insgesamt 500 Erledigungen ein." else if (language == "ka") "დაარეგისტრირეთ სულ 500 დასრულება ყველა ჩვევაში." else "Log a total of 500 completions across all habits.",
                targetValue = 500,
                currentValue = totalGlobalCompletions,
                isUnlocked = totalGlobalCompletions >= 500
            )
        )
    }

    val globalPerfectDaysAchievements = remember(perfectDaysStreak, currentPerfectStreak, language) {
        listOf(
            Achievement(
                type = "PERFECT_DAYS",
                tier = "PERF_7",
                title = if (language == "de") "Perfekte Woche" else if (language == "ka") "იდეალური კვირა" else "Perfect Week",
                description = if (language == "de") "Erreiche eine Serie von 7 perfekten Tagen am Stück." else if (language == "ka") "მიაღწიეთ ზედიზედ 7 სრულყოფილი დღის სერიას." else "Achieve a streak of 7 consecutive perfect days.",
                targetValue = 7,
                currentValue = if (perfectDaysStreak >= 7) 7 else currentPerfectStreak,
                isUnlocked = perfectDaysStreak >= 7
            ),
            Achievement(
                type = "PERFECT_DAYS",
                tier = "PERF_30",
                title = if (language == "de") "Perfekter Monat" else if (language == "ka") "იდეალური თვე" else "Perfect Month",
                description = if (language == "de") "Erreiche eine Serie von 30 perfekten Tagen am Stück." else if (language == "ka") "მიაღწიეთ ზედიზედ 30 სრულყოფილი დღის სერიას." else "Achieve a streak of 30 consecutive perfect days.",
                targetValue = 30,
                currentValue = if (perfectDaysStreak >= 30) 30 else currentPerfectStreak,
                isUnlocked = perfectDaysStreak >= 30
            ),
            Achievement(
                type = "PERFECT_DAYS",
                tier = "PERF_100",
                title = if (language == "de") "Perfektion" else if (language == "ka") "სრულყოფილება" else "Perfection",
                description = if (language == "de") "Erreiche eine Serie von 100 perfekten Tagen am Stück." else if (language == "ka") "მიაღწიეთ ზედიზედ 100 სრულყოფილი დღის სერიებს." else "Achieve a streak of 100 consecutive perfect days.",
                targetValue = 100,
                currentValue = if (perfectDaysStreak >= 100) 100 else currentPerfectStreak,
                isUnlocked = perfectDaysStreak >= 100
            )
        )
    }

    // Filtered lists for rendering
    val displayedHabitStreaks = remember(habitStreaksList, selectedTab) {
        if (selectedTab == 0) {
            habitStreaksList.filter { (_, longestStreak, _) -> longestStreak >= 7 }
        } else {
            habitStreaksList
        }
    }

    val displayedCompletions = remember(globalCompletionsAchievements, selectedTab) {
        if (selectedTab == 0) {
            globalCompletionsAchievements.filter { it.isUnlocked }
        } else {
            globalCompletionsAchievements
        }
    }

    val displayedPerfectDays = remember(globalPerfectDaysAchievements, selectedTab) {
        if (selectedTab == 0) {
            globalPerfectDaysAchievements.filter { it.isUnlocked }
        } else {
            globalPerfectDaysAchievements
        }
    }

    Column(modifier = Modifier.fillMaxSize()) {
        // Fixed Top Header Row with Share on Top Left and Settings on Top Right
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .padding(start = 16.dp, end = 16.dp, top = 28.dp, bottom = 12.dp)
        ) {
            // Top Left: Share Profile Button
            Box(
                modifier = Modifier
                    .size(44.dp)
                    .border(1.dp, AppBorder, RoundedCornerShape(12.dp))
                    .background(AppCard, RoundedCornerShape(12.dp))
                    .clickable { showProfileShareDialog = true }
                    .align(Alignment.CenterStart)
                    .testTag("profile_share_button"),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.Default.Share,
                    contentDescription = "Share Profile",
                    tint = TextPrimary,
                    modifier = Modifier.size(20.dp)
                )
            }

            // Center Title
            Text(
                text = if (language == "de") "Profil" else if (language == "ka") "პროფილი" else "Profile",
                style = MaterialTheme.typography.displayLarge,
                color = TextPrimary,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center,
                modifier = Modifier.align(Alignment.Center)
            )

            // Top Right: Settings Gear Button
            Box(
                modifier = Modifier
                    .size(44.dp)
                    .border(1.dp, AppBorder, RoundedCornerShape(12.dp))
                    .background(AppCard, RoundedCornerShape(12.dp))
                    .clickable { onSettingsClick(null) }
                    .align(Alignment.CenterEnd)
                    .testTag("profile_settings_button"),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.Default.Settings,
                    contentDescription = "Settings",
                    tint = TextPrimary,
                    modifier = Modifier.size(20.dp)
                )
            }
        }

        Box(modifier = Modifier.weight(1f)) {
            LazyColumn(
                state = listState,
                modifier = Modifier
                    .fillMaxSize()
                    .padding(horizontal = 16.dp),
                contentPadding = PaddingValues(top = 8.dp, bottom = 180.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                item {
                    // Profile Avatar & Username Header (Matching Screenshot 1)
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 12.dp),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Box(
                            modifier = Modifier
                                .size(104.dp)
                                .clickable { onSettingsClick("profile") },
                            contentAlignment = Alignment.Center
                        ) {
                            Surface(
                                modifier = Modifier.size(104.dp),
                                shape = CircleShape,
                                color = AppCard,
                                border = BorderStroke(2.dp, PrimaryViolet)
                            ) {
                                if (profileImageUri.isNotEmpty()) {
                                    AsyncImage(
                                        model = profileImageUri,
                                        contentDescription = "Profile Picture",
                                        modifier = Modifier
                                            .fillMaxSize()
                                            .clip(CircleShape),
                                        contentScale = ContentScale.Crop
                                    )
                                } else {
                                    Box(
                                        modifier = Modifier
                                            .fillMaxSize()
                                            .background(PrimaryViolet.copy(alpha = 0.2f)),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Person,
                                            contentDescription = "Avatar Placeholder",
                                            tint = PrimaryViolet,
                                            modifier = Modifier.size(54.dp)
                                        )
                                    }
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(12.dp))

                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(8.dp))
                                .clickable { onSettingsClick("profile") }
                                .padding(horizontal = 16.dp, vertical = 6.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            if (userName.isBlank()) {
                                Text(
                                    text = "______",
                                    style = MaterialTheme.typography.titleLarge,
                                    color = TextSecondary,
                                    fontWeight = FontWeight.Bold,
                                    textAlign = TextAlign.Center
                                )
                            } else {
                                Text(
                                    text = userName,
                                    style = MaterialTheme.typography.titleLarge,
                                    color = TextPrimary,
                                    fontWeight = FontWeight.Bold,
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                    }
                }

                item {
                    Card(
                        colors = CardDefaults.cardColors(containerColor = AppCard),
                        shape = RoundedCornerShape(16.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .border(1.dp, AppBorder, RoundedCornerShape(16.dp))
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 16.dp, vertical = 14.dp),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = if (language == "de") "Erfolge freigeschaltet" else if (language == "ka") "მიღწევები განბლოკილია" else "Achievements Unlocked",
                                    style = MaterialTheme.typography.bodyMedium,
                                    fontWeight = FontWeight.SemiBold,
                                    color = TextPrimary
                                )
                                Text(
                                    text = "$totalUnlockedCount / $totalPossibleCount",
                                    style = MaterialTheme.typography.bodyMedium,
                                    fontWeight = FontWeight.Bold,
                                    color = HabitYellow
                                )
                            }
                            val progressFraction = if (totalPossibleCount > 0) totalUnlockedCount.toFloat() / totalPossibleCount.toFloat() else 0f
                            LinearProgressIndicator(
                                progress = { progressFraction.coerceIn(0f, 1f) },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(6.dp)
                                    .clip(RoundedCornerShape(3.dp)),
                                color = HabitYellow,
                                trackColor = ProgressTrack
                            )
                        }
                    }
                }

            // Visual filter tabs to toggle: Freigeschaltet, Alle Erfolge
            item {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 4.dp),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    val tabs = if (language == "de") listOf("Freigeschaltet", "Alle Erfolge") else listOf("Unlocked", "All Achievements")
                    tabs.forEachIndexed { index, label ->
                        val isSelected = selectedTab == index
                        Surface(
                            onClick = { selectedTab = index },
                            shape = RoundedCornerShape(20.dp),
                            color = if (isSelected) PrimaryViolet else AppCard,
                            border = BorderStroke(1.dp, if (isSelected) PrimaryViolet else AppBorder),
                            modifier = Modifier
                                .weight(1f)
                                .height(42.dp)
                                .testTag(if (index == 0) "tab_unlocked" else "tab_all_achievements")
                        ) {
                            Box(
                                contentAlignment = Alignment.Center,
                                modifier = Modifier.fillMaxSize()
                            ) {
                                Text(
                                    text = label,
                                    style = MaterialTheme.typography.labelMedium,
                                    color = if (isSelected) Color.White else TextSecondary,
                                    fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium
                                )
                            }
                        }
                    }
                }
            }



            // Checks if everything is empty
            if (displayedHabitStreaks.isEmpty() && displayedCompletions.isEmpty() && displayedPerfectDays.isEmpty()) {
                item {
                    Card(
                        colors = CardDefaults.cardColors(containerColor = AppCard),
                        shape = RoundedCornerShape(16.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .border(1.dp, AppBorder, RoundedCornerShape(16.dp))
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(24.dp),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            Icon(
                                imageVector = Icons.Default.EmojiEvents,
                                contentDescription = null,
                                tint = TextSecondary.copy(alpha = 0.2f),
                                modifier = Modifier.size(64.dp)
                            )
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = if (language == "de") {
                                    "Noch keine Erfolge"
                                } else if (language == "ka") {
                        "მიღწევები ჯერ არ არის"
                    } else {
                        "No Achievements Yet"
                    },
                                style = MaterialTheme.typography.titleMedium,
                                color = TextPrimary,
                                fontWeight = FontWeight.Bold
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = if (language == "de") {
                                    "Arbeite an deinen Gewohnheiten, um deinen ersten Meilenstein freizuschalten!"
                                } else if (language == "ka") {
                        "იმუშავეთ თქვენს ჩვევებზე, რათა გახსნათ თქვენი პირველი ეტაპი!"
                    } else {
                        "Work on your habits to unlock your first milestone!"
                    },
                                style = MaterialTheme.typography.bodyMedium,
                                color = TextSecondary,
                                textAlign = TextAlign.Center
                            )
                        }
                    }
                }
            } else {
                // CATEGORY 1: HABIT STREAKS
                if (displayedHabitStreaks.isNotEmpty()) {
                    item {
                        val explanationTitle = if (language == "de") "Gewohnheiten-Serien" else if (language == "ka") "ჩვევების ზოლები" else "Habit Streaks"
                        val explanationText = if (language == "de") {
                            "Gewohnheiten-Serien belohnen deine Beständigkeit bei einzelnen Gewohnheiten!\n\n" +
                            "Jede Gewohnheit hat ihre eigene Erfolgssträhne. Du schaltest die Stufen frei, indem du die Gewohnheit an aufeinanderfolgenden Tagen erfüllst:\n\n" +
                            "• 🪵 Holz-Serie: 7 Tage am Stück\n" +
                            "• 🥉 Bronze-Serie: 14 Tage am Stück\n" +
                            "• 🥈 Silber-Serie: 30 Tage am Stück\n" +
                            "• 🥇 Gold-Serie: 100 Tage am Stück\n\n" +
                            "Tippe auf die Abzeichen der einzelnen Gewohnheits-Karten, um Details zu sehen!"
                        } else if (language == "ka") {
                        "ჩვევების სტრიქები აჯილდოვებს თქვენს თანმიმდევრულობას ინდივიდუალური ჩვევებისთვის!\n\n" +
                            "თითოეულ ჩვევას აქვს თავისი სტრიქის ბარათი. თქვენ განბლოკავთ იარუსებს ჩვევის შესრულებით ზედიზედ დღეებში:\n\n" +
                            "• 🪵 ხის ზოლი: 7 დღიანი ზოლი\n" +
