@Composable
fun HabitAnalyticsSection(
    habit: Habit,
    language: String,
    calendarRows: List<List<CalendarCellState?>>,
    viewModel: HabitsViewModel,
    onInfoClick: (String, String) -> Unit
) {
    val analyticsState by viewModel.habitAnalyticsState.collectAsStateWithLifecycle()
    val activeFilter by viewModel.analyticsFilter.collectAsStateWithLifecycle()

    val minVerlaufOffset = analyticsState?.minVerlaufOffset ?: 0
    val verlaufTitle = analyticsState?.verlaufTitle ?: ""
    val canPrevVerlauf = analyticsState?.canPrevVerlauf ?: false
    val canNextVerlauf = analyticsState?.canNextVerlauf ?: false
    val barData = analyticsState?.barData ?: emptyList()

    val totalDays = calendarRows.flatten().filterNotNull().filter { it.status != "INACTIVE" }
    val successCount = totalDays.count { it.status == "SUCCESS" }
    val failedCount = totalDays.count { it.status == "FAILED" }
    val pendingCount = totalDays.count { it.status == "PENDING" }
        Column(
        modifier = Modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        // --- Card 1: Verlauf (Balkendiagramm) ---
        if (habit.type == "NUMBER" || habit.type == "NUMERICAL") {
            Card(
                colors = CardDefaults.cardColors(containerColor = AppCard),
                shape = RoundedCornerShape(16.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .border(1.dp, AppBorder, RoundedCornerShape(16.dp))
            ) {
                Column(modifier = Modifier.padding(12.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                imageVector = Icons.Default.BarChart,
                                contentDescription = "Verlauf",
                                tint = PrimaryViolet,
                                modifier = Modifier.size(20.dp)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(
                                text = if (language == "de") "VERLAUF" else if (language == "ka") "ისტორია" else "HISTORY",
                                style = MaterialTheme.typography.labelSmall,
                                color = TextSecondary,
                                fontWeight = FontWeight.Bold
                            )
                            Spacer(modifier = Modifier.width(4.dp))
                            InfoIconButton(
                                title = if (language == "de") "Habit-Verlauf" else if (language == "ka") "ჩვევების ისტორია" else "Habit History",
                                explanation = if (language == "de") {
                                    "Zeigt an, wie viel du an jedem Tag eingetragen hast. Bei numerischen Gewohnheiten wird das Erfüllungsverhältnis (z.B. 50% deines Ziels) dargestellt. Wechsle zwischen Woche, Monat und Jahr, um langfristige Muster zu erkennen."
                                } else if (language == "ka") {
                        "აჩვენებს, თუ რამდენს შედიხართ ყოველ დღე. რიცხვითი ჩვევებისთვის, ის აჩვენებს დასრულების კოეფიციენტს (მაგ. თქვენი მიზნის 50%). გადართეთ კვირის, თვის და წლის ხედებს შორის გრძელვადიანი შაბლონების დასანახად."
                    } else {
                        "Shows how much you logged on each day. For numeric habits, it displays the completion ratio (e.g. 50% of your target). Switch between Week, Month, and Year views to spot long-term patterns."
                    },
                                onClick = onInfoClick
                            )
                        }

                        Text(
                            text = if (language == "de") "Mal pro Tag" else if (language == "ka") "ჯერ დღეში" else "Times per day",
                            style = MaterialTheme.typography.labelSmall,
                            color = TextSecondary
                        )
                    }

                    Spacer(modifier = Modifier.height(8.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        IconButton(
                            onClick = { if (canPrevVerlauf) viewModel.navigateAnalyticsVerlauf(-1) },
                            enabled = canPrevVerlauf
                        ) {
                            Icon(
                                Icons.Default.ChevronLeft,
                                contentDescription = "Prev",
                                tint = if (canPrevVerlauf) TextSecondary else TextSecondary.copy(alpha = 0.3f)
                            )
                        }

                        Text(
                            text = verlaufTitle,
                            style = MaterialTheme.typography.bodyMedium,
                            color = TextPrimary,
                            fontWeight = FontWeight.Bold
                        )

                        IconButton(
                            onClick = { if (canNextVerlauf) viewModel.navigateAnalyticsVerlauf(1) },
                            enabled = canNextVerlauf
                        ) {
                            Icon(
                                Icons.Default.ChevronRight,
                                contentDescription = "Next",
                                tint = if (canNextVerlauf) TextSecondary else TextSecondary.copy(alpha = 0.3f)
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(130.dp)
                            .padding(horizontal = 4.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.Bottom
                    ) {
                        barData.forEach { (label, ratio) ->
                            val barWidth = when (activeFilter) {
                                "WEEK" -> 16.dp
                                "MONTH" -> 4.dp
                                else -> 16.dp
                            }
                            Column(
                                modifier = Modifier.weight(1f),
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.Bottom
                            ) {
                                Box(
                                    modifier = Modifier
                                        .height(100.dp)
                                        .width(barWidth)
                                        .clip(RoundedCornerShape(topStart = 4.dp, topEnd = 4.dp))
                                        .background(ProgressTrack),
                                    contentAlignment = Alignment.BottomCenter
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .fillMaxHeight(ratio.coerceIn(0f, 1f))
                                            .fillMaxWidth()
                                            .background(SuccessGreen)
                                    )
                                }

                                Spacer(modifier = Modifier.height(4.dp))

                                Text(
                                    text = label,
                                    style = MaterialTheme.typography.labelSmall,
                                    color = TextSecondary,
                                    fontSize = 7.sp,
                                    maxLines = 1,
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceEvenly
                    ) {
                        listOf(
                            "WEEK" to (if (language == "de") "Woche" else if (language == "ka") "კვირა" else "Week"),
                            "MONTH" to (if (language == "de") "Monat" else if (language == "ka") "თვე" else "Month"),
                            "YEAR" to (if (language == "de") "Jahr" else if (language == "ka") "წელიწადი" else "Year")
                        ).forEach { (key, display) ->
                            val isSelected = activeFilter == key
                            Button(
                                onClick = {
                                    viewModel.setAnalyticsFilter(key)
                                },
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = if (isSelected) PrimaryViolet else ProgressTrack,
                                    contentColor = if (isSelected) TextPrimary else TextSecondary
                                ),
                                contentPadding = PaddingValues(horizontal = 16.dp, vertical = 2.dp),
                                modifier = Modifier.height(32.dp),
                                shape = RoundedCornerShape(16.dp)
                            ) {
                                Text(text = display, style = MaterialTheme.typography.labelMedium)
                            }
                        }
                    }
                }
            }
        }
    }
}

private data class ConfettiParticle(
    val cosVal: Float,
    val sinVal: Float,
    val speed: Float,
    val color: Color
)

@Composable
fun ConfettiAnimation(onFinished: () -> Unit) {
    val particles = remember {
        List(24) {
            val angle = (0..360).random().toFloat()
            val radian = Math.toRadians(angle.toDouble())
            ConfettiParticle(
                cosVal = Math.cos(radian).toFloat(),
                sinVal = Math.sin(radian).toFloat(),
                speed = (15..45).random().toFloat(),
                color = listOf(SuccessGreen, HabitYellow, HabitRed, PrimaryViolet).random()
            )
        }
    }
    var progress by remember { mutableStateOf(0f) }

    LaunchedEffect(Unit) {
        animate(
            initialValue = 0f,
            targetValue = 1f,
            animationSpec = tween(durationMillis = 1500, easing = LinearOutSlowInEasing)
        ) { value, _ ->
            progress = value
        }
        onFinished()
    }

    Canvas(modifier = Modifier.size(80.dp)) {
        val radiusMultiplier = 6f * (1f - progress)
        val alphaVal = (1f - progress).coerceIn(0f, 1f)
        val progressFactor = progress * 1.5f

        particles.forEach { particle ->
            val distance = particle.speed * progressFactor
            val x = center.x + particle.cosVal * distance
            val y = center.y + particle.sinVal * distance
            
            drawCircle(
                color = particle.color,
                radius = radiusMultiplier,
                center = androidx.compose.ui.geometry.Offset(x, y),
                alpha = alphaVal
            )
        }
    }
}

@Composable
fun InfoIconButton(
    title: String,
    explanation: String,
    onClick: (String, String) -> Unit,
    modifier: Modifier = Modifier
) {
    if (!LocalInfoCardsEnabled.current) return
    IconButton(
        onClick = { onClick(title, explanation) },
        modifier = if (modifier == Modifier) Modifier.size(44.dp) else modifier
    ) {
        Icon(
            imageVector = Icons.Default.Info,
            contentDescription = "Help Info",
            tint = PrimaryViolet,
            modifier = Modifier.size(18.dp)
        )
    }
}

@Composable
fun ExplanationDialog(
    title: String,
    explanation: String,
    onDismiss: () -> Unit
) {
    AlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Text(
                text = title,
                style = MaterialTheme.typography.titleMedium,
                color = TextPrimary,
                fontWeight = FontWeight.Bold
            )
        },
        text = {
            Text(
                text = explanation,
                style = MaterialTheme.typography.bodyMedium,
                color = TextSecondary
            )
        },
        confirmButton = {
            TextButton(onClick = onDismiss) {
                Text(
                    text = "OK",
                    style = MaterialTheme.typography.labelLarge,
                    color = PrimaryViolet
                )
            }
        },
        containerColor = AppCard,
        shape = RoundedCornerShape(16.dp)
    )
}

@Composable
fun DailyNoteDialog(
    currentNote: String,
    language: String,
    onDismiss: () -> Unit,
    onSave: (String) -> Unit
) {
    var noteText by remember(currentNote) { mutableStateOf(currentNote) }
    val focusRequester = remember { FocusRequester() }
    val keyboardController = androidx.compose.ui.platform.LocalSoftwareKeyboardController.current

    LaunchedEffect(Unit) {
        kotlinx.coroutines.delay(250)
        focusRequester.requestFocus()
        keyboardController?.show()
    }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Text(
                    text = if (language == "de") "Tägliche Notiz" else if (language == "ka") "ყოველდღიური შენიშვნა" else "Daily Note",
                    style = MaterialTheme.typography.titleLarge,
                    color = TextPrimary,
                    fontWeight = FontWeight.Bold
                )
                IconButton(onClick = onDismiss) {
                    Icon(
                        imageVector = Icons.Default.Close,
                        contentDescription = "Close",
                        tint = TextSecondary
                    )
                }
            }
        },
        text = {
            Column {
                ClearFocusOnKeyboardDismiss()
                OutlinedTextField(
                value = noteText,
                onValueChange = { noteText = it },
                placeholder = {
                    Text(
                        text = if (language == "de") "Gedanken, Erfolge oder Notizen für diesen Tag..." else if (language == "ka") "აზრები, მიღწევები თუ ნოტები ამ დღისთვის..." else "Thoughts, achievements, or notes for this day...",
                        color = TextSecondary.copy(alpha = 0.6f)
                    )
                },
                textStyle = MaterialTheme.typography.bodyMedium.copy(color = TextPrimary),
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(min = 120.dp, max = 240.dp)
                    .focusRequester(focusRequester),
                shape = RoundedCornerShape(12.dp),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedTextColor = TextPrimary,
                    unfocusedTextColor = TextPrimary,
                    focusedBorderColor = PrimaryViolet,
                    unfocusedBorderColor = AppBorder,
                    focusedContainerColor = AppBg,
                    unfocusedContainerColor = AppBg,
                    cursorColor = PrimaryViolet
                )
            )
        }
    },
        confirmButton = {
            Button(
                onClick = { onSave(noteText) },
                colors = ButtonDefaults.buttonColors(containerColor = PrimaryViolet),
                shape = RoundedCornerShape(8.dp)
            ) {
                Text(
                    text = if (language == "de") "Speichern" else if (language == "ka") "შენახვა" else "Save",
                    color = TextPrimary,
                    fontWeight = FontWeight.Bold
                )
            }
        },
        containerColor = AppCard,
        shape = RoundedCornerShape(20.dp),
        modifier = Modifier.border(1.dp, AppBorder, RoundedCornerShape(20.dp))
    )
}

fun Modifier.saturationFilter(saturation: Float): Modifier = this.drawWithContent {
    if (saturation >= 0.99f) {
        drawContent()
    } else {
        val matrix = ColorMatrix().apply {
            setToSaturation(saturation)
        }
        val filter = ColorFilter.colorMatrix(matrix)
        val paint = androidx.compose.ui.graphics.Paint().apply {
            colorFilter = filter
        }
        drawIntoCanvas { canvas ->
            canvas.saveLayer(androidx.compose.ui.geometry.Rect(0f, 0f, size.width, size.height), paint)
            drawContent()
            canvas.restore()
        }
    }
}

private data class ScreenConfettiParticle(
    val startXRatio: Float,
    val startYRatio: Float,
    val vx: Float,
    val vy: Float,
    val pSize: Float,
    val color: Color,
    val rotation: Float,
    val rotationSpeed: Float,
    val shapeType: Int
)

@Composable
fun FullScreensCelebrationConfetti(
    onFinished: () -> Unit
) {
    val context = LocalContext.current

    LaunchedEffect(Unit) {
        FeedbackHelper.playCompletionFeedback(
            context = context,
            vibrationEnabled = true
        )
    }

    val particles = remember {
        val colors = listOf(
            Color(0xFFFFD54F), // Gold
            Color(0xFFAB47BC), // Violet
            Color(0xFF66BB6A), // Green
            Color(0xFF29B6F6), // Cyan
            Color(0xFFFF7043), // Coral
            Color(0xFFEC407A), // Pink
            Color(0xFF7E57C2), // Deep Purple
            Color(0xFF26A69A), // Teal
            Color(0xFFFFFFFF)  // White
        )
        val list = mutableListOf<ScreenConfettiParticle>()
        val random = java.util.Random(42)
        for (i in 0 until 180) {
            val angle = random.nextFloat() * 2f * Math.PI.toFloat()
            val speed = 200f + random.nextFloat() * 750f
            list.add(
                ScreenConfettiParticle(
                    startXRatio = random.nextFloat(),
                    startYRatio = -0.2f + random.nextFloat() * 0.5f,
                    vx = (kotlin.math.cos(angle) * speed).toFloat(),
                    vy = (kotlin.math.sin(angle) * speed - 200f).toFloat(),
                    pSize = (12f + random.nextFloat() * 22f),
                    color = colors[random.nextInt(colors.size)],
                    rotation = random.nextFloat() * 360f,
                    rotationSpeed = (random.nextFloat() - 0.5f) * 720f,
                    shapeType = random.nextInt(3)
                )
            )
        }
        list
    }

    val timeAnim = remember { Animatable(0f) }
    LaunchedEffect(Unit) {
        timeAnim.animateTo(
            targetValue = 1f,
            animationSpec = tween(durationMillis = 2000, easing = LinearEasing)
        )
        onFinished()
    }

    val progress = timeAnim.value
    val alpha = (1f - progress).coerceIn(0f, 1f)

    Canvas(
        modifier = Modifier
            .fillMaxSize()
            .clickable(enabled = false) {}
    ) {
        val canvasWidth = size.width
        val canvasHeight = size.height

        val t = progress * 2.0f
        val gravity = 500f

        particles.forEach { p ->
            val startX = p.startXRatio * canvasWidth
            val startY = p.startYRatio * canvasHeight
            val curX = startX + p.vx * t
            val curY = startY + p.vy * t + 0.5f * gravity * t * t
            val curRot = p.rotation + p.rotationSpeed * t

            if (curX in -100f..(canvasWidth + 100f) && curY in -100f..(canvasHeight + 100f)) {
                withTransform({
                    translate(left = curX, top = curY)
                    rotate(degrees = curRot)
                }) {
                    val pColor = p.color.copy(alpha = alpha)
                    when (p.shapeType) {
                        0 -> drawCircle(color = pColor, radius = p.pSize / 2f)
                        1 -> drawRect(
                            color = pColor,
                            topLeft = androidx.compose.ui.geometry.Offset(-p.pSize / 2f, -p.pSize / 2f),
                            size = androidx.compose.ui.geometry.Size(p.pSize, p.pSize * 0.7f)
                        )
                        else -> drawOval(
                            color = pColor,
                            topLeft = androidx.compose.ui.geometry.Offset(-p.pSize / 2f, -p.pSize / 2f),
                            size = androidx.compose.ui.geometry.Size(p.pSize * 1.4f, p.pSize * 0.6f)
                        )
                    }
                }
            }
        }
    }
}

