fun parseHabitColor(colorName: String): Color {
    return when (colorName.lowercase()) {
        "blue" -> HabitBlue
        "purple", "violet" -> HabitPurple
        "cyan" -> HabitCyan
        "green" -> HabitGreen
        "yellow" -> HabitYellow
        "orange" -> HabitOrange
        "red" -> HabitRed
        "pink" -> HabitPink
        "slate" -> HabitSlate
        "teal" -> HabitTeal
        "rose" -> HabitRose
        "indigo" -> HabitIndigo
        else -> try {
            if (colorName.startsWith("#")) Color(android.graphics.Color.parseColor(colorName))
            else PrimaryViolet
        } catch (e: Exception) {
            PrimaryViolet
        }
    }
}

data class MonthlyReviewData(
    val year: Int,
    val month: Int,
    val monthName: String,
    val totalCompletions: Int,
    val totalCheckIns: Int = 0,
    val prevMonthCompletions: Int,
    val growthPercentage: Int,
    val startScore: Int,
    val endScore: Int,
    val scoreDelta: Int,
    val mvpHabit: Habit?,
    val mvpCompletions: Int,
    val mvpStrength: Int,
    val focusHabit: Habit?,
    val focusCompletions: Int,
    val focusExpected: Int,
    val bestDayOfWeekName: String,
    val bestDayOfWeekRate: Int
)

fun calculateHabitStrengthOnDate(habit: Habit, logs: List<HabitLog>, targetDateStr: String): Int {
    val todayStr = java.time.LocalDate.now().toString()
    if (targetDateStr >= todayStr) {
        return com.example.data.calculateHabitStrength(habit, logs)
    }

    val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
    val targetDate = try { sdf.parse(targetDateStr) } catch (e: Exception) { java.util.Date() }
    val targetMillis = targetDate?.time ?: System.currentTimeMillis()
    val validStartMillis = if (habit.startDate > 946684800000L) habit.startDate else habit.createdAt
    val startSdfStr = sdf.format(java.util.Date(validStartMillis))
    
    val filteredLogs = logs.filter { it.date <= targetDateStr && it.date >= startSdfStr }
    val habitLogs = filteredLogs.filter { it.habitId == habit.id }
    
    val completedEpochDays = habitLogs.filter { log ->
        com.example.data.isLogCompleted(habit, log)
    }.map { 
        try {
            java.time.LocalDate.parse(it.date).toEpochDay().toInt()
        } catch (e: Exception) {
            0
        }
    }.toSet()
    
    if (habit.frequency == "TIMES_WEEKLY") {
        val targetTimes = habit.specificDays.toIntOrNull() ?: 3
        val activeDays = (targetMillis - validStartMillis) / (24 * 3600 * 1000) + 1
        val activeWeeks = (activeDays / 7.0).coerceAtMost(4.0).coerceAtLeast(1.0)
        val expectedCompletions = (activeWeeks * targetTimes).toInt().coerceAtLeast(1)
        
        val limitMillis = targetMillis - 28L * 24 * 3600 * 1000
        val limitSdfStr = sdf.format(java.util.Date(limitMillis.coerceAtLeast(validStartMillis)))
        val completedInLast4Weeks = habitLogs.filter { log ->
            com.example.data.isLogCompleted(habit, log) && log.date >= limitSdfStr
        }.size
        
        return (completedInLast4Weeks.toFloat() / expectedCompletions.toFloat() * 100).toInt().coerceIn(0, 100)
    }
    
    val loggedEpochDays = habitLogs.map { 
        try {
            java.time.LocalDate.parse(it.date).toEpochDay().toInt()
        } catch (e: Exception) {
            0
        }
    }.toSet()
    
    val todayEpoch = try {
        java.time.LocalDate.parse(targetDateStr).toEpochDay().toInt()
    } catch (e: Exception) {
        0
    }
    val startEpoch = try {
        java.time.Instant.ofEpochMilli(validStartMillis).atZone(java.time.ZoneId.systemDefault()).toLocalDate().toEpochDay().toInt()
    } catch (e: Exception) {
        (validStartMillis / 86400000L).toInt()
    }
    
    var weightedCompleted = 0
    var totalPossibleWeight = 0
    val totalDaysToCheck = 30
    
    val maxDays = if (todayEpoch - startEpoch + 1 < totalDaysToCheck) {
        todayEpoch - startEpoch + 1
    } else {
        totalDaysToCheck
    }
    
    if (maxDays <= 0) return 0
    
    val realTodayEpoch = java.time.LocalDate.now().toEpochDay().toInt()
    
    for (i in 0 until maxDays) {
        val currentEpoch = todayEpoch - i
        val dayWeight = 20 + (totalDaysToCheck - i)
        
        val successful = if (habit.isNegative) {
            !loggedEpochDays.contains(currentEpoch) || completedEpochDays.contains(currentEpoch)
        } else {
            completedEpochDays.contains(currentEpoch)
        }
        
        // Skip penalizing if it's the actual today, it's a positive habit, and hasn't been logged yet
        val isPendingRealToday = (currentEpoch == realTodayEpoch) && !habit.isNegative && !loggedEpochDays.contains(currentEpoch)
        if (isPendingRealToday) {
            continue
        }
        
        if (successful) {
            weightedCompleted += dayWeight
        }
        totalPossibleWeight += dayWeight
    }
    
    val percentage = if (totalPossibleWeight > 0) {
        (weightedCompleted.toFloat() / totalPossibleWeight.toFloat() * 100).toInt()
    } else {
        0
    }
    return percentage.coerceIn(0, 100)
}

fun isLogCompleted(log: HabitLog, habit: Habit?): Boolean {
    if (habit == null) return false
    return com.example.data.isLogCompleted(habit, log)
}

fun calculateMonthlyReviewData(
    year: Int,
    month: Int,
    allHabits: List<Habit>,
    allLogs: List<HabitLog>,
    language: String
): MonthlyReviewData {
    val monthPrefix = String.format(java.util.Locale.US, "%04d-%02d-", year, month)
    
    val monthLogs = allLogs.filter { it.date.startsWith(monthPrefix) }
    val validMonthLogs = monthLogs.filter { log ->
        isLogCompleted(log, allHabits.find { it.id == log.habitId })
    }
    val totalCompletions = validMonthLogs.size
    val totalCheckIns = monthLogs.count { it.value != 0f && !it.isPaused }
    
    val prevYear = if (month == 1) year - 1 else year
    val prevMonth = if (month == 1) 12 else month - 1
    val prevMonthPrefix = String.format(java.util.Locale.US, "%04d-%02d-", prevYear, prevMonth)
    
    val validPrevLogs = allLogs.filter { log ->
        log.date.startsWith(prevMonthPrefix) && isLogCompleted(log, allHabits.find { it.id == log.habitId })
    }
    val prevMonthCompletions = validPrevLogs.size
    
    val growthPercentage = if (prevMonthCompletions > 0) {
        (((totalCompletions - prevMonthCompletions).toFloat() / prevMonthCompletions) * 100).toInt()
    } else {
        0
    }
    
    val calendar = java.util.Calendar.getInstance()
    // Last day of previous month
    calendar.set(java.util.Calendar.YEAR, prevYear)
    calendar.set(java.util.Calendar.MONTH, prevMonth - 1)
    val prevMaxDay = calendar.getActualMaximum(java.util.Calendar.DAY_OF_MONTH)
    val prevMonthLastDay = String.format(java.util.Locale.US, "%04d-%02d-%02d", prevYear, prevMonth, prevMaxDay)
    
    // Last day of this month
    calendar.set(java.util.Calendar.YEAR, year)
    calendar.set(java.util.Calendar.MONTH, month - 1)
    val thisMaxDay = calendar.getActualMaximum(java.util.Calendar.DAY_OF_MONTH)
    val thisMonthLastDay = String.format(java.util.Locale.US, "%04d-%02d-%02d", year, month, thisMaxDay)
    
    val activeHabits = allHabits.filter { !it.isArchived }
    
    val habitsAtStart = activeHabits.filter { h ->
        val startStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
            .format(java.util.Date(if (h.startDate > 946684800000L) h.startDate else h.createdAt))
        startStr <= prevMonthLastDay
    }
    val startScore = if (habitsAtStart.isNotEmpty()) {
        habitsAtStart.map { calculateHabitStrengthOnDate(it, allLogs, prevMonthLastDay) }.average().toInt()
    } else 0
    
    val habitsAtEnd = activeHabits.filter { h ->
        val startStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
            .format(java.util.Date(if (h.startDate > 946684800000L) h.startDate else h.createdAt))
        startStr <= thisMonthLastDay
    }
    val endScore = if (habitsAtEnd.isNotEmpty()) {
        habitsAtEnd.map { calculateHabitStrengthOnDate(it, allLogs, thisMonthLastDay) }.average().toInt()
    } else 0
    
    val scoreDelta = endScore - startScore
    
    // MVP Habit: most completions in this month
    val mvpHabit = activeHabits.maxByOrNull { h ->
        allLogs.count { it.habitId == h.id && it.date.startsWith(monthPrefix) && isLogCompleted(it, h) }
    }
    val mvpCompletions = if (mvpHabit != null) {
        allLogs.count { it.habitId == mvpHabit.id && it.date.startsWith(monthPrefix) && isLogCompleted(it, mvpHabit) }
    } else 0
    val mvpStrength = if (mvpHabit != null) {
        calculateHabitStrengthOnDate(mvpHabit, allLogs, thisMonthLastDay)
    } else 0
    
    // Focus Habit: lowest completion rate in this month
    val focusHabit = activeHabits.filter { h ->
        val validStartStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US).format(java.util.Date(if (h.startDate > 946684800000L) h.startDate else h.createdAt))
        validStartStr <= thisMonthLastDay
    }.minByOrNull { h ->
        val comps = allLogs.count { it.habitId == h.id && it.date.startsWith(monthPrefix) && isLogCompleted(it, h) }
        val expected = if (h.frequency == "TIMES_WEEKLY") (h.specificDays.toIntOrNull() ?: 3) * 4 else 28
        comps.toFloat() / expected.coerceAtLeast(1).toFloat()
    }
    
    val focusCompletions = if (focusHabit != null) {
        allLogs.count { it.habitId == focusHabit.id && it.date.startsWith(monthPrefix) && isLogCompleted(it, focusHabit) }
    } else 0
    
    val focusExpected = if (focusHabit != null) {
        if (focusHabit.frequency == "TIMES_WEEKLY") (focusHabit.specificDays.toIntOrNull() ?: 3) * 4 else 28
    } else 0
    
    // Power day of week
    val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
    val logsByDayOfWeek = validMonthLogs.groupBy { log ->
        try {
            val d = sdf.parse(log.date)
            val cal = java.util.Calendar.getInstance()
            if (d != null) cal.time = d
            cal.get(java.util.Calendar.DAY_OF_WEEK)
        } catch (e: Exception) {
            java.util.Calendar.MONDAY
        }
    }
    val bestDayEntry = logsByDayOfWeek.maxByOrNull { it.value.size }
    val bestDayOfWeekNum = bestDayEntry?.key ?: java.util.Calendar.MONDAY
    val bestDayOfWeekName = getDayOfWeekNameLocalized(bestDayOfWeekNum, language)
    val bestDayOfWeekRate = bestDayEntry?.value?.size ?: 0
    
    return MonthlyReviewData(
        year = year,
        month = month,
        monthName = getMonthNameLocalized(month, language),
        totalCompletions = totalCompletions,
        totalCheckIns = totalCheckIns,
        prevMonthCompletions = prevMonthCompletions,
        growthPercentage = growthPercentage,
        startScore = startScore,
        endScore = endScore,
        scoreDelta = scoreDelta,
        mvpHabit = mvpHabit,
        mvpCompletions = mvpCompletions,
        mvpStrength = mvpStrength,
        focusHabit = focusHabit,
        focusCompletions = focusCompletions,
        focusExpected = focusExpected,
        bestDayOfWeekName = bestDayOfWeekName,
        bestDayOfWeekRate = bestDayOfWeekRate
    )
}

fun calculateStreakFast(habit: Habit, logs: List<HabitLog>): Pair<Int, Int> {
    val validStartMillis = if (habit.startDate > 946684800000L) habit.startDate else habit.createdAt
    val startSdfStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US).format(java.util.Date(validStartMillis))
    val habitLogs = logs.filter { it.habitId == habit.id && it.date >= startSdfStr }
    if (habitLogs.isEmpty()) return 0 to 0

    val completedDates = habitLogs.filter { log ->
        com.example.data.isLogCompleted(habit, log) && !log.isPaused
    }.map { it.date }.toSet()

    if (habit.frequency == "TIMES_WEEKLY") {
        val comps = completedDates.size
        return comps to comps
    }

    val sortedDates = completedDates.sorted()
    if (sortedDates.isEmpty()) return 0 to 0

    var longest = 0
    var current = 0
    val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
    val todayStr = sdf.format(java.util.Date())
    
    val epochDays = sortedDates.map { 
        try {
            java.time.LocalDate.parse(it).toEpochDay().toInt()
        } catch (e: Exception) {
            0
        }
    }.toSet()
    
    if (epochDays.isEmpty()) return 0 to 0
    
    val minEpoch = epochDays.minOrNull() ?: 0
    val maxEpoch = epochDays.maxOrNull() ?: 0
    
    var tempCurrent = 0
    for (epoch in minEpoch..maxEpoch) {
        if (epochDays.contains(epoch)) {
            tempCurrent++
            if (tempCurrent > longest) {
                longest = tempCurrent
            }
        } else {
            tempCurrent = 0
        }
    }
    
    val todayEpoch = try {
        java.time.LocalDate.parse(todayStr).toEpochDay().toInt()
    } catch (e: Exception) {
        0
    }
    
    var currentStreak = 0
    var checkEpoch = todayEpoch
    if (!epochDays.contains(todayEpoch) && epochDays.contains(todayEpoch - 1)) {
        checkEpoch = todayEpoch - 1
    }
    
    while (epochDays.contains(checkEpoch)) {
        currentStreak++
        checkEpoch--
    }

    return currentStreak to longest
}

data class YearlyReviewData(
    val year: Int,
    val totalCompletions: Int,
    val totalCheckIns: Int = 0,
    val activeDaysCount: Int,
    val activeDaysPercentage: Int,
    val topHabit: Habit?,
    val topHabitCompletions: Int,
    val growthHabit: Habit?,
    val growthHabitCompletions: Int,
    val bestMonthName: String,
    val bestMonthCompletions: Int,
    val bestDayOfWeekName: String,
    val bestDayOfWeekCompletions: Int,
    val perfectDaysCount: Int,
    val longestStreak: Int = 0,
    val longestStreakHabit: Habit? = null,
    val isStreakActive: Boolean = false,
    val startScore: Int = 0,
    val endScore: Int = 0,
    val scoreDelta: Int = 0
)

fun calculateYearlyReviewData(
    year: Int,
    allHabits: List<Habit>,
    allLogs: List<HabitLog>,
    language: String
): YearlyReviewData {
    val yearPrefix = "$year-"
    
    val yearLogs = allLogs.filter { it.date.startsWith(yearPrefix) }
    val validYearLogs = yearLogs.filter { log -> 
        isLogCompleted(log, allHabits.find { it.id == log.habitId })
    }
    val totalCompletions = validYearLogs.size
    val totalCheckIns = yearLogs.count { it.value != 0f && !it.isPaused }

    val activeDates = validYearLogs.map { it.date }.distinct()
    val totalActiveDays = activeDates.size
    
    val activeHabits = allHabits.filter { !it.isArchived }
    
    // Calculate Score from Dec 31 of prev year to Dec 31 of this year
    val prevYearLastDay = "${year - 1}-12-31"
    val thisYearLastDay = "$year-12-31"
    
    val habitsAtStart = activeHabits.filter { h ->
        val startStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
            .format(java.util.Date(if (h.startDate > 946684800000L) h.startDate else h.createdAt))
        startStr <= prevYearLastDay
    }
    val startScore = if (habitsAtStart.isNotEmpty()) {
        habitsAtStart.map { calculateHabitStrengthOnDate(it, allLogs, prevYearLastDay) }.average().toInt()
    } else 0
    
    val habitsAtEnd = activeHabits.filter { h ->
        val startStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
            .format(java.util.Date(if (h.startDate > 946684800000L) h.startDate else h.createdAt))
        startStr <= thisYearLastDay
    }
    val endScore = if (habitsAtEnd.isNotEmpty()) {
        habitsAtEnd.map { calculateHabitStrengthOnDate(it, allLogs, thisYearLastDay) }.average().toInt()
    } else 0
    
    val scoreDelta = endScore - startScore

    val mvpHabit = activeHabits.maxByOrNull { h ->
        allLogs.count { it.habitId == h.id && it.date.startsWith(yearPrefix) && isLogCompleted(it, h) }
    }
    val mvpCompletions = if (mvpHabit != null) {
        allLogs.count { it.habitId == mvpHabit.id && it.date.startsWith(yearPrefix) && isLogCompleted(it, mvpHabit) }
    } else 0

    val growthHabit = activeHabits.maxByOrNull { h ->
        val startH = calculateHabitStrengthOnDate(h, allLogs, prevYearLastDay)
        val endH = calculateHabitStrengthOnDate(h, allLogs, thisYearLastDay)
        endH - startH
    }
    val growthHabitCompletions = if (growthHabit != null) {
        allLogs.count { it.habitId == growthHabit.id && it.date.startsWith(yearPrefix) && isLogCompleted(it, growthHabit) }
    } else 0

    val activeDaysPercentage = if (totalActiveDays > 0) {
        (totalActiveDays * 100) / 365
    } else 0

    val completionsByMonth = validYearLogs.groupBy { 
        if (it.date.length >= 7) it.date.substring(5, 7).toIntOrNull() ?: 1 else 1 
    }
    val bestMonthEntry = completionsByMonth.maxByOrNull { it.value.size }
    val bestMonthNum = bestMonthEntry?.key ?: 1
    val bestMonthName = getMonthNameLocalized(bestMonthNum, language)
    val bestMonthCompletions = bestMonthEntry?.value?.size ?: 0

    val sdfDay = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
    val calDay = Calendar.getInstance()
    val completionsByDayOfWeek = validYearLogs.groupBy { log ->
        try {
            val date = sdfDay.parse(log.date)
            if (date != null) {
                calDay.time = date
                calDay.get(Calendar.DAY_OF_WEEK)
            } else Calendar.MONDAY
        } catch (e: Exception) {
            Calendar.MONDAY
        }
    }
    val bestDayOfWeekEntry = completionsByDayOfWeek.maxByOrNull { it.value.size }
    val bestDayOfWeekNum = bestDayOfWeekEntry?.key ?: Calendar.MONDAY
    val bestDayOfWeekName = when (bestDayOfWeekNum) {
        Calendar.SUNDAY -> if (language == "de") "Sonntag" else if (language == "ka") "კვირა" else "Sunday"
        Calendar.MONDAY -> if (language == "de") "Montag" else if (language == "ka") "ორშაბათი" else "Monday"
        Calendar.TUESDAY -> if (language == "de") "Dienstag" else if (language == "ka") "სამშაბათი" else "Tuesday"
        Calendar.WEDNESDAY -> if (language == "de") "Mittwoch" else if (language == "ka") "ოთხშაბათი" else "Wednesday"
        Calendar.THURSDAY -> if (language == "de") "Donnerstag" else if (language == "ka") "ხუთშაბათი" else "Thursday"
        Calendar.FRIDAY -> if (language == "de") "Freitag" else if (language == "ka") "პარასკევი" else "Friday"
        Calendar.SATURDAY -> if (language == "de") "Samstag" else if (language == "ka") "შაბათი" else "Saturday"
        else -> if (language == "de") "Montag" else if (language == "ka") "ორშაბათი" else "Monday"
    }
    val bestDayOfWeekCompletions = bestDayOfWeekEntry?.value?.size ?: 0

    var perfectDaysCount = 0
    val daysInYearWithLogs = validYearLogs.groupBy { it.date }
    for ((_, logsOnDay) in daysInYearWithLogs) {
        if (activeHabits.isNotEmpty() && logsOnDay.size >= activeHabits.size) {
            perfectDaysCount++
        }
    }

    val streakPairs = activeHabits.map { h ->
        h to calculateStreakFast(h, allLogs)
    }
    val longestStreakPair = streakPairs.maxByOrNull { it.second.second }
    val longestStreak = longestStreakPair?.second?.second ?: 0
    val longestStreakHabit = longestStreakPair?.first
    val isStreakActive = (longestStreakPair?.second?.first ?: 0) > 0

    return YearlyReviewData(
        year = year,
        totalCompletions = totalCompletions,
        totalCheckIns = totalCheckIns,
        activeDaysCount = totalActiveDays,
        activeDaysPercentage = activeDaysPercentage,
        topHabit = mvpHabit,
        topHabitCompletions = mvpCompletions,
        growthHabit = growthHabit,
        growthHabitCompletions = growthHabitCompletions,
        bestMonthName = bestMonthName,
        bestMonthCompletions = bestMonthCompletions,
        bestDayOfWeekName = bestDayOfWeekName,
        bestDayOfWeekCompletions = bestDayOfWeekCompletions,
        perfectDaysCount = perfectDaysCount,
        longestStreak = longestStreak,
        longestStreakHabit = longestStreakHabit,
        isStreakActive = isStreakActive,
        startScore = startScore,
        endScore = endScore,
        scoreDelta = scoreDelta
    )
}

fun getMonthNameLocalized(month: Int, language: String): String {
    val GermanMonths = listOf(
        "Januar", "Februar", "März", "April", "Mai", "Juni",
        "Juli", "August", "September", "Oktober", "November", "Dezember"
    )
    val EnglishMonths = listOf(
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    )
    val idx = (month - 1).coerceIn(0, 11)
    return if (language == "de") GermanMonths[idx] else EnglishMonths[idx]
}

fun getDayOfWeekNameLocalized(dayOfWeek: Int, language: String): String {
    val GermanDays = mapOf(
        Calendar.MONDAY to "Montag",
        Calendar.TUESDAY to "Dienstag",
        Calendar.WEDNESDAY to "Mittwoch",
        Calendar.THURSDAY to "Donnerstag",
        Calendar.FRIDAY to "Freitag",
        Calendar.SATURDAY to "Samstag",
        Calendar.SUNDAY to "Sonntag"
    )
    val EnglishDays = mapOf(
        Calendar.MONDAY to "Monday",
        Calendar.TUESDAY to "Tuesday",
        Calendar.WEDNESDAY to "Wednesday",
        Calendar.THURSDAY to "Thursday",
        Calendar.FRIDAY to "Friday",
        Calendar.SATURDAY to "Saturday",
        Calendar.SUNDAY to "Sunday"
    )
    return if (language == "de") GermanDays[dayOfWeek] ?: "Montag" else EnglishDays[dayOfWeek] ?: "Monday"
}

@Composable
fun ReviewArchiveDialog(
    showReviewArchive: Boolean,
    availableYears: List<Int>,
    availableMonths: List<Pair<Int, Int>>,
    allHabits: List<com.example.data.Habit>,
    allLogs: List<com.example.data.HabitLog>,
    language: String,
    onShowReviewExplanation: () -> Unit,
    onSelectReviewMonth: (Pair<Int, Int>) -> Unit,
    onSelectReviewYear: (Int) -> Unit,
    onDismiss: () -> Unit
) {
    if (!showReviewArchive) return

    var selectedTabIndex by remember { mutableStateOf(0) } // 0 = Monthly, 1 = Yearly

    Dialog(onDismissRequest = onDismiss) {
        Surface(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 4.dp, vertical = 16.dp),
            color = AppCard,
            border = BorderStroke(1.dp, AppBorder),
            shape = RoundedCornerShape(24.dp)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(20.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Text(
                            text = if (language == "de") "Deine Rückblicke" else if (language == "ka") "თქვენი მიმოხილვები" else "Your Reviews",
                            style = MaterialTheme.typography.titleLarge,
                            color = TextPrimary,
                            fontWeight = FontWeight.Bold
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        IconButton(
                            onClick = onShowReviewExplanation,
                            modifier = Modifier.size(24.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.Info,
                                contentDescription = "Info",
                                tint = PrimaryViolet,
                                modifier = Modifier.size(20.dp)
                            )
                        }
                    }
                    IconButton(onClick = onDismiss) {
                        Icon(imageVector = Icons.Default.Close, contentDescription = "Close", tint = TextSecondary)
                    }
                }

                Spacer(modifier = Modifier.height(12.dp))

                TabRow(
                    selectedTabIndex = selectedTabIndex,
                    containerColor = Color.Transparent,
                    contentColor = PrimaryViolet
                ) {
                    Tab(
                        selected = selectedTabIndex == 0,
                        onClick = { selectedTabIndex = 0 },
                        text = { 
                            Text(
                                text = if (language == "de") "Monatlich (${availableMonths.size})" else if (language == "ka") "ყოველთვიური ( ${availableMonths.size} )" else "Monthly (${availableMonths.size})", 
                                color = if (selectedTabIndex == 0) PrimaryViolet else TextSecondary
                            ) 
                        }
                    )
                    Tab(
                        selected = selectedTabIndex == 1,
                        onClick = { selectedTabIndex = 1 },
                        text = { 
                            Text(
                                text = if (language == "de") "Jährlich (${availableYears.size})" else if (language == "ka") "ყოველწლიურად ( ${availableYears.size} )" else "Yearly (${availableYears.size})", 
                                color = if (selectedTabIndex == 1) PrimaryViolet else TextSecondary
                            ) 
                        }
                    )
                }

                Spacer(modifier = Modifier.height(16.dp))

                LazyColumn(
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(max = 420.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    if (selectedTabIndex == 0) {
                        if (availableMonths.isEmpty()) {
                            item {
                                Text(
                                    text = if (language == "de") "Noch keine Monatsrückblicke verfügbar." else if (language == "ka") "ყოველთვიური მიმოხილვები ჯერ არ არის ხელმისაწვდომი." else "No monthly reviews available yet.",
                                    style = MaterialTheme.typography.bodyMedium,
                                    color = TextSecondary,
                                    modifier = Modifier.padding(vertical = 16.dp)
                                )
