                        style = MaterialTheme.typography.bodyMedium
                    )
                    Text(
                        text = reviewData.endScore.toString(),
                        color = Color.White,
                        fontWeight = FontWeight.Bold,
                        style = MaterialTheme.typography.bodyMedium
                    )
                }

                if (reviewData.mvpHabit != null) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = if (language == "de") "Habit MVP:" else if (language == "ka") "ჩვევა MVP:" else "Habit MVP:",
                            color = Color.White.copy(alpha = 0.8f),
                            style = MaterialTheme.typography.bodyMedium
                        )
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                imageVector = HabitIconMapping.getIcon(reviewData.mvpHabit.icon),
                                contentDescription = null,
                                tint = parseHabitColor(reviewData.mvpHabit.color),
                                modifier = Modifier.size(16.dp)
                            )
                            Spacer(modifier = Modifier.width(4.dp))
                            Text(
                                text = reviewData.mvpHabit.name,
                                color = Color.White,
                                fontWeight = FontWeight.Bold,
                                style = MaterialTheme.typography.bodyMedium
                            )
                        }
                    }
                }

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Text(
                        text = if (language == "de") "Power day:" else if (language == "ka") "დენის დღე:" else "Power day:",
                        color = Color.White.copy(alpha = 0.8f),
                        style = MaterialTheme.typography.bodyMedium
                    )
                    Text(
                        text = reviewData.bestDayOfWeekName,
                        color = Color.White,
                        fontWeight = FontWeight.Bold,
                        style = MaterialTheme.typography.bodyMedium
                    )
                }
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        Button(
            onClick = {
                showShareDialog = true
            },
            colors = ButtonDefaults.buttonColors(
                containerColor = Color(0xFF3B82F6),
                contentColor = Color.White
            ),
            shape = RoundedCornerShape(16.dp),
            modifier = Modifier
                .fillMaxWidth()
                .height(48.dp)
        ) {
            Icon(imageVector = Icons.Default.Share, contentDescription = null, modifier = Modifier.size(18.dp))
            Spacer(modifier = Modifier.width(8.dp))
            Text(
                text = if (language == "de") "Rückblick teilen" else if (language == "ka") "გააზიარეთ მიმოხილვა" else "Share Review",
                fontWeight = FontWeight.Bold,
                style = MaterialTheme.typography.bodyLarge
            )
        }

        Spacer(modifier = Modifier.height(16.dp))

        Text(
            text = if (language == "de") 
                "Großartige Arbeit! Jeder Tag ist eine Chance, besser zu werden. Weiter so!" 
            else if (language == "ka") "დიდი სამუშაო! ყოველი დღე არის ზრდის ახალი შანსი. ასე გააგრძელე!" else "Great job! Every day is a new chance to grow. Keep it up!",
            style = MaterialTheme.typography.bodyMedium,
            color = Color.White.copy(alpha = 0.85f),
            textAlign = TextAlign.Center
        )

        if (showShareDialog) {
            com.example.ui.MonthlyReviewShareDialog(
                year = year,
                reviewData = reviewData,
                language = language,
                onDismiss = { showShareDialog = false }
            )
        }
    }
}


