@Composable
fun YearlyReviewTransformationSlide(year: Int, language: String, reviewData: YearlyReviewData) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
