            text = "🏆 " + (if (language == "de") "Erfolge & Trophäen" else if (language == "ka") "მიღწევები და თასები" else "Achievements & Trophies"),
            style = MaterialTheme.typography.headlineMedium,
            color = Color.White,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center
        )

        Text(
            text = if (language == "de") 
                "Deine verdienten Abzeichen im Jahr $year" 
            else if (language == "ka") "თქვენი მიღებული სამკერდე ნიშნები $year -ში" else "Your earned badges in $year",
            style = MaterialTheme.typography.bodyMedium,
            color = Color.White.copy(alpha = 0.8f),
            textAlign = TextAlign.Center,
            modifier = Modifier.padding(top = 6.dp)
        )

        Spacer(modifier = Modifier.height(28.dp))

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceAround
        ) {
            val trophies = listOf(
                Triple("🥇", if (language == "de") "100+ Abschlüsse" else if (language == "ka") "100+ დასრულება" else "100+ Completions", reviewData.totalCompletions >= 100),
                Triple("⭐", if (language == "de") "Perfekt" else if (language == "ka") "სრულყოფილი" else "Perfect", reviewData.perfectDaysCount >= 10),
                Triple("🔥", if (language == "de") "Disziplin" else if (language == "ka") "მწკრივი" else "Streak", reviewData.longestStreak >= 7)
            )

            for ((emoji, name, unlocked) in trophies) {
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    modifier = Modifier.padding(8.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(72.dp)
                            .background(
                                if (unlocked) Color(0xFFFBBF24).copy(alpha = 0.25f) else Color.White.copy(alpha = 0.1f),
                                CircleShape
                            )
                            .border(
                                2.dp,
                                if (unlocked) Color(0xFFFBBF24) else Color.White.copy(alpha = 0.2f),
                                CircleShape
                            ),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = emoji,
                            style = MaterialTheme.typography.headlineMedium,
                            modifier = Modifier.graphicsLayer(alpha = if (unlocked) 1f else 0.4f)
                        )
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        text = name,
                        style = MaterialTheme.typography.labelLarge,
                        color = if (unlocked) Color.White else Color.White.copy(alpha = 0.5f),
                        fontWeight = FontWeight.Bold
                    )
                    Text(
                        text = if (unlocked) (if (language == "de") "Freigeschaltet" else if (language == "ka") "განბლოკილია" else "Unlocked") else (if (language == "de") "Gesperrt" else if (language == "ka") "ჩაკეტილი" else "Locked"),
                        style = MaterialTheme.typography.bodySmall,
                        color = if (unlocked) Color(0xFF34D399) else Color.White.copy(alpha = 0.4f)
                    )
                }
            }
        }
    }
}


// STEP 1: Gewohnheiten bedienen & bearbeiten (Direct 1-to-1 HabitItemRow Usage)
@Composable
private fun OnboardingStep1(language: String) {
    val sampleHabit1 = remember(language) {
        Habit(
            id = 991,
            name = if (language == "de") "Wasser trinken" else if (language == "ka") "დალიე წყალი" else "Drink Water",
            category = "Gesundheit",
            icon = "water",
            color = "teal",
            type = "NUMBER",
            unit = "ml",
            targetValue = 3000f,
            reminderEnabled = true,
            reminderHour = 9,
            reminderMinute = 0
        )
    }
    val sampleHabit2 = remember(language) {
        Habit(
            id = 992,
            name = if (language == "de") "Morgenmeditation" else if (language == "ka") "დილის მედიტაცია" else "Morning Meditation",
            category = "Achtsamkeit",
            icon = "meditation",
            color = "purple",
            type = "BINARY"
        )
    }

    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center,
        modifier = Modifier.fillMaxWidth()
    ) {
        // Real 1-to-1 Habit Item Rows from the App
        Column(
            verticalArrangement = Arrangement.spacedBy(8.dp),
            modifier = Modifier.fillMaxWidth()
        ) {
            HabitItemRow(
                habit = sampleHabit1,
                currentValue = 2250f,
                isCompleted = false,
                isFailed = false,
                isPaused = false,
                hasLog = true,
                onToggle = { _, _ -> },
                onAddQuantity = { _, _, _ -> },
                onLongClick = {},
                language = language
            )

            HabitItemRow(
                habit = sampleHabit2,
                currentValue = 1f,
                isCompleted = true,
                isFailed = false,
                isPaused = false,
                hasLog = true,
                onToggle = { _, _ -> },
                onAddQuantity = { _, _, _ -> },
                onLongClick = {},
                language = language
            )
        }

        Spacer(modifier = Modifier.height(14.dp))

        Text(
            text = if (language == "de") "Gewohnheiten steuern & anpassen" else if (language == "ka") "ჩვევების კონტროლი და მორგება" else "Control & Customize Habits",
            style = MaterialTheme.typography.titleMedium,
            color = TextPrimary,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center
        )

        Spacer(modifier = Modifier.height(8.dp))

        // Accurately detailed Interaction Instructions
        Column(
            verticalArrangement = Arrangement.spacedBy(6.dp),
            modifier = Modifier.fillMaxWidth()
        ) {
            Row(verticalAlignment = Alignment.Top) {
                Text("👆 ", fontSize = 14.sp)
                Text(
                    text = if (language == "de") {
                        "Tippen auf Karte: Abhaken (Ja/Nein) oder Wert-Eingabedialog öffnen (Zahlen)."
                    } else {
                        "Tap card: Toggle completion (binary) or open exact value dialog (numeric)."
                    },
                    style = MaterialTheme.typography.bodySmall,
                    color = TextPrimary
                )
            }
            Row(verticalAlignment = Alignment.Top) {
                Text("➕ ", fontSize = 14.sp)
                Text(
                    text = if (language == "de") {
                        "Kreis-Symbol rechts: Erhöht bei Zahlen-Gewohnheiten sofort den Wert um +1."
                    } else if (language == "ka") {
                        "მარჯვენა წრის ხატულა: სწრაფად ზრდის ციფრულ მნიშვნელობას +1-ით ერთი შეხებით."
                    } else {
                        "Right circle icon: Quickly increments numeric value by +1 with one tap."
                    },
                    style = MaterialTheme.typography.bodySmall,
                    color = TextPrimary
                )
            }
            Row(verticalAlignment = Alignment.Top) {
                Text("⏱️ ", fontSize = 14.sp)
                Text(
                    text = if (language == "de") {
                        "Gedrückt halten: Kontextmenü zum Pausieren, Fehlgeschlagen, Bearbeiten & Löschen."
                    } else if (language == "ka") {
                        "დიდხანს დააჭირეთ: კონტექსტური მენიუ პაუზისთვის, წარუმატებელი სტატუსისთვის, რედაქტირება და წაშლა."
                    } else {
                        "Long Press: Context menu for Pause, Failed status, Edit & Delete."
                    },
                    style = MaterialTheme.typography.bodySmall,
                    color = TextPrimary
                )
            }
        }
    }
}

// STEP 2: Audio Soundscapes & Fokus-Timer
@Composable
private fun OnboardingStep2(language: String) {
    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center,
        modifier = Modifier.fillMaxWidth()
    ) {
        // Complete Audio Timer Menu as called in the app (WidgetAddValueDialog / Value Dialog)
        Card(
            colors = CardDefaults.cardColors(containerColor = AppCard),
            shape = RoundedCornerShape(20.dp),
            modifier = Modifier
                .fillMaxWidth()
                .border(1.dp, AppBorder, RoundedCornerShape(20.dp))
        ) {
            Column(
                modifier = Modifier.padding(16.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                // Timer Header Title
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
