@Composable
fun TimeCapsuleSlide(
    type: String, // "MONTHLY" or "YEARLY"
    year: Int,
    month: Int = 1, // Only used for Monthly
    language: String,
    viewModel: HabitsViewModel
) {
    // 1. Calculate current period string & upcoming period string
    val currentPeriod = if (type == "MONTHLY") {
        "$year-%02d".format(month)
    } else {
        "$year"
    }

    val upcomingPeriod = if (type == "MONTHLY") {
        val currentYearMonth = java.time.YearMonth.of(year, month)
        currentYearMonth.plusMonths(1).toString() // "yyyy-MM"
    } else {
        "${year + 1}"
    }

    // 2. Fetch Past Note (targeting currentPeriod)
    val pastNoteFlow = remember(type, currentPeriod) { viewModel.getTimeCapsuleNote(type, currentPeriod) }
    val pastNote by pastNoteFlow.collectAsStateWithLifecycle(initialValue = null)

    // 3. Fetch Future Note draft (targeting upcomingPeriod)
    val futureNoteFlow = remember(type, upcomingPeriod) { viewModel.getTimeCapsuleNote(type, upcomingPeriod) }
    val futureNote by futureNoteFlow.collectAsStateWithLifecycle(initialValue = null)

    // Local state for the future note text input
    var futureText by remember { mutableStateOf("") }

    // Synchronize the input field text when the database loads the draft
    LaunchedEffect(futureNote) {
        if (futureNote != null && futureText.isEmpty()) {
            futureText = futureNote!!.content
        }
    }

    val titleText = if (type == "MONTHLY") {
        if (language == "de") "Zeitkapsel" else if (language == "ka") "დროის კაფსულა" else "Time Capsule"
    } else {
        if (language == "de") "Jahres-Zeitkapsel" else if (language == "ka") "წლიური დროის კაფსულა" else "Yearly Time Capsule"
    }

    val subtitleText = if (type == "MONTHLY") {
        if (language == "de") "Botschaften zwischen deinem vergangenen und zukünftigen Ich." else if (language == "ka") "შეტყობინებები თქვენს წარსულსა და მომავალს შორის." else "Messages between your past and future self."
    } else {
        if (language == "de") "Wirf einen Blick zurück und hinterlassen Wünsche für das nächste Jahr." else if (language == "ka") "გადახედეთ თქვენს მიზნებს და დატოვეთ შეტყობინებები მომავალი წლისთვის." else "Look back at your goals and leave messages for next year."
    }

    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 4.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Top
    ) {
        item {
            Text(
                text = "⏳ $titleText",
                style = MaterialTheme.typography.headlineMedium,
                color = Color.White,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center,
                modifier = Modifier.padding(top = 8.dp)
            )

            Text(
                text = subtitleText,
                style = MaterialTheme.typography.bodyMedium,
                color = Color.White.copy(alpha = 0.8f),
                textAlign = TextAlign.Center,
                modifier = Modifier.padding(top = 6.dp, bottom = 24.dp)
            )
        }

        // PAST MESSAGE CARD
        item {
            val pastPeriodLabel = if (type == "MONTHLY") {
                // Get month name of currentPeriod
                val yearMonth = java.time.YearMonth.parse(currentPeriod)
                val formatter = java.time.format.DateTimeFormatter.ofPattern("MMMM yyyy", if (language == "de") Locale.GERMAN else Locale.ENGLISH)
                yearMonth.format(formatter)
            } else {
                currentPeriod
            }

            Text(
                text = "✉️ " + (if (language == "de") "Nachricht für $pastPeriodLabel" else if (language == "ka") "შეტყობინება $pastPeriodLabel -სთვის" else "Message for $pastPeriodLabel"),
                style = MaterialTheme.typography.titleMedium,
                color = Color.White,
                fontWeight = FontWeight.Bold,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 4.dp, vertical = 8.dp),
                textAlign = TextAlign.Start
            )

            if (pastNote != null) {
                // VISUALLY DISTINCT UNSEALED NOTE CARD WITH MAIL/ENVELOPE DESIGN
                Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 24.dp),
                    color = Color(0xFFFEF3C7).copy(alpha = 0.95f), // Warm yellow/parchment background
                    shape = RoundedCornerShape(16.dp),
                    border = BorderStroke(1.5.dp, Color(0xFFD97706)) // Amber border
                ) {
                    Column(
                        modifier = Modifier.padding(18.dp)
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.Drafts, // open envelope / unsealed note
                                contentDescription = "Unsealed Mail",
                                tint = Color(0xFFD97706),
                                modifier = Modifier.size(24.dp)
                            )
                            Text(
                                text = if (language == "de") "Brief entsiegelt!" else if (language == "ka") "წერილი დალუქული!" else "Letter unsealed!",
                                style = MaterialTheme.typography.titleSmall,
                                color = Color(0xFF92400E),
                                fontWeight = FontWeight.Bold
                            )
                        }

                        Spacer(modifier = Modifier.height(10.dp))

                        Text(
                            text = "\"${pastNote!!.content}\"",
                            style = MaterialTheme.typography.bodyLarge,
                            color = Color(0xFF1F2937), // Dark text for parchment
                            fontStyle = androidx.compose.ui.text.font.FontStyle.Italic,
                            fontWeight = FontWeight.Medium,
                            modifier = Modifier.fillMaxWidth()
                        )

                        Spacer(modifier = Modifier.height(12.dp))

                        val sdf = SimpleDateFormat("dd.MM.yyyy", Locale.getDefault())
                        val dateFormatted = sdf.format(Date(pastNote!!.createdAt))
                        Text(
                            text = if (language == "de") "Geschrieben am $dateFormatted" else if (language == "ka") "დაწერილია $dateFormatted -ზე" else "Written on $dateFormatted",
                            style = MaterialTheme.typography.labelSmall,
                            color = Color(0xFF78350F),
                            modifier = Modifier.align(Alignment.End)
                        )
                    }
                }
            } else {
                // Friendly placeholder
                Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 24.dp),
                    color = Color.White.copy(alpha = 0.1f),
                    shape = RoundedCornerShape(16.dp),
                    border = BorderStroke(1.dp, Color.White.copy(alpha = 0.2f))
                ) {
                    Column(
                        modifier = Modifier
                            .padding(20.dp)
                            .fillMaxWidth(),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Icon(
                            imageVector = Icons.Default.Mail,
                            contentDescription = "Closed envelope",
                            tint = Color.White.copy(alpha = 0.4f),
                            modifier = Modifier.size(36.dp)
                        )
                        Spacer(modifier = Modifier.height(8.dp))
                        Text(
                            text = if (language == "de") 
                                "Keine Nachricht aus der Vergangenheit versiegelt." 
                            else if (language == "ka") "წარსულიდან არ არის დალუქული მესიჯი." else "No message from the past unsealed.",
                            style = MaterialTheme.typography.bodyMedium,
                            color = Color.White.copy(alpha = 0.6f),
                            textAlign = TextAlign.Center
                        )
                    }
                }
            }
        }

        // FUTURE MESSAGE CARD
        item {
            val futurePeriodLabel = if (type == "MONTHLY") {
                val yearMonth = java.time.YearMonth.parse(upcomingPeriod)
                val formatter = java.time.format.DateTimeFormatter.ofPattern("MMMM yyyy", if (language == "de") Locale.GERMAN else Locale.ENGLISH)
                yearMonth.format(formatter)
            } else {
                upcomingPeriod
            }

            Text(
                text = "✍️ " + (if (language == "de") "Brief an dein zukünftiges Ich für $futurePeriodLabel" else if (language == "ka") "წერილი თქვენს მომავალ საკუთარ თავს $futurePeriodLabel -სთვის" else "Letter to your future self for $futurePeriodLabel"),
                style = MaterialTheme.typography.titleMedium,
                color = Color.White,
                fontWeight = FontWeight.Bold,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 4.dp, vertical = 8.dp),
                textAlign = TextAlign.Start
            )

            Surface(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 36.dp),
                color = Color.White.copy(alpha = 0.08f),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, Color.White.copy(alpha = 0.15f))
            ) {
                Column(
                    modifier = Modifier.padding(16.dp)
                ) {
                    Text(
                        text = if (type == "MONTHLY") {
                            if (language == "de")
                                "Was möchtest du im nächsten Monat erreichen? Welche Gewohnheiten willst du meistern? Schreib es hier nieder:"
                            else if (language == "ka") "რისი მიღწევა გსურთ შემდეგ თვეში? რომელი ჩვევების დაუფლება გსურთ? დაწერე აქ:" else "What do you want to achieve next month? Which habits do you want to master? Write it here:"
                        } else {
                            if (language == "de")
                                "Hinterlasse eine Nachricht oder ein großes Lebensziel an dein zukünftiges Ich für das kommende Jahr:"
                            else if (language == "ka") "დატოვეთ მესიჯი ან მთავარი ცხოვრებისეული მიზანი მომავალი წლისთვის:" else "Leave a message or a major life goal for your future self for the upcoming year:"
                        },
                        style = MaterialTheme.typography.bodyMedium,
                        color = Color.White.copy(alpha = 0.85f),
                        modifier = Modifier.padding(bottom = 12.dp)
                    )

                    OutlinedTextField(
                        value = futureText,
                        onValueChange = { newValue ->
                            futureText = newValue
                            viewModel.saveTimeCapsuleNote(type, upcomingPeriod, newValue)
                        },
                        placeholder = {
                            Text(
                                text = if (language == "de") "Liebes zukünftiges Ich..." else if (language == "ka") "ძვირფასო მომავალო..." else "Dear future self...",
                                color = Color.White.copy(alpha = 0.4f)
                            )
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(130.dp),
                        shape = RoundedCornerShape(12.dp),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = Color(0xFFF59E0B),
                            unfocusedBorderColor = Color.White.copy(alpha = 0.25f),
                            focusedContainerColor = Color.Black.copy(alpha = 0.2f),
                            unfocusedContainerColor = Color.Black.copy(alpha = 0.1f),
                            focusedTextColor = Color.White,
                            unfocusedTextColor = Color.White
                        ),
                        maxLines = 5,
                        textStyle = MaterialTheme.typography.bodyMedium
                    )

                    Spacer(modifier = Modifier.height(10.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Icon(
                            imageVector = Icons.Default.Lock,
                            contentDescription = "Lock",
                            tint = Color(0xFFF59E0B),
                            modifier = Modifier.size(16.dp)
                        )
                        Text(
                            text = if (type == "MONTHLY") {
                                if (language == "de") "Diese Kapsel bleibt bis zum Beginn von $futurePeriodLabel versiegelt." else if (language == "ka") "ეს კაფსულა რჩება დალუქული $futurePeriodLabel -ის დაწყებამდე." else "This capsule remains sealed until the start of $futurePeriodLabel."
                            } else {
                                if (language == "de") "Diese Kapsel bleibt bis zum Beginn von $futurePeriodLabel versiegelt." else if (language == "ka") "ეს კაფსულა რჩება დალუქული $futurePeriodLabel -ის დაწყებამდე." else "This capsule remains sealed until the start of $futurePeriodLabel."
                            },
                            style = MaterialTheme.typography.labelSmall,
                            color = Color.White.copy(alpha = 0.5f)
                        )
                    }
                }
            }
        }
    }
}


@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RewardsOverviewSheet(
    viewModel: com.example.ui.HabitsViewModel,
    language: String,
    onDismiss: () -> Unit
) {
    val allRewards by viewModel.allMilestoneRewards.collectAsStateWithLifecycle(initialValue = emptyList())
    val allHabits by viewModel.allHabits.collectAsStateWithLifecycle(initialValue = emptyList())
    val profileStats by viewModel.profileStats.collectAsStateWithLifecycle(initialValue = com.example.data.ProfileStats())
    
    var selectedTabIndex by remember { mutableStateOf(0) }
    
    val activeRewards = allRewards.filter { it.unlockedAt == 0L }
    val achievedRewards = allRewards.filter { it.unlockedAt > 0L }.sortedByDescending { it.unlockedAt }

    Dialog(onDismissRequest = onDismiss) {
        Surface(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 4.dp, vertical = 16.dp),
            color = AppCard,
            border = BorderStroke(1.dp, AppBorder),
            shape = RoundedCornerShape(24.dp)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(20.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = if (language == "de") "Belohnungs-Übersicht" else if (language == "ka") "ჯილდოების მიმოხილვა" else "Rewards Overview",
                        style = MaterialTheme.typography.titleLarge,
                        color = TextPrimary,
                        fontWeight = FontWeight.Bold
                    )
                    IconButton(onClick = onDismiss) {
                        Icon(imageVector = Icons.Default.Close, contentDescription = "Close", tint = TextSecondary)
                    }
                }
                
                Spacer(modifier = Modifier.height(12.dp))

                TabRow(
                    selectedTabIndex = selectedTabIndex,
                    containerColor = Color.Transparent,
                    contentColor = PrimaryViolet
                ) {
                    Tab(
                        selected = selectedTabIndex == 0,
                        onClick = { selectedTabIndex = 0 },
                        text = { Text(if (language == "de") "Aktive (${activeRewards.size})" else if (language == "ka") "აქტიური ( ${activeRewards.size} )" else "Active (${activeRewards.size})", color = if (selectedTabIndex == 0) PrimaryViolet else TextSecondary) }
                    )
                    Tab(
                        selected = selectedTabIndex == 1,
                        onClick = { selectedTabIndex = 1 },
                        text = { Text(if (language == "de") "Erreicht (${achievedRewards.size})" else if (language == "ka") "მიღწეული ( ${achievedRewards.size} )" else "Achieved (${achievedRewards.size})", color = if (selectedTabIndex == 1) PrimaryViolet else TextSecondary) }
                    )
                }

                Spacer(modifier = Modifier.height(16.dp))

                LazyColumn(
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(max = 420.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    if (selectedTabIndex == 0) {
                        if (activeRewards.isEmpty()) {
                            item {
                                Text(
                                    text = if (language == "de") "Keine aktiven Belohnungen definiert." else if (language == "ka") "არ არის განსაზღვრული აქტიური ჯილდოები." else "No active rewards defined.",
                                    color = TextSecondary,
                                    modifier = Modifier.padding(vertical = 16.dp)
                                )
                            }
                        } else {
                            items(activeRewards) { reward ->
                                val habitStat = profileStats.habitStreaks.find { it.habit.id == reward.habitId }
                                val currentValue = when (reward.conditionType) {
                                    "STREAK" -> habitStat?.longestStreak ?: 0
                                    "COMPLETIONS" -> habitStat?.totalCompletions ?: 0
                                    else -> 0
                                }
                                val targetValue = reward.conditionValue.coerceAtLeast(1)
                                val progress = if (reward.conditionType == "TROPHY_COUPLED") 0f else (currentValue.toFloat() / targetValue.toFloat()).coerceIn(0f, 1f)
                                val trophy = if (reward.conditionType == "TROPHY_COUPLED") STANDARD_TROPHIES.find { it.id == reward.trophyId } else null

                                Card(
                                    colors = CardDefaults.cardColors(containerColor = AppBg),
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp),
                                    border = BorderStroke(1.dp, AppBorder)
                                ) {
                                    Column(modifier = Modifier.padding(14.dp)) {
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            if (trophy != null) {
                                                AchievementBadge(
                                                    type = trophy.type,
                                                    tier = trophy.tier,
                                                    isUnlocked = false,
                                                    modifier = Modifier.size(28.dp)
                                                )
                                                Spacer(modifier = Modifier.width(10.dp))
                                            } else {
                                                Icon(Icons.Default.Star, contentDescription = null, tint = PrimaryViolet, modifier = Modifier.size(20.dp))
                                                Spacer(modifier = Modifier.width(8.dp))
                                            }
                                            Text(
                                                text = reward.rewardText,
                                                style = MaterialTheme.typography.titleMedium,
                                                color = TextPrimary,
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                        
                                        val habit = allHabits.find { it.id == reward.habitId }
                                        if (habit != null) {
                                            Spacer(modifier = Modifier.height(6.dp))
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                modifier = Modifier
                                                    .background(
                                                        parseHabitColor(habit.color).copy(alpha = 0.15f),
                                                        RoundedCornerShape(6.dp)
                                                    )
                                                    .padding(horizontal = 8.dp, vertical = 4.dp)
                                            ) {
                                                Icon(
                                                    imageVector = HabitIconMapping.getIcon(habit.icon),
                                                    contentDescription = null,
                                                    tint = parseHabitColor(habit.color),
                                                    modifier = Modifier.size(14.dp)
                                                )
                                                Spacer(modifier = Modifier.width(6.dp))
                                                Text(
                                                    text = habit.name,
                                                    style = MaterialTheme.typography.bodySmall,
                                                    color = parseHabitColor(habit.color),
                                                    fontWeight = FontWeight.SemiBold
                                                )
                                            }
                                        }

                                        Spacer(modifier = Modifier.height(10.dp))
                                        
                                        if (reward.conditionType != "TROPHY_COUPLED") {
                                            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                                Text(
                                                    text = if (language == "de") "Fortschritt" else if (language == "ka") "პროგრესი" else "Progress",
                                                    style = MaterialTheme.typography.bodySmall,
                                                    color = TextSecondary
                                                )
                                                Text(
                                                    text = "$currentValue / $targetValue",
                                                    style = MaterialTheme.typography.bodySmall,
                                                    color = TextPrimary,
                                                    fontWeight = FontWeight.Bold
                                                )
                                            }
                                            Spacer(modifier = Modifier.height(6.dp))
                                            LinearProgressIndicator(
                                                progress = progress,
                                                modifier = Modifier.fillMaxWidth().height(8.dp).clip(RoundedCornerShape(4.dp)),
                                                color = PrimaryViolet,
                                                trackColor = AppBorder
                                            )
                                        } else {
                                            val tName = if (trophy != null) (if (language == "de") trophy.titleDe else trophy.titleEn) else (reward.trophyId ?: "")
                                            Text(
                                                text = if (language == "de") "Gekoppelt an Trophäe: $tName" else if (language == "ka") "დაწყვილებული Trophy: $tName" else "Coupled to Trophy: $tName",
                                                style = MaterialTheme.typography.bodySmall,
                                                color = TextSecondary
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    } else {
                        if (achievedRewards.isEmpty()) {
                            item {
                                Text(
                                    text = if (language == "de") "Noch keine Belohnungen erreicht." else if (language == "ka") "ჯერ არ არის მიღებული ჯილდო." else "No rewards achieved yet.",
                                    color = TextSecondary,
                                    modifier = Modifier.padding(vertical = 16.dp)
                                )
                            }
                        } else {
                            items(achievedRewards) { reward ->
                                val trophy = if (reward.conditionType == "TROPHY_COUPLED") STANDARD_TROPHIES.find { it.id == reward.trophyId } else null
                                Card(
                                    colors = CardDefaults.cardColors(containerColor = if (reward.isRedeemed) AppBg else PrimaryViolet.copy(alpha = 0.12f)),
                                    border = if (reward.isRedeemed) BorderStroke(1.dp, AppBorder) else BorderStroke(1.dp, PrimaryViolet.copy(alpha = 0.5f)),
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth().padding(14.dp),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Row(modifier = Modifier.weight(1f), verticalAlignment = Alignment.CenterVertically) {
                                            if (trophy != null) {
                                                AchievementBadge(
                                                    type = trophy.type,
                                                    tier = trophy.tier,
                                                    isUnlocked = true,
                                                    modifier = Modifier.size(28.dp)
                                                )
                                                Spacer(modifier = Modifier.width(10.dp))
                                            }
                                            Column {
                                                Text(
                                                    text = reward.rewardText,
                                                    style = MaterialTheme.typography.titleMedium,
                                                    color = if (reward.isRedeemed) TextSecondary else TextPrimary,
                                                    fontWeight = FontWeight.Bold,
                                                    textDecoration = if (reward.isRedeemed) TextDecoration.LineThrough else TextDecoration.None
                                                )
                                                Text(
                                                    text = if (reward.isRedeemed) {
                                                        if (language == "de") "Eingelöst" else if (language == "ka") "გამოისყიდა" else "Redeemed"
                                                    } else {
                                                        if (language == "de") "Bereit zum Einlösen!" else if (language == "ka") "მზად არის გამოსასყიდად!" else "Ready to redeem!"
                                                    },
                                                    style = MaterialTheme.typography.bodySmall,
                                                    color = if (reward.isRedeemed) TextSecondary else PrimaryViolet
                                                )
                                                
                                                val habit = allHabits.find { it.id == reward.habitId }
                                                if (habit != null) {
                                                    Spacer(modifier = Modifier.height(4.dp))
                                                    Row(
                                                        verticalAlignment = Alignment.CenterVertically,
                                                        modifier = Modifier
                                                            .background(
                                                                parseHabitColor(habit.color).copy(alpha = 0.15f),
                                                                RoundedCornerShape(6.dp)
                                                            )
                                                            .padding(horizontal = 6.dp, vertical = 2.dp)
                                                    ) {
                                                        Icon(
                                                            imageVector = HabitIconMapping.getIcon(habit.icon),
                                                            contentDescription = null,
                                                            tint = parseHabitColor(habit.color),
                                                            modifier = Modifier.size(12.dp)
                                                        )
                                                        Spacer(modifier = Modifier.width(4.dp))
                                                        Text(
                                                            text = habit.name,
                                                            style = MaterialTheme.typography.labelSmall,
                                                            color = parseHabitColor(habit.color),
                                                            fontWeight = FontWeight.SemiBold
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                        if (!reward.isRedeemed) {
                                            Button(
                                                onClick = { viewModel.redeemMilestoneReward(reward.id) },
                                                colors = ButtonDefaults.buttonColors(containerColor = PrimaryViolet),
                                                contentPadding = PaddingValues(horizontal = 14.dp, vertical = 6.dp)
                                            ) {
                                                Text(
                                                    text = if (language == "de") "Einlösen" else if (language == "ka") "გამოისყიდე" else "Redeem",
                                                    style = MaterialTheme.typography.labelMedium,
                                                    fontWeight = FontWeight.Bold
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}










fun Modifier.animatedGlowingBorder(
    glowColor: Color,
    cornerRadius: Dp = 20.dp,
    borderWidth: Dp = 2.dp,
    baseColor: Color? = null
): Modifier = composed {
    val infiniteTransition = rememberInfiniteTransition(label = "glow_pulse")
    val pulseAlpha by infiniteTransition.animateFloat(
        initialValue = 0.6f,
        targetValue = 1.0f,
        animationSpec = infiniteRepeatable(
            animation = tween(2000, easing = FastOutSlowInEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "pulse_alpha"
    )

    this.drawBehind {
        val radiusPx = cornerRadius.toPx()
        
        // Layer 1: Broad soft ambient aura (outermost)
        drawRoundRect(
            color = glowColor.copy(alpha = 0.18f * pulseAlpha),
            size = androidx.compose.ui.geometry.Size(
                width = size.width + 24.dp.toPx(),
                height = size.height + 24.dp.toPx()
            ),
            topLeft = androidx.compose.ui.geometry.Offset(-12.dp.toPx(), -12.dp.toPx()),
            cornerRadius = CornerRadius(radiusPx + 12.dp.toPx(), radiusPx + 12.dp.toPx())
        )
        
        // Layer 2: Medium vibrant glow halo
        drawRoundRect(
            color = glowColor.copy(alpha = 0.35f * pulseAlpha),
            size = androidx.compose.ui.geometry.Size(
                width = size.width + 14.dp.toPx(),
                height = size.height + 14.dp.toPx()
            ),
            topLeft = androidx.compose.ui.geometry.Offset(-7.dp.toPx(), -7.dp.toPx()),
            cornerRadius = CornerRadius(radiusPx + 7.dp.toPx(), radiusPx + 7.dp.toPx())
        )

        // Layer 3: Intense inner glowing ring
        drawRoundRect(
            color = glowColor.copy(alpha = 0.55f * pulseAlpha),
            size = androidx.compose.ui.geometry.Size(
                width = size.width + 6.dp.toPx(),
                height = size.height + 6.dp.toPx()
            ),
            topLeft = androidx.compose.ui.geometry.Offset(-3.dp.toPx(), -3.dp.toPx()),
            cornerRadius = CornerRadius(radiusPx + 3.dp.toPx(), radiusPx + 3.dp.toPx())
        )
    }.drawWithContent {
        drawContent()
        val radiusPx = cornerRadius.toPx()
        val widthPx = borderWidth.toPx()
        
        // Solid vibrant border outline
        drawRoundRect(
            color = baseColor?.copy(alpha = 0.85f) ?: glowColor.copy(alpha = 0.85f),
            size = size,
            cornerRadius = CornerRadius(radiusPx, radiusPx),
            style = Stroke(widthPx)
        )
    }
}

@Composable
private fun CsvImportPreviewDialog(
    preview: com.example.data.CsvImportPreview?,
    isAnalyzing: Boolean,
    language: String,
    onConfirm: (replaceExisting: Boolean) -> Unit,
    onDismiss: () -> Unit
) {
    if (!isAnalyzing && preview == null) return

    androidx.compose.ui.window.Dialog(
        onDismissRequest = onDismiss,
        properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false)
    ) {
        Surface(
            modifier = Modifier
                .fillMaxWidth(0.92f)
                .wrapContentHeight()
                .padding(16.dp),
            shape = RoundedCornerShape(28.dp),
            color = MaterialTheme.colorScheme.surface,
            tonalElevation = 8.dp,
            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.2f))
        ) {
            if (isAnalyzing) {
                Column(
                    modifier = Modifier.padding(32.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    CircularProgressIndicator(color = PrimaryViolet, modifier = Modifier.size(48.dp))
                    Spacer(modifier = Modifier.height(16.dp))
                    Text(
                        text = if (language == "de") "Analysiere CSV / ZIP Datei..." else if (language == "ka") "მიმდინარეობს CSV / ZIP ფაილის ანალიზი..." else "Analyzing CSV / ZIP file...",
                        style = MaterialTheme.typography.titleMedium,
                        fontWeight = FontWeight.Bold
                    )
                }
            } else if (preview != null) {
                var replaceExisting by remember { mutableStateOf(false) }

                Column(
                    modifier = Modifier
                        .padding(20.dp)
                        .verticalScroll(rememberScrollState())
                ) {
                    // Header Tag
                    Surface(
                        color = PrimaryViolet.copy(alpha = 0.12f),
                        shape = RoundedCornerShape(100.dp),
                        border = BorderStroke(1.dp, PrimaryViolet.copy(alpha = 0.3f))
                    ) {
                        Text(
                            text = "IMPORT ANALYSE",
                            style = MaterialTheme.typography.labelSmall.copy(letterSpacing = 1.2.sp),
                            color = PrimaryViolet,
                            fontWeight = FontWeight.Bold,
                            modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp)
                        )
                    }

                    Spacer(modifier = Modifier.height(10.dp))

                    Text(
                        text = if (language == "de") "Gewohnheiten importieren" else if (language == "ka") "იმპორტის ჩვევები" else "Import Habits",
                        style = MaterialTheme.typography.headlineSmall,
                        fontWeight = FontWeight.ExtraBold
                    )

                    Spacer(modifier = Modifier.height(4.dp))

                    Text(
                        text = "Quelle: ${preview.sourceName}",
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.primary,
                        fontWeight = FontWeight.Bold
                    )

                    Spacer(modifier = Modifier.height(16.dp))

                    if (preview.errorMessage != null) {
                        // Error Card
                        Surface(
                            color = ErrorRed.copy(alpha = 0.1f),
                            shape = RoundedCornerShape(16.dp),
                            border = BorderStroke(1.dp, ErrorRed.copy(alpha = 0.3f)),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(
                                modifier = Modifier.padding(14.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Icon(Icons.Default.ErrorOutline, contentDescription = null, tint = ErrorRed, modifier = Modifier.size(24.dp))
                                Spacer(modifier = Modifier.width(12.dp))
                                Text(
                                    text = preview.errorMessage,
                                    style = MaterialTheme.typography.bodyMedium,
                                    color = ErrorRed
                                )
                            }
                        }
                    } else {
                        // Stats Overview
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Surface(
                                color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                                shape = RoundedCornerShape(16.dp),
                                modifier = Modifier.weight(1f)
                            ) {
                                Column(modifier = Modifier.padding(12.dp)) {
                                    Text(
                                        text = if (language == "de") "Gewohnheiten" else if (language == "ka") "ჩვევები" else "Habits",
                                        style = MaterialTheme.typography.labelSmall,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = "${preview.habits.size}",
                                        style = MaterialTheme.typography.titleLarge,
                                        fontWeight = FontWeight.Bold,
                                        color = PrimaryViolet
                                    )
                                }
                            }

                            Surface(
                                color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                                shape = RoundedCornerShape(16.dp),
                                modifier = Modifier.weight(1f)
                            ) {
                                Column(modifier = Modifier.padding(12.dp)) {
                                    Text(
                                        text = if (language == "de") "Einträge" else if (language == "ka") "ჟურნალები" else "Logs",
                                        style = MaterialTheme.typography.labelSmall,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = "${preview.totalLogsCount}",
                                        style = MaterialTheme.typography.titleLarge,
                                        fontWeight = FontWeight.Bold,
                                        color = SuccessGreen
                                    )
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(10.dp))

                        // Date range badge
                        Surface(
                            color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(
                                modifier = Modifier.padding(10.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Icon(Icons.Default.DateRange, contentDescription = null, tint = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = "Zeitraum: ${preview.dateRange}",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                                    fontWeight = FontWeight.Medium
                                )
                            }
                        }

                        Spacer(modifier = Modifier.height(16.dp))

                        Text(
                            text = if (language == "de") "Gefundene Gewohnheiten:" else if (language == "ka") "გამოვლენილი ჩვევები:" else "Detected Habits:",
                            style = MaterialTheme.typography.titleSmall,
                            fontWeight = FontWeight.Bold
                        )

                        Spacer(modifier = Modifier.height(8.dp))

                        // List of Preview Habits (max height container)
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .heightIn(max = 180.dp)
                                .verticalScroll(rememberScrollState()),
                            verticalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            preview.habits.forEach { habit ->
                                Surface(
                                    color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f),
                                    shape = RoundedCornerShape(12.dp),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    Row(
                                        modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.SpaceBetween
                                    ) {
                                        Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.weight(1f)) {
                                            Box(
                                                modifier = Modifier
                                                    .size(10.dp)
                                                    .background(PrimaryViolet, CircleShape)
                                            )
                                            Spacer(modifier = Modifier.width(8.dp))
                                            Text(
                                                text = habit.name,
                                                style = MaterialTheme.typography.bodyMedium,
                                                fontWeight = FontWeight.SemiBold,
                                                maxLines = 1,
                                                overflow = TextOverflow.Ellipsis
                                            )
                                        }

                                        Text(
                                            text = "${habit.logs.size} Einträge",
                                            style = MaterialTheme.typography.labelSmall,
                                            color = MaterialTheme.colorScheme.onSurfaceVariant
                                        )
                                    }
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(18.dp))

                        // Import Mode Switcher
                        Text(
                            text = if (language == "de") "Import-Modus:" else if (language == "ka") "იმპორტის რეჟიმი:" else "Import Mode:",
                            style = MaterialTheme.typography.titleSmall,
                            fontWeight = FontWeight.Bold
                        )

                        Spacer(modifier = Modifier.height(6.dp))

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(12.dp))
                                .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                                .clickable { replaceExisting = false }
                                .padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            RadioButton(
                                selected = !replaceExisting,
                                onClick = { replaceExisting = false },
                                colors = RadioButtonDefaults.colors(selectedColor = PrimaryViolet)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Column {
                                Text(
                                    text = if (language == "de") "Zusammenführen (Empfohlen)" else if (language == "ka") "შერწყმა (რეკომენდირებულია)" else "Merge (Recommended)",
                                    style = MaterialTheme.typography.bodyMedium,
                                    fontWeight = FontWeight.Bold
                                )
                                Text(
                                    text = if (language == "de") "Fügt neue Daten zu bestehenden hinzu." else if (language == "ka") "ამატებს ახალ ჩანაწერებს მიმდინარე ჩვევებთან ერთად." else "Adds new entries alongside current habits.",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                        }

                        Spacer(modifier = Modifier.height(6.dp))

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(12.dp))
                                .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                                .clickable { replaceExisting = true }
                                .padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            RadioButton(
                                selected = replaceExisting,
                                onClick = { replaceExisting = true },
                                colors = RadioButtonDefaults.colors(selectedColor = ErrorRed)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Column {
                                Text(
                                    text = if (language == "de") "Bestehende ersetzen" else if (language == "ka") "შეცვალეთ არსებული" else "Replace existing",
                                    style = MaterialTheme.typography.bodyMedium,
                                    fontWeight = FontWeight.Bold,
                                    color = ErrorRed
                                )
                                Text(
                                    text = if (language == "de") "Löscht aktuelle Gewohnheiten und überschreibt diese." else if (language == "ka") "ასუფთავებს არსებულ მონაცემებს და ანაცვლებს იმპორტით." else "Clears existing data and replaces with import.",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(20.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        OutlinedButton(
                            onClick = onDismiss,
                            modifier = Modifier.weight(1f),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Text(if (language == "de") "Abbrechen" else if (language == "ka") "გაუქმება" else "Cancel")
                        }

                        if (preview.errorMessage == null && preview.habits.isNotEmpty()) {
                            Button(
                                onClick = { onConfirm(replaceExisting) },
                                colors = ButtonDefaults.buttonColors(containerColor = PrimaryViolet),
                                modifier = Modifier.weight(1.2f),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Icon(Icons.Default.UploadFile, contentDescription = null, modifier = Modifier.size(18.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(if (language == "de") "Importieren" else if (language == "ka") "იმპორტი" else "Import")
                            }
                        }
                    }
                }
            }
        }
    }
}
